internal static class CombatContentTests
{
    private static bool MatchesCoopMuzzleObservation(CoopQueuedMuzzleSample? actual, CoopQueuedMuzzleSample expected)
    {
        const float TimeTolerance = 0.00001f;
        const float PositionTolerance = 0.00002f;
        const float RotationTolerance = 0.000001f;
        if (actual == null)
        {
            return false;
        }

        // Native animation samples and curve evaluation agree within the reviewed float tolerances.
        return Math.Abs(actual.FireClipSeconds - expected.FireClipSeconds) <= TimeTolerance &&
            Vector3.Distance(actual.LocalPosition, expected.LocalPosition) <= PositionTolerance &&
            1f - Math.Abs(Quaternion.Dot(actual.LocalRotation, expected.LocalRotation)) <= RotationTolerance;
    }

    private static int VerifyCoopSkillShotScores(CoopSkillShotScoreCatalog scores)
    {
        if (scores.Rows.Count != 19 || scores.Rows[0].Name != "HeadShot" ||
            scores.PointsForFlags(0) != 0 ||
            scores.PointsForFlags(1) != 5 ||
            scores.PointsForFlags(1 | 2) != 6 ||
            scores.PointsForConfirmedEnemyKill(CoopEnemyKillCredit.Player) != 10 ||
            scores.PointsForConfirmedEnemyKill(CoopEnemyKillCredit.Player, 32) != 15 ||
            scores.PointsForConfirmedEnemyKill(CoopEnemyKillCredit.Player, 64) != 20 ||
            scores.PointsForConfirmedEnemyKill(CoopEnemyKillCredit.Player, 128) != 35 ||
            scores.PointsForConfirmedEnemyKill(CoopEnemyKillCredit.AlliedArmy) != 5 ||
            scores.PointsForConfirmedEnemyKill(CoopEnemyKillCredit.UnownedBasicDamage) != 12 ||
            scores.PointsForConfirmedEnemyKill(CoopEnemyKillCredit.UnownedExplosion) != 14)
            throw new Exception("Recovered co-op skill-shot points differ from Client.");

        try
        {
            scores.PointsForFlags(1 << 20);
            throw new Exception("An unknown skill-shot flag was accepted.");
        }
        catch (ArgumentOutOfRangeException)
        {
            // The host must establish every flag before it can add Score points.
        }

        return 13;
    }

    private static int VerifyMissionCatalog(
        string directory, BattleCombatContent content)
    {
        string path = Path.Combine(directory, "recovered-mission-catalog.json");
        MissionCatalog catalog = MissionCatalog.Load(path);
        if (catalog.Missions.Count != 75 ||
            catalog.Get(0).MissionType != "KillXEnemies" ||
            catalog.Get(0).Objective != 10 ||
            catalog.Get(74).MissionType != "KillOpponent" ||
            catalog.MapForMission(0).Scene != "Desert_New" ||
            catalog.MapForMission(4).Scene != "Desert_Multiplayer" ||
            catalog.MapForMission(74).Scene != "Park_Multiplayer")
            throw new Exception("Recovered mission rules did not load in source order.");
        int behaviourCount = catalog.Missions.Sum(mission => mission.Behaviours.Count);
        int eventCount = catalog.Missions.Sum(mission => mission.Events.Count);
        if (behaviourCount != 343 || eventCount != 363)
            throw new Exception("Recovered mission unit and timed-event rows are incomplete.");
        int objectiveAssertions = VerifyMissionObjectives(catalog);
        int scoreAssertions = VerifyMissionScoring(catalog);
        int spawnAssertions = VerifyMissionAutomaticSpawns(catalog);
        int eventAssertions = VerifyMissionTimedEvents(catalog);
        CoopSkillShotScoreCatalog skillShots = CoopSkillShotScoreCatalog.Load(
            Path.Combine(directory, "recovered-coop-skillshot-scores.json"),
            content.Stats.SceneRevision, content.Stats.Revision);
        int coopAssertions = VerifyCoopMissionEngine(catalog, skillShots);
        coopAssertions += MissionTransportCrewTests.Run(catalog);
        coopAssertions += MissionDeathCascadeTests.Run(catalog);
        CoopSurvivorMissionTests.Run(catalog, skillShots);
        int allocationAssertions = VerifyCoopAllocation(
            directory, catalog, content);
        int skillShotAssertions = VerifyCoopSkillShotScores(skillShots);
        int mapAssertions = VerifyCoopSpawnCatalog(directory, catalog);
        int enemyPointAssertions = VerifyCoopEnemyPoints(directory, catalog,
            content.Army);
        int colliderAssertions = VerifyCoopSceneColliders(directory, catalog);
        int prefabColliderAssertions = VerifyCoopPrefabColliders(directory);
        int nativeRayAssertions = VerifyCoopNativeSceneRays(directory, catalog);
        int navMeshAssertions = VerifyCoopNavMeshSources(directory, catalog);
        int routeAssertions = VerifyCoopNavMeshRoutes(directory, catalog);
        int botAssertions = VerifyCoopBotRules(directory, catalog, content);
        int bossSpawnAssertions = VerifyCoopBossAiSpawns(catalog,
            content.ArmySpawnPoints, content.Maps);

        string temporaryPath = Path.Combine(Path.GetTempPath(),
            $"war-mission-catalog-{Guid.NewGuid():N}.json");
        try
        {
            JsonNode document = JsonNode.Parse(File.ReadAllText(path))!;
            document["missions"]![0]!["rewardGold"] = -1;
            RejectMissionCatalog(temporaryPath, document,
                "A corrupt mission reward was accepted.");

            document = JsonNode.Parse(File.ReadAllText(path))!;
            JsonNode firstMission = document["missions"]![0]!;
            firstMission["events"]![0]!["time"] =
                firstMission["timeSeconds"]!.GetValue<int>() + 1;
            RejectMissionCatalog(temporaryPath, document,
                "An event beyond the source mission timer was accepted.");

            document = JsonNode.Parse(File.ReadAllText(path))!;
            document["bossMaps"]![0]!["sceneSha256"] = new string('0', 64);
            RejectMissionCatalog(temporaryPath, document,
                "A changed boss scene hash was accepted.");
            return 5 + skillShotAssertions + objectiveAssertions + scoreAssertions +
                spawnAssertions + eventAssertions + coopAssertions +
                allocationAssertions + mapAssertions + enemyPointAssertions +
                colliderAssertions +
                prefabColliderAssertions +
                nativeRayAssertions + navMeshAssertions +
                routeAssertions + botAssertions + bossSpawnAssertions;
        }
        finally
        {
            File.Delete(temporaryPath);
        }
    }

    private static void RejectMissionCatalog(
        string path, JsonNode document, string failureMessage)
    {
        File.WriteAllText(path, document.ToJsonString());
        try
        {
            _ = MissionCatalog.Load(path);
        }
        catch (InvalidDataException)
        {
            return;
        }
        throw new Exception(failureMessage);
    }

    private static int VerifyMissionObjectives(MissionCatalog catalog)
    {
        const string firstEvent = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        const string secondEvent = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
        MissionRule killRule = catalog.Missions.First(mission => mission.MissionType == "KillXEnemies");
        MissionObjectiveState killMission = catalog.CreateObjectiveState(killRule.Index);
        if (killMission.RecordEnemyKill(firstEvent, 0) || !killMission.Start(100) ||
            !killMission.RecordEnemyKill(firstEvent, 100) ||
            killMission.RecordEnemyKill(firstEvent, 100) || killMission.EnemyKills != 1)
            throw new Exception("Enemy kills must be confirmed after start and counted once.");

        MissionRule scoreRule = catalog.Missions.First(mission => mission.MissionType == "Score");
        MissionObjectiveState scoreMission = catalog.CreateObjectiveState(scoreRule.Index);
        scoreMission.Start(100);
        if (!scoreMission.RecordScore(firstEvent, scoreRule.Objective!.Value, 100) ||
            scoreMission.Outcome != MissionOutcome.Succeeded ||
            scoreMission.RecordScore(secondEvent, 1, 101))
            throw new Exception("Confirmed score reaches the source target exactly once.");

        MissionRule survivalRule = catalog.Missions.First(mission => mission.MissionType == "SurviveXSeconds");
        MissionObjectiveState survivalMission = catalog.CreateObjectiveState(survivalRule.Index);
        survivalMission.Start(100);
        ulong survivalDeadline = survivalMission.DeadlineTick!.Value;
        if (survivalMission.AdvanceClock(survivalDeadline - 1) ||
            !survivalMission.AdvanceClock(survivalDeadline) ||
            survivalMission.Outcome != MissionOutcome.Succeeded)
            throw new Exception("Survival succeeds only when its source timer expires.");

        MissionRule bossRule = catalog.Missions.First(mission => mission.MissionType == "KillOpponent");
        MissionObjectiveState bossMission = catalog.CreateObjectiveState(bossRule.Index);
        bossMission.Start(100);
        if (!bossMission.RecordBossKilled(firstEvent, 100) ||
            bossMission.Outcome != MissionOutcome.Succeeded ||
            bossMission.RecordBossKilled(secondEvent, 101))
            throw new Exception("A confirmed boss death ends its mission once.");

        MissionObjectiveState timedKillMission = catalog.CreateObjectiveState(killRule.Index);
        timedKillMission.Start(100);
        timedKillMission.AdvanceClock(timedKillMission.DeadlineTick!.Value);
        if (timedKillMission.Outcome != MissionOutcome.Failed ||
            timedKillMission.RecordEnemyKill(firstEvent, timedKillMission.DeadlineTick.Value))
            throw new Exception("Unfinished kill missions fail at the source deadline.");
        return 5;
    }

    private static int VerifyMissionScoring(MissionCatalog catalog)
    {
        MissionRule killRule = catalog.Get(0);
        MissionScoreResult healthyKill = MissionScoreCalculator.Calculate(
            killRule, killRule.HealthTargetFraction, 0);
        if (healthyKill.Score != killRule.ScoreThreeStars || healthyKill.Stars != 3)
            throw new Exception("Kill mission score must follow the source health bonus.");

        MissionRule bossRule = catalog.Missions.First(mission => mission.MissionType == "KillOpponent");
        MissionScoreResult targetBoss = MissionScoreCalculator.Calculate(
            bossRule, bossRule.HealthTargetFraction, bossRule.TimeTargetFraction);
        MissionScoreResult earlyBoss = MissionScoreCalculator.Calculate(
            bossRule, bossRule.HealthTargetFraction, 0);
        if (targetBoss.Score != bossRule.ScoreThreeStars || targetBoss.Stars != 3 ||
            earlyBoss.Score != bossRule.ScoreTwoStars || earlyBoss.Stars != 2)
            throw new Exception("Boss mission score must combine source health and time targets.");

        try
        {
            _ = MissionScoreCalculator.Calculate(bossRule, float.NaN, 0);
            throw new Exception("Non-finite health was accepted for mission scoring.");
        }
        catch (ArgumentOutOfRangeException)
        {
            return 3;
        }
    }

    private static int VerifyMissionAutomaticSpawns(MissionCatalog catalog)
    {
        MissionRule firstMission = catalog.Get(0);
        var spawns = catalog.CreateAutomaticSpawnState(firstMission.Index, _ => 0);
        if (spawns.EligibleBehaviourIndexes(100).Count != 0 ||
            !spawns.Start(100) || spawns.Start(100) ||
            spawns.SelectAutomaticBehaviour(107) != null ||
            spawns.ConfirmSpawn(0, 101, 107))
            throw new Exception("Automatic units need a started mission and an eighth-tick opportunity.");

        bool SpawnAt(int index, ulong entityId, ulong tick)
        {
            return spawns.SelectAutomaticBehaviour(tick) == index &&
                spawns.ConfirmSpawn(index, entityId, tick);
        }

        if (spawns.SelectAutomaticBehaviour(108) != 0 ||
            spawns.ConfirmSpawn(1, 999, 108) ||
            !spawns.ConfirmSpawn(0, 101, 108) ||
            spawns.ConfirmSpawn(0, 102, 108) ||
            spawns.SelectAutomaticBehaviour(108) != null ||
            !SpawnAt(0, 102, 116) || !SpawnAt(0, 103, 124) ||
            spawns.SelectAutomaticBehaviour(132) != 1 ||
            spawns.ConfirmSpawn(0, 104, 132))
            throw new Exception("One unit may spawn per opportunity and the source lifetime limit holds.");

        if (!SpawnAt(1, 201, 140) || !SpawnAt(1, 202, 148) ||
            spawns.LiveCount != firstMission.MaxUnitsAtOnce ||
            spawns.SelectAutomaticBehaviour(156) != null)
            throw new Exception("Source scene and global limits cap living AI.");

        if (!spawns.ConfirmDeath(201) || spawns.ConfirmDeath(201) ||
            !SpawnAt(1, 203, 164) ||
            spawns.SelectAutomaticBehaviour(172) != null ||
            spawns.ConfirmSpawn(1, 204, 172))
            throw new Exception("A death reopens live capacity without resetting lifetime totals.");

        var invalidChoice = catalog.CreateAutomaticSpawnState(firstMission.Index,
            count => count);
        invalidChoice.Start(0);
        try
        {
            invalidChoice.SelectAutomaticBehaviour(8);
            throw new Exception("An invalid server random choice was accepted.");
        }
        catch (InvalidDataException)
        {
            return 5;
        }
    }

    private static int VerifyMissionTimedEvents(MissionCatalog catalog)
    {
        MissionRule firstMission = catalog.Get(0);
        var events = catalog.CreateAutomaticSpawnState(firstMission.Index);
        events.Start(100);
        ulong firstEventTick = 100 + (ulong)firstMission.Events[0].TimeSeconds *
            MatchManifest.TickRate;
        if (events.DueTimedEvents(firstEventTick - 1).Contains(0) ||
            !events.DueTimedEvents(firstEventTick).Contains(0) ||
            events.DueTimedEvents(firstEventTick).Count != 0)
            throw new Exception("A timed event is offered once in its source second.");
        if (!events.DueTimedEvents(firstEventTick + MatchManifest.TickRate).Contains(0) ||
            !events.ConfirmTimedEventSpawn(0, 301, firstEventTick + MatchManifest.TickRate) ||
            events.ConfirmTimedEventSpawn(0, 302, firstEventTick + MatchManifest.TickRate) || events.LiveCount != 0)
            throw new Exception("A failed event retries; an unmatched event does not use wave capacity.");
        if (events.DueTimedEvents(firstEventTick + 2 * MatchManifest.TickRate).Contains(0) ||
            !events.ConfirmDeath(301) || events.ConfirmDeath(301))
            throw new Exception("A completed timed event is not replayed or killed twice.");

        MissionRule matchedMission = catalog.Missions.First(mission =>
            mission.Events.Any(timedEvent => mission.Behaviours.Any(behavior =>
                string.Equals(behavior.Name, timedEvent.Behaviour,
                    StringComparison.OrdinalIgnoreCase))));
        int matchedIndex = matchedMission.Events.ToList().FindIndex(timedEvent =>
            matchedMission.Behaviours.Any(behavior =>
                string.Equals(behavior.Name, timedEvent.Behaviour,
                    StringComparison.OrdinalIgnoreCase)));
        var matchedEvents = catalog.CreateAutomaticSpawnState(matchedMission.Index);
        matchedEvents.Start(0);
        ulong matchedTick = (ulong)matchedMission.Events[matchedIndex].TimeSeconds *
            MatchManifest.TickRate;
        if (!matchedEvents.DueTimedEvents(matchedTick).Contains(matchedIndex) ||
            !matchedEvents.ConfirmTimedEventSpawn(matchedIndex, 401, matchedTick) ||
            matchedEvents.LiveCount != 1 || !matchedEvents.ConfirmDeath(401) ||
            matchedEvents.LiveCount != 0)
            throw new Exception("A matching timed event contributes to source wave accounting.");
        matchedEvents.Finish();
        if (matchedEvents.DueTimedEvents(matchedTick + MatchManifest.TickRate).Count != 0)
            throw new Exception("A finished mission cannot issue later timed events.");

        var expiredEvents = catalog.CreateAutomaticSpawnState(firstMission.Index);
        expiredEvents.Start(0);
        ulong sourceDeadline = (ulong)firstMission.TimeSeconds * MatchManifest.TickRate;
        expiredEvents.DueTimedEvents((ulong)firstMission.Events[0].TimeSeconds *
            MatchManifest.TickRate);
        if (expiredEvents.ConfirmTimedEventSpawn(0, 501, sourceDeadline) ||
            expiredEvents.ConfirmSpawn(0, 502, sourceDeadline))
            throw new Exception("A mission cannot confirm a spawn after its source deadline.");
        return 5;
    }

    private static int VerifyCoopMissionEngine(MissionCatalog catalog,
        CoopSkillShotScoreCatalog skillShots)
    {
        const string firstPlayer = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        const string secondPlayer = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
        var mission = new CoopMissionEngine(catalog, 0, _ => 0);
        if (!mission.Admit(firstPlayer) || !mission.Admit(secondPlayer) ||
            mission.Admit("cccccccccccccccccccccccccccccccc") ||
            !mission.MarkReady(firstPlayer, 0) || mission.Started ||
            !mission.MarkReady(secondPlayer, 0) || !mission.Started)
            throw new Exception("Two allied participants must be admitted and ready before mission start.");

        ulong[] automaticTicks = [8, 16, 24, 32, 40, 48];
        for (int index = 0; index < automaticTicks.Length; index++)
        {
            ulong tick = automaticTicks[index];
            int expectedBehaviour = index < 3 ? 0 : 1;
            ulong entityId = (ulong)(index + 1);
            if (mission.SelectAutomaticBehaviour(tick) != expectedBehaviour ||
                !mission.ConfirmAutomaticSpawn(expectedBehaviour, entityId, tick) ||
                !mission.ConfirmAiDeath(entityId, tick) ||
                mission.ConfirmAiDeath(entityId, tick))
                throw new Exception("Each confirmed automatic AI death counts once toward the kill mission.");
        }

        int[] eventIndexes = [0, 2, 1, 3];
        for (int index = 0; index < eventIndexes.Length; index++)
        {
            int eventIndex = eventIndexes[index];
            ulong tick = (ulong)catalog.Get(0).Events[eventIndex].TimeSeconds *
                MatchManifest.TickRate;
            ulong entityId = (ulong)(100 + index);
            if (!mission.DueTimedEvents(tick).Contains(eventIndex) ||
                !mission.ConfirmTimedEventSpawn(eventIndex, entityId, tick) ||
                !mission.ConfirmAiDeath(entityId, tick))
                throw new Exception("A confirmed timed AI death advances the shared objective.");
        }

        if (mission.EnemyKills != 10 || mission.Outcome != MissionOutcome.Succeeded ||
            mission.SelectAutomaticBehaviour(800) != null ||
            mission.ConfirmAiDeath(103, 800))
            throw new Exception("The source kill target ends the shared mission exactly once.");

        MissionRule scoreRule = catalog.Missions.First(rule =>
            rule.MissionType == "Score");
        var scored = new CoopMissionEngine(catalog, scoreRule.Index, _ => 0);
        scored.Admit(firstPlayer);
        scored.Admit(secondPlayer);
        scored.MarkReady(firstPlayer, 0);
        scored.MarkReady(secondPlayer, 0);
        int? firstScoreBehaviour = scored.SelectAutomaticBehaviour(8);
        if (firstScoreBehaviour == null ||
            !scored.ConfirmAutomaticSpawn(firstScoreBehaviour.Value, 801, 8))
            throw new Exception("Score mission did not spawn its first source enemy.");
        try
        {
            scored.ConfirmAttributedAiDeath(801, firstPlayer,
                (CoopEnemyKillCredit)99, skillShots, 8);
            throw new Exception("Unknown host kill credit was accepted.");
        }
        catch (ArgumentOutOfRangeException)
        {
            // A malformed credit cannot consume the entity's one death receipt.
        }
        if (scored.ConfirmAttributedAiDeath(801, "unknown", CoopEnemyKillCredit.Player,
                skillShots, 8) ||
            !scored.ConfirmAttributedAiDeath(801, firstPlayer,
                CoopEnemyKillCredit.Player, skillShots, 8) ||
            scored.ConfirmAttributedAiDeath(801, firstPlayer,
                CoopEnemyKillCredit.Player, skillShots, 8) ||
            scored.Score != 10 || scored.ScoreFor(firstPlayer) != 10 ||
            scored.ScoreFor(secondPlayer) != 0)
            throw new Exception("One host-credited player kill must award one source Kill score.");

        int? secondScoreBehaviour = scored.SelectAutomaticBehaviour(16);
        if (secondScoreBehaviour == null ||
            !scored.ConfirmAutomaticSpawn(secondScoreBehaviour.Value, 802, 16) ||
            !scored.ConfirmAttributedAiDeath(802, secondPlayer,
                CoopEnemyKillCredit.AlliedArmy, skillShots, 16) ||
            scored.Score != 15 || scored.ScoreFor(secondPlayer) != 5 ||
            scored.Outcome != MissionOutcome.InProgress)
            throw new Exception("Both allies' host-credited kills must share the Score objective.");

        int? uncreditedBehaviour = scored.SelectAutomaticBehaviour(24);
        if (uncreditedBehaviour == null ||
            !scored.ConfirmAutomaticSpawn(uncreditedBehaviour.Value, 803, 24) ||
            !scored.ConfirmAiDeath(803, 24) || scored.Score != 15)
            throw new Exception("An unattributed AI death must not award mission score.");
        int? laterPlayerBehaviour = scored.SelectAutomaticBehaviour(32);
        if (laterPlayerBehaviour == null ||
            !scored.ConfirmAutomaticSpawn(laterPlayerBehaviour.Value, 804, 32) ||
            !scored.ConfirmAttributedAiDeath(804, firstPlayer,
                CoopEnemyKillCredit.Player, skillShots, 32) ||
            scored.Score != 30)
            throw new Exception("Army and unattributed kills must not consume the player combo.");

        var comboMission = new CoopMissionEngine(catalog, scoreRule.Index, _ => 0);
        comboMission.Admit(firstPlayer);
        comboMission.Admit(secondPlayer);
        comboMission.MarkReady(firstPlayer, 0);
        comboMission.MarkReady(secondPlayer, 0);
        int[] expectedComboTotals = [10, 25, 45, 80];
        for (int index = 0; index < expectedComboTotals.Length; index++)
        {
            ulong killTick = (ulong)(8 + index * 8);
            int? behaviour = comboMission.SelectAutomaticBehaviour(killTick);
            ulong entityId = (ulong)(900 + index);
            if (behaviour == null ||
                !comboMission.ConfirmAutomaticSpawn(behaviour.Value, entityId, killTick) ||
                !comboMission.ConfirmAttributedAiDeath(entityId, firstPlayer,
                    CoopEnemyKillCredit.Player, skillShots, killTick) ||
                comboMission.ConfirmAttributedAiDeath(entityId, firstPlayer,
                    CoopEnemyKillCredit.Player, skillShots, killTick) ||
                comboMission.Score != expectedComboTotals[index])
                throw new Exception("Client's 0.9-second kill combo changed Score points.");
        }

        var alliedCombos = new CoopMissionEngine(catalog, scoreRule.Index, _ => 0);
        alliedCombos.Admit(firstPlayer);
        alliedCombos.Admit(secondPlayer);
        alliedCombos.MarkReady(firstPlayer, 0);
        alliedCombos.MarkReady(secondPlayer, 0);
        string[] creditedPlayers = [firstPlayer, secondPlayer, firstPlayer];
        int[] expectedAlliedTotals = [10, 20, 35];
        for (int index = 0; index < creditedPlayers.Length; index++)
        {
            ulong killTick = (ulong)(8 + index * 8);
            int? behaviour = alliedCombos.SelectAutomaticBehaviour(killTick);
            ulong entityId = (ulong)(920 + index);
            if (behaviour == null ||
                !alliedCombos.ConfirmAutomaticSpawn(behaviour.Value, entityId, killTick) ||
                !alliedCombos.ConfirmAttributedAiDeath(entityId,
                    creditedPlayers[index], CoopEnemyKillCredit.Player,
                    skillShots, killTick) ||
                alliedCombos.Score != expectedAlliedTotals[index])
                throw new Exception("One ally's kill must not advance the other's combo.");
        }

        var expiredCombo = new CoopMissionEngine(catalog, scoreRule.Index, _ => 0);
        expiredCombo.Admit(firstPlayer);
        expiredCombo.Admit(secondPlayer);
        expiredCombo.MarkReady(firstPlayer, 0);
        expiredCombo.MarkReady(secondPlayer, 0);
        int? firstComboBehaviour = expiredCombo.SelectAutomaticBehaviour(8);
        if (firstComboBehaviour == null ||
            !expiredCombo.ConfirmAutomaticSpawn(firstComboBehaviour.Value, 911, 8) ||
            !expiredCombo.ConfirmAttributedAiDeath(911, firstPlayer,
                CoopEnemyKillCredit.Player, skillShots, 8))
            throw new Exception("A combo boundary fixture needs a confirmed first kill.");
        int? nextComboBehaviour = expiredCombo.SelectAutomaticBehaviour(16);
        if (nextComboBehaviour == null ||
            !expiredCombo.ConfirmAutomaticSpawn(nextComboBehaviour.Value, 912, 16) ||
            !expiredCombo.ConfirmAttributedAiDeath(912, firstPlayer,
                CoopEnemyKillCredit.Player, skillShots, 35) ||
            expiredCombo.Score != 20)
            throw new Exception("A kill at the exact combo deadline must start a new streak.");

        MissionRule survivalRule = catalog.Missions.First(rule =>
            rule.MissionType == "SurviveXSeconds");
        var survival = new CoopMissionEngine(catalog, survivalRule.Index);
        survival.Admit(firstPlayer);
        survival.Admit(secondPlayer);
        survival.MarkReady(firstPlayer, 100);
        if (survival.MarkReady(secondPlayer, 99) ||
            !survival.MarkReady(secondPlayer, 100))
            throw new Exception("Ready callbacks cannot move the mission start backward in time.");
        ulong deadline = 100 + (ulong)survivalRule.TimeSeconds *
            MatchManifest.TickRate;
        if (survival.AdvanceTick(deadline - 1) ||
            !survival.AdvanceTick(deadline) ||
            survival.Outcome != MissionOutcome.Succeeded)
            throw new Exception("The shared survival mission succeeds at its source deadline.");

        var abandoned = new CoopMissionEngine(catalog, 0);
        abandoned.Admit(firstPlayer);
        abandoned.Admit(secondPlayer);
        abandoned.MarkReady(firstPlayer, 0);
        abandoned.MarkReady(secondPlayer, 0);
        if (!abandoned.Leave(firstPlayer) ||
            abandoned.Outcome != MissionOutcome.Failed ||
            abandoned.SelectAutomaticBehaviour(8) != null)
            throw new Exception("A participant departure fails and closes an active mission.");
        return 13;
    }

    private static int VerifyCoopAllocationBinding(MatchManifest coop,
        MissionCatalog missions, CoopSpawnPointCatalog spawnPoints,
        CoopNavMeshPathCatalog routes, CoopEnemyCombatCatalog combat,
        ArmyDeploymentCatalog army)
    {
        string firstPlayer = coop.Players[0].PlayerId;
        string secondPlayer = coop.Players[1].PlayerId;
        var cards = new List<string> { "card-a" };
        var first = new BattleAllocationProjection(firstPlayer,
            cards, [], [], [], []) { CardCounts = [1] };
        var second = new BattleAllocationProjection(secondPlayer,
            [], [], [], [], []);

        CoopMatchRuntime NewRuntime() => new(coop, missions,
            spawnPoints, routes, combat);

        var runtime = NewRuntime();
        runtime.ConfigureBattleAllocations([first, second]);
        cards[0] = "card-b";
        BattleAllocationProjection copy = runtime.AllocationFor(firstPlayer);
        if (copy.CardIds.Single() != "card-a")
            throw new Exception("Co-op allocation retained mutable Backend input.");
        copy.CardIds = ["card-c"];
        if (runtime.AllocationFor(firstPlayer).CardIds.Single() != "card-a")
            throw new Exception("Co-op allocation leaked mutable lookup output.");

        void RejectRows(BattleAllocationProjection[] rows)
        {
            try
            {
                NewRuntime().ConfigureBattleAllocations(rows);
                throw new Exception("Invalid co-op allocation was accepted.");
            }
            catch (InvalidDataException)
            {
            }
        }
        RejectRows([first]);
        RejectRows([first, first]);
        RejectRows([first, new BattleAllocationProjection("outsider",
            [], [], [], [], [])]);

        runtime.Admit(firstPlayer);
        try
        {
            runtime.ConfigureBattleAllocations([first, second]);
            throw new Exception("Co-op allocation was rebound after admission.");
        }
        catch (InvalidOperationException)
        {
        }
        var admittedWithoutAllocation = NewRuntime();
        admittedWithoutAllocation.Admit(firstPlayer);
        try
        {
            admittedWithoutAllocation.ConfigureBattleAllocations([first, second]);
            throw new Exception("Co-op allocation was added after admission.");
        }
        catch (InvalidOperationException)
        {
        }

        MatchManifest signedStages = coop with
        {
            Players = coop.Players.Select(player => player with
            {
                EquippedArmyUnitIds = [army.Families[0].UnitId],
                ArmyNormalUpgradeIndexes = [2],
                ArmySpecialUpgradeIndexes = [-1],
                ArmyEliteUpgradeIndexes = [-1]
            }).ToArray()
        };
        MatchManifest.Validate(signedStages);
        var stageRuntime = new CoopMatchRuntime(signedStages, missions,
            spawnPoints, routes, combat);
        var wrongStage = new BattleAllocationProjection(firstPlayer,
            [], [], [3], [-1], [-1]);
        var correctStage = new BattleAllocationProjection(secondPlayer,
            [], [], [2], [-1], [-1]);
        try
        {
            stageRuntime.ConfigureBattleAllocations([wrongStage, correctStage]);
            throw new Exception("Backend stage replaced a signed co-op army stage.");
        }
        catch (InvalidDataException)
        {
        }
        stageRuntime.ConfigureBattleAllocations([
            new BattleAllocationProjection(firstPlayer, [], [], [2], [-1], [-1]),
            correctStage
        ]);
        if (stageRuntime.AllocationFor(firstPlayer).NormalUpgradeIndexes.Single() != 2)
            throw new Exception("Signed co-op army stage was not retained.");
        return 9;
    }

    private static void VerifyCoopCornerUnityPose(
        string directory, MissionCatalog missions,
        BattleCombatContent content)
    {
        string path = Path.Combine(directory,
            "coop-corner-idle-unity-reference.json");
        byte[] source = File.ReadAllBytes(path);
        string digest = Convert.ToHexStringLower(SHA256.HashData(source));
        if (digest !=
            "3fe549e9239407aef66c72652d8722505555101d9084192db5c096794056a4c1")
            throw new Exception("Unity corner pose reference changed.");

        using JsonDocument document = JsonDocument.Parse(source);
        JsonElement reference = document.RootElement;
        if (reference.GetProperty("version").GetInt32() != 1 ||
            reference.GetProperty("client").GetString() != "1.4.0" ||
            reference.GetProperty("prefab").GetString() !=
                "Assets/GameObject/enemy.prefab" ||
            reference.GetProperty("prefabSha256").GetString() !=
                "64b4db85d1c9a0bd46a690a86102a22f66feeab8d4157a4c87824ac3d5dbeb54" ||
            reference.GetProperty("scene").GetString() !=
                missions.MapForMission(0).Scene ||
            reference.GetProperty("sceneSha256").GetString() !=
                missions.MapForMission(0).SceneSha256 ||
            reference.GetProperty("pointComponentFileId").GetInt32() != 1698)
            throw new Exception("Unity corner pose lost source identity.");

        static Vector3 Vector(JsonElement values) => new(
            values[0].GetSingle(), values[1].GetSingle(),
            values[2].GetSingle());
        static Quaternion Rotation(JsonElement values) => new(
            values[0].GetSingle(), values[1].GetSingle(),
            values[2].GetSingle(), values[3].GetSingle());
        Vector3 position = Vector(reference.GetProperty("position"));
        Quaternion rotation = Rotation(reference.GetProperty("rotation"));
        foreach (JsonElement sample in reference.GetProperty("samples")
            .EnumerateArray())
        {
            int afterArrivalTicks = sample.GetProperty(
                "afterArrivalTicks").GetInt32();
            IReadOnlyList<PlayerHitbox> placed = content.EnemyPoses.Place(
                "idle_1", position, rotation,
                afterArrivalTicks / (float)MatchManifest.TickRate);
            JsonElement[] expectedParts = sample.GetProperty("parts")
                .EnumerateArray().ToArray();
            if (placed.Count != expectedParts.Length)
                throw new Exception("Unity corner part count changed.");
            for (int index = 0; index < expectedParts.Length; index++)
            {
                JsonElement expected = expectedParts[index];
                string pathOfPart = expected.GetProperty("path").GetString()!;
                PlayerHitbox part = placed[index];
                Vector3 expectedCenter = Vector(expected.GetProperty("center"));
                Quaternion expectedRotation = Rotation(
                    expected.GetProperty("rotation"));
                if (part.SourcePath != pathOfPart ||
                    Vector3.Distance(part.Center, expectedCenter) > 0.0002f ||
                    1 - Math.Abs(Quaternion.Dot(part.Rotation,
                        expectedRotation)) > 0.00002f)
                    throw new Exception(
                        "Host corner idle collider differs from Unity placement.");
            }
        }
        Quaternion turnTarget = Rotation(reference.GetProperty(
            "turnTarget"));
        JsonElement[] turnSamples = reference.GetProperty("turnSamples")
            .EnumerateArray().ToArray();
        if (turnSamples.Length != 10)
            throw new Exception("Unity corner turn lost a fixed tick.");
        for (int turnTick = 0; turnTick <= 9; turnTick++)
        {
            JsonElement sample = turnSamples[turnTick];
            float progress = turnTick / 9f;
            float eased = progress - MathF.Sin(progress * 2f * MathF.PI) /
                (2f * MathF.PI);
            Quaternion expected = Quaternion.Slerp(rotation, turnTarget,
                eased);
            Quaternion actual = Rotation(sample.GetProperty("rotation"));
            if (sample.GetProperty("tick").GetInt32() != turnTick ||
                1 - Math.Abs(Quaternion.Dot(expected, actual)) > 0.00002f)
                throw new Exception("Host corner turn differs from Unity NGUI.");
        }
        string lookClip = reference.GetProperty("lookClip").GetString()!;
        if (lookClip != "player_look_right3")
            throw new Exception("Unity corner look clip lost its source side.");
        foreach (JsonElement sample in reference.GetProperty(
            "uncoverSamples").EnumerateArray())
        {
            int sampleTick = sample.GetProperty("tick").GetInt32();
            Quaternion rootFacing = Rotation(turnSamples[Math.Min(
                sampleTick, 9)]
                .GetProperty("rotation"));
            IReadOnlyList<PlayerHitbox> placed = content.EnemyPoses.Place(
                lookClip, position, rootFacing,
                sampleTick / (float)MatchManifest.TickRate);
            JsonElement[] parts = sample.GetProperty("parts")
                .EnumerateArray().ToArray();
            if (parts.Length != 3 || placed.Count != parts.Length)
                throw new Exception("Unity corner uncover lost collider parts.");
            for (int index = 0; index < parts.Length; index++)
            {
                PlayerHitbox part = placed[index];
                Vector3 expectedCenter = Vector(parts[index].GetProperty(
                    "center"));
                Quaternion expectedRotation = Rotation(parts[index]
                    .GetProperty("rotation"));
                if (part.SourcePath != parts[index].GetProperty("path")
                        .GetString() ||
                    Vector3.Distance(part.Center, expectedCenter) > 0.0002f ||
                    1 - Math.Abs(Quaternion.Dot(part.Rotation,
                        expectedRotation)) > 0.00002f)
                    throw new Exception(
                        "Host corner uncover collider differs from Unity.");
            }
        }
        string fireClip = reference.GetProperty("fireClip").GetString()!;
        if (fireClip != "player_fire_right3")
            throw new Exception("Unity corner fire clip lost its source side.");
        foreach (JsonElement sample in reference.GetProperty("fireSamples")
            .EnumerateArray())
        {
            int sampleTick = sample.GetProperty("tick").GetInt32();
            float seconds = sampleTick / (float)MatchManifest.TickRate -
                content.EnemyPoses.Clip(lookClip).Length;
            if (Math.Abs(seconds - sample.GetProperty("fireSeconds")
                    .GetSingle()) > 0.00001f)
                throw new Exception("Unity corner fire start time changed.");
            // The source clip exceeds fifteen fixed ticks by less than a
            // microsecond. Sample the nearest exported 30 Hz frame.
            float frameSeconds = (sampleTick - 15) /
                (float)MatchManifest.TickRate;
            IReadOnlyList<PlayerHitbox> placed = content.EnemyPoses.Place(
                fireClip, position, turnTarget, frameSeconds);
            JsonElement[] parts = sample.GetProperty("parts")
                .EnumerateArray().ToArray();
            if (parts.Length != 3 || placed.Count != parts.Length)
                throw new Exception("Unity corner fire lost collider parts.");
            for (int index = 0; index < parts.Length; index++)
            {
                PlayerHitbox part = placed[index];
                Vector3 expectedCenter = Vector(parts[index].GetProperty(
                    "center"));
                Quaternion expectedRotation = Rotation(parts[index]
                    .GetProperty("rotation"));
                if (part.SourcePath != parts[index].GetProperty("path")
                        .GetString() ||
                    Vector3.Distance(part.Center, expectedCenter) > 0.0002f ||
                    1 - Math.Abs(Quaternion.Dot(part.Rotation,
                        expectedRotation)) > 0.00002f)
                    throw new Exception(
                        $"Host corner fire collider differs from Unity at " +
                        $"tick {sampleTick}, part {index}: " +
                        $"{part.Center} versus {expectedCenter}.");
            }
        }
        string coverBackClip = reference.GetProperty("coverBackClip")
            .GetString()!;
        if (coverBackClip != "player_right_coverBack3")
            throw new Exception("Unity corner cover return lost its source side.");
        foreach (JsonElement sample in reference.GetProperty(
            "coverBackSamples").EnumerateArray())
        {
            int sampleTick = sample.GetProperty("tick").GetInt32();
            IReadOnlyList<PlayerHitbox> placed = content.EnemyPoses.Place(
                coverBackClip, position, turnTarget,
                (sampleTick - 22) / (float)MatchManifest.TickRate);
            JsonElement[] parts = sample.GetProperty("parts")
                .EnumerateArray().ToArray();
            if (parts.Length != 3 || placed.Count != parts.Length)
                throw new Exception("Unity corner cover return lost collider parts.");
            for (int index = 0; index < parts.Length; index++)
            {
                PlayerHitbox part = placed[index];
                Vector3 expectedCenter = Vector(parts[index].GetProperty(
                    "center"));
                Quaternion expectedRotation = Rotation(parts[index]
                    .GetProperty("rotation"));
                if (part.SourcePath != parts[index].GetProperty("path")
                        .GetString() ||
                    Vector3.Distance(part.Center, expectedCenter) > 0.0002f ||
                    1 - Math.Abs(Quaternion.Dot(part.Rotation,
                        expectedRotation)) > 0.00002f)
                    throw new Exception(
                        "Host corner cover-back collider differs from Unity.");
            }
        }
    }

    private static void VerifyCoopCornerQueue(string directory,
        EnemyPoseCatalog poses, CoopCornerQueuePoseCatalog queue)
    {
        string path = Path.Combine(directory,
            "coop-corner-queue-unity-reference.json");
        byte[] source = File.ReadAllBytes(path);
        string digest = Convert.ToHexStringLower(SHA256.HashData(source));
        if (digest !=
            "2b5701f1973edcf465295ea55e84cfe8aa4783b8641b9a670b48d95ad59d42c3")
            throw new Exception("Unity corner queue reference changed.");

        using JsonDocument document = JsonDocument.Parse(source);
        JsonElement reference = document.RootElement;
        if (reference.GetProperty("version").GetInt32() != 1 ||
            reference.GetProperty("client").GetString() != "1.4.0" ||
            reference.GetProperty("unity").GetString() != "2018.3.0f2" ||
            reference.GetProperty("prefab").GetString() !=
                "Assets/GameObject/enemy.prefab" ||
            reference.GetProperty("prefabSha256").GetString() !=
                poses.SourceSha256 ||
            reference.GetProperty("captureRate").GetInt32() !=
                MatchManifest.TickRate)
            throw new Exception("Unity corner queue lost source identity.");

        string[] coverClips =
            ["player_right_coverBack3", "player_left_coverBack3"];
        int[] firstBlendedTicks = [6, 8];
        int[] firstIdleTicks = [14, 16];
        JsonElement[] scenarios = reference.GetProperty("scenarios")
            .EnumerateArray().ToArray();
        if (scenarios.Length != coverClips.Length)
            throw new Exception("Unity corner queue lost a cover side.");
        for (int side = 0; side < scenarios.Length; side++)
        {
            JsonElement scenario = scenarios[side];
            string coverClip = coverClips[side];
            if (scenario.GetProperty("coverClip").GetString() != coverClip ||
                scenario.GetProperty("idleClip").GetString() != "idle_1")
                throw new Exception("Unity corner queue changed clips.");
            JsonElement[] samples = scenario.GetProperty("samples")
                .EnumerateArray().ToArray();
            if (samples.Length != 31)
                throw new Exception("Unity corner queue lost fixed frames.");
            for (int frame = 0; frame < samples.Length; frame++)
            {
                JsonElement sample = samples[frame];
                if (Math.Abs(sample.GetProperty("seconds").GetSingle() -
                        frame / (float)MatchManifest.TickRate) > 0.00001f)
                    throw new Exception("Unity corner queue changed its clock.");
                JsonElement[] parts = sample.GetProperty("parts")
                    .EnumerateArray().ToArray();
                if (parts.Length != 3)
                    throw new Exception("Unity corner queue lost colliders.");
                for (int partIndex = 0; partIndex < parts.Length; partIndex++)
                {
                    JsonElement part = parts[partIndex];
                    string expectedPath = poses.Clip(coverClip)
                        .Frames[0].Parts[partIndex].SourcePath;
                    JsonElement center = part.GetProperty("center");
                    JsonElement rotation = part.GetProperty("rotation");
                    if (part.GetProperty("path").GetString() != expectedPath ||
                        center.GetArrayLength() != 3 ||
                        rotation.GetArrayLength() != 4 ||
                        center.EnumerateArray().Any(value =>
                            !float.IsFinite(value.GetSingle())) ||
                        rotation.EnumerateArray().Any(value =>
                            !float.IsFinite(value.GetSingle())))
                        throw new Exception(
                            "Unity corner queue contains invalid collider data.");
                }
            }
            Vector3 rootPosition = new(2, 3, -4);
            Quaternion rootRotation = Quaternion.CreateFromAxisAngle(
                Vector3.UnitY, 0.75f);
            foreach (int frame in new[] { 0, 4, 6, 14, 30 })
            {
                IReadOnlyList<PlayerHitbox> placed = queue.Place(
                    coverClip, frame, rootPosition, rootRotation,
                    "coop/audit/");
                JsonElement[] sourceParts = samples[frame]
                    .GetProperty("parts").EnumerateArray().ToArray();
                for (int index = 0; index < sourceParts.Length; index++)
                {
                    JsonElement center = sourceParts[index]
                        .GetProperty("center");
                    JsonElement rotation = sourceParts[index]
                        .GetProperty("rotation");
                    Vector3 localCenter = new(center[0].GetSingle(),
                        center[1].GetSingle(), center[2].GetSingle());
                    Quaternion localRotation = new(
                        rotation[0].GetSingle(), rotation[1].GetSingle(),
                        rotation[2].GetSingle(), rotation[3].GetSingle());
                    Vector3 expectedCenter = rootPosition +
                        Vector3.Transform(localCenter, rootRotation);
                    Quaternion expectedRotation = Quaternion.Normalize(
                        rootRotation * localRotation);
                    if (placed[index].SourcePath != "coop/audit/" +
                            sourceParts[index].GetProperty("path")
                                .GetString() ||
                        Vector3.Distance(placed[index].Center,
                            expectedCenter) > 0.0002f ||
                        1 - Math.Abs(Quaternion.Dot(placed[index].Rotation,
                            expectedRotation)) > 0.00002f)
                        throw new Exception(
                            "Host queued corner collider differs from Unity.");
                }
            }
            float idleSeconds = samples[30].GetProperty("states")[0]
                .GetProperty("time").GetSingle();
            IReadOnlyList<PlayerHitbox> queuedAtOneSecond = queue.Place(
                coverClip, 30, rootPosition, rootRotation);
            IReadOnlyList<PlayerHitbox> loopingIdle = poses.Place(
                "idle_1", rootPosition, rootRotation, idleSeconds);
            for (int index = 0; index < queuedAtOneSecond.Count; index++)
            {
                if (Vector3.Distance(queuedAtOneSecond[index].Center,
                        loopingIdle[index].Center) > 0.0002f ||
                    1 - Math.Abs(Quaternion.Dot(
                        queuedAtOneSecond[index].Rotation,
                        loopingIdle[index].Rotation)) > 0.00002f)
                    throw new Exception(
                        "Unity corner queue does not join the looping idle rig.");
            }
            IReadOnlyList<PlayerHitbox> continuedIdle = queue.Place(
                coverClip, 31, rootPosition, rootRotation);
            IReadOnlyList<PlayerHitbox> expectedNextIdle = poses.Place(
                "idle_1", rootPosition, rootRotation,
                idleSeconds + 1f / MatchManifest.TickRate);
            for (int index = 0; index < continuedIdle.Count; index++)
            {
                if (Vector3.Distance(continuedIdle[index].Center,
                        expectedNextIdle[index].Center) > 0.0002f ||
                    1 - Math.Abs(Quaternion.Dot(
                        continuedIdle[index].Rotation,
                        expectedNextIdle[index].Rotation)) > 0.00002f)
                    throw new Exception(
                        "Co-op corner looping idle lost its queue clock.");
            }
            JsonElement[] blended = samples[firstBlendedTicks[side]]
                .GetProperty("states").EnumerateArray().ToArray();
            JsonElement[] idle = samples[firstIdleTicks[side]]
                .GetProperty("states").EnumerateArray().ToArray();
            if (blended.Length != 2 || idle.Length != 1 ||
                idle[0].GetProperty("name").GetString() !=
                    "idle_1 - Queued Clone" ||
                idle[0].GetProperty("weight").GetSingle() != 1)
                throw new Exception("Unity corner queue changed its fade.");
        }
    }

    private static int VerifyCoopAllocation(
        string directory, MissionCatalog catalog, BattleCombatContent content)
    {
        VerifyCoopCornerUnityPose(directory, catalog, content);
        CoopObstacleVolleyObservationTests.Run(directory, content);
        CoopObstaclePoseCatalogTests.Run(directory, content);
        CoopObstaclePoseCatalogTests.Run(directory, content, "coop-obstacle-volley-neutral-look-reference.json");
        CoopGameplayQueryObservationTests.Run(directory, content);
        CoopGameplayQueryObservationTests.RunPreparation(directory, content);
        CoopShotCallbackClockTests.Run(directory, content);
        CoopShotCallbackMuzzleTests.Run(directory, content);
        CoopCornerCallbackTests.Run(directory, content);
        CoopObstacleProofIntegrityTests.Run(directory, content);
        CoopObstacleCrawlReturnClockTests.Run();
        CoopObstaclePreparationStartTests.Run(directory, content.EnemyPoses);
        CoopObservedObstaclePoseCatalogTests.Run(directory, content);
        CoopObstacleTurnObservationTests.Run(directory, content);
        CoopShotRootTweenTests.Run(directory);
        CoopShotRootCompositionTests.Run(directory);
        CoopInfantryFacingEstimateTests.Run(directory);
        VerifyCoopCornerQueue(directory, content.EnemyPoses,
            content.CoopCornerQueuePoses);
        CoopCornerReturnAnimationTests.Run(directory, content);
        CoopCornerPreparationPlanTests.Run(directory);
        ArmyDeploymentCatalog army = content.Army;
        CoopAssaulterWeaponCatalog rifle = content.CoopAssaulterWeapon;
        if (rifle.WeaponPrefabGuid !=
                "d03f97fa25701ab42ab60f1fa86421ce" ||
            rifle.BulletPrefabGuid !=
                "855689762fa6e774aaee190652b08c6f" ||
            rifle.MuzzleTransformFileId != 455190 ||
            Vector3.Distance(rifle.MuzzleRestPosition,
                new Vector3(0, 0.045f, 0.17f)) > 0.0001f ||
            rifle.ShotOffset != Vector3.Zero ||
            rifle.RealBulletSpeed != 5f ||
            rifle.FakeBulletSpeed != 7.5f ||
            rifle.CollisionCheckDistance != 0.35f ||
            rifle.CriticalProbability != 0f ||
            rifle.CriticalAmount != 2f ||
            rifle.RealBulletFlight() !=
                new BulletFlightDefinition(5f, 0.35f, false) ||
            rifle.CadenceSeconds != 0.35f ||
            rifle.NextRoundEligibleTick(100) != 111)
            throw new Exception("Co-op Assaulter rifle lost its source cadence or binding.");
        CoopEnemyMuzzleCatalog muzzles = content.CoopEnemyMuzzles;
        CoopMuzzlePose shotStart = muzzles.Place("rifle_shot",
            Vector3.Zero, Quaternion.Identity, 0);
        Vector3 expectedStart = new(-0.138744667f, 0.1866135f, 0.180271789f);
        if (Vector3.Distance(shotStart.Position, expectedStart) > 0.00001f)
            throw new Exception("Co-op Assaulter muzzle lost its Unity shot pose.");
        Vector3 placement = new(4, 2, -3);
        Quaternion facing = Quaternion.CreateFromAxisAngle(Vector3.UnitY,
            MathF.PI / 2);
        CoopMuzzlePose worldMuzzle = muzzles.Place("rifle_shot",
            placement, facing, 0);
        Vector3 expectedWorld = placement + Vector3.Transform(expectedStart, facing);
        if (Vector3.Distance(worldMuzzle.Position, expectedWorld) > 0.00001f ||
            Math.Abs(worldMuzzle.Rotation.LengthSquared() - 1) > 0.0002f)
            throw new Exception("Co-op Assaulter muzzle placement changed.");
        try
        {
            muzzles.Place("rifle_shot", Vector3.Zero,
                Quaternion.Identity, float.NaN);
            throw new Exception("Invalid muzzle time was accepted.");
        }
        catch (InvalidDataException) { }
        CoopAssaulterQueueCatalog queue = content.CoopAssaulterQueue;
        CoopQueuedMuzzleSample? obstacleSample = queue.Sample(
            "stand_up_begin", "rifle_shot_loop", 11);
        CoopQueuedMuzzleSample? rightSample = queue.Sample(
            "player_look_right3", "player_fire_right3", 18);
        CoopQueuedMuzzleSample? leftSample = queue.Sample(
            "player_look_left3", "player_fire_left3", 18);
        if (obstacleSample == null || rightSample == null ||
            leftSample == null ||
            Math.Abs(obstacleSample.FireClipSeconds - 4f / 30) > 0.00001f ||
            Math.Abs(rightSample.FireClipSeconds - 3f / 30) > 0.00001f ||
            Math.Abs(leftSample.FireClipSeconds - 3f / 30) > 0.00001f ||
            Vector3.Distance(obstacleSample.LocalPosition,
                new Vector3(0.0866239f, 0.28705934f, 0.15951629f)) >
                0.00001f ||
            queue.Sample("stand_up_begin", "rifle_shot_loop", 40) != null)
            throw new Exception("Co-op queued muzzle observation changed.");
        try
        {
            muzzles.Place("rifle_shot", Vector3.Zero,
                Quaternion.Zero, 0);
            throw new Exception("Invalid muzzle rotation was accepted.");
        }
        catch (InvalidDataException) { }
        string contentRevision = content.Stats.Revision;
        CoopSpawnPointCatalog spawnPoints = CoopSpawnPointCatalog.Load(
            Path.Combine(directory, "recovered-coop-spawn-points.json"), catalog);
        CoopNavMeshSourceCatalog navMeshSources = CoopNavMeshSourceCatalog.Load(
            Path.Combine(directory, "recovered-coop-navmesh-sources.json"), catalog);
        CoopNavMeshPathCatalog routes = CoopNavMeshPathCatalog.Load(
            Path.Combine(directory, "recovered-coop-navmesh-paths.json"),
            catalog, spawnPoints, navMeshSources);
        CoopCardRowCatalog cardRows = CoopCardRowCatalog.Load(
            Path.Combine(directory, "recovered-coop-card-rows.json"),
            catalog, army, contentRevision);
        ArmyBaseShotStats cardMinimum = cardRows.Shot("ID_UNIT-ASSAULT", 0);
        ArmyBaseShotStats cardMidpoint = cardRows.Shot("ID_UNIT-ASSAULT", 0.5f);
        ArmyBaseShotStats cardMaximum = cardRows.Shot("ID_UNIT-ASSAULT", 1);
        ArmyBaseShotStats missionCard = cardRows.Shot(
            "ID_UNIT-ASSAULT", 14f / 25f);
        if (cardMinimum.MinShootTime != 3f ||
            cardMinimum.MaxShootTime != 5f ||
            cardMaximum.MinShootTime != 2f ||
            cardMaximum.MaxShootTime != 4f ||
            cardMidpoint.MinShootTime != 2.5f ||
            cardMidpoint.MaxShootTime != 4.5f ||
            cardMidpoint.FireBatchSizeMin != 2 ||
            cardMidpoint.FireBatchSizeMax != 3 ||
            MathF.Abs(missionCard.MinShootTime - 2.44f) > 0.00001f ||
            MathF.Abs(missionCard.MaxShootTime - 4.44f) > 0.00001f)
            throw new Exception("Co-op card Assaulter shot timing differs from CARDS_MIN/MAX.");
        string alteredCardPath = Path.Combine(Path.GetTempPath(),
            $"war-coop-cards-{Guid.NewGuid():N}.json");
        try
        {
            JsonNode altered = JsonNode.Parse(File.ReadAllText(
                Path.Combine(directory, "recovered-coop-card-rows.json")))!;
            altered["rows"]![0]!["minimumIndex"] = 0;
            File.WriteAllText(alteredCardPath, altered.ToJsonString());
            try
            {
                _ = CoopCardRowCatalog.Load(
                    alteredCardPath, catalog, army, contentRevision);
                throw new Exception("Altered card row indexes bypassed source revision pinning.");
            }
            catch (InvalidDataException)
            {
            }
        }
        finally
        {
            File.Delete(alteredCardPath);
        }
        var enemyCombat = new CoopEnemyCombatCatalog(catalog, army, cardRows);
        if (enemyCombat.ShieldHitProbability("Assaulter") != 0f)
            throw new Exception("Assaulter shield preference differs from ArmyUpgrades.");
        CoopEnemyPointCatalog enemyPointCatalog = CoopEnemyPointCatalog.Load(
            Path.Combine(directory, "recovered-coop-enemy-points.json"),
            catalog, spawnPoints);
        CoopEnemyPointMaskCatalog enemyPointMasks = CoopEnemyPointMaskCatalog.Load(
            Path.Combine(directory, "recovered-coop-enemy-point-masks.json"),
            army);
        CoopHelicopterDestinationTests.Run(enemyPointCatalog.MapForMission(catalog, 0), enemyPointMasks, enemyCombat,
            new CoopAiSpawnSelector(catalog, spawnPoints, 0));
        CoopRusherPointCatalog rusherPointCatalog = CoopRusherPointCatalog.Load(
            Path.Combine(directory, "recovered-coop-rusher-points.json"),
            catalog, spawnPoints);
        ArmyBaseCombatStats sniperStart = enemyCombat.CardStats("Sniper", 0);
        ArmyBaseCombatStats sniperEnd = enemyCombat.CardStats("Sniper", 1);
        ArmyBaseCombatStats grenadeStart = enemyCombat.CardStats("Grenadier", 0);
        ArmyBaseCombatStats grenadeEnd = enemyCombat.CardStats("Grenadier", 1);
        ArmyBaseCombatStats grenadeMid = enemyCombat.CardStats("Grenadier", .5f);
        if (sniperStart != sniperEnd ||
            MathF.Abs(grenadeMid.Health -
                (grenadeStart.Health + grenadeEnd.Health) / 2f) > .001f ||
            grenadeStart.Health == grenadeEnd.Health)
            throw new Exception("Card sheets must preserve interpolation and row-zero fallback.");
        ArmyBaseCombatStats ordinary = enemyCombat.OrdinaryStats("Assaulter", 0);
        ArmyBaseCombatStats heroic = enemyCombat.OrdinaryStats("Assaulter", 0, heroic: true);
        if (MathF.Abs(ordinary.Health - 140f * 2.34f) > .0001f ||
            MathF.Abs(ordinary.Damage - 29.6f * 1.6f) > .0001f ||
            MathF.Abs(heroic.Health - 140f * 3.37f) > .0001f)
            throw new Exception("Recovered co-op scales must multiply the selected upgrade row.");
        MatchManifest duel = MatchManifest.Read(
            Path.Combine(directory, "local-rifle-match-template.json"));
        MissionMapRule sourceMap = catalog.MapForMission(0);
        if (CoopMissionScorePolicy.Calculate(catalog.Get(0), 1f, 0f) !=
                new CoopMissionSuccessScore(117, 3) ||
            CoopMissionScorePolicy.Calculate(catalog.Get(1), 1f, 0f) !=
                new CoopMissionSuccessScore(117, 3) ||
            CoopMissionScorePolicy.Calculate(catalog.Get(3), 0.5f, 1f) !=
                new CoopMissionSuccessScore(263, 2) ||
            CoopMissionScorePolicy.Calculate(catalog.Get(4), 1f, 1f) !=
                new CoopMissionSuccessScore(250, 3))
            throw new Exception("Recovered mission success score or stars changed.");
        try
        {
            _ = CoopMissionScorePolicy.Calculate(catalog.Get(4),
                float.NaN, 1f);
            throw new Exception("Invalid co-op player health entered score authority.");
        }
        catch (InvalidDataException)
        {
        }
        CoopShieldStateCatalog shieldStates = CoopShieldStateCatalog.Load(
            Path.Combine(directory, "recovered-coop-shield-states.json"), catalog);
        CoopBotRuleCatalog bossRules = CoopBotRuleCatalog.Load(Path.Combine(
            directory, "recovered-coop-bot-rules.json"), catalog);
        if (shieldStates.ForMission(4).Player.Count != 0 ||
            shieldStates.ForMission(14).Player.Count != 4 ||
            shieldStates.ForMission(14).Player[0].MaxHealthRatio != 0.8f ||
            shieldStates.ForMission(14).Player[0].Regenerate ||
            shieldStates.ForMission(14).Bot[0].MaxHealthRatio != 0.6f)
            throw new Exception("Boss mission shield overrides differ from MainScene.");
        MatchManifest coop = duel with
        {
            Mode = MatchManifest.CoopMissionMode,
            MissionIndex = 0,
            CatalogRevision = MissionCatalog.SourceRevision,
            MapId = sourceMap.Scene,
            MapRevision = sourceMap.SceneSha256,
            DurationSeconds = catalog.Get(0).TimeSeconds,
            Players = duel.Players.Select(player => player with { Fraction = 2 }).ToArray()
        };
        MatchManifest.Validate(coop);
        CoopPlayerWeaponCatalog playerWeapons =
            CoopPlayerWeaponCatalog.Bind(coop, content);
        var weaponRuntime = new CoopMatchRuntime(coop, catalog,
            spawnPoints, routes, enemyCombat,
            playerWeaponContent: content);
        CoopPlayerWeapon firstSourceWeapon = playerWeapons.ForPlayer(
            coop.Players[0].PlayerId).Single();
        CoopWeaponAtomicityTests.Run(firstSourceWeapon);
        RifleTimelineCopyTests.Run(content.Poses);
        var weaponState = new CoopPlayerWeaponState([firstSourceWeapon], 0);
        CoopWeaponReadiness initialAmmo = weaponState.Readiness(firstSourceWeapon.Slot);
        ulong cadenceTicks = (ulong)Math.Ceiling(
            firstSourceWeapon.Weapon.CadenceSeconds * MatchManifest.TickRate);
        ulong reloadTicks = (ulong)Math.Ceiling(
            firstSourceWeapon.Weapon.ReloadSeconds * MatchManifest.TickRate);
        if (initialAmmo.Clip != firstSourceWeapon.Weapon.ClipSize ||
            initialAmmo.Reserve != firstSourceWeapon.Weapon.ReserveAmmo ||
            !weaponState.ConfirmHostShot(firstSourceWeapon.Slot, 0) ||
            weaponState.ConfirmHostShot(firstSourceWeapon.Slot, 0) ||
            weaponState.Readiness(firstSourceWeapon.Slot).NextFireTick != cadenceTicks ||
            !weaponState.TryStartReload(firstSourceWeapon.Slot, 0) ||
            weaponState.Readiness(firstSourceWeapon.Slot).ReloadEndTick != reloadTicks)
            throw new Exception("Co-op weapon shot/cadence/reload changed source ammo.");
        weaponState.Advance(reloadTicks - 1);
        if (weaponState.Readiness(firstSourceWeapon.Slot).Clip !=
                firstSourceWeapon.Weapon.ClipSize - 1 ||
            !weaponState.Advance(reloadTicks) ||
            weaponState.Readiness(firstSourceWeapon.Slot).Clip !=
                firstSourceWeapon.Weapon.ClipSize ||
            weaponState.Readiness(firstSourceWeapon.Slot).Reserve !=
                firstSourceWeapon.Weapon.ReserveAmmo - 1)
            throw new Exception("Co-op reload must transfer one round at its deadline.");
        var emptyClip = new CoopPlayerWeaponState([firstSourceWeapon], 0);
        for (int shot = 0; shot < firstSourceWeapon.Weapon.ClipSize; shot++)
        {
            ulong shotTick = (ulong)shot * cadenceTicks;
            emptyClip.Advance(shotTick);
            if (!emptyClip.ConfirmHostShot(firstSourceWeapon.Slot, shotTick))
                throw new Exception("Source co-op rifle rejected an in-cadence host shot.");
        }
        ulong lastShotTick =
            (ulong)(firstSourceWeapon.Weapon.ClipSize - 1) * cadenceTicks;
        CoopWeaponReadiness exhausted = emptyClip.Readiness(firstSourceWeapon.Slot);
        if (exhausted.Clip != 0 ||
            exhausted.ReloadEndTick != lastShotTick + reloadTicks ||
            emptyClip.ConfirmHostShot(firstSourceWeapon.Slot, lastShotTick))
            throw new Exception("An empty co-op clip must start one automatic reload.");
        BattlePlayerState initialWeaponView = weaponRuntime.Snapshot().Players.Single(
            player => player.PlayerId == coop.Players[0].PlayerId);
        if (playerWeapons.ForPlayer(coop.Players[0].PlayerId).Single().Weapon !=
                coop.Players[0].Weapon ||
            playerWeapons.ForPlayer(coop.Players[1].PlayerId).Single().UpgradeIndex != 0 ||
            weaponRuntime.PlayerWeapons?.ForPlayer(
                coop.Players[0].PlayerId).Single().Weapon != coop.Players[0].Weapon ||
            initialWeaponView.ClipAmmo != coop.Players[0].Weapon.ClipSize ||
            initialWeaponView.ReserveAmmo != coop.Players[0].Weapon.ReserveAmmo ||
            initialWeaponView.CombatEnabled || initialWeaponView.ShotsFired != 0)
            throw new Exception("Co-op weapons did not bind the signed source stages.");
        weaponRuntime.Admit(coop.Players[0].PlayerId);
        weaponRuntime.Admit(coop.Players[1].PlayerId);
        var initialReady = new MatchCommand { CommandId = 1,
            Ready = new ReadyCommand { ManifestHash = weaponRuntime.ManifestHash } };
        weaponRuntime.Command(coop.Players[0].PlayerId, initialReady);
        weaponRuntime.Command(coop.Players[1].PlayerId, initialReady);
        if (weaponRuntime.Command(coop.Players[0].PlayerId,
                new MatchCommand { CommandId = 2,
                    Reload = new ReloadCommand() }).Code != "reload-unavailable")
            throw new Exception("Full co-op clip must not start a reload.");

        const string alternateRifle = "Google2u.AssaultRifle_Famas";
        WeaponManifest alternateWeapon = content.CreateCoopWeaponManifest(
            alternateRifle, 0);
        int alternateIndex = content.AllWeaponBindings.Get(
            alternateRifle).InventoryIndex;
        int firstWeaponIndex = content.AllWeaponBindings.Get(
            coop.Players[0].Weapon.SourceId).InventoryIndex;
        MatchManifest twoWeapons = coop with
        {
            Players = coop.Players.Select((player, index) => index == 0
                ? player with { WeaponSlots =
                [
                    new WeaponSlotManifest(0, firstWeaponIndex,
                        player.Weapon, player.WeaponUpgrade!.Value),
                    new WeaponSlotManifest(1, alternateIndex,
                        alternateWeapon, 0)
                ] }
                : player).ToArray()
        };
        CoopPlayerWeaponCatalog twoWeaponCatalog =
            CoopPlayerWeaponCatalog.Bind(twoWeapons, content);
        var selectedAmmo = new CoopPlayerWeaponState(
            twoWeaponCatalog.ForPlayer(twoWeapons.Players[0].PlayerId), 0);
        if (selectedAmmo.HasFiredAnyShot ||
            selectedAmmo.CheckShot(0, 0) != CoopShotAvailability.Ready ||
            selectedAmmo.CheckShot(1, 0) != CoopShotAvailability.WrongSlot ||
            selectedAmmo.CheckShot(0, 1) != CoopShotAvailability.WrongTick ||
            !selectedAmmo.TrySelectSlot(1, 0) ||
            !selectedAmmo.ConfirmHostShot(1, 0) ||
            selectedAmmo.CheckShot(1, 0) != CoopShotAvailability.Cooldown ||
            !selectedAmmo.TrySelectSlot(0, 0) ||
            !selectedAmmo.HasFiredAnyShot ||
            selectedAmmo.Readiness(0).Clip != coop.Players[0].Weapon.ClipSize ||
            !selectedAmmo.TrySelectSlot(1, 0) ||
            selectedAmmo.Readiness(1).Clip != alternateWeapon.ClipSize - 1)
            throw new Exception("Co-op weapon slots lost independent ammunition.");
        var switchingRuntime = new CoopMatchRuntime(twoWeapons, catalog,
            spawnPoints, routes, enemyCombat, playerWeaponContent: content);
        string switcher = twoWeapons.Players[0].PlayerId;
        string partner = twoWeapons.Players[1].PlayerId;
        switchingRuntime.Admit(switcher);
        switchingRuntime.Admit(partner);
        var switchReady = new MatchCommand { CommandId = 1,
            Ready = new ReadyCommand { ManifestHash = switchingRuntime.ManifestHash } };
        switchingRuntime.Command(switcher, switchReady);
        switchingRuntime.Command(partner, switchReady);
        var selectSecond = new MatchCommand { CommandId = 2,
            SwitchWeapon = new SwitchWeaponCommand { Slot = 1 } };
        if (switchingRuntime.Command(switcher, selectSecond).Code != "weapon-selected" ||
            switchingRuntime.Command(switcher, selectSecond).Code != "weapon-selected" ||
            switchingRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == switcher).ActiveWeaponSlot != 1 ||
            switchingRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == switcher).ClipAmmo != alternateWeapon.ClipSize ||
            switchingRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == switcher).RiflePose is not
                    RiflePoseState initialIdlePose ||
            !RiflePoseProjection.ValidWire(initialIdlePose, 0) ||
            initialIdlePose.Layers.Count != 1 ||
            initialIdlePose.Layers[0].Clip != RiflePoseClip.QbzIdle ||
            switchingRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == partner).ActiveWeaponSlot != 0)
            throw new Exception("Only the signed ally switched to the second source rifle.");
        BattleCombatContent specialPoseContent = BattleCombatContent.Load(
            Path.Combine(directory, "combat-content-manifest.json"),
            minigunManifestPath: Path.Combine(directory,
                "minigun-content-manifest.json"),
            pistolManifestPath: Path.Combine(directory,
                "pistol-content-manifest.json"),
            shotgunManifestPath: Path.Combine(directory,
                "shotgun-content-manifest.json"),
            sniperManifestPath: Path.Combine(directory,
                "sniper-content-manifest.json"),
            bazookaManifestPath: Path.Combine(directory,
                "bazooka-content-manifest.json"),
            grenadeManifestPath: Path.Combine(directory,
                "grenade-content-manifest.json"));
        (string WeaponId, string IdleClip)[] specialIdleWeapons =
        [
            ("Google2u.SniperRifle_MSR", "sniper_idle"),
            ("Google2u.LMG_Minigun", "minigun_idle"),
            ("Google2u.Bazooka_RPG7", "bazooka_idle"),
            ("Google2u.Pistol_Berreta", "pistol_idle"),
            ("Google2u.Shotgun_Benelli", "shotgunner_idle"),
            ("Google2u.AssaultRifle_AKS47U", "shotgunner_idle"),
            ("Google2u.Grenade_FRAG", "grenade_idle"),
            ("Google2u.GrenadeLauncher_M320", "grenadelauncher_idle")
        ];
        foreach ((string weaponId, string idleClip) in specialIdleWeapons)
        {
            WeaponManifest specialWeapon = specialPoseContent
                .CreateCoopWeaponManifest(weaponId, 0);
            int inventoryIndex = specialPoseContent.AllWeaponBindings
                .Get(weaponId).InventoryIndex;
            MatchManifest specialSlots = twoWeapons with
            {
                Players = twoWeapons.Players.Select((player, index) =>
                    index == 0 ? player with
                    {
                        WeaponSlots =
                        [
                            player.WeaponSlots![0],
                            new WeaponSlotManifest(1, inventoryIndex,
                                specialWeapon, 0)
                        ]
                    } : player).ToArray()
            };
            var poseRuntime = new CoopMatchRuntime(specialSlots, catalog,
                spawnPoints, routes, enemyCombat,
                playerWeaponContent: specialPoseContent);
            poseRuntime.Admit(switcher);
            poseRuntime.Admit(partner);
            var ready = new MatchCommand { CommandId = 1,
                Ready = new ReadyCommand
                { ManifestHash = poseRuntime.ManifestHash } };
            poseRuntime.Command(switcher, ready);
            poseRuntime.Command(partner, ready);
            if (poseRuntime.PlaceIdleAlliedCollisionPoses() == null ||
                poseRuntime.Command(switcher, selectSecond).Code !=
                    "weapon-selected")
                throw new Exception($"Co-op {weaponId} switch was rejected.");

            IReadOnlyList<CollisionPlayer>? allies =
                poseRuntime.PlaceIdleAlliedCollisionPoses();
            if (allies?.Count != 2)
                throw new Exception($"Co-op {weaponId} lacks an idle pose.");
            CoopPlayerAnchor coverAnchor = spawnPoints
                .MapForMission(catalog, 0).PlayerPositions.Single(anchor =>
                    anchor.Position == allies[0].Pose.RootPosition);
            PlayerCollisionModel expectedPose = specialPoseContent.Poses
                .SampleBlended(idleClip, 0, true,
                    idleClip, 0, true, 0, Quaternion.Identity)
                .Place(coverAnchor.Position,
                    coverAnchor.SourceRotation!.Value).Collision;
            if (allies[0].Pose.Parts[0].Center !=
                    expectedPose.Parts[0].Center ||
                (poseRuntime.PlaceIdlePlayerMuzzle(switcher) != null) !=
                    weaponId.StartsWith("Google2u.AssaultRifle_",
                        StringComparison.Ordinal))
                throw new Exception($"Co-op {weaponId} reused rifle idle.");
            if (weaponId is "Google2u.Grenade_FRAG" or
                "Google2u.GrenadeLauncher_M320")
            {
                RiflePoseClip expectedWireClip = weaponId ==
                    "Google2u.Grenade_FRAG"
                    ? RiflePoseClip.GrenadeIdle
                    : RiflePoseClip.GrenadeLauncherIdle;
                RiflePoseState? wirePose = poseRuntime.Snapshot().Players
                    .Single(player => player.PlayerId == switcher).RiflePose;
                if (wirePose?.Layers.Count != 1 ||
                    wirePose.Layers[0].Clip != expectedWireClip)
                    throw new Exception($"Co-op {weaponId} lost its idle wire pose.");

                var selectFirst = new MatchCommand { CommandId = 3,
                    SwitchWeapon = new SwitchWeaponCommand { Slot = 0 } };
                var selectGrenadeAgain = new MatchCommand { CommandId = 4,
                    SwitchWeapon = new SwitchWeaponCommand { Slot = 1 } };
                if (poseRuntime.Command(switcher, selectFirst).Code !=
                        "weapon-selected" ||
                    !poseRuntime.ConfirmHostPlayerShot(switcher, 0,
                        new Vector3(100, 0, 100), 0) ||
                    poseRuntime.Command(switcher, selectGrenadeAgain).Code !=
                        "weapon-selected" ||
                    poseRuntime.PlaceIdleAlliedCollisionPoses() != null)
                    throw new Exception($"Co-op {weaponId} bypassed rifle shot settling.");
                poseRuntime.Advance(MatchManifest.TickRate);
                if (poseRuntime.PlaceIdleAlliedCollisionPoses() == null ||
                    poseRuntime.Snapshot().Players.Single(player =>
                        player.PlayerId == switcher).RiflePose?.Layers[0].Clip !=
                            expectedWireClip)
                    throw new Exception($"Co-op {weaponId} failed to settle after a rifle shot.");
            }
        }
        if (switchingRuntime.Command(switcher, new MatchCommand { CommandId = 3,
                SwitchWeapon = new SwitchWeaponCommand { Slot = 7 } }).Code !=
            "weapon-slot-unavailable" ||
            switchingRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == switcher).ActiveWeaponSlot != 1)
            throw new Exception("An unallocated co-op weapon slot became active.");
        BattlePlayerState beforeHostShot = switchingRuntime.Snapshot().Players.Single(
            player => player.PlayerId == switcher);
        CoopPlayerAnchor shotCover = spawnPoints.MapForMission(catalog, 0)
            .PlayerPositions.Single(position =>
                position.Index == beforeHostShot.CoverIndex);
        Vector3 shotOrigin = new(beforeHostShot.PositionX,
            beforeHostShot.PositionY, beforeHostShot.PositionZ);
        Vector3 shotTarget = shotOrigin + Vector3.Transform(Vector3.UnitZ,
            shotCover.SourceRotation!.Value) * 3;
        var unsupportedFire = new MatchCommand { CommandId = 4,
            Fire = new FireCommand { TargetX = 1 } };
        if (switchingRuntime.Command(switcher, unsupportedFire).Code !=
                "coop-command-unavailable" ||
            switchingRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == switcher).ClipAmmo != beforeHostShot.ClipAmmo ||
            switchingRuntime.ConfirmHostPlayerShot("outside", 1,
                shotTarget, 0) ||
            switchingRuntime.ConfirmHostPlayerShot(partner, 1,
                shotTarget, 0) ||
            switchingRuntime.ConfirmHostPlayerShot(switcher, 1,
                new Vector3(float.MaxValue, 0, 0), 0) ||
            switchingRuntime.ConfirmHostPlayerShot(switcher, 1,
                shotOrigin, 0) ||
            !switchingRuntime.ConfirmHostPlayerShot(switcher, 1,
                shotTarget, 0) ||
            switchingRuntime.ConfirmHostPlayerShot(switcher, 1,
                shotTarget, 0) ||
            switchingRuntime.PlaceIdlePlayerMuzzle(switcher) != null ||
            switchingRuntime.PlaceIdleAlliedCollisionPoses() != null ||
            switchingRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == switcher).RiflePose is not
                    RiflePoseState shotPose ||
            !RiflePoseProjection.ValidWire(shotPose, 0) ||
            switchingRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == switcher).ClipAmmo != alternateWeapon.ClipSize - 1)
            throw new Exception("Only a host-created co-op shot may consume ammo.");
        var reloadSecond = new MatchCommand { CommandId = 5,
            Reload = new ReloadCommand() };
        ulong alternateReloadTicks = (ulong)Math.Ceiling(
            alternateWeapon.ReloadSeconds * MatchManifest.TickRate);
        if (switchingRuntime.Command(switcher, reloadSecond).Code != "reloading" ||
            switchingRuntime.Command(switcher, reloadSecond).Code != "reloading" ||
            switchingRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == switcher).ReloadEndTick != alternateReloadTicks)
            throw new Exception("Co-op reload did not start once from host ammo.");
        switchingRuntime.Advance(alternateReloadTicks);
        BattlePlayerState reloadedAlly = switchingRuntime.Snapshot().Players.Single(
            player => player.PlayerId == switcher);
        if (reloadedAlly.ClipAmmo != alternateWeapon.ClipSize ||
            reloadedAlly.ReserveAmmo != alternateWeapon.ReserveAmmo - 1 ||
            reloadedAlly.ReloadEndTick != 0 ||
            switchingRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == partner).ReserveAmmo !=
                twoWeapons.Players[1].Weapon.ReserveAmmo)
            throw new Exception("Co-op reload changed the wrong slot or ally.");
        switchingRuntime.Advance(Math.Max(alternateReloadTicks + 1, 120));
        IReadOnlyList<CollisionPlayer>? postShotAllies =
            switchingRuntime.PlaceIdleAlliedCollisionPoses();
        if (switchingRuntime.PlaceIdlePlayerMuzzle(switcher) == null ||
            postShotAllies?.Count != 2 ||
            postShotAllies[0].PlayerId != switcher ||
            postShotAllies[1].PlayerId != partner ||
            switchingRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == switcher).RiflePose is not
                    RiflePoseState settledPose ||
            !RiflePoseProjection.ValidWire(settledPose,
                switchingRuntime.Snapshot().ServerTick) ||
            settledPose.Layers[0].Clip != RiflePoseClip.QbzIdle)
            throw new Exception(
                "A host-confirmed co-op shot never restored both source collision poses.");
        ulong repeatedShotTick = switchingRuntime.Snapshot().ServerTick;
        if (!switchingRuntime.ConfirmHostPlayerShot(switcher, 1,
                shotTarget, repeatedShotTick))
            throw new Exception("A settled co-op ally could not fire again.");
        switchingRuntime.Advance(repeatedShotTick + 1);
        RiflePoseState? activeShotPose = switchingRuntime.Snapshot()
            .Players.Single(player => player.PlayerId == switcher).RiflePose;
        if (activeShotPose == null ||
            !RiflePoseProjection.ValidWire(activeShotPose,
                repeatedShotTick + 1) ||
            activeShotPose.Layers.Count != 1 ||
            (int)activeShotPose.Layers[0].Clip is not (8 or 11) ||
            switchingRuntime.PlaceIdleAlliedCollisionPoses() != null)
            throw new Exception(
                "A second co-op shot did not publish its host-owned uncover pose.");
        MatchManifest skippedSlot = twoWeapons with
        {
            Players = twoWeapons.Players.Select((player, index) => index == 0
                ? player with { WeaponSlots =
                    [player.WeaponSlots![0],
                        player.WeaponSlots[1] with { Slot = 3 }] }
                : player).ToArray()
        };
        try
        {
            _ = CoopPlayerWeaponCatalog.Bind(skippedSlot, content);
            throw new Exception("Co-op accepted a slot the Client cannot select.");
        }
        catch (InvalidDataException)
        {
        }
        try
        {
            MatchManifest alteredWeapon = coop with
            {
                Players = coop.Players.Select((player, index) => index == 0
                    ? player with { Weapon = player.Weapon with
                        { ClipSize = player.Weapon.ClipSize + 1 } }
                    : player).ToArray()
            };
            _ = CoopPlayerWeaponCatalog.Bind(alteredWeapon, content);
            throw new Exception("Co-op accepted a forged weapon clip size.");
        }
        catch (InvalidDataException)
        {
        }
        int sourceWeaponIndex = content.AllWeaponBindings.Get(
            coop.Players[0].Weapon.SourceId).InventoryIndex;
        try
        {
            MatchManifest alteredIndex = coop with
            {
                Players = coop.Players.Select((player, index) => index == 0
                    ? player with { WeaponSlots =
                        [new WeaponSlotManifest(0, sourceWeaponIndex + 1,
                            player.Weapon, player.WeaponUpgrade!.Value)] }
                    : player).ToArray()
            };
            _ = CoopPlayerWeaponCatalog.Bind(alteredIndex, content);
            throw new Exception("Co-op accepted a forged weapon inventory index.");
        }
        catch (InvalidDataException)
        {
        }
        int allocationBindingAssertions = VerifyCoopAllocationBinding(
            coop, catalog, spawnPoints, routes, enemyCombat, army);
        MatchManifest shieldAllocation = coop with
        {
            SceneMasterPlayerId = coop.Players[1].PlayerId,
            Players = coop.Players.Select((player, index) => player with
            {
                ShieldLevel = index + 2,
                PlayerLevel = index + 2
            }).ToArray()
        };
        MatchManifest.Validate(shieldAllocation);
        if (CoopShieldRankResolver.AlliedRank(shieldAllocation) != 3 ||
            CoopShieldRankResolver.AlliedRank(shieldAllocation with
            {
                SceneMasterPlayerId = coop.Players[0].PlayerId
            }) != 2)
            throw new Exception("Co-op allied shields lost the scene master's rank.");
        MatchManifest shieldBossAllocation = shieldAllocation with
        {
            MissionIndex = 14,
            MapId = catalog.MapForMission(14).Scene,
            MapRevision = catalog.MapForMission(14).SceneSha256,
            DurationSeconds = catalog.Get(14).TimeSeconds
        };
        MatchManifest.Validate(shieldBossAllocation);
        IReadOnlyList<ShieldMutation> initialShields =
            CoopShieldRankResolver.InitialAlliedShields(
                shieldBossAllocation, shieldStates, content.Shields, 4);
        float expectedMaximum = content.Shields.Health(3) * 0.8f;
        if (initialShields.Count != 4 ||
            initialShields.Any(shield => shield.OwnerFraction != 2 ||
                shield.CoverIndex is < 4 or > 7 ||
                shield.MaxHealth != expectedMaximum ||
                shield.Health != expectedMaximum || shield.Destroyed))
            throw new Exception("Boss shield starts differ from ordered mission overrides.");
        var missionShields = new CoopShieldMatchSimulation(
            shieldBossAllocation, shieldStates, content.Shields, 4, 0);
        if (!missionShields.Snapshot().SequenceEqual(initialShields) ||
            missionShields.ApplyHostShot(5, "Google2u.AssaultRifle_AK47",
                10f, 0)?.Health != expectedMaximum - 10f)
            throw new Exception("Mission shield initialization or host damage changed.");
        missionShields.Advance(1, [5]);
        if (missionShields.Snapshot().Single(shield =>
                shield.CoverIndex == 5).Health != expectedMaximum - 10f)
            throw new Exception("Mission-disabled shield regeneration ran for an occupied cover.");
        var botMissionShields = new CoopShieldMatchSimulation(1,
            bossRules.ForMission(14).Level,
            shieldStates.ForMission(14).Bot, content.Shields, 0, 0);
        float botShieldMaximum = content.Shields.Health(
            bossRules.ForMission(14).Level) * 0.6f;
        if (botMissionShields.Snapshot().Count != 4 ||
            botMissionShields.Snapshot().Any(shield =>
                shield.OwnerFraction != 1 ||
                shield.MaxHealth != botShieldMaximum ||
                shield.Health != botShieldMaximum))
            throw new Exception("Boss enemy shields lost their source bot level or overrides.");
        try
        {
            _ = CoopShieldRankResolver.AlliedRank(coop);
            throw new Exception("Co-op shields accepted an unknown scene master.");
        }
        catch (InvalidDataException)
        {
        }

        var router = new MatchRouter([], coop.ServerId,
            Convert.ToBase64String(new byte[32]));
        if (router.Register(coop).Code != "mode-unavailable" || router.Count != 0)
            throw new Exception("Co-op allocations must stay closed until runtime routing exists.");

        void Reject(MatchManifest invalid)
        {
            try
            {
                MatchManifest.Validate(invalid);
            }
            catch (InvalidDataException)
            {
                return;
            }
            throw new Exception("Invalid co-op allocation was accepted.");
        }

        Reject(coop with { MissionIndex = -1 });
        Reject(coop with { CatalogRevision = new string('0', 64) });
        Reject(coop with { Players = coop.Players.Select(player =>
            player with { Fraction = 1 }).ToArray() });
        Reject(duel with { MissionIndex = 0 });

        try
        {
            _ = new CoopMatchRuntime(coop with { MapId = duel.MapId },
                catalog, spawnPoints, routes, enemyCombat);
            throw new Exception("A PvP map was accepted for a source co-op mission.");
        }
        catch (InvalidDataException)
        {
        }

        MissionMapRule bossMap = catalog.MapForMission(4);
        MatchManifest bossAllocation = shieldAllocation with
        {
            // This fixture's first actor is its master; reversed storage is exercised by CoopSceneRoleTests.
            Players = shieldAllocation.Players.Reverse().ToArray(),
            MissionIndex = 4,
            MapId = bossMap.Scene,
            MapRevision = bossMap.SceneSha256,
            DurationSeconds = catalog.Get(4).TimeSeconds
        };
        MatchManifest.Validate(bossAllocation);
        try
        {
            _ = new CoopMatchRuntime(bossAllocation, catalog,
                spawnPoints, routes, enemyCombat);
            throw new Exception("A boss mission used single-player co-op geometry.");
        }
        catch (InvalidDataException)
        {
        }

        CoopBossAnchorCatalog bossAnchors = CoopBossAnchorCatalog.Load(Path.Combine(
            directory, "recovered-coop-boss-anchors.json"), catalog);
        CoopBossPathCatalog bossPaths = CoopBossPathCatalog.Load(Path.Combine(
            directory, "recovered-coop-boss-paths.json"), catalog,
            bossAnchors, content.ArmyNavMeshes);
        CoopBotHealthCatalog bossHealth = CoopBotHealthCatalog.Load(Path.Combine(
            directory, "recovered-coop-bot-health.json"), catalog, bossRules);
        CoopBossAttackTimingCatalog bossAttackTimings =
            CoopBossAttackTimingCatalog.Load(Path.Combine(directory,
                "recovered-coop-boss-attack-timing.json"), catalog, bossRules);
        CoopBossLoadoutCatalog bossLoadouts = CoopBossLoadoutCatalog.Load(
            Path.Combine(directory, "recovered-coop-boss-loadouts.json"),
            catalog, bossRules, bossAttackTimings, content.AllWeaponBindings);
        BattleCombatContent bossWeaponContent = LoadCoopBossWeaponContent(directory);
        RecoveredBattleMap bossScene = content.Maps.Single(map =>
            map.Source == "Assets/Scenes/" + bossMap.Scene + ".unity");
        var bossSources = new CoopBossRuntimeSources(bossAnchors, bossPaths,
            content.ArmySpawnPoints, bossScene, bossHealth, bossAttackTimings,
            bossLoadouts, bossWeaponContent, shieldStates);
        var bossRuntime = new CoopMatchRuntime(bossAllocation, catalog,
            spawnPoints, routes, enemyCombat, bossSources,
            _ => 0, _ => 0, () => 0f);
        string bossFirstPlayer = bossAllocation.Players[0].PlayerId;
        string bossSecondPlayer = bossAllocation.Players[1].PlayerId;
        if (!bossRuntime.Admit(bossFirstPlayer) ||
            !bossRuntime.Admit(bossSecondPlayer) ||
            bossRuntime.Snapshot().Coop.Boss != null ||
            bossRuntime.BossAttackCadence != null ||
            bossRuntime.BossArsenal != null ||
            bossRuntime.ApplyHostBossDamage(1, 0))
            throw new Exception("Boss runtime rejected the signed allied roster.");
        foreach (string playerId in new[] { bossFirstPlayer, bossSecondPlayer })
        {
            MatchReply ready = bossRuntime.Command(playerId, new MatchCommand
            {
                CommandId = 1,
                Ready = new ReadyCommand { ManifestHash = bossRuntime.ManifestHash }
            });
            if (ready.Code != "ready")
                throw new Exception("Boss allies could not start the isolated runtime.");
            if (playerId == bossFirstPlayer &&
                bossRuntime.ApplyHostPlayerDamage(500, bossFirstPlayer,
                    new ResolvedPlayerDamage(5, CombatDamageType.Basic,
                        HasWeapon: false), 1f, 0) != null)
                throw new Exception("A co-op ally took damage before both peers were ready.");
        }
        MatchSnapshot bossStart = bossRuntime.Snapshot();
        CoopBossMapAnchors bossSourceAnchors = bossAnchors.MapForMission(
            catalog, 4);
        Vector3 bossExpectedAim = -Vector3.Transform(Vector3.UnitZ,
            bossSourceAnchors.PlayerPositions[5].Rotation);
        if (Vector3.Distance(bossRuntime.PlayerAimForward(bossFirstPlayer),
                bossExpectedAim) > 0.00001f)
            throw new Exception("Boss ally aim differs from its multiplayer defend anchor.");
        BattleCoopBossState? transmittedBoss = MatchSnapshot.Parser
            .ParseFrom(bossStart.ToByteArray()).Coop.Boss;
        int transmittedShields = MatchSnapshot.Parser
            .ParseFrom(bossStart.ToByteArray()).Shields.Count;
        if (bossStart.Phase != BattlePhase.Running ||
            bossStart.Coop.SuccessScores.Count != 0 ||
            bossStart.Shields.Count != 8 ||
            transmittedShields != 8 ||
            bossStart.Shields.Where(shield => shield.OwnerFraction == 2)
                .Count() != 4 ||
            bossStart.Shields.Where(shield => shield.OwnerFraction == 1)
                .Count() != 4 ||
            bossStart.Shields.Where(shield => shield.OwnerFraction == 2)
                .Any(shield =>
                shield.Health != content.Shields.Health(3) ||
                shield.MaxHealth != content.Shields.Health(3)) ||
            bossStart.Shields.Where(shield => shield.OwnerFraction == 1)
                .Any(shield =>
                    shield.Health != content.Shields.Health(
                        bossRules.ForMission(4).Level)) ||
            bossStart.Coop.Boss?.EntityId != CoopMissionEngine.BossEntityId ||
            transmittedBoss?.EntityId != CoopMissionEngine.BossEntityId ||
            transmittedBoss.MaxHealth != bossStart.Coop.Boss.MaxHealth ||
            transmittedBoss.Weapons.Count != 4 ||
            transmittedBoss.Weapons.Select(weapon => weapon.LevelManagerIndex)
                .SequenceEqual([1, 3, 6, 13]) == false ||
            transmittedBoss.Weapons.Select(weapon => weapon.InventoryIndex)
                .SequenceEqual([11, 2, 5, 12]) == false ||
            bossRuntime.BossArsenal?.Definition(CoopBossWeaponSlotKind.Primary)
                .SourceId != bossLoadouts.ForMission(4).Slots[0].SheetName ||
            bossStart.Coop.Boss.DefendComponentFileId !=
                bossAnchors.Maps[0].BossStart.ComponentFileId ||
            bossStart.Coop.Boss.MaxHealth != bossHealth.ForMission(4).MaximumHealth ||
            bossRuntime.BossAttackCadence?.NextWindowTick != 61 ||
            bossStart.Coop.ParticipantStarts[0].DefendComponentFileId !=
                bossAnchors.Maps[0].AlliedStarts[0].ComponentFileId ||
            bossStart.Coop.ParticipantStarts[1].DefendComponentFileId !=
                bossAnchors.Maps[0].AlliedStarts[1].ComponentFileId ||
            bossStart.Players.Single(player => player.PlayerId == bossFirstPlayer)
                .CoverIndex != 5)
            throw new Exception("Boss allies started outside multiplayer fraction two.");
        if (bossRuntime.ChooseHostBossPlayerPreference(0f, 0.02f) !=
                bossFirstPlayer ||
            bossRuntime.ChooseHostBossPlayerPreference(0f, 0.07f) !=
                bossSecondPlayer ||
            bossRuntime.PlanPreferredBossPlayerShot(0f, 0.02f,
                false, 0.999f, 0f) != null)
            throw new Exception("Boss preference did not use the live allied roster.");
        ShieldMutation? destroyedAllyCover = bossRuntime.ApplyHostShieldShot(
            5, "Google2u.AssaultRifle_AK47", 100_000f);
        if (destroyedAllyCover?.Destroyed != true ||
            bossRuntime.Snapshot().Shields.Single(shield =>
                shield.OwnerFraction == 2 && shield.CoverIndex == 5).Health != 0 ||
            bossRuntime.ChooseHostBossPlayerPreference(0f, 0.1f) !=
                bossFirstPlayer ||
            bossRuntime.ApplyHostEnemyShieldShot(1,
                "Google2u.AssaultRifle_AK47", 10f)?.Health !=
                    content.Shields.Health(bossRules.ForMission(4).Level) - 10f)
            throw new Exception("Host shield impact did not destroy the allied cover.");
        MatchReply bossMove = bossRuntime.Command(bossFirstPlayer, new MatchCommand
        {
            CommandId = 2,
            MoveCover = new MoveCoverCommand { Direction = 1 }
        });
        if (bossMove.Code != "moving" ||
            bossMove.Snapshot.Players.Single(player =>
                player.PlayerId == bossFirstPlayer).CoverIndex != 5 ||
            bossRuntime.Command(bossSecondPlayer, new MatchCommand
            {
                CommandId = 2,
                MoveCover = new MoveCoverCommand { Direction = 1 }
            }).Code != "cover-unavailable")
            throw new Exception("Boss movement must skip occupied allied shields.");
        bossRuntime.Advance(8);
        MatchSnapshot bossAfterSpawn = bossRuntime.Snapshot();
        if (bossAfterSpawn.Coop.EnemySpawns.Count == 0 ||
            bossRuntime.BossAttackCadence?.WindowCount != 0 ||
            bossAfterSpawn.Coop.EnemySpawns.Any(enemy => enemy.SourceRotation != null) ||
            bossAfterSpawn.Coop.EnemySpawns.Any(enemy =>
            !content.ArmySpawnPoints.ForMap(bossScene).Any(point =>
                point.Fraction == 1 &&
                point.ComponentFileId == enemy.SpawnComponentFileId)))
            throw new Exception("Boss mission spawned an AI outside enemy fraction one.");
        bossRuntime.Advance(200);
        if (bossRuntime.BossAttackCadence?.WindowCount != 2 ||
            bossRuntime.BossAttackCadence.WindowOpen != true ||
            bossRuntime.Snapshot().Shields.Single(shield =>
                shield.OwnerFraction == 2 && shield.CoverIndex == 5).Destroyed)
            throw new Exception("Boss attack windows lost source shooting timing.");
        CoopBossPreferredShotPlan? primaryPlan =
            bossRuntime.PlanPreferredBossPlayerShot(0f, 0.02f,
                false, 0.999f, 0f);
        CoopBossPreferredShotPlan? secondaryPlan =
            bossRuntime.PlanPreferredBossPlayerShot(0f, 0.07f,
                false, 0.999f, 0.999f);
        if (primaryPlan?.PlayerId != bossFirstPlayer ||
            primaryPlan.Slot != CoopBossWeaponSlotKind.Primary ||
            primaryPlan.WeaponSourceId != bossRuntime.BossArsenal!.Definition(
                CoopBossWeaponSlotKind.Primary).SourceId ||
            secondaryPlan?.PlayerId != bossSecondPlayer ||
            secondaryPlan.Slot != CoopBossWeaponSlotKind.Secondary)
            throw new Exception("Boss shot planning lost host target or source weapon.");
        BattlePlayerState movedBossAlly = bossRuntime.Snapshot().Players.Single(
            player => player.PlayerId == bossFirstPlayer);
        if (movedBossAlly.Moving || movedBossAlly.CoverIndex != 7 ||
            Vector3.Distance(new Vector3(movedBossAlly.PositionX,
                movedBossAlly.PositionY, movedBossAlly.PositionZ),
                bossAnchors.Maps[0].PlayerPositions[7].Position) > 0.0001f)
            throw new Exception("Boss ally did not reach the skipped multiplayer shield.");
        float secondMaximum = bossAllocation.Players[1].Combat!.MaxHealth;
        if (bossRuntime.ApplyHostPlayerDamage(501, bossSecondPlayer,
                new ResolvedPlayerDamage(5, CombatDamageType.Basic,
                    HasWeapon: false), 1f, 199) != null ||
            bossRuntime.ApplyHostPlayerDamage(502, bossSecondPlayer,
                new ResolvedPlayerDamage(5, CombatDamageType.Basic,
                    HasWeapon: false), 1f, 201) != null)
            throw new Exception("Co-op host damage must use the current mission tick.");
        PlayerDamageResult? nonlethalHit = bossRuntime.ApplyHostPlayerDamage(
            503, bossSecondPlayer, new ResolvedPlayerDamage(5, CombatDamageType.Basic,
                HasWeapon: false), 1f, 200);
        BattlePlayerState woundedAlly = bossRuntime.Snapshot().Players.Single(
            player => player.PlayerId == bossSecondPlayer);
        if (nonlethalHit?.Applied != true || nonlethalHit.Dead ||
            woundedAlly.Health != secondMaximum - 5 ||
            woundedAlly.MaxHealth != secondMaximum ||
            woundedAlly.DamageRevision != 1)
            throw new Exception("Co-op host damage did not update player vitality.");
        PlayerDamageResult? replayedHit = bossRuntime.ApplyHostPlayerDamage(
            503, bossSecondPlayer, new ResolvedPlayerDamage(5,
                CombatDamageType.Basic, HasWeapon: false), 1f, 200);
        if (replayedHit != nonlethalHit ||
            bossRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == bossSecondPlayer).DamageRevision != 1 ||
            bossRuntime.ApplyHostPlayerDamage(0, bossSecondPlayer,
                new ResolvedPlayerDamage(5, CombatDamageType.Basic,
                    HasWeapon: false), 1f, 200) != null ||
            bossRuntime.ApplyHostPlayerDamage(503, bossSecondPlayer,
                new ResolvedPlayerDamage(6, CombatDamageType.Basic,
                    HasWeapon: false), 1f, 200) != null ||
            bossRuntime.ApplyHostPlayerDamage(503, bossFirstPlayer,
                new ResolvedPlayerDamage(5, CombatDamageType.Basic,
                    HasWeapon: false), 1f, 200) != null)
            throw new Exception("A co-op hit replay changed host-owned health.");
        PlayerDamageResult? lethalHit = bossRuntime.ApplyHostPlayerDamage(
            504, bossSecondPlayer, new ResolvedPlayerDamage(secondMaximum,
                CombatDamageType.Basic, HasWeapon: false), 1f, 200);
        // DestroyableObject clamps health only at the maximum. A lethal hit
        // can leave a negative value, which terminal evidence must preserve.
        if (lethalHit?.Dead != true || lethalHit.Health >= 0 ||
            !bossRuntime.Snapshot().Players.Single(player =>
                player.PlayerId == bossSecondPlayer).Dead ||
            bossRuntime.Snapshot().Phase != BattlePhase.Running ||
            bossRuntime.ApplyHostPlayerDamage(505, bossSecondPlayer,
                new ResolvedPlayerDamage(1, CombatDamageType.Basic), 1f,
                200) != null ||
            bossRuntime.ApplyHostPlayerDamage(504, bossSecondPlayer,
                new ResolvedPlayerDamage(secondMaximum,
                    CombatDamageType.Basic, HasWeapon: false), 1f,
                200) != lethalHit ||
            bossRuntime.Command(bossSecondPlayer, new MatchCommand
            {
                CommandId = 3,
                MoveCover = new MoveCoverCommand { Direction = -1 }
            }).Code != "match-not-running")
            throw new Exception("A dead co-op ally must spectate while the mission continues.");
        if (bossRuntime.ChooseHostBossPlayerPreference(0f, 0.07f) !=
            bossFirstPlayer)
            throw new Exception("Boss preference still considered a dead ally.");
        if (!bossRuntime.ApplyHostBossDamage(100, 200) ||
            bossRuntime.Snapshot().Coop.Boss?.Health !=
                bossHealth.ForMission(4).MaximumHealth - 100 ||
            bossRuntime.Snapshot().Phase != BattlePhase.Running ||
            !bossRuntime.ApplyHostBossDamage(1000, 200) ||
            bossRuntime.Snapshot().Phase != BattlePhase.Ended ||
            !bossRuntime.Snapshot().Coop.Completed ||
            bossRuntime.ApplyHostBossDamage(1000, 200))
            throw new Exception("Boss damage must be host-owned and settle only once.");
        CoopMissionSuccessScore? survivingScore =
            bossRuntime.HostSuccessScore(bossFirstPlayer);
        MatchSnapshot completedBoss = bossRuntime.TerminalEvidenceSnapshot();
        BattleCoopPlayerScore[] wireScores = MatchSnapshot.Parser
            .ParseFrom(completedBoss.ToByteArray()).Coop.SuccessScores.ToArray();
        if (survivingScore?.Stars != 3 ||
            survivingScore.Score < catalog.Get(4).ScoreThreeStars ||
            bossRuntime.HostSuccessScore(bossSecondPlayer) != null ||
            completedBoss.RewardEligible ||
            wireScores.Length != 1 ||
            wireScores[0].PlayerId != bossFirstPlayer ||
            wireScores[0].Score != survivingScore.Score ||
            wireScores[0].Stars != survivingScore.Stars)
            throw new Exception("Boss success score did not use frozen host outcome.");
        CoopTerminalScoreValidator.ValidateSuccess(
            completedBoss, bossAllocation, catalog, enemyCombat, bossSources);
        MatchSnapshot swappedBossStarts = completedBoss.Clone();
        BattleCoopParticipantStart firstBossStart =
            swappedBossStarts.Coop.ParticipantStarts[0].Clone();
        swappedBossStarts.Coop.ParticipantStarts[0] =
            swappedBossStarts.Coop.ParticipantStarts[1];
        swappedBossStarts.Coop.ParticipantStarts[1] = firstBossStart;
        try
        {
            CoopTerminalScoreValidator.ValidateSuccess(
                swappedBossStarts, bossAllocation, catalog, enemyCombat,
                bossSources);
            throw new Exception("Boss allies swapped their signed start anchors.");
        }
        catch (InvalidDataException) { }
        MatchSnapshot forgedBossHealth = completedBoss.Clone();
        forgedBossHealth.Coop.Boss.MaxHealth++;
        try
        {
            CoopTerminalScoreValidator.ValidateSuccess(
                forgedBossHealth, bossAllocation, catalog, enemyCombat,
                bossSources);
            throw new Exception("Forged boss maximum health passed terminal proof.");
        }
        catch (InvalidDataException) { }
        MatchSnapshot forgedBossAnchor = completedBoss.Clone();
        forgedBossAnchor.Coop.Boss.DefendComponentFileId++;
        try
        {
            CoopTerminalScoreValidator.ValidateSuccess(
                forgedBossAnchor, bossAllocation, catalog, enemyCombat,
                bossSources);
            throw new Exception("Forged boss anchor passed terminal proof.");
        }
        catch (InvalidDataException) { }
        MatchSnapshot forgedBossWeapon = completedBoss.Clone();
        forgedBossWeapon.Coop.Boss.Weapons[0].InventoryIndex++;
        try
        {
            CoopTerminalScoreValidator.ValidateSuccess(
                forgedBossWeapon, bossAllocation, catalog, enemyCombat,
                bossSources);
            throw new Exception("Forged boss weapon passed terminal proof.");
        }
        catch (InvalidDataException) { }
        MatchSnapshot undeclaredEnemyDeath = completedBoss.Clone();
        undeclaredEnemyDeath.Coop.EnemySpawns.Add(
            new BattleCoopEnemySpawn
            {
                EntityId = (ulong)undeclaredEnemyDeath.Coop.EnemySpawns.Count + 1,
                Behaviour = "Assaulter",
                Level = 0,
                MaxHealth = enemyCombat.OrdinaryStats(
                    "Assaulter", 0).Health,
                Health = 0,
                SpawnTick = 1,
                DeathTick = 0
            });
        try
        {
            CoopTerminalScoreValidator.ValidateSuccess(
                undeclaredEnemyDeath, bossAllocation, catalog, enemyCombat, bossSources);
            throw new Exception(
                "A zero-health enemy without a death tick passed co-op proof.");
        }
        catch (InvalidDataException) { }
        MatchSnapshot forgedBossDeath = completedBoss.Clone();
        forgedBossDeath.Coop.Boss.DeathTick = 0;
        try
        {
            CoopTerminalScoreValidator.ValidateSuccess(
                forgedBossDeath, bossAllocation, catalog, enemyCombat, bossSources);
            throw new Exception("A boss success without a host death was accepted.");
        }
        catch (InvalidDataException)
        {
        }
        MatchSnapshot forgedBossScore = completedBoss.Clone();
        forgedBossScore.Coop.SuccessScores[0].Score++;
        try
        {
            CoopTerminalScoreValidator.ValidateSuccess(
                forgedBossScore, bossAllocation, catalog, enemyCombat, bossSources);
            throw new Exception("Forged co-op score passed terminal validation.");
        }
        catch (InvalidDataException)
        {
        }
        MatchSnapshot forgedBossObjective = completedBoss.Clone();
        forgedBossObjective.Coop.ObjectiveScore = 10;
        try
        {
            CoopTerminalScoreValidator.ValidateSuccess(
                forgedBossObjective, bossAllocation, catalog, enemyCombat, bossSources);
            throw new Exception("A boss mission accepted forged Score objective progress.");
        }
        catch (InvalidDataException)
        {
        }
        MatchSnapshot forgedBossLedger = completedBoss.Clone();
        forgedBossLedger.Coop.ParticipantScores.Add(new BattleCoopParticipantScore
        {
            PlayerId = bossFirstPlayer,
            Score = 10
        });
        try
        {
            CoopTerminalScoreValidator.ValidateSuccess(
                forgedBossLedger, bossAllocation, catalog, enemyCombat, bossSources);
            throw new Exception("A boss mission accepted a forged allied score row.");
        }
        catch (InvalidDataException)
        {
        }
        MatchSnapshot forgedBossDeadline = completedBoss.Clone();
        forgedBossDeadline.Coop.DeadlineTick++;
        try
        {
            CoopTerminalScoreValidator.ValidateSuccess(
                forgedBossDeadline, bossAllocation, catalog, enemyCombat, bossSources);
            throw new Exception("Forged co-op deadline passed terminal validation.");
        }
        catch (InvalidDataException)
        {
        }

        CoopSceneColliderCatalog shotScenes = CoopSceneColliderCatalog.Load(
            Path.Combine(directory, "recovered-coop-scene-colliders.json"),
            catalog);
        CoopMeshGeometryCatalog shotMeshes = CoopMeshGeometryCatalog.Load(
            Path.Combine(directory, "recovered-coop-mesh-geometry.json"),
            shotScenes);
        var alliedShotWorld = new CoopPlayerShotCollisionWorld(
            shotScenes.MapForMission(catalog, 0),
            spawnPoints.MapForMission(catalog, 0), shotMeshes);

        var ordinaryShieldRuntime = new CoopMatchRuntime(shieldAllocation,
            catalog, spawnPoints, routes, enemyCombat,
            chooseBehaviour: _ => 0, choosePoint: _ => 0,
            shieldSources: new CoopShieldRuntimeSources(
                shieldStates, content.Shields),
            playerWeaponContent: content);
        foreach (ParticipantManifest player in shieldAllocation.Players)
        {
            if (!ordinaryShieldRuntime.Admit(player.PlayerId) ||
                ordinaryShieldRuntime.Command(player.PlayerId, new MatchCommand
                {
                    CommandId = 1,
                    Ready = new ReadyCommand
                    {
                        ManifestHash = ordinaryShieldRuntime.ManifestHash
                    }
                }).Code != "ready")
                throw new Exception("Ordinary co-op allies could not start shields.");
        }
        MatchSnapshot ordinaryShieldStart = ordinaryShieldRuntime.Snapshot();
        if (ordinaryShieldStart.Shields.Count != 4 ||
            ordinaryShieldStart.Shields.Any(shield =>
                shield.CoverIndex is < 0 or > 3 ||
                shield.OwnerFraction != 2 ||
                shield.Health != content.Shields.Health(3)))
            throw new Exception("Ordinary co-op covers did not use the master rank.");
        if (ordinaryShieldRuntime.ApplyHostShieldShot(0,
                "Google2u.AssaultRifle_AK47", 10f)?.Health !=
            content.Shields.Health(3) - 10f)
            throw new Exception("Ordinary co-op shield rejected a host impact.");
        var unitShieldProbe = new CoopShieldMatchSimulation(
            shieldAllocation, shieldStates, content.Shields,
            firstCover: 0, startingTick: 0);
        float assaulterDamage = enemyCombat.OrdinaryStats(
            "Assaulter", normalUpgradeIndex: 0).Damage;
        ShieldMutation? unitShieldHit = unitShieldProbe.ApplyHostUnitShot(
            881, 1, assaulterDamage, 0);
        float expectedShieldHealth = content.Shields.Health(3) -
            assaulterDamage * content.Shields.UnitToShieldCoefficient;
        if (unitShieldHit == null ||
            Math.Abs(unitShieldHit.Health - expectedShieldHealth) > 0.0001f)
            throw new Exception("Co-op Assaulter shot lost its unit-to-shield rule.");
        if (unitShieldProbe.ApplyHostUnitShot(881, 1,
                assaulterDamage, 0) != unitShieldHit ||
            unitShieldProbe.Snapshot()[1] != unitShieldHit)
            throw new Exception("Co-op unit shield shot repeated its damage.");
        try
        {
            unitShieldProbe.ApplyHostUnitShot(881, 2,
                assaulterDamage, 0);
            throw new Exception("Co-op unit shield receipt accepted a new cover.");
        }
        catch (InvalidDataException) { }
        try
        {
            unitShieldProbe.ApplyHostUnitShot(881, 1,
                assaulterDamage + 1f, 0);
            throw new Exception("Co-op unit shield receipt accepted new damage.");
        }
        catch (InvalidDataException) { }
        unitShieldProbe.Advance(1, [1]);
        if (unitShieldProbe.ApplyHostUnitShot(881, 1,
                assaulterDamage, 0) != unitShieldHit ||
            unitShieldProbe.Snapshot()[1] != unitShieldHit)
            throw new Exception("A later replay changed co-op shield health.");
        ShieldMutation? destroyedByUnit = unitShieldProbe
            .ApplyHostUnitShot(882, 1, 1_000_000f, 1);
        if (destroyedByUnit?.Destroyed != true)
            throw new Exception("Host unit shot failed to destroy the allied shield.");
        ulong unitRepairTick = 1 + (ulong)MathF.Ceiling(
            content.Shields.RepairSeconds * MatchManifest.TickRate);
        for (ulong hostTick = 2; hostTick <= unitRepairTick; hostTick++)
            unitShieldProbe.Advance(hostTick, [1]);
        ShieldMutation repairedUnitShield = unitShieldProbe.Snapshot()[1];
        if (repairedUnitShield.Destroyed ||
            unitShieldProbe.ApplyHostUnitShot(882, 1,
                1_000_000f, 1) != destroyedByUnit ||
            unitShieldProbe.Snapshot()[1] != repairedUnitShield)
            throw new Exception("A replay consumed a repaired co-op shield.");
        // The Unity ray-reference artifact hits Desert's cover-1 collider
        // 1531 from this point. Use the runtime's own shield snapshots.
        using JsonDocument shieldRays = JsonDocument.Parse(File.ReadAllBytes(
            Path.Combine(directory, "recovered-coop-scene-ray-reference.json")));
        JsonElement sourceShieldRays = shieldRays.RootElement
            .GetProperty("maps")[0].GetProperty("rays");
        (Vector3 Start, Vector3 Direction, CoopPlayerShotHit? Hit)[]
            candidateShieldRays = sourceShieldRays.EnumerateArray()
            .Where(ray => ray.GetProperty("componentFileId").GetInt32() ==
                1531 && ray.GetProperty("hit").GetBoolean())
            .Select(ray =>
            {
                Vector3 start = ReadRayVector(ray.GetProperty("origin"));
                Vector3 direction = ReadRayVector(
                    ray.GetProperty("direction"));
                CoopPlayerShotHit? hit = ordinaryShieldRuntime
                    .TraceIdleAlliedEnemyRay(alliedShotWorld, start,
                        direction, ray.GetProperty("maxDistance").GetSingle());
                return (start, direction, hit);
            }).ToArray();
        var selectedShieldRay = candidateShieldRays.FirstOrDefault(
            candidate => candidate.Hit?.SceneColliderFileId == 1531);
        if (selectedShieldRay.Hit == null)
            throw new Exception("No source shield ray reached cover under the full enemy mask: " +
                string.Join(",", candidateShieldRays.Select(candidate =>
                    candidate.Hit?.SceneColliderFileId.ToString() ?? "none")));
        Vector3 coverRayStart = selectedShieldRay.Start;
        Vector3 coverRayDirection = selectedShieldRay.Direction;
        CoopPlayerShotHit covered = selectedShieldRay.Hit;
        ShieldMutation? brokenCover = ordinaryShieldRuntime
            .ApplyHostShieldShot(1, "Google2u.AssaultRifle_AK47",
