            !arrivalRuntime.CurrentEnemyCollisionFrame()
                .UnplacedEnemyIds.Contains(arrivalEnemy.EntityId))
            throw new Exception("Co-op Assaulter walked beyond its reached point.");
        ulong firstShootTick = obstacleArrival.FirstShootEligibleTick;
        arrivalRuntime.Advance(firstShootTick - 1);
        if (arrivalRuntime.InfantryFirstPlayerTarget(
                arrivalEnemy.EntityId) != null)
            throw new Exception("Assaulter selected a player before its shot window.");
        arrivalRuntime.Advance(firstShootTick);
        Vector3 towardAssaulter = new(
            reachedEnemy.CurrentX - mainAnchors[0].Position.X,
            reachedEnemy.CurrentY - mainAnchors[0].Position.Y,
            reachedEnemy.CurrentZ - mainAnchors[0].Position.Z);
        int expectedTargetMask = MatchEngine.HeavyTurretStationaryTargetMask(
            arrivalRuntime.PlayerAimForward(firstPlayer), towardAssaulter,
            shieldProbability: 0f, () => 0.5f);
        CoopInfantryPlayerTargetPlan? targetPlan = arrivalRuntime
            .InfantryFirstPlayerTarget(arrivalEnemy.EntityId);
        if (targetPlan?.ShotTargetMask != expectedTargetMask ||
            targetPlan.PlayerId != firstPlayer ||
            targetPlan.Tick != firstShootTick)
            throw new Exception("Co-op Assaulter target mask lacks host player authority.");
        CoopInfantryPlayerShotTarget? placedTarget = arrivalRuntime
            .PlaceFirstAssaulterPlayerTarget(arrivalEnemy.EntityId);
        PlayerShotTarget? sourceTarget = placedTarget == null ? null :
            content.PlayerShotTargets.Gameplay.Single(target =>
                target.TransformFileId == placedTarget.TransformFileId);
        if (placedTarget?.PlayerId != firstPlayer ||
            placedTarget.Tick != firstShootTick ||
            sourceTarget == null ||
            (sourceTarget.Type & expectedTargetMask) != sourceTarget.Type ||
            placedTarget.SourcePath != sourceTarget.Path ||
            !PlayerHitbox.Finite(placedTarget.Position) ||
            Vector3.Distance(placedTarget.Position,
                mainAnchors[0].Position) > 3f)
            throw new Exception("Co-op Assaulter lacks an idle source player target.");
        Quaternion sourceCoverRotation = mainAnchors[0].SourceRotation ??
            throw new Exception("Co-op cover has no source rotation.");
        Vector3 expectedRootTarget = mainAnchors[0].Position +
            Vector3.Transform(sourceTarget.LocalPosition,
                sourceCoverRotation);
        if (Vector3.Distance(placedTarget.Position,
                expectedRootTarget) > 0.0002f)
            throw new Exception(
                "Co-op body target differs from its serialized root transform.");
        BattleInfantryAnimationFrame? initialObstacle = arrivalRuntime.Snapshot().Coop.EnemySpawns
            .Single(enemy => enemy.EntityId == arrivalEnemy.EntityId).InfantryAnimation;
        if (initialObstacle?.SampleTick != firstShootTick || initialObstacle.Clips.Count != 2 ||
            initialObstacle.Clips[0].ClipName != "stand_up_crawl" ||
