        arrivalRuntime.Advance(firstShootTick + 1);
        BattleInfantryAnimationFrame? firstObstacleStep = arrivalRuntime.Snapshot().Coop.EnemySpawns
            .Single(enemy => enemy.EntityId == arrivalEnemy.EntityId).InfantryAnimation;
        if (firstObstacleStep?.SampleTick != firstShootTick + 1 || firstObstacleStep.Clips.Count != 1 ||
            firstObstacleStep.Clips[0].ClipName != "stand_up_begin" || firstObstacleStep.Clips[0].Weight != 2f / 3f)
        {
            throw new Exception("The next obstacle step must preserve its partial begin weight.");
        }
        File.WriteAllBytes(Path.Combine(directory, "..", ".local", "obstacle-initial-1.bin"),
            firstObstacleStep.ToByteArray());
        if (arrivalRuntime.InfantryFirstPlayerTarget(
                arrivalEnemy.EntityId) != targetPlan)
            throw new Exception("Co-op Assaulter first target was chosen more than once.");
        ulong expectedCrawlCallback = firstShootTick +
            (ulong)Math.Ceiling((content.EnemyPoses.Clip("stand_up_begin")
                .Length + 0.05f) * MatchManifest.TickRate);
        CoopInfantryShotWindup? crawlWindup = arrivalRuntime
            .InfantryShotWindup(arrivalEnemy.EntityId);
        CoopObstacleVolleySnapshot? preparedObstacle = arrivalRuntime.ObstacleVolleyState(arrivalEnemy.EntityId);
        if (preparedObstacle == null || !preparedObstacle.HasPendingShot || preparedObstacle.IsCrawling ||
            preparedObstacle.NextPositionTick != firstShootTick + 90)
        {
            throw new Exception("Obstacle preparation lost its source 2-3-second position clock.");
        }

        if (arrivalRuntime.ObserveIdleAssaulterMuzzle(
                arrivalEnemy.EntityId) != null ||
            arrivalRuntime.PlanDiagnosticWalkingTargetAtCover(
                arrivalEnemy.EntityId, firstPlayer) != null)
            throw new Exception("Co-op idle muzzle survived the shot windup.");
        ArmyBaseShotStats sourceBatch = content.Army.ComposeShot(
            "ID_UNIT-ASSAULT", arrivalEnemy.Level, null, null);
        int expectedBatchCount = Math.Clamp(
            sourceBatch.FireBatchSizeMax > sourceBatch.FireBatchSizeMin
                ? sourceBatch.FireBatchSizeMax - 1
                : sourceBatch.FireBatchSizeMin, 0, 14);
        int expectedRealMask = sourceBatch.ProbabilityOfRealShot > 0
            ? (1 << expectedBatchCount) - 1 : 0;
        if (crawlWindup?.AnimationClip != "stand_up_begin" ||
