            {
                float distance = 2 - from.Z;
                return distance > 0 && distance <= range
                    ? new ShotCollision(distance,
                        from + direction * distance,
                        "diagnostic/wall", null, 0, Static: true)
                    : null;
            });
        BulletImpact? enemyImpact = null;
        for (ulong flightTick = 1; flightTick <= 30 &&
             enemyImpact == null; flightTick++)
            enemyImpact = enemyIdentityProbe.Advance(flightTick);
        if (enemyImpact?.EnemyEntityId != arrivalEnemy.EntityId ||
            enemyImpact.OwnerId != string.Empty ||
            !enemyImpact.Hit.Static)
            throw new Exception("Enemy bullet impact lost its host entity identity.");

        CoopMatchRuntime ReadyShotRuntime(Func<float> distance,
            Func<float> sideRoll, float realShotRoll = 0.999f)
        {
            var destinations = new CoopEnemyDestinationState(
                enemyMap, enemyPointMasks, enemyCombat,
                chooseObstacleFraction: () => 0.5f);
            var runtime = new CoopMatchRuntime(coop, catalog,
                spawnPoints, routes, enemyCombat, chooseBehaviour: _ => 0,
                choosePoint: _ => 0,
                enemyDestinations: destinations,
                infantryNavigation: infantryNavigation,
                playerWeaponContent: content,
                chooseInfantryShotFraction: () => 0f,
                chooseInfantryRepositionFraction: () => 0.999f,
                chooseInfantryPlayer: _ => 0,
                chooseInfantryShieldRoll: () => 0.5f,
                chooseInfantryBatchSize: (min, max) =>
                    max > min ? max - 1 : min,
                chooseInfantryRealShotRoll: () => realShotRoll,
                chooseInfantryFakeDistance: distance,
                chooseInfantryFakeSideRoll: sideRoll);
            runtime.Admit(firstPlayer);
            runtime.Admit(secondPlayer);
            foreach (string playerId in new[] { firstPlayer, secondPlayer })
                runtime.Command(playerId, new MatchCommand
                {
                    CommandId = 1,
                    Ready = new ReadyCommand
                    {
                        ManifestHash = runtime.ManifestHash
                    }
                });
            return runtime;
        }
        var movingShieldDestinations = new CoopEnemyDestinationState(
            enemyMap, enemyPointMasks, enemyCombat,
            chooseObstacleFraction: () => 0.5f);
        var movingShieldRuntime = new CoopMatchRuntime(shieldAllocation,
            catalog, spawnPoints, routes, enemyCombat,
            chooseBehaviour: _ => 0, choosePoint: _ => 0,
            enemyDestinations: movingShieldDestinations,
            infantryNavigation: infantryNavigation,
            shieldSources: new CoopShieldRuntimeSources(shieldStates,
                content.Shields), playerWeaponContent: content,
            chooseInfantryShotFraction: () => 0f,
            chooseInfantryRepositionFraction: () => 0.999f,
            chooseInfantryPlayer: _ => 0,
            chooseInfantryShieldRoll: () => 0f,
            chooseInfantryBatchSize: (min, max) =>
                max > min ? max - 1 : min,
            chooseInfantryRealShotRoll: () => 0f);
        movingShieldRuntime.AttachDiagnosticWorld(alliedShotWorld);
        foreach (string playerId in new[] { firstPlayer, secondPlayer })
        {
            if (!movingShieldRuntime.Admit(playerId) ||
                movingShieldRuntime.Command(playerId, new MatchCommand
                {
                    CommandId = 1,
                    Ready = new ReadyCommand
                    {
                        ManifestHash = movingShieldRuntime.ManifestHash
                    }
                }).Code != "ready")
                throw new Exception(
                    "Co-op shield flight fixture could not start its roster.");
        }
        movingShieldRuntime.Advance(movingShootTick - 3);
        if (movingShieldRuntime.Command(firstPlayer, new MatchCommand
            {
                CommandId = 2,
                MoveCover = new MoveCoverCommand { Direction = 1 }
            }).Code != "moving")
            throw new Exception(
                "Co-op shield flight fixture could not start the ally walk.");
        movingShieldRuntime.Advance(walkingWindup.CallbackTick + 100);
        CoopDiagnosticFlightResult[] barrierImpacts = movingShieldRuntime
            .DiagnosticFlightResults().Where(result =>
                result.Outcome == "impact" &&
                result.Impact?.Hit.ColliderIndex == 1527).ToArray();
        if (barrierImpacts.Length == 0 ||
            !movingShieldRuntime.InfantryRoundIntents(
                movingCoverEnemy.EntityId).Any(round =>
                    round.Real && round.ShieldTarget) ||
            barrierImpacts.Any(result =>
                result.Impact?.Hit.ColliderLayer != 13 ||
                movingShieldRuntime.PlanDiagnosticShieldImpact(
                    result.ProjectileId) != null) ||
            movingShieldRuntime.Snapshot().Shields.Any(shield =>
                shield.Health != shield.MaxHealth))
            throw new Exception(
                "Static co-op barrier was mistaken for an allied shield hit.");
        var fakeRuntime = ReadyShotRuntime(() => 0.75f, () => 0.25f);
        fakeRuntime.AttachDiagnosticWorld(alliedShotWorld);
        fakeRuntime.Advance(expectedCrawlCallback + 1);
        BattleCoopEnemySpawn fakeEnemy = fakeRuntime.Snapshot().Coop
            .EnemySpawns.Single(enemy =>
                enemy.EntityId == arrivalEnemy.EntityId);
        CoopInfantryShotWindup? fakeWindup = fakeRuntime
            .InfantryShotWindup(fakeEnemy.EntityId);
        CoopInfantryRoundIntent? fakeRound = fakeRuntime
            .InfantryRoundIntents(fakeEnemy.EntityId).SingleOrDefault();
        if (fakeWindup == null || fakeRound == null || fakeRound.Real ||
            fakeRound.Tick != expectedCrawlCallback + 1 ||
            fakeWindup.PreparedAimPosition != placedTarget.Position)
            throw new Exception("Co-op fake rifle round was not host-owned.");
        if (fakeRuntime.CreateDiagnosticAssaulterFlight(
                fakeEnemy.EntityId, 0, alliedShotWorld) != null)
            throw new Exception("A fake co-op round created a damaging bullet.");
        if (fakeRuntime.ActiveDiagnosticFlightIds().Count != 0 ||
            fakeRuntime.TrackDiagnosticAssaulterFlight(
                fakeEnemy.EntityId, 0, alliedShotWorld))
            throw new Exception("A fake co-op round entered the flight loop.");
        Vector3 fakeEnemyPosition = new(fakeEnemy.CurrentX,
            fakeEnemy.CurrentY, fakeEnemy.CurrentZ);
        Vector3 fakeSideways = Vector3.Normalize(Vector3.Cross(
            fakeEnemyPosition - fakeWindup.PreparedAimPosition,
            Vector3.UnitY)) * -0.75f;
        Vector3 expectedFakeAim = fakeWindup.PreparedAimPosition +
            fakeSideways + new Vector3(0, 0.5f, 0);
        if (Vector3.Distance(fakeRound.AimPosition, expectedFakeAim) >
            0.00001f || !MatchesCoopMuzzleObservation(fakeRound.ObservedLocalMuzzle, gameplayObstacleSample) ||
            fakeRound.ObservedWorldLaunchOrigin is not Vector3 fakeOrigin ||
            Vector3.Distance(fakeOrigin, expectedLaunchOrigin) > 0.00001f)
            throw new Exception("Co-op fake round lost its source sideways/upward aim.");
        var poseLossRuntime = ReadyShotRuntime(() => 0.75f,
            () => 0.25f, realShotRoll: 0f);
        try
        {
            poseLossRuntime.AttachDiagnosticWorld(
                new CoopPlayerShotCollisionWorld(
                    shotScenes.Maps.First(map =>
                        map.Scene != coop.MapId),
                    spawnPoints.Maps.First(map =>
                        map.Scene != coop.MapId), shotMeshes));
            throw new Exception("Co-op diagnostic ray used another mission scene.");
        }
        catch (InvalidOperationException) { }
        poseLossRuntime.AttachDiagnosticWorld(alliedShotWorld);
        poseLossRuntime.Advance(expectedCrawlCallback + 1);
        ulong poseLossProjectileId = poseLossRuntime.InfantryRoundIntents(
            arrivalEnemy.EntityId).Single().ProjectileId;
        if (!poseLossRuntime.ActiveDiagnosticFlightIds().Contains(
                poseLossProjectileId) ||
            poseLossRuntime.Command(firstPlayer, new MatchCommand
            {
                CommandId = 2,
                MoveCover = new MoveCoverCommand { Direction = 1 }
            }).Code != "moving")
            throw new Exception("Co-op pose-loss flight setup was rejected.");
        poseLossRuntime.Advance(expectedCrawlCallback + 2);
        CoopDiagnosticFlightResult? cancelledFlight = poseLossRuntime
            .DiagnosticFlightResults().SingleOrDefault(result =>
                result.ProjectileId == poseLossProjectileId);
        if (cancelledFlight?.Outcome != "pose-unavailable" ||
            cancelledFlight.EnemyEntityId != arrivalEnemy.EntityId ||
            poseLossRuntime.ActiveDiagnosticFlightIds().Contains(
                poseLossProjectileId))
            throw new Exception("A moving ally left a stale diagnostic flight active.");
        foreach ((Func<float> distance, Func<float> sideRoll) in new[]
            {
                ((Func<float>)(() => float.NaN), (Func<float>)(() => 0.25f)),
                ((Func<float>)(() => 0.75f), (Func<float>)(() => -0.1f))
            })
        {
            CoopMatchRuntime invalid = ReadyShotRuntime(distance, sideRoll);
            try
            {
                invalid.Advance(expectedCrawlCallback + 1);
                throw new Exception("Invalid fake-round draw was accepted.");
            }
            catch (InvalidDataException) { }
            if (invalid.InfantryRoundIntents(arrivalEnemy.EntityId).Count != 0)
                throw new Exception("Invalid fake-round draw published an intent.");
        }
        ulong secondRoundTick = rifle.NextRoundEligibleTick(firstRound[0].Tick);
        arrivalRuntime.Advance(secondRoundTick - 1);
        Vector3? flightPosition = arrivalRuntime.DiagnosticFlightPosition(
            enemyFlight!.Id);
        IReadOnlyList<CoopDiagnosticFlightResult> flightResults =
            arrivalRuntime.DiagnosticFlightResults();
        if ((flightPosition == null || flightPosition == origin) &&
            !flightResults.Any(result =>
                result.ProjectileId == enemyFlight.Id &&
                result.EnemyEntityId == arrivalEnemy.EntityId &&
                result.Outcome is "impact" or "miss"))
            throw new Exception("Co-op diagnostic bullet did not advance on host ticks.");
        if (arrivalRuntime.Snapshot().Players.Any(player =>
                player.Health != player.MaxHealth))
            throw new Exception("Diagnostic enemy flight changed player health.");
        if (arrivalRuntime.InfantryRoundIntents(
                arrivalEnemy.EntityId).Count != 1)
            throw new Exception("Co-op rifle scheduled a round before its cadence.");
        arrivalRuntime.Advance(secondRoundTick);
        BattleInfantryAnimationFrame? secondObstacleFire = arrivalRuntime.Snapshot().Coop.EnemySpawns
            .Single(enemy => enemy.EntityId == arrivalEnemy.EntityId).InfantryAnimation;
        if (secondObstacleFire?.SampleTick != secondRoundTick || secondObstacleFire.Clips[0].TimeSeconds != 0f)
        {
            throw new Exception("A later obstacle round must restart its displayed fire clock.");
        }
        IReadOnlyList<CoopInfantryRoundIntent> secondRound = arrivalRuntime
            .InfantryRoundIntents(arrivalEnemy.EntityId);
        if (expectedBatchCount < 2 || secondRound.Count != 2 ||
            secondRound[1].RoundIndex != 1 ||
            secondRound[1].Tick != secondRoundTick ||
            secondRound[1].ProjectileId <= secondRound[0].ProjectileId ||
            secondRound[1].Real != ((expectedRealMask & 2) != 0))
            throw new Exception("Co-op rifle lost its second batch round.");
        if (expectedBatchCount > 2 && arrivalRuntime.InfantryShotWindup(
                arrivalEnemy.EntityId)?.CompletedTick != null)
            throw new Exception("Co-op rifle ended before its final round.");
        ulong lastRoundTick = secondRoundTick;
        for (int index = 2; index < expectedBatchCount; index++)
        {
            lastRoundTick = rifle.NextRoundEligibleTick(lastRoundTick);
            arrivalRuntime.Advance(lastRoundTick);
            IReadOnlyList<CoopInfantryRoundIntent> rounds = arrivalRuntime
                .InfantryRoundIntents(arrivalEnemy.EntityId);
            if (rounds.Count != index + 1 ||
                rounds[index].RoundIndex != index ||
                rounds[index].Tick != lastRoundTick ||
                rounds[index].ProjectileId <=
                    rounds[index - 1].ProjectileId ||
                rounds[index].Real !=
                    ((expectedRealMask & (1 << index)) != 0))
                throw new Exception("Co-op rifle lost a prepared batch round.");
        }
        ulong afterBatch = rifle.NextRoundEligibleTick(lastRoundTick);
        CoopInfantryShotWindup? completedBatch = arrivalRuntime
            .InfantryShotWindup(arrivalEnemy.EntityId);
        ulong expectedNextShot = lastRoundTick +
            (ulong)Math.Floor(sourceBatch.MinShootTime *
                MatchManifest.TickRate) + 1;
        if (completedBatch?.CompletedTick != lastRoundTick ||
            completedBatch.NextEligibleTick != expectedNextShot)
            throw new Exception("Co-op rifle missed its source batch end.");
        CoopObstacleVolleySnapshot? completedObstacle = arrivalRuntime.ObstacleVolleyState(arrivalEnemy.EntityId);
        if (completedObstacle == null || completedObstacle.HasPendingShot || !completedObstacle.IsCrawling ||
            completedObstacle.NextShotTick != expectedNextShot ||
            completedObstacle.NextPositionTick != preparedObstacle.NextPositionTick)
        {
            throw new Exception("The final obstacle round did not publish one conserved volley clock.");
        }

        arrivalRuntime.Advance(afterBatch);
        if (arrivalRuntime.InfantryRoundIntents(
                arrivalEnemy.EntityId).Count != expectedBatchCount)
            throw new Exception("Co-op rifle exceeded its source batch size.");
        ulong expectedReturnTick = lastRoundTick;
        float crawlDeadline = (float)(lastRoundTick / (double)MatchManifest.TickRate) + 0.5f;
        do
        {
            expectedReturnTick++;
        }
        while ((float)(expectedReturnTick / (double)MatchManifest.TickRate) <= crawlDeadline);
        if (expectedReturnTick + 1 >= Math.Min(expectedNextShot, preparedObstacle.NextPositionTick))
        {
            throw new Exception("The obstacle return fixture needs a stationary interval before the next action.");
        }
        arrivalRuntime.Advance(expectedReturnTick - 1);
        BattleInfantryAnimationFrame? beforeReturn = arrivalRuntime.Snapshot().Coop.EnemySpawns
            .Single(enemy => enemy.EntityId == arrivalEnemy.EntityId).InfantryAnimation;
        if (beforeReturn?.Clips[0].ClipName != "rifle_shot_loop")
        {
            throw new Exception("The last fire pose must persist until the strict crawl deadline expires.");
        }
        arrivalRuntime.Advance(expectedReturnTick);
        BattleInfantryAnimationFrame? crawlFrame = arrivalRuntime.Snapshot().Coop.EnemySpawns
            .Single(enemy => enemy.EntityId == arrivalEnemy.EntityId).InfantryAnimation;
        if (arrivalRuntime.ObstacleCrawlReturnTick(arrivalEnemy.EntityId) != expectedReturnTick ||
            crawlFrame?.SampleTick != expectedReturnTick || crawlFrame.Clips.Count != 1 ||
            crawlFrame.Clips[0].ClipName != "stand_up_crawl" || crawlFrame.Clips[0].TimeSeconds != 0f ||
            crawlFrame.Clips[0].Wrap != BattleInfantryAnimationWrap.ClampForever)
        {
            throw new Exception("Expired obstacle hide time must publish one zero-time clamped crawl frame.");
        }
        arrivalRuntime.Advance(expectedReturnTick + 1);
        BattleInfantryAnimationFrame? advancedCrawl = arrivalRuntime.Snapshot().Coop.EnemySpawns
            .Single(enemy => enemy.EntityId == arrivalEnemy.EntityId).InfantryAnimation;
        if (advancedCrawl?.Clips[0].TimeSeconds != 1f / MatchManifest.TickRate)
        {
            throw new Exception("Obstacle return presentation must advance from its actual consumed timer tick.");
        }
        ulong lastFirstVolleyProjectile = arrivalRuntime.InfantryRoundIntents(arrivalEnemy.EntityId)
            .Max(round => round.ProjectileId);
        arrivalRuntime.Advance(expectedNextShot - 1);
        if (arrivalRuntime.ObstacleVolleyState(arrivalEnemy.EntityId)?.HasPendingShot != false)
        {
            throw new Exception("Obstacle repeated its volley before the source cooldown.");
        }
        ulong expectedPostVolleyMove = Math.Max(preparedObstacle.NextPositionTick, lastRoundTick + 1);
        if (expectedPostVolleyMove < expectedNextShot &&
            arrivalRuntime.ObstacleRepositionStartedTick(arrivalEnemy.EntityId) != expectedPostVolleyMove)
        {
            throw new Exception("An overdue obstacle reposition did not resume after its completed volley.");
        }
        arrivalRuntime.Advance(expectedNextShot);
        CoopInfantryShotWindup? secondObstacleVolley = arrivalRuntime.InfantryShotWindup(arrivalEnemy.EntityId);
        if (secondObstacleVolley == null || secondObstacleVolley.StartTick != expectedNextShot ||
            arrivalRuntime.ObstacleVolleyState(arrivalEnemy.EntityId)?.HasPendingShot != true ||
            arrivalRuntime.InfantryFirstPlayerTarget(arrivalEnemy.EntityId) != targetPlan)
        {
            throw new Exception("Obstacle did not begin its second volley while preserving first-target evidence.");
        }
        ulong secondObstacleRoundTick = secondObstacleVolley.CallbackTick + 1;
        arrivalRuntime.Advance(secondObstacleRoundTick);
        IReadOnlyList<CoopInfantryRoundIntent> secondObstacleRounds =
            arrivalRuntime.InfantryRoundIntents(arrivalEnemy.EntityId);
        if (secondObstacleRounds.Count != 1 || secondObstacleRounds[0].ProjectileId <= lastFirstVolleyProjectile)
        {
            throw new Exception("Repeated obstacle rounds must retain unique match projectile identities.");
        }
        arrivalRuntime.Advance(secondObstacleRoundTick);
        if (arrivalRuntime.InfantryRoundIntents(arrivalEnemy.EntityId).Count != 1)
        {
            throw new Exception("Replaying the second volley tick emitted another round.");
        }
        ulong obstacleDeathTick = secondObstacleRoundTick + 1;
        arrivalRuntime.Advance(obstacleDeathTick);
        if (!arrivalRuntime.ApplyHostEnemyDamage(arrivalEnemy.EntityId,
                heldEnemy.Health, obstacleDeathTick) ||
            arrivalRuntime.ObstacleVolleyState(arrivalEnemy.EntityId) != null ||
            arrivalRuntime.InfantryPointArrival(arrivalEnemy.EntityId) != null ||
            arrivalRuntime.InfantryFirstPlayerTarget(
                arrivalEnemy.EntityId) != null ||
            arrivalRuntime.InfantryShotWindup(
                arrivalEnemy.EntityId) != null ||
            arrivalRuntime.InfantryRoundIntents(
                arrivalEnemy.EntityId).Count != 0 ||
            arrivalRuntime.PlaceFirstAssaulterPlayerTarget(
                arrivalEnemy.EntityId) != null)
            throw new Exception("Dead co-op infantry retained a point-arrival marker.");

        int obstaclePositionDraws = 0;
        var earlyRepositionDestinations = new CoopEnemyDestinationState(
            enemyMap, enemyPointMasks, enemyCombat,
            chooseObstacleFraction: () => obstaclePositionDraws++ switch
            {
                0 => 0.5f,
                1 => 1f,
                _ => 0f
            });
        var earlyRepositionRuntime = new CoopMatchRuntime(coop, catalog,
            spawnPoints, routes, enemyCombat, chooseBehaviour: _ => 0,
            choosePoint: _ => 0,
            enemyDestinations: earlyRepositionDestinations,
            infantryNavigation: infantryNavigation,
            playerWeaponContent: content,
            chooseInfantryShotFraction: () => 0.999f,
            chooseInfantryRepositionFraction: () => 0f,
            chooseInfantryPlayer: _ => 0);
        earlyRepositionRuntime.Admit(firstPlayer);
        earlyRepositionRuntime.Admit(secondPlayer);
        foreach (string playerId in new[] { firstPlayer, secondPlayer })
            earlyRepositionRuntime.Command(playerId, new MatchCommand
            {
                CommandId = 1,
                Ready = new ReadyCommand
                {
                    ManifestHash = earlyRepositionRuntime.ManifestHash
                }
            });
        earlyRepositionRuntime.Advance(expectedArrival);
        BattleCoopEnemySpawn earlyRepositionEnemy = earlyRepositionRuntime
            .Snapshot().Coop.EnemySpawns.First();
        CoopInfantryPointArrival? earlyReposition = earlyRepositionRuntime
            .InfantryPointArrival(earlyRepositionEnemy.EntityId);
        CoopAssignedEnemyDestination? originalObstacle =
            earlyRepositionRuntime.EnemyDestination(
                earlyRepositionEnemy.EntityId);
        if (earlyReposition is not { FirstRepositionTick: not null } ||
            earlyReposition.FirstRepositionTick >=
                earlyReposition.FirstShootEligibleTick)
            throw new Exception("Co-op obstacle did not schedule reposition first.");
        earlyRepositionRuntime.Advance(
            earlyReposition.FirstRepositionTick.Value);
        CoopAssignedEnemyDestination? regeneratedObstacle =
            earlyRepositionRuntime.EnemyDestination(
                earlyRepositionEnemy.EntityId);
        if (originalObstacle == null || regeneratedObstacle == null ||
            regeneratedObstacle.PointComponentFileId !=
                originalObstacle.PointComponentFileId ||
            regeneratedObstacle.Position == originalObstacle.Position ||
            earlyRepositionRuntime.ObstacleRepositionStartedTick(
                earlyRepositionEnemy.EntityId) !=
                earlyReposition.FirstRepositionTick ||
            earlyRepositionRuntime.PlaceWalkingAssaulterHitboxes(
                earlyRepositionEnemy.EntityId).Count != 0)
            throw new Exception("Co-op obstacle did not regenerate its reserved segment position.");
        int drawsAfterFirstReposition = obstaclePositionDraws;
        earlyRepositionRuntime.Advance(firstShootTick);
        BattleCoopEnemySpawn movingObstacle = earlyRepositionRuntime
            .Snapshot().Coop.EnemySpawns.First(enemy =>
                enemy.EntityId == earlyRepositionEnemy.EntityId);
        if (Vector3.Distance(
                new Vector3(movingObstacle.CurrentX, movingObstacle.CurrentY,
                    movingObstacle.CurrentZ), originalObstacle.Position) < 0.01f ||
            earlyRepositionRuntime.InfantryFirstPlayerTarget(
                earlyRepositionEnemy.EntityId) != null)
            throw new Exception("Obstacle reposition neither moved nor closed the old target.");
        ulong secondReposition = earlyReposition.FirstRepositionTick.Value +
            2UL * MatchManifest.TickRate + 1;
        if (earlyRepositionRuntime.NextObstacleRepositionTick(
                earlyRepositionEnemy.EntityId) != secondReposition ||
            secondReposition >= earlyReposition.FirstShootEligibleTick)
            throw new Exception("Obstacle did not schedule its later 2–6 second draw.");
        earlyRepositionRuntime.Advance(secondReposition - 1);
        if (earlyRepositionRuntime.EnemyDestination(
                earlyRepositionEnemy.EntityId)?.Position !=
            regeneratedObstacle.Position)
            throw new Exception("Obstacle repositioned before its second gate.");
        earlyRepositionRuntime.Advance(secondReposition);
        CoopAssignedEnemyDestination? secondObstacle =
            earlyRepositionRuntime.EnemyDestination(
                earlyRepositionEnemy.EntityId);
        if (secondObstacle?.PointComponentFileId !=
                originalObstacle.PointComponentFileId ||
            obstaclePositionDraws <= drawsAfterFirstReposition)
            throw new Exception("Obstacle did not regenerate its reserved point again.");
        ulong? thirdReposition = earlyRepositionRuntime
            .NextObstacleRepositionTick(earlyRepositionEnemy.EntityId);
        if (thirdReposition == null ||
            thirdReposition <= earlyReposition.FirstShootEligibleTick)
            throw new Exception("Obstacle fixture lacks a shot-before-move gate.");
        CoopObstacleVolleyRuntimeTests.VerifyFirstShotAfterReposition(
            earlyRepositionRuntime, earlyRepositionEnemy.EntityId, earlyReposition);

        int cornerSpawnIndex = assaultCandidates.ToList().FindIndex(point =>
            point.ComponentFileId == 1694);
        if (cornerSpawnIndex < 0)
            throw new Exception("Recovered Desert corner spawn is absent.");
        var cornerDestinations = new CoopEnemyDestinationState(
            enemyMap, enemyPointMasks, enemyCombat,
            chooseObstacleFraction: () => 0.5f);
        var cornerRuntime = new CoopMatchRuntime(coop, catalog,
            spawnPoints, routes, enemyCombat,
            chooseBehaviour: _ => 0,
            choosePoint: count => count > cornerSpawnIndex ?
                cornerSpawnIndex : 0,
            enemyDestinations: cornerDestinations,
            infantryNavigation: infantryNavigation,
            playerWeaponContent: content,
            chooseInfantryShotFraction: () => 0.5f,
            chooseInfantryPlayer: _ => 0,
            chooseInfantryShieldRoll: () => 0.5f,
            chooseInfantryBatchSize: (min, _) => min,
            chooseInfantryRealShotRoll: () => 0f,
            // Keep the preparation/interruption fixture at its corner until all three attempts finish.
            chooseEnemyPointChangeSeconds: () => 19);
        cornerRuntime.Admit(firstPlayer);
        cornerRuntime.Admit(secondPlayer);
        foreach (string playerId in new[] { firstPlayer, secondPlayer })
            cornerRuntime.Command(playerId, new MatchCommand
            {
                CommandId = 1,
                Ready = new ReadyCommand
                {
                    ManifestHash = cornerRuntime.ManifestHash
                }
            });
        cornerRuntime.Advance(8);
        BattleCoopEnemySpawn cornerEnemy = cornerRuntime.Snapshot()
            .Coop.EnemySpawns.Single();
        if (cornerEnemy.SpawnComponentFileId != 1694 ||
            cornerDestinations.PointTypeFor(cornerEnemy.EntityId) !=
                "EnemyPointCorner")
            throw new Exception("Co-op corner fixture selected a different point.");
        CoopAssignedEnemyDestination cornerDestination =
            cornerRuntime.EnemyDestination(cornerEnemy.EntityId) ??
            throw new Exception("Corner Assaulter lacks a destination.");
        ArmyNavMeshCorridor cornerCorridor = infantryNavigation
            .PlanSourceSpawnCorridor(catalog, 0,
                cornerEnemy.SpawnComponentFileId,
                cornerDestination.PointComponentFileId,
                new Vector3(cornerEnemy.CurrentX, cornerEnemy.CurrentY,
                    cornerEnemy.CurrentZ), cornerDestination.Position) ??
            throw new Exception("Corner Assaulter lacks a host path.");
        var cornerPath = new CoopInfantryPathState(cornerCorridor,
            enemyCombat.MovementSpeed("Assaulter"), firstTick: 8);
        ulong cornerArrivalTick = Enumerable.Range(9, 291)
            .Select(value => (ulong)value).First(candidate =>
                Vector2.Distance(new Vector2(
                    cornerPath.PositionAt(candidate).X,
                    cornerPath.PositionAt(candidate).Z),
                    new Vector2(cornerDestination.Position.X,
                        cornerDestination.Position.Z)) < 0.04f);
        cornerRuntime.Advance(cornerArrivalTick + 14);
        if (cornerRuntime.PlaceSettledCornerAssaulterHitboxes(
                cornerEnemy.EntityId).Count != 0)
            throw new Exception("Corner hitboxes appeared during the source tween.");
        cornerRuntime.Advance(cornerArrivalTick + 15);
        IReadOnlyList<PlayerHitbox> settledCorner = cornerRuntime
            .PlaceSettledCornerAssaulterHitboxes(cornerEnemy.EntityId);
        BattleCoopEnemySpawn settledCornerEnemy = cornerRuntime.Snapshot()
            .Coop.EnemySpawns.Single(enemy =>
                enemy.EntityId == cornerEnemy.EntityId);
        CoopEnemyPoint cornerPoint = cornerDestinations.PointFor(
            cornerEnemy.EntityId) ??
            throw new Exception("Settled corner lost its source point.");
        CoopEnemyCollisionFrame cornerFrame = cornerRuntime
            .CurrentEnemyCollisionFrame();
        if (settledCorner.Count != 3 ||
            settledCornerEnemy.CurrentX != cornerPoint.Position.X ||
            settledCornerEnemy.CurrentZ != cornerPoint.Position.Z ||
            settledCornerEnemy.PoseTick != cornerArrivalTick + 15 ||
            cornerFrame.Targets.Count(target =>
                target.EntityId == cornerEnemy.EntityId) != 3 ||
            !cornerFrame.UnplacedEnemyIds.Contains(cornerEnemy.EntityId))
            throw new Exception("Settled corner pose lost its diagnostic-only gate.");
        using (JsonDocument cornerAudit = JsonDocument.Parse(File.ReadAllText(
            Path.Combine(directory, "coop-corner-idle-unity-reference.json"))))
        {
            float fixtureRootY = cornerAudit.RootElement
                .GetProperty("position")[1].GetSingle();
            JsonElement[] unityParts = cornerAudit.RootElement
                .GetProperty("samples")[0].GetProperty("parts")
                .EnumerateArray().ToArray();
            for (int index = 0; index < unityParts.Length; index++)
            {
                JsonElement center = unityParts[index].GetProperty("center");
                Vector3 unityCenter = new(center[0].GetSingle(),
                    center[1].GetSingle(), center[2].GetSingle());
                // EnemyController keeps the agent's Y when its corner
                // TweenPosition moves X/Z to the source point.
                unityCenter.Y += settledCornerEnemy.CurrentY - fixtureRootY;
                JsonElement rotationValues = unityParts[index]
                    .GetProperty("rotation");
                Quaternion unityRotation = new(rotationValues[0].GetSingle(),
                    rotationValues[1].GetSingle(),
                    rotationValues[2].GetSingle(),
                    rotationValues[3].GetSingle());
                if (Vector3.Distance(settledCorner[index].Center,
                        unityCenter) > 0.0002f ||
                    1 - Math.Abs(Quaternion.Dot(
                        settledCorner[index].Rotation,
                        unityRotation)) > 0.00002f)
                    throw new Exception($"Runtime corner center differs from Unity: " +
                        $"{settledCorner[index].Center} versus {unityCenter}.");
            }
        }
        cornerRuntime.Advance(300);
        CoopInfantryPointArrival? cornerArrival = cornerRuntime
            .InfantryPointArrival(cornerEnemy.EntityId);
        ArmyBaseShotStats cornerShot = content.Army.ComposeShot(
            "ID_UNIT-ASSAULT", cornerEnemy.Level, null, null);
        float cornerDelay = cornerShot.MinShootTime +
            (cornerShot.MaxShootTime - cornerShot.MinShootTime) * 0.5f;
        if (cornerArrival?.State != CoopInfantryPointState.CornerHiding ||
            cornerArrival.PointComponentFileId != 1698 ||
            cornerArrival.Tick is <= 8 or > 300 ||
            cornerArrival.FirstRepositionTick != null ||
            cornerArrival.HasUnchangedObstaclePointForFirstShot ||
            cornerArrival.FirstShootEligibleTick != cornerArrival.Tick +
                (ulong)Math.Floor(cornerDelay * MatchManifest.TickRate) + 1)
            throw new Exception("Co-op corner arrival missed its source state.");
        cornerRuntime.Advance(cornerArrival.FirstShootEligibleTick);
        CoopCornerShotAttempt? cornerAttempt = cornerRuntime
            .CornerFirstShotAttempt(cornerEnemy.EntityId);
        BattleCoopEnemySpawn cornerAtShot = cornerRuntime.Snapshot()
            .Coop.EnemySpawns.Single(enemy =>
                enemy.EntityId == cornerEnemy.EntityId);
        CoopEnemyPoint sourceCorner = enemyMap.Points.Single(point =>
            point.ComponentFileId == cornerArrival.PointComponentFileId);
        bool expectedExposure = cornerAttempt != null &&
            CoopCornerShotPolicy.CanExpose(sourceCorner,
                new Vector3(cornerAtShot.CurrentX, cornerAtShot.CurrentY,
                    cornerAtShot.CurrentZ), cornerAttempt.TargetPosition);
        if (cornerAttempt?.Tick != cornerArrival.FirstShootEligibleTick ||
            cornerAttempt.PlayerId != firstPlayer ||
            cornerAttempt.Exposed != expectedExposure ||
            cornerAttempt.Batch.Count != Math.Clamp(
                cornerShot.FireBatchSizeMin, 0, 14) ||
            (cornerRuntime.InfantryFirstPlayerTarget(cornerEnemy.EntityId)
                != null) != expectedExposure)
            throw new Exception($"Co-op first corner target escaped its source angle gate: eligible={cornerArrival.FirstShootEligibleTick}, attempt={cornerAttempt}, expected={expectedExposure}, plan={cornerRuntime.InfantryFirstPlayerTarget(cornerEnemy.EntityId)}.");
        CoopInfantryShotWindup? coverWindup = cornerRuntime
            .InfantryShotWindup(cornerEnemy.EntityId);
        if (expectedExposure)
        {
            ulong expectedCoverCallback = cornerArrival.FirstShootEligibleTick +
                (ulong)Math.Ceiling((content.EnemyPoses.Clip(
                    "player_look_right3").Length + 0.05f) *
                    MatchManifest.TickRate);
            string expectedLook = sourceCorner.CornerRightSide == true
                ? "player_look_right3" : "player_look_left3";
            string expectedFire = sourceCorner.CornerRightSide == true
                ? "player_fire_right3" : "player_fire_left3";
            if (coverWindup?.AnimationClip != expectedLook ||
                coverWindup.QueuedFireClip != expectedFire ||
                coverWindup.PlayerId != firstPlayer ||
                coverWindup.CallbackTick != expectedCoverCallback ||
                coverWindup.CallbackStartedTick != null)
                throw new Exception("Co-op cover shot lost its source uncover delay.");
        }
        else if (coverWindup != null)
            throw new Exception("Rejected co-op corner started a shot windup.");
        cornerRuntime.Advance(cornerArrival.FirstShootEligibleTick + 2);
        if (cornerRuntime.CornerFirstShotAttempt(cornerEnemy.EntityId)
            != cornerAttempt)
            throw new Exception("Co-op corner retried without a new shot clock.");
        if (coverWindup != null)
        {
            cornerRuntime.Advance(coverWindup.StartTick + 8);
            BattleCoopEnemySpawn beforeTurn = cornerRuntime.Snapshot()
                .Coop.EnemySpawns.Single(enemy =>
                    enemy.EntityId == cornerEnemy.EntityId);
            BattleJointRotation intermediate = beforeTurn.CurrentRotation ??
                throw new Exception("Co-op corner turn lost its intermediate facing.");
            Quaternion cornerStartRotation = Quaternion.CreateFromAxisAngle(
                Vector3.UnitY, MathF.Atan2(
                    -sourceCorner.CornerDirection!.Value.X,
                    -sourceCorner.CornerDirection.Value.Z));
            float progress = 8f / 9f;
            float eased = progress - MathF.Sin(progress * 2f * MathF.PI) /
                (2f * MathF.PI);
            Quaternion expectedIntermediate = Quaternion.Slerp(
                cornerStartRotation, coverWindup.FinalRootRotation, eased);
            Quaternion actualIntermediate = new(intermediate.X,
                intermediate.Y, intermediate.Z, intermediate.W);
            if (beforeTurn.PoseTick != coverWindup.StartTick + 8 ||
                1 - Math.Abs(Quaternion.Dot(actualIntermediate,
                    expectedIntermediate)) > 0.00002f)
                throw new Exception("Co-op corner turn missed its eased frame.");
            if (beforeTurn.InfantryAnimation?.Clips.Count != 1 ||
                beforeTurn.InfantryAnimation.Clips[0].ClipName != coverWindup.AnimationClip ||
                beforeTurn.InfantryAnimation.Clips[0].TimeSeconds != 8f / MatchManifest.TickRate ||
                beforeTurn.InfantryAnimation.SampleTick != coverWindup.StartTick + 8)
            {
                throw new Exception("The first source corner preparation must share the confirmed turn clock.");
            }
            if (cornerRuntime.PlaceCornerUncoverHitboxes(
                    cornerEnemy.EntityId).Count != 3 ||
                cornerRuntime.CurrentEnemyCollisionFrame().Targets.Count(
                    target => target.EntityId == cornerEnemy.EntityId) != 3 ||
                !cornerRuntime.CurrentEnemyCollisionFrame()
                    .UnplacedEnemyIds.Contains(cornerEnemy.EntityId))
                throw new Exception(
                    "Co-op corner uncover escaped its diagnostic gate.");
            cornerRuntime.Advance(coverWindup.StartTick + 9);
            BattleCoopEnemySpawn afterTurn = cornerRuntime.Snapshot()
                .Coop.EnemySpawns.Single(enemy =>
                    enemy.EntityId == cornerEnemy.EntityId);
            BattleJointRotation actual = afterTurn.CurrentRotation ??
                throw new Exception("Co-op corner turn lost its facing.");
            Quaternion actualRotation = new(actual.X, actual.Y,
                actual.Z, actual.W);
            if (afterTurn.PoseTick != coverWindup.StartTick + 9 ||
                1 - Math.Abs(Quaternion.Dot(actualRotation,
                    coverWindup.FinalRootRotation)) > 0.00002f ||
                !cornerRuntime.CurrentEnemyCollisionFrame()
                    .UnplacedEnemyIds.Contains(cornerEnemy.EntityId))
                throw new Exception("Co-op corner turn crossed its diagnostic gate.");
            cornerRuntime.Advance(coverWindup.StartTick + 12);
            if (cornerRuntime.PlaceCornerUncoverHitboxes(
                    cornerEnemy.EntityId).Count != 3 ||
                !cornerRuntime.CurrentEnemyCollisionFrame()
                    .UnplacedEnemyIds.Contains(cornerEnemy.EntityId))
                throw new Exception(
                    "Co-op corner lost the late diagnostic uncover pose.");
            cornerRuntime.Advance(coverWindup.StartTick + 15);
            BattleInfantryAnimationFrame? queuedStart = cornerRuntime.Snapshot().Coop.EnemySpawns
                .Single(enemy => enemy.EntityId == cornerEnemy.EntityId).InfantryAnimation;
            if (queuedStart?.Clips.Count != 1 || queuedStart.Clips[0].ClipName != coverWindup.QueuedFireClip ||
                queuedStart.Clips[0].TimeSeconds != 0f)
            {
                throw new Exception("The first measured queued-fire frame must start at source time zero.");
            }
            cornerRuntime.Advance(coverWindup.StartTick + 17);
            BattleCoopEnemySpawn fireVisual = cornerRuntime.Snapshot().Coop.EnemySpawns
                .Single(enemy => enemy.EntityId == cornerEnemy.EntityId);
            if (fireVisual.InfantryAnimation?.Clips.Count != 1 ||
                fireVisual.InfantryAnimation.Clips[0].ClipName != coverWindup.QueuedFireClip ||
                MathF.Abs(fireVisual.InfantryAnimation.Clips[0].TimeSeconds - 2f / 30f) > 0.0001f)
            {
                throw new Exception("A supported corner queued-fire sample must preserve its source clock.");
            }
            if (cornerRuntime.PlaceCornerUncoverHitboxes(
                    cornerEnemy.EntityId).Count != 0 ||
                cornerRuntime.PlaceCornerFireHitboxes(
                    cornerEnemy.EntityId).Count != 3 ||
                !cornerRuntime.CurrentEnemyCollisionFrame()
                    .UnplacedEnemyIds.Contains(cornerEnemy.EntityId))
                throw new Exception(
                    "Co-op corner fire escaped its diagnostic gate.");
            ulong firstRoundTick = coverWindup.CallbackTick + 1;
            cornerRuntime.Advance(firstRoundTick);
            BattleInfantryAnimationFrame? resetFrame = cornerRuntime.Snapshot().Coop.EnemySpawns
                .Single(enemy => enemy.EntityId == cornerEnemy.EntityId).InfantryAnimation;
            if (resetFrame?.SampleTick != firstRoundTick || resetFrame.Clips[0].ClipName != coverWindup.QueuedFireClip ||
                resetFrame.Clips[0].TimeSeconds != 0f)
            {
                throw new Exception("The current host round must publish its confirmed post-command fire reset.");
            }
            cornerRuntime.Advance(coverWindup.StartTick + 21);
            BattleInfantryAnimationFrame? currentRoundFrame = cornerRuntime.Snapshot().Coop.EnemySpawns
                .Single(enemy => enemy.EntityId == cornerEnemy.EntityId).InfantryAnimation;
            IReadOnlyList<CoopInfantryRoundIntent> currentRounds = cornerRuntime.InfantryRoundIntents(cornerEnemy.EntityId);
            if (currentRoundFrame?.Clips[0].TimeSeconds !=
                (cornerRuntime.Snapshot().ServerTick - currentRounds[^1].Tick) / (float)MatchManifest.TickRate)
            {
                throw new Exception("Confirmed firing presentation must follow the latest source notification.");
            }
            if (cornerRuntime.PlaceCornerFireHitboxes(
                    cornerEnemy.EntityId).Count != 3)
                throw new Exception("Co-op corner fire ended before cover return.");
            cornerRuntime.Advance(coverWindup.StartTick + 22);
            if (cornerRuntime.PlaceCornerFireHitboxes(
                    cornerEnemy.EntityId).Count != 3 ||
                cornerRuntime.PlaceCornerCoverBackHitboxes(
                    cornerEnemy.EntityId).Count != 0 ||
                !cornerRuntime.CurrentEnemyCollisionFrame()
                    .UnplacedEnemyIds.Contains(cornerEnemy.EntityId))
                throw new Exception("Co-op corner returned to cover before its round timer.");
            ulong finalCornerRound = coverWindup.CallbackTick + 1;
            for (int index = 1; index < coverWindup.Batch.Count; index++)
                finalCornerRound = rifle.NextRoundEligibleTick(
                    finalCornerRound);
            if (finalCornerRound > coverWindup.StartTick + 22)
                cornerRuntime.Advance(finalCornerRound);
            if (cornerRuntime.InfantryShotWindup(
                    cornerEnemy.EntityId)?.CompletedTick != finalCornerRound)
                throw new Exception("Co-op corner batch missed its final round.");
            ulong coverReturnTick = finalCornerRound + 16;
            cornerRuntime.Advance(coverReturnTick - 1);
            if (cornerRuntime.PlaceCornerFireHitboxes(
                    cornerEnemy.EntityId).Count != 3 ||
                cornerRuntime.PlaceCornerCoverBackHitboxes(
                    cornerEnemy.EntityId).Count != 0)
                throw new Exception("Co-op corner cover return started too early.");
            cornerRuntime.Advance(coverReturnTick);
            BattleCoopEnemySpawn returnVisual = cornerRuntime.Snapshot().Coop.EnemySpawns
                .Single(enemy => enemy.EntityId == cornerEnemy.EntityId);
            if (returnVisual.InfantryAnimation?.Clips[0].ClipName !=
                    (coverWindup.AnimationClip == "player_look_right3"
                        ? "player_right_coverBack3" : "player_left_coverBack3") ||
                returnVisual.InfantryAnimation.Clips[0].TimeSeconds != 0f)
            {
                throw new Exception("Confirmed cover return must project its source Play epoch.");
            }
            if (cornerRuntime.PlaceCornerCoverBackHitboxes(
                    cornerEnemy.EntityId).Count != 3 ||
                !cornerRuntime.CurrentEnemyCollisionFrame()
                    .UnplacedEnemyIds.Contains(cornerEnemy.EntityId))
                throw new Exception("Co-op corner missed the round-owned cover return.");
            cornerRuntime.Advance(coverReturnTick + 3);
            if (cornerRuntime.PlaceCornerCoverBackHitboxes(
                    cornerEnemy.EntityId).Count != 3)
                throw new Exception("Co-op corner cover return ended too early.");
            cornerRuntime.Advance(coverReturnTick + 4);
            if (cornerRuntime.PlaceCornerCoverBackHitboxes(
                    cornerEnemy.EntityId).Count != 0 ||
                cornerRuntime.PlaceCornerQueuedIdleHitboxes(
                    cornerEnemy.EntityId).Count != 3 ||
                cornerRuntime.CurrentEnemyCollisionFrame().Targets.Count(
                    target => target.EntityId == cornerEnemy.EntityId) != 3 ||
                !cornerRuntime.CurrentEnemyCollisionFrame()
                    .UnplacedEnemyIds.Contains(cornerEnemy.EntityId))
                throw new Exception(
                    "Co-op corner queued blend escaped its diagnostic gate.");
            if (cornerRuntime.ObserveIdleAssaulterMuzzle(
                    cornerEnemy.EntityId) != null)
                throw new Exception(
                    "Co-op corner selected an idle muzzle during its blend.");
            cornerRuntime.Advance(coverReturnTick + 14);
            if (cornerRuntime.PlaceCornerQueuedIdleHitboxes(
                    cornerEnemy.EntityId).Count != 3 ||
                !cornerRuntime.CurrentEnemyCollisionFrame()
                    .UnplacedEnemyIds.Contains(cornerEnemy.EntityId))
                throw new Exception(
                    "Co-op corner lost its captured queued idle pose.");
            cornerRuntime.Advance(coverReturnTick + 31);
            if (cornerRuntime.PlaceCornerQueuedIdleHitboxes(
                    cornerEnemy.EntityId).Count != 3 ||
                !cornerRuntime.CurrentEnemyCollisionFrame()
                    .UnplacedEnemyIds.Contains(cornerEnemy.EntityId))
                throw new Exception(
                    "Co-op corner lost its continued diagnostic idle.");
            string completedCoverClip = coverWindup.AnimationClip ==
                "player_look_right3" ? "player_right_coverBack3" :
                "player_left_coverBack3";
            float? resumedIdleSeconds = content.CoopCornerQueuePoses
                .PureIdleSeconds(completedCoverClip, 31);
            BattleCoopEnemySpawn resumedEnemy = cornerRuntime.Snapshot()
                .Coop.EnemySpawns.Single(enemy =>
                    enemy.EntityId == cornerEnemy.EntityId);
            if (resumedEnemy.InfantryAnimation?.Clips.Count != 1 ||
                resumedEnemy.InfantryAnimation.Clips[0].ClipName != "idle")
            {
                throw new Exception("Completed source return must keep its actual idle alias for presentation.");
            }
            BattleJointRotation resumedFacing =
                resumedEnemy.CurrentRotation!;
            CoopMuzzlePose expectedResumedMuzzle = content.CoopEnemyMuzzles
                .Place("idle_1", new Vector3(resumedEnemy.CurrentX,
                    resumedEnemy.CurrentY, resumedEnemy.CurrentZ),
                    new Quaternion(resumedFacing.X, resumedFacing.Y,
                        resumedFacing.Z, resumedFacing.W),
                    resumedIdleSeconds!.Value);
            CoopMuzzlePose? resumedMuzzle = cornerRuntime
                .ObserveIdleAssaulterMuzzle(cornerEnemy.EntityId);
            if (content.CoopCornerQueuePoses.PureIdleSeconds(
                    completedCoverClip, 29) != null ||
                resumedMuzzle == null ||
                Vector3.Distance(resumedMuzzle.Position,
                    expectedResumedMuzzle.Position) > 0.00001f)
                throw new Exception(
                    "Co-op corner did not resume its queued idle muzzle.");
            ulong nextCornerShot = cornerRuntime.InfantryShotWindup(
                    cornerEnemy.EntityId)?.NextEligibleTick ??
                throw new Exception("Co-op corner lost its next shot clock.");
            IReadOnlyList<CoopInfantryRoundIntent> firstVolley =
                cornerRuntime.InfantryRoundIntents(cornerEnemy.EntityId);
            BattleJointRotation facingBeforeSecondVolley = cornerRuntime
                .Snapshot().Coop.EnemySpawns.Single(enemy =>
                    enemy.EntityId == cornerEnemy.EntityId).CurrentRotation ??
                throw new Exception("Co-op corner lost its second-volley facing.");
            cornerRuntime.Advance(nextCornerShot);
            CoopInfantryShotWindup? secondWindup = cornerRuntime
                .InfantryShotWindup(cornerEnemy.EntityId);
            if (secondWindup?.StartTick != nextCornerShot ||
                secondWindup.CompletedTick != null ||
                cornerRuntime.CornerLatestShotAttempt(
                    cornerEnemy.EntityId)?.Tick != nextCornerShot ||
                cornerRuntime.InfantryRoundIntents(
                    cornerEnemy.EntityId).Count != 0 ||
                Quaternion.Dot(secondWindup.StartRootRotation,
                    new Quaternion(facingBeforeSecondVolley.X,
                        facingBeforeSecondVolley.Y,
                        facingBeforeSecondVolley.Z,
                        facingBeforeSecondVolley.W)) < 0.99999f)
                throw new Exception(
                    "Co-op corner did not restart a fresh volley from its current facing.");
            if (cornerRuntime.PlaceCornerQueuedIdleHitboxes(
                    cornerEnemy.EntityId).Count != 0)
                throw new Exception(
                    "Co-op corner reused idle past its next shot deadline.");
            cornerRuntime.Advance(secondWindup.StartTick + 1);
            BattleInfantryAnimationFrame? laterPreparation = cornerRuntime.Snapshot().Coop.EnemySpawns.Single(enemy =>
                enemy.EntityId == cornerEnemy.EntityId).InfantryAnimation;
            if (laterPreparation?.Clips[0].ClipName != secondWindup.AnimationClip ||
                laterPreparation.Clips[0].TimeSeconds != 1f / MatchManifest.TickRate)
            {
                throw new Exception("A later attempt from confirmed idle must retain its captured preparation plan.");
            }
            cornerRuntime.Advance(secondWindup.CallbackTick + 1);
            IReadOnlyList<CoopInfantryRoundIntent> secondVolley =
                cornerRuntime.InfantryRoundIntents(cornerEnemy.EntityId);
            if (firstVolley.Count != coverWindup.Batch.Count ||
                secondVolley.Count != 1 ||
                secondVolley[0].RoundIndex != 0 ||
                secondVolley[0].ProjectileId <= firstVolley[^1].ProjectileId)
                throw new Exception(
                    "Co-op corner reused its first volley or projectile identity.");
            CoopCornerPreparationPlanTests.VerifyRuntimeInterruption(cornerRuntime,
                cornerEnemy.EntityId, rifle, content.EnemyPoses);
        }

        // Flip only the test point's exposed side when needed so this
        // otherwise identical fixture exercises CornerHidingUpdate's
        // rejected-angle retry. Production maps remain digest-pinned.
        bool rejectedSide = cornerAttempt.Exposed
            ? !sourceCorner.CornerRightSide!.Value
            : sourceCorner.CornerRightSide!.Value;
        CoopMapEnemyPoints rejectedMap = enemyMap with
        {
            Points = enemyMap.Points.Select(point =>
                point.ComponentFileId == sourceCorner.ComponentFileId
                    ? point with { CornerRightSide = rejectedSide }
                    : point).ToArray()
        };
        var rejectedDestinations = new CoopEnemyDestinationState(
            rejectedMap, enemyPointMasks, enemyCombat,
            chooseObstacleFraction: () => 0.5f,
            chooseNextPoint: _ => 0);
        CoopMatchRuntime CreateReadyCornerRuntime(
            CoopEnemyDestinationState destinations,
            Func<int, int>? choosePlayer = null)
        {
            var result = new CoopMatchRuntime(coop, catalog,
                spawnPoints, routes, enemyCombat,
                chooseBehaviour: _ => 0,
                choosePoint: count => count > cornerSpawnIndex
                    ? cornerSpawnIndex : 0,
                enemyDestinations: destinations,
                infantryNavigation: infantryNavigation,
                playerWeaponContent: content,
                chooseInfantryShotFraction: () => 0.5f,
                chooseInfantryPlayer: choosePlayer ?? (_ => 0),
                chooseInfantryShieldRoll: () => 0.5f,
                chooseEnemyPointChangeSeconds: () => 10,
                chooseInfantryBatchSize: (min, _) => min,
                chooseInfantryRealShotRoll: () => 0.999f);
            result.Admit(firstPlayer);
            result.Admit(secondPlayer);
            foreach (string playerId in new[] { firstPlayer, secondPlayer })
                result.Command(playerId, new MatchCommand
                {
                    CommandId = 1,
                    Ready = new ReadyCommand
                    {
                        ManifestHash = result.ManifestHash
                    }
                });
            return result;
        }
        var repeatMovingDestinations = new CoopEnemyDestinationState(
            enemyMap, enemyPointMasks, enemyCombat,
            chooseObstacleFraction: () => 0.5f);
        CoopMatchRuntime repeatMovingRuntime = CreateReadyCornerRuntime(
            repeatMovingDestinations);
        repeatMovingRuntime.Advance(8);
        ulong repeatMovingEnemyId = repeatMovingRuntime.Snapshot()
            .Coop.EnemySpawns.Single().EntityId;
        repeatMovingRuntime.Advance(
            cornerArrival.FirstShootEligibleTick);
        CoopInfantryShotWindup repeatFirstWindup = repeatMovingRuntime
            .InfantryShotWindup(repeatMovingEnemyId) ??
            throw new Exception("Repeated walking fixture missed its first volley.");
        ulong repeatFinalRound = repeatFirstWindup.CallbackTick + 1;
        for (int index = 1; index < repeatFirstWindup.Batch.Count; index++)
            repeatFinalRound = rifle.NextRoundEligibleTick(
                repeatFinalRound);
        repeatMovingRuntime.Advance(repeatFinalRound);
        ulong repeatMovingShot = repeatMovingRuntime.InfantryShotWindup(
                repeatMovingEnemyId)?.NextEligibleTick ??
            throw new Exception("Repeated walking fixture lost its cooldown.");
        repeatMovingRuntime.Advance(repeatMovingShot - 3);
        if (repeatMovingRuntime.Command(firstPlayer, new MatchCommand
            {
                CommandId = 2,
                MoveCover = new MoveCoverCommand { Direction = 1 }
            }).Code != "moving")
            throw new Exception(
                "Repeated walking fixture did not lock another cover.");
        repeatMovingRuntime.Advance(repeatMovingShot);
        CoopInfantryShotWindup? repeatWalkingWindup = repeatMovingRuntime
            .InfantryShotWindup(repeatMovingEnemyId);
        if (repeatWalkingWindup?.StartTick != repeatMovingShot ||
            repeatWalkingWindup.TargetWasWalking != true)
            throw new Exception(
                "Repeated corner volley did not select its moving ally.");
        repeatMovingRuntime.Advance(repeatWalkingWindup.CallbackTick);
        if (repeatMovingRuntime.InfantryShotWindup(
                repeatMovingEnemyId)?.CallbackAimReady != true)
            throw new Exception(
                "Repeated corner volley lost its queued callback aim.");
        int cornerTargetChoices = 0;
        var changingTargetDestinations = new CoopEnemyDestinationState(
            enemyMap, enemyPointMasks, enemyCombat,
            chooseObstacleFraction: () => 0.5f);
        CoopMatchRuntime changingTargetRuntime = CreateReadyCornerRuntime(
            changingTargetDestinations,
            _ => cornerTargetChoices++ == 0 ? 0 : 1);
        changingTargetRuntime.Advance(8);
        ulong changingTargetEnemyId = changingTargetRuntime.Snapshot()
            .Coop.EnemySpawns.Single().EntityId;
        changingTargetRuntime.Advance(cornerArrival.FirstShootEligibleTick);
        CoopInfantryShotWindup firstChangingWindup =
            changingTargetRuntime.InfantryShotWindup(
                changingTargetEnemyId) ??
            throw new Exception("Co-op changing-target corner did not start.");
        ulong changingFinalRound = firstChangingWindup.CallbackTick + 1;
        for (int index = 1; index < firstChangingWindup.Batch.Count; index++)
            changingFinalRound = rifle.NextRoundEligibleTick(
                changingFinalRound);
        changingTargetRuntime.Advance(changingFinalRound);
        ulong changingNextShot = changingTargetRuntime.InfantryShotWindup(
                changingTargetEnemyId)?.NextEligibleTick ??
            throw new Exception("Co-op changing-target corner lost cooldown.");
        changingTargetRuntime.Advance(changingNextShot);
        CoopCornerShotAttempt? changedTargetAttempt = changingTargetRuntime
            .CornerLatestShotAttempt(changingTargetEnemyId);
        // Other source-ready enemies may choose players in the same runtime; assert this corner's own history below.
        if (cornerTargetChoices < 2 ||
            changedTargetAttempt?.Tick != changingNextShot ||
            changedTargetAttempt.PlayerId != secondPlayer ||
            changingTargetRuntime.CornerFirstShotAttempt(
                changingTargetEnemyId)?.PlayerId != firstPlayer ||
            changingTargetRuntime.InfantryFirstPlayerTarget(
                changingTargetEnemyId)?.PlayerId != firstPlayer)
            throw new Exception(
                $"Co-op corner target mismatch: choices={cornerTargetChoices}, " +
                $"attempt={changedTargetAttempt?.Tick}/{changedTargetAttempt?.PlayerId}, " +
                $"expected={changingNextShot}/{secondPlayer}, " +
                $"first={changingTargetRuntime.CornerFirstShotAttempt(changingTargetEnemyId)?.PlayerId}.");
        CoopInfantryShotWindup? changedTargetWindup = changingTargetRuntime
            .InfantryShotWindup(changingTargetEnemyId);
        if (changedTargetAttempt.Exposed &&
            (changedTargetWindup?.PlayerId != secondPlayer ||
             changedTargetWindup.StartTick != changingNextShot))
            throw new Exception(
                "Co-op corner did not wind up for its newly selected target.");
        if (!changedTargetAttempt.Exposed &&
            (changedTargetWindup?.StartTick == changingNextShot ||
             changedTargetAttempt.NextEligibleTick <= changingNextShot))
            throw new Exception(
                "Co-op corner ignored the newly selected target's angle rejection.");

        var noTargetDestinations = new CoopEnemyDestinationState(
            enemyMap, enemyPointMasks, enemyCombat,
            chooseObstacleFraction: () => 0.5f);
        CoopMatchRuntime noTargetRuntime = CreateReadyCornerRuntime(
            noTargetDestinations);
        noTargetRuntime.Advance(8);
        ulong noTargetEnemyId = noTargetRuntime.Snapshot()
            .Coop.EnemySpawns.Single().EntityId;
        ulong noTargetShotTick = cornerArrival.FirstShootEligibleTick;
        noTargetRuntime.Advance(noTargetShotTick - 1);
        // Both dead would end the mission. Keep its master alive but in the unsampled movement-start frame.
        PlayerDamageResult? noTargetPeerDeath = noTargetRuntime.ApplyHostPlayerDamage(
            1, secondPlayer, new ResolvedPlayerDamage(1_000_000,
                CombatDamageType.Basic, HasWeapon: false), 1f, noTargetShotTick - 1);
        if (noTargetPeerDeath?.Dead != true || noTargetRuntime.Command(firstPlayer, new MatchCommand
            {
                CommandId = 2,
                MoveCover = new MoveCoverCommand { Direction = 1, TargetCoverIndex = 2 }
            }).Code != "moving")
        {
            throw new Exception("Co-op no-target fixture requires a living master entering the released peer cover.");
        }
        noTargetRuntime.Advance(noTargetShotTick);
        ulong noTargetRetry = noTargetRuntime.CornerNoTargetRetryTick(
                noTargetEnemyId) ??
            throw new Exception("Co-op corner did not delay after no target.");
        ulong expectedNoTargetRetry = noTargetShotTick +
            (ulong)Math.Floor(cornerDelay * MatchManifest.TickRate) + 1;
        if (noTargetRetry != expectedNoTargetRetry ||
            noTargetRuntime.CornerLatestShotAttempt(noTargetEnemyId) != null)
            throw new Exception(
                "Co-op corner treated missing target as an angle attempt.");
        noTargetRuntime.Advance(noTargetRetry - 1);
        if (noTargetRuntime.CornerNoTargetRetryTick(noTargetEnemyId) !=
            noTargetRetry)
            throw new Exception("Co-op corner retried an absent target early.");
        noTargetRuntime.Advance(noTargetRetry);
        CoopCornerShotAttempt? recoveredTarget = noTargetRuntime.CornerLatestShotAttempt(noTargetEnemyId);
        if (noTargetRuntime.CornerNoTargetRetryTick(noTargetEnemyId) != null ||
            recoveredTarget?.Tick != noTargetRetry || recoveredTarget.PlayerId != firstPlayer)
            throw new Exception(
                "Co-op corner did not resume target selection at the exact retry after the master's pose returned.");

        CoopMatchRuntime rejectedRuntime =
            CreateReadyCornerRuntime(rejectedDestinations);
        rejectedRuntime.Advance(8);
        ulong rejectedEntityId = rejectedRuntime.Snapshot()
            .Coop.EnemySpawns.Single().EntityId;
        rejectedRuntime.Advance(cornerArrival.FirstShootEligibleTick);
        CoopCornerShotAttempt? rejectedFirst = rejectedRuntime
            .CornerFirstShotAttempt(rejectedEntityId);
        ulong expectedRetry = cornerArrival.FirstShootEligibleTick +
            (ulong)Math.Floor(cornerDelay * MatchManifest.TickRate) + 1;
        if (rejectedFirst?.Exposed != false ||
            rejectedFirst.NextEligibleTick != expectedRetry ||
            rejectedFirst.Batch.Count != Math.Clamp(
                cornerShot.FireBatchSizeMin, 0, 14) ||
            rejectedFirst.Batch.RealShotMask !=
                (0.999f < cornerShot.ProbabilityOfRealShot
                    ? (1 << rejectedFirst.Batch.Count) - 1 : 0) ||
            rejectedRuntime.InfantryFirstPlayerTarget(rejectedEntityId) != null)
            throw new Exception("Rejected co-op corner angle did not schedule a retry.");
        rejectedRuntime.Advance(expectedRetry - 1);
        if (rejectedRuntime.CornerLatestShotAttempt(rejectedEntityId) !=
            rejectedFirst)
            throw new Exception("Co-op corner retried before the strict shot gate.");
        rejectedRuntime.Advance(expectedRetry);
        CoopCornerShotAttempt? retriedCorner = rejectedRuntime
            .CornerLatestShotAttempt(rejectedEntityId);
        if (retriedCorner?.Tick != expectedRetry ||
            retriedCorner.Exposed ||
            retriedCorner.NextEligibleTick <= expectedRetry ||
            rejectedRuntime.CornerFirstShotAttempt(rejectedEntityId) !=
                rejectedFirst)
            throw new Exception("Co-op corner did not retry its rejected target.");
        ulong expectedChange = cornerArrival.Tick +
            10UL * MatchManifest.TickRate + 1;
        if (rejectedRuntime.NextCornerChangeTick(rejectedEntityId) !=
            expectedChange)
            throw new Exception("Co-op corner change clock missed the source draw.");
        rejectedRuntime.Advance(expectedChange - 1);
        if (rejectedDestinations.ForEnemy(rejectedEntityId)?
            .PointComponentFileId != sourceCorner.ComponentFileId)
            throw new Exception("Co-op corner released its point before change time.");
        rejectedRuntime.Advance(expectedChange);
        CoopAssignedEnemyDestination? changedPoint =
            rejectedDestinations.ForEnemy(rejectedEntityId);
        if (changedPoint == null ||
            changedPoint.PointComponentFileId == sourceCorner.ComponentFileId ||
            rejectedRuntime.InfantryPointArrival(rejectedEntityId) != null ||
            rejectedRuntime.NextCornerChangeTick(rejectedEntityId) != null)
            throw new Exception("Co-op corner did not reserve a new walking point.");

        // A one-point test map leaves no different candidate. The first
        // failed change keeps the same reservation and extends the original
        // threshold by ten seconds; it must not retry on every frame.
        CoopMapEnemyPoints loneCornerMap = rejectedMap with
        {
            Points = [rejectedMap.Points.Single(point =>
                point.ComponentFileId == sourceCorner.ComponentFileId)]
        };
        var loneCornerDestinations = new CoopEnemyDestinationState(
            loneCornerMap, enemyPointMasks, enemyCombat,
            chooseObstacleFraction: () => 0.5f,
            chooseNextPoint: _ => 0);
        CoopMatchRuntime loneCornerRuntime =
            CreateReadyCornerRuntime(loneCornerDestinations);
        loneCornerRuntime.Advance(8);
        ulong loneCornerEnemyId = loneCornerRuntime.Snapshot()
            .Coop.EnemySpawns.Single().EntityId;
        loneCornerRuntime.Advance(expectedChange);
        ulong secondChange = expectedChange +
            10UL * MatchManifest.TickRate;
        if (loneCornerRuntime.NextCornerChangeTick(loneCornerEnemyId) !=
                secondChange ||
            loneCornerDestinations.ForEnemy(loneCornerEnemyId)?
                .PointComponentFileId != sourceCorner.ComponentFileId)
            throw new Exception("Co-op corner lost its point when none was free.");
        loneCornerRuntime.Advance(secondChange - 1);
        if (loneCornerRuntime.NextCornerChangeTick(loneCornerEnemyId) !=
            secondChange)
            throw new Exception("Co-op corner retried its change too early.");
        loneCornerRuntime.Advance(secondChange);
        if (loneCornerRuntime.NextCornerChangeTick(loneCornerEnemyId) !=
                secondChange + 10UL * MatchManifest.TickRate ||
            loneCornerDestinations.ForEnemy(loneCornerEnemyId)?
                .PointComponentFileId != sourceCorner.ComponentFileId)
            throw new Exception("Co-op corner did not defer its next change.");

        MissionRule rusherRule = catalog.Get(2);
        MissionMapRule rusherMissionMap = catalog.MapForMission(2);
        MatchManifest rusherAllocation = coop with
        {
            MissionIndex = 2,
            MapId = rusherMissionMap.Scene,
            MapRevision = rusherMissionMap.SceneSha256,
            DurationSeconds = rusherRule.TimeSeconds
        };
        CoopMapRusherPoints rusherMap = rusherPointCatalog.MapForMission(
            catalog, 2);
        var rusherDestinations = new CoopEnemyDestinationState(enemyMap,
            enemyPointMasks, enemyCombat, rusherPoints: rusherMap);
        var rusherRuntime = new CoopMatchRuntime(rusherAllocation, catalog,
            spawnPoints, routes, enemyCombat,
            chooseBehaviour: _ => 3, choosePoint: _ => 0,
            enemyDestinations: rusherDestinations,
            chooseRusherPlayer: _ => 1);
        rusherRuntime.Admit(firstPlayer);
        rusherRuntime.Admit(secondPlayer);
        foreach (string playerId in new[] { firstPlayer, secondPlayer })
            rusherRuntime.Command(playerId, new MatchCommand
            {
                CommandId = 1,
                Ready = new ReadyCommand
                {
                    ManifestHash = rusherRuntime.ManifestHash
                }
            });
        rusherRuntime.Advance(8);
        BattleCoopEnemySpawn rusherEnemy = rusherRuntime.Snapshot()
            .Coop.EnemySpawns.Single();
        CoopAssignedEnemyDestination? rusherDestination =
            rusherRuntime.EnemyDestination(rusherEnemy.EntityId);
        int secondAllyCover = rusherRuntime.Snapshot().Players.Single(
            player => player.PlayerId == secondPlayer).CoverIndex;
        if (rusherEnemy.Behaviour != "Shotgunner" ||
            rusherDestination == null ||
            !rusherMap.PlayerPoints[secondAllyCover].Points.Any(point =>
                point.ComponentFileId ==
                    rusherDestination.PointComponentFileId) ||
            !rusherRuntime.ApplyHostEnemyDamage(rusherEnemy.EntityId,
                rusherEnemy.Health, 8) ||
            rusherRuntime.EnemyDestination(rusherEnemy.EntityId) != null)
            throw new Exception("Host Rusher did not reserve and release the selected allied shield point.");
        var claimedRusherIds = new HashSet<int>();
