            PlayerId = firstPlayer,
            ManifestHash = udpRuntime.ManifestHash,
            SessionId = 901,
            IssuedUnixSeconds = 10,
            ExpiresUnixSeconds = 100
        };
        var hello = new Packet
        {
            Version = 1,
            SessionId = claims.SessionId,
            Sequence = 1,
            MatchHello = new MatchHello { Ticket = tokens.Sign(claims) }
        };
        byte[] authenticatedHello = PacketCodec.Encode(hello, tokens.SessionKey(claims));
        var peer = new IPEndPoint(IPAddress.Loopback, 40111);
        if (udpEndpoint.Handle(hello, authenticatedHello, peer, 11) == null ||
            !udpRuntime.Snapshot().Players[0].Admitted)
            throw new Exception("A signed co-op hello must reach its isolated runtime.");

        MatchAdmission secondClaims = claims.Clone();
        secondClaims.PlayerId = secondPlayer;
        secondClaims.SessionId = 902;
        byte[] firstKey = tokens.SessionKey(claims);
        byte[] secondKey = tokens.SessionKey(secondClaims);
        var secondPeer = new IPEndPoint(IPAddress.Loopback, 40112);
        Packet Send(MatchAdmission admission, byte[] key, IPEndPoint sender,
            ulong sequence, MatchCommand? command)
        {
            var request = new Packet
            {
                Version = 1,
                SessionId = admission.SessionId,
                Sequence = sequence
            };
            if (command == null)
                request.MatchHello = new MatchHello { Ticket = tokens.Sign(admission) };
            else
                request.MatchCommand = command;
            byte[]? response = udpEndpoint.Handle(request,
                PacketCodec.Encode(request, key), sender, 11);
            if (response == null || !PacketCodec.Authenticate(response, key))
                throw new Exception("An authenticated co-op UDP command had no valid reply.");
            return PacketCodec.ReadUntrusted(response) ??
                throw new Exception("An authenticated co-op UDP reply was malformed.");
        }
        if (Send(secondClaims, secondKey, secondPeer, 1, null).MatchReply.Code != "admitted")
            throw new Exception("The second signed ally must join the same co-op endpoint.");
        var udpReady = new MatchCommand { CommandId = 1,
            Ready = new ReadyCommand { ManifestHash = udpRuntime.ManifestHash } };
        if (Send(claims, firstKey, peer, 2, udpReady).MatchReply.Code != "ready" ||
            Send(secondClaims, secondKey, secondPeer, 2, udpReady).MatchReply.Code != "ready")
            throw new Exception("Both UDP allies must make the co-op mission ready.");
        var mismatchedUdpMove = new MatchCommand { CommandId = 2,
            MoveCover = new MoveCoverCommand
            { Direction = 1, TargetCoverIndex = 2 } };
        if (Send(claims, firstKey, peer, 3,
                mismatchedUdpMove).MatchReply.Code !=
            "cover-target-mismatch")
            throw new Exception("UDP discarded the asserted co-op shield identity.");
        var udpMove = new MatchCommand { CommandId = 3,
            MoveCover = new MoveCoverCommand
            { Direction = 1, TargetCoverIndex = 3 } };
        var secondUdpMove = new MatchCommand { CommandId = 2,
            MoveCover = new MoveCoverCommand { Direction = 1 } };
        if (Send(claims, firstKey, peer, 4, udpMove).MatchReply.Code != "moving" ||
            Send(secondClaims, secondKey, secondPeer, 3,
                secondUdpMove).MatchReply.Code !=
                "cover-unavailable")
            throw new Exception("UDP co-op movement must reserve one authoritative shield.");
        udpEndpoint.Advance(2);
        var poll = new MatchCommand { Poll = new PollMatch() };
        MatchSnapshot firstView = Send(claims, firstKey, peer, 5, poll)
            .MatchReply.Snapshot;
        MatchSnapshot secondView = Send(secondClaims, secondKey, secondPeer, 4, poll)
            .MatchReply.Snapshot;
        if (!firstView.ToByteArray().AsSpan().SequenceEqual(secondView.ToByteArray()) ||
            firstView.Players.Single(player => player.PlayerId == firstPlayer).PositionZ <=
                mainAnchors[0].Position.Z ||
            firstView.Players.Single(player => player.PlayerId == secondPlayer).Moving)
            throw new Exception("Both UDP allies must observe the same host-owned movement.");
        RiflePoseState? sharedMovingPose = firstView.Players.Single(player =>
            player.PlayerId == firstPlayer).RiflePose;
        if (sharedMovingPose?.Layers.Count != 1 ||
            sharedMovingPose.Layers[0].Clip != RiflePoseClip.Run ||
            !RiflePoseProjection.ValidWire(sharedMovingPose, 2))
            throw new Exception(
                "Authenticated co-op peers lost the moving ally's run pose.");

        BattlePlayerState stationaryAlly = secondView.Players.Single(player =>
            player.PlayerId == secondPlayer);
        CoopPlayerAnchor stationaryCover = spawnPoints.MapForMission(catalog,
            coop.MissionIndex!.Value).PlayerPositions.Single(anchor =>
                anchor.Index == stationaryAlly.CoverIndex);
        Vector3 stationaryOrigin = new(stationaryAlly.PositionX,
            stationaryAlly.PositionY, stationaryAlly.PositionZ);
        Vector3 stationaryTarget = stationaryOrigin + Vector3.Transform(
            Vector3.UnitZ, stationaryCover.SourceRotation!.Value) * 3;
        if (!udpRuntime.ConfirmHostPlayerShot(secondPlayer,
                stationaryAlly.ActiveWeaponSlot, stationaryTarget, 2))
            throw new Exception("The host could not confirm a stationary co-op shot.");
        udpEndpoint.Advance(3);
        MatchSnapshot firstShotView = Send(claims, firstKey, peer, 6, poll)
            .MatchReply.Snapshot;
        MatchSnapshot secondShotView = Send(secondClaims, secondKey,
            secondPeer, 5, poll).MatchReply.Snapshot;
        RiflePoseState? remoteShotPose = firstShotView.Players.Single(player =>
            player.PlayerId == secondPlayer).RiflePose;
        if (!firstShotView.ToByteArray().AsSpan().SequenceEqual(
                secondShotView.ToByteArray()) ||
            remoteShotPose == null ||
            !RiflePoseProjection.ValidWire(remoteShotPose, 3) ||
            remoteShotPose.Layers.Count != 1 ||
            (int)remoteShotPose.Layers[0].Clip is not (2 or 5))
            throw new Exception(
                "Authenticated co-op peers did not receive the host shot pose.");

        VerifyCoopSdkCoverMove(coop, catalog, spawnPoints, routes,
            enemyCombat, firstPlayer, secondPlayer).GetAwaiter().GetResult();

        var earlyForfeit = new CoopMatchRuntime(coop, catalog, spawnPoints, routes, enemyCombat);
        earlyForfeit.Admit(firstPlayer);
        earlyForfeit.Command(firstPlayer, new MatchCommand
            { CommandId = 1, Forfeit = new ForfeitCommand() });
        if (!earlyForfeit.Terminal || !earlyForfeit.Snapshot().Coop.Failed ||
            earlyForfeit.TerminalEvidenceSnapshot().RewardEligible)
            throw new Exception("A pre-start forfeit must close without reward eligibility.");
        var cancelled = new CoopMatchRuntime(coop, catalog,
            spawnPoints, routes, enemyCombat);
        if (!cancelled.CancelBeforeStart() ||
            cancelled.TerminalEvidenceSnapshot().TerminalReason !=
                "cancelled-before-start")
            throw new Exception("A cancelled co-op allocation was not an abort.");
        var admissionTimeout = new CoopMatchRuntime(coop, catalog,
            spawnPoints, routes, enemyCombat);
        admissionTimeout.Advance((ulong)coop.AdmissionSeconds *
            MatchManifest.TickRate);
        if (admissionTimeout.TerminalEvidenceSnapshot().TerminalReason !=
            "admission-timeout")
            throw new Exception("A co-op admission timeout was not an abort.");
        var hostShutdown = new CoopMatchRuntime(coop, catalog,
            spawnPoints, routes, enemyCombat);
        hostShutdown.Admit(firstPlayer);
        hostShutdown.Admit(secondPlayer);
        hostShutdown.Command(firstPlayer, firstReady);
        hostShutdown.Command(secondPlayer, firstReady);
        if (!hostShutdown.AbortForHostShutdown() ||
            hostShutdown.TerminalEvidenceSnapshot().TerminalReason !=
                "host-shutdown")
            throw new Exception("A running co-op host shutdown was not an abort.");
        return 75 + allocationBindingAssertions;
    }

    private static async Task VerifyCoopSdkCoverMove(MatchManifest manifest,
        MissionCatalog missions, CoopSpawnPointCatalog spawnPoints,
        CoopNavMeshPathCatalog routes, CoopEnemyCombatCatalog enemyCombat,
        string firstPlayer, string secondPlayer)
    {
        string signingKey = Convert.ToBase64String(new byte[32]);
        var runtime = new CoopMatchRuntime(manifest, missions, spawnPoints,
            routes, enemyCombat);
        var endpoint = new MatchEndpoint(manifest, signingKey, runtime, 0);
        var tokens = new MatchTokens(signingKey);
        using var socket = new UdpClient(new IPEndPoint(IPAddress.Loopback, 0));
        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(10));
        int port = ((IPEndPoint)socket.Client.LocalEndPoint!).Port;
        long now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();

        MatchConnectionGrant Grant(string playerId, ulong sessionId)
        {
            var admission = new MatchAdmission
            {
                MatchId = manifest.MatchId,
                PlayerId = playerId,
                ServerId = manifest.ServerId,
                ManifestHash = runtime.ManifestHash,
                SessionId = sessionId,
                IssuedUnixSeconds = now,
                ExpiresUnixSeconds = now + MatchTokens.GrantLifetimeSeconds
            };
            return new MatchConnectionGrant
            {
                Host = "127.0.0.1",
                Port = (uint)port,
                Ticket = tokens.Sign(admission),
                SessionKey = ByteString.CopyFrom(tokens.SessionKey(admission)),
                SessionId = sessionId,
                MatchId = manifest.MatchId,
                PlayerId = playerId,
                ManifestHash = runtime.ManifestHash,
                ExpiresUnixSeconds = admission.ExpiresUnixSeconds
            };
        }

        async Task Serve()
        {
            try
            {
                while (!timeout.IsCancellationRequested)
                {
                    UdpReceiveResult datagram = await socket.ReceiveAsync(timeout.Token);
                    Packet? packet = PacketCodec.ReadUntrusted(datagram.Buffer);
                    if (packet == null) continue;
                    byte[]? reply = endpoint.Handle(packet, datagram.Buffer,
                        datagram.RemoteEndPoint, DateTimeOffset.UtcNow.ToUnixTimeSeconds());
                    if (reply != null)
                        await socket.SendAsync(reply, datagram.RemoteEndPoint,
                            timeout.Token);
                }
            }
            catch (OperationCanceledException) when (timeout.IsCancellationRequested) { }
        }

        Task server = Serve();
        try
        {
            using var first = new MatchConnection(Grant(firstPlayer, 1901));
            using var second = new MatchConnection(Grant(secondPlayer, 1902));
            if ((await first.ConnectAsync(timeout.Token)).Code != "admitted" ||
                (await second.ConnectAsync(timeout.Token)).Code != "admitted" ||
                (await first.ReadyAsync(timeout.Token)).Code != "ready" ||
                (await second.ReadyAsync(timeout.Token)).Code != "ready")
                throw new Exception("Portable SDK peers did not start the co-op match.");

            MatchReply rejected = await first.MoveCoopCoverAsync(1, 2,
                timeout.Token);
            MatchReply accepted = await first.MoveCoopCoverAsync(1, 3,
                timeout.Token);
            if (rejected.Code != "cover-target-mismatch" ||
                accepted.Code != "moving" ||
                !accepted.Snapshot.Players.Single(player =>
                    player.PlayerId == firstPlayer).Moving)
                throw new Exception("Portable SDK lost the requested co-op shield identity.");
        }
        finally
        {
            timeout.Cancel();
            await server;
        }
    }

    private static int VerifyCoopBossAiSpawns(MissionCatalog missions,
        ArmySpawnPointCatalog spawns, IReadOnlyList<RecoveredBattleMap> maps)
    {
        int checkedMissions = 0;
        foreach (MissionRule mission in missions.Missions.Where(
                     rule => rule.MissionType == "KillOpponent"))
        {
            MissionMapRule source = missions.MapForMission(mission.Index);
            RecoveredBattleMap map = maps.Single(candidate =>
                candidate.Source == "Assets/Scenes/" + source.Scene + ".unity");
            var selector = new CoopBossAiSpawnSelector(
                missions, spawns, map, mission.Index);
            foreach (string behaviour in mission.Behaviours.Select(item => item.Name)
                         .Concat(mission.Events.Select(item => item.Behaviour)).Distinct())
            {
                if (selector.Candidates(behaviour).Any(point =>
                        point.Fraction != 1 || point.ComponentFileId <= 0))
                    throw new Exception("Boss AI selected an allied or invalid spawn.");
            }
            checkedMissions++;
        }
        if (checkedMissions != 15)
            throw new Exception("Every source boss mission needs a validated AI spawn map.");

        RecoveredBattleMap wrongMap = maps.Single(map =>
            map.Source == "Assets/Scenes/Snow_Multiplayer.unity");
        try
        {
            _ = new CoopBossAiSpawnSelector(missions, spawns, wrongMap, 4);
            throw new Exception("A boss mission accepted the wrong multiplayer map.");
        }
        catch (InvalidDataException)
        {
            return 16;
        }
    }

    private static int VerifyCoopBotRules(string directory, MissionCatalog missions,
        BattleCombatContent content)
    {
        string path = Path.Combine(directory, "recovered-coop-bot-rules.json");
        CoopBotRuleCatalog bots = CoopBotRuleCatalog.Load(path, missions);
        CoopBotRule first = bots.ForMission(4);
        if (bots.Bots.Count != 15 ||
            bots.Bots.Count(bot => bot.HealthMultiplier == 0) != 6 ||
            first.Name != "Private Pink" || first.Level != 2 ||
            first.HealthMultiplier != 0.8f || first.Cards.Count != 5 ||
            bots.ForMission(74).Name != "General Bad")
            throw new Exception("Source boss missions lost their bot definitions.");
        CoopBotHealthCatalog health = CoopBotHealthCatalog.Load(Path.Combine(
            directory, "recovered-coop-bot-health.json"), missions, bots);
        string attackPath = Path.Combine(directory,
            "recovered-coop-boss-attack-timing.json");
        CoopBossAttackTimingCatalog attacks = CoopBossAttackTimingCatalog.Load(
            attackPath, missions, bots);
        CoopBossLoadoutCatalog loadouts = CoopBossLoadoutCatalog.Load(Path.Combine(
            directory, "recovered-coop-boss-loadouts.json"), missions, bots,
            attacks, content.AllWeaponBindings);
        if (loadouts.Weapons.Count != 66 || loadouts.Missions.Count != 15 ||
            loadouts.ForMission(4).Slots.Select(slot => slot.InventoryIndex)
                .SequenceEqual([11, 2, 5, 12]) == false ||
            loadouts.ForMission(74).Slots.Select(slot => slot.InventoryIndex)
                .SequenceEqual([31, 32, 42, 0]) == false ||
            loadouts.Weapons[0].SheetName != "Google2u.AssaultRifle_M16")
            throw new Exception("Boss weapons differ from the original OBB order.");
        int arsenalAssertions = VerifyCoopBossArsenal(
            directory, loadouts, attacks.ForMission(4));
        if (attacks.Missions.Count != 15 ||
            attacks.ForMission(4).ConfigIndex != 1 ||
            attacks.ForMission(4).PrimaryCategory != "AssaultRifle " ||
            attacks.ForMission(24).SecondaryCategory != "Shotgun" ||
            attacks.ForMission(74).ExplosiveCategory != "RocketLauncher" ||
            attacks.ForMission(4).ShootFrequencyMinSeconds != 3.25f ||
            attacks.ForMission(4).ExplosiveSwitchProbability != 0.05f ||
            attacks.ForMission(4).OpponentShotProbability != 0.105f ||
            attacks.ForMission(4).HeadshotProbability != 0.15f ||
            attacks.ForMission(74).ConfigIndex != 12 ||
            attacks.ForMission(74).ShootAccuracy != 0.565f)
            throw new Exception("Boss attack timing differs from source bot sheets.");
        var readyWeapon = new CoopBossWeaponReadiness(false, false, true, 10);
        var emptyWeapon = new CoopBossWeaponReadiness(true, false, false, 0);
        CoopBossAttackTiming firstTiming = attacks.ForMission(4);
        if (CoopBossWeaponChoice.ForOrdinaryPlayerTarget(firstTiming, false,
                readyWeapon, readyWeapon, readyWeapon, 0.01f, 0.8f) !=
                    CoopBossWeaponSlotKind.Explosive ||
            CoopBossWeaponChoice.ForOrdinaryPlayerTarget(firstTiming, true,
                readyWeapon, readyWeapon, readyWeapon, 0.01f, 0.8f) !=
                    CoopBossWeaponSlotKind.Secondary ||
            CoopBossWeaponChoice.ForOrdinaryPlayerTarget(firstTiming, false,
                emptyWeapon, readyWeapon, emptyWeapon, 0.5f, 0f) !=
                    CoopBossWeaponSlotKind.Secondary ||
            CoopBossWeaponChoice.ForOrdinaryPlayerTarget(firstTiming, false,
                emptyWeapon, emptyWeapon, emptyWeapon, 0.5f, 0f) !=
                    CoopBossWeaponSlotKind.Pistol)
            throw new Exception("Boss ordinary player-target weapon choice changed.");
        try
        {
            _ = CoopBossWeaponChoice.ForOrdinaryPlayerTarget(firstTiming, false,
                readyWeapon, readyWeapon, readyWeapon, float.NaN, 0f);
            throw new Exception("Invalid boss weapon random evidence was accepted.");
        }
        catch (InvalidDataException)
        {
        }
        const string firstAlly = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        const string secondAlly = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
        CoopBossPlayerCandidate[] preferenceCandidates =
        [
            new(firstAlly, 1f, 1f, false, true),
            new(secondAlly, 1f, 1f, false, true)
        ];
        if (CoopBossPlayerPreference.Choose(firstTiming, preferenceCandidates,
                0f, 0.02f) != firstAlly ||
            CoopBossPlayerPreference.Choose(firstTiming, preferenceCandidates,
                0f, 0.07f) != secondAlly ||
            CoopBossPlayerPreference.Choose(firstTiming, preferenceCandidates,
                0f, 0.2f) != null ||
            CoopBossPlayerPreference.Choose(firstTiming,
                [preferenceCandidates[0] with { ShieldHealthRatio = 0f },
                 preferenceCandidates[1]], 0f, 0.1f) != firstAlly)
            throw new Exception("Boss player preference differs from Client weights.");
        try
        {
            _ = CoopBossPlayerPreference.Choose(firstTiming,
                preferenceCandidates, float.NaN, 0.02f);
            throw new Exception("Invalid boss pressure became target authority.");
        }
        catch (InvalidDataException)
        {
        }
        CoopBossPriorityCandidate[] priorityCandidates =
        [
            new("player", 0f, 1f, false, false),
            new("low-danger", 2f, 1f, true, true),
            new("wounded", 2f, 0.25f, true, true),
            new("same-priority", 4f, 0.5f, true, true)
        ];
        string[] priorityOrder = CoopBossPriorityOrder.Sort(priorityCandidates)
            .Select(candidate => candidate.EntityId).ToArray();
        if (!priorityOrder.SequenceEqual(
                ["wounded", "same-priority", "low-danger", "player"]))
            throw new Exception("Boss priority order differs from Client danger/health sorting.");
        try
        {
            _ = CoopBossPriorityOrder.Sort(
                [priorityCandidates[1] with { HealthRatio = float.NaN }]);
            throw new Exception("Invalid boss target health became priority authority.");
        }
        catch (InvalidDataException)
        {
        }
        var firstAttackClock = new CoopBossAttackCadence(
            attacks.ForMission(4), 0, () => 0f);
        if (firstAttackClock.Advance(60) || firstAttackClock.WindowOpen ||
            !firstAttackClock.Advance(61) || !firstAttackClock.WindowOpen ||
            firstAttackClock.WindowEndTick != 85 ||
            !firstAttackClock.Advance(85) || firstAttackClock.WindowOpen ||
            firstAttackClock.NextWindowTick != 183)
            throw new Exception("Boss shot windows differ from source timing bounds.");
        try
        {
            var invalidAttackClock = new CoopBossAttackCadence(
                attacks.ForMission(4), 0, () => 1f);
            invalidAttackClock.Advance(61);
            throw new Exception("An invalid boss attack random draw was accepted.");
        }
        catch (InvalidDataException)
        {
        }
        if (health.PlayerHealthByLevel.Count != 44 ||
            health.PlayerHealthByLevel[0] != 280f ||
            health.ForMission(4).MaximumHealth != 312f * 0.8f ||
            health.ForMission(74).BaseHealth != 2185f ||
            health.Bosses.Count(row => row.MaximumHealth == 0) != 6)
            throw new Exception("Decoded boss health differs from the Client balance table.");
        string anchorPath = Path.Combine(directory,
            "recovered-coop-boss-anchors.json");
        CoopBossAnchorCatalog anchors = CoopBossAnchorCatalog.Load(
            anchorPath, missions);
        CoopBossMapAnchors desertBoss = anchors.MapForMission(missions, 4);
        if (anchors.Maps.Count != 5 ||
            anchors.Maps.Any(map => map.PlayerPositions.Count != 8 ||
                map.BossStart.Fraction != 1 || map.BossStart.Index != 1 ||
                map.AlliedStarts.Count != 2) ||
            desertBoss.Scene != "Desert_Multiplayer" ||
            MathF.Abs(desertBoss.BossStart.Position.X - (-28.64718f)) > 0.0001f ||
            Enumerable.Range(0, 15).Any(index =>
                anchors.MapForMission(missions, index * 5 + 4).Stage !=
                    missions.Get(index * 5 + 4).MapStage))
            throw new Exception("Boss anchors differ from the multiplayer source maps.");
        int combatAssertions = VerifyCoopBossCombat(missions, health, anchors);
        CoopBossPathCatalog bossPaths = CoopBossPathCatalog.Load(Path.Combine(
            directory, "recovered-coop-boss-paths.json"), missions, anchors,
            content.ArmyNavMeshes);
        if (bossPaths.Maps.Count != 5 ||
            bossPaths.Maps.Any(map => map.Routes.Count != 24 ||
                map.Between(5, 7).Corners.Count < 2) ||
            Enumerable.Range(0, 15).Any(index =>
                bossPaths.MapForMission(missions, index * 5 + 4).Stage !=
                    missions.Get(index * 5 + 4).MapStage))
            throw new Exception("Boss routes differ from source multiplayer maps.");
        try
        {
            _ = bossPaths.Maps[0].Between(1, 5);
            throw new Exception("A cross-faction boss route was accepted.");
        }
        catch (ArgumentOutOfRangeException)
        {
        }

        string temporaryPath = Path.Combine(Path.GetTempPath(),
            $"war-coop-bots-{Guid.NewGuid():N}.json");
        string changedAnchorPath = Path.Combine(Path.GetTempPath(),
            $"war-coop-boss-anchors-{Guid.NewGuid():N}.json");
        string changedAttackPath = Path.Combine(Path.GetTempPath(),
            $"war-coop-boss-attacks-{Guid.NewGuid():N}.json");
        string changedLoadoutPath = Path.Combine(Path.GetTempPath(),
            $"war-coop-boss-loadouts-{Guid.NewGuid():N}.json");
        try
        {
            JsonNode changedLoadout = JsonNode.Parse(File.ReadAllText(Path.Combine(
                directory, "recovered-coop-boss-loadouts.json")))!;
            changedLoadout["weapons"]![0]!["levelManagerIndex"] = 1;
            File.WriteAllText(changedLoadoutPath, changedLoadout.ToJsonString());
            try
            {
                _ = CoopBossLoadoutCatalog.Load(changedLoadoutPath,
                    missions, bots, attacks, content.AllWeaponBindings);
                throw new Exception("Altered OBB weapon order was accepted.");
            }
            catch (InvalidDataException)
            {
            }
            JsonNode changedAttack = JsonNode.Parse(File.ReadAllText(attackPath))!;
            changedAttack["missions"]![0]!["shootFrequencyMinSeconds"] = 0;
            File.WriteAllText(changedAttackPath, changedAttack.ToJsonString());
            try
            {
                _ = CoopBossAttackTimingCatalog.Load(changedAttackPath, missions, bots);
                throw new Exception("Altered boss attack timing was accepted.");
            }
            catch (InvalidDataException)
            {
            }
            JsonNode altered = JsonNode.Parse(File.ReadAllText(path))!;
            altered["bots"]![0]!["bot"]!["hpReduction"] = 1;
            File.WriteAllText(temporaryPath, altered.ToJsonString());
            try
            {
                _ = CoopBotRuleCatalog.Load(temporaryPath, missions);
                throw new Exception("Altered boss vitality was accepted.");
            }
            catch (InvalidDataException)
            {
            }
            JsonNode changedAnchors = JsonNode.Parse(File.ReadAllText(anchorPath))!;
            changedAnchors["maps"]![0]!["playerPositions"]![1]!["worldPosition"]![0] = 999;
            File.WriteAllText(changedAnchorPath, changedAnchors.ToJsonString());
            try
            {
                _ = CoopBossAnchorCatalog.Load(changedAnchorPath, missions);
                throw new Exception("Altered boss placement was accepted.");
            }
            catch (InvalidDataException)
            {
                return 48 + combatAssertions + arsenalAssertions;
            }
        }
        finally
        {
            File.Delete(temporaryPath);
            File.Delete(changedAnchorPath);
            File.Delete(changedAttackPath);
            File.Delete(changedLoadoutPath);
        }
    }

    private static int VerifyCoopBossArsenal(string directory,
        CoopBossLoadoutCatalog loadouts, CoopBossAttackTiming timing)
    {
        BattleCombatContent content = LoadCoopBossWeaponContent(directory);
        foreach (CoopBossLoadout missionLoadout in loadouts.Missions)
        {
            var missionArsenal = new CoopBossArsenal(missionLoadout, content, 0);
            for (int slot = 0; slot < 4; slot++)
            {
                WeaponManifest selected = missionArsenal.Definition(
                    (CoopBossWeaponSlotKind)slot);
                if (selected.SourceId != missionLoadout.Slots[slot].SheetName ||
                    selected.ClipSize <= 0)
                    throw new Exception("A boss weapon lacks source stage-zero stats.");
            }
        }
        CoopBossLoadout loadout = loadouts.ForMission(4);
        var arsenal = new CoopBossArsenal(loadout, content, 0);
        WeaponManifest rifle = arsenal.Definition(CoopBossWeaponSlotKind.Primary);
        WeaponManifest explosive = arsenal.Definition(CoopBossWeaponSlotKind.Explosive);
        if (rifle.SourceId != loadout.Slots[0].SheetName ||
            rifle.ClipSize < 2 || rifle.ReserveAmmo <= 0 ||
            explosive.SourceId != loadout.Slots[2].SheetName ||
            explosive.ReserveAmmo != 0)
            throw new Exception("Boss arsenal lost its source stage-zero ammunition.");

        CoopBossWeaponSlotKind choice = CoopBossWeaponChoice.ForOrdinaryPlayerTarget(
            timing, false,
            arsenal.Readiness(CoopBossWeaponSlotKind.Primary, 0),
            arsenal.Readiness(CoopBossWeaponSlotKind.Secondary, 0),
            arsenal.Readiness(CoopBossWeaponSlotKind.Explosive, 0),
            0.01f, 0f);
        if (choice != CoopBossWeaponSlotKind.Explosive)
            throw new Exception("Boss weapon choice ignored host-owned ammunition.");

        ulong cadence = (ulong)Math.Ceiling(
            rifle.CadenceSeconds * MatchManifest.TickRate);
        for (int shot = 0; shot < rifle.ClipSize; shot++)
        {
            ulong shotTick = (ulong)shot * cadence;
            if (!arsenal.ConfirmShot(CoopBossWeaponSlotKind.Primary, shotTick) ||
                arsenal.ConfirmShot(CoopBossWeaponSlotKind.Primary, shotTick))
                throw new Exception("Boss rifle ammunition or cadence was bypassed.");
        }
        ulong lastShotTick = (ulong)(rifle.ClipSize - 1) * cadence;
        CoopBossWeaponReadiness reloading = arsenal.Readiness(
            CoopBossWeaponSlotKind.Primary, lastShotTick);
        if (!reloading.Reloading || reloading.WillShoot || reloading.OutOfAmmo)
            throw new Exception("Boss rifle did not start its source reload.");
        ulong reloadEnd = lastShotTick + (ulong)Math.Ceiling(
            rifle.ReloadSeconds * MatchManifest.TickRate);
        arsenal.Advance(reloadEnd);
        if (!arsenal.Readiness(CoopBossWeaponSlotKind.Primary, reloadEnd).WillShoot)
            throw new Exception("Boss rifle did not receive reserve ammunition.");
        return 20;
    }

    private static BattleCombatContent LoadCoopBossWeaponContent(string directory)
    {
        return BattleCombatContent.Load(
            Path.Combine(directory, "combat-content-manifest.json"),
            Path.Combine(directory, "shotgun-content-manifest.json"),
            pistolManifestPath: Path.Combine(directory, "pistol-content-manifest.json"),
            sniperManifestPath: Path.Combine(directory, "sniper-content-manifest.json"),
            bazookaManifestPath: Path.Combine(directory, "bazooka-content-manifest.json"),
            grenadeManifestPath: Path.Combine(directory, "grenade-content-manifest.json"));
    }

    private static int VerifyCoopBossCombat(MissionCatalog missions,
        CoopBotHealthCatalog health, CoopBossAnchorCatalog anchors)
    {
        const string firstPlayer = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        const string secondPlayer = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
        var mission = new CoopMissionEngine(missions, 4);
        if (mission.RegisterBoss(CoopMissionEngine.BossEntityId, 0))
            throw new Exception("A boss cannot spawn before both allies are ready.");
        mission.Admit(firstPlayer);
        mission.Admit(secondPlayer);
        mission.MarkReady(firstPlayer, 0);
        mission.MarkReady(secondPlayer, 0);
        var boss = new CoopBossCombatState(mission, health.ForMission(4),
            anchors.MapForMission(missions, 4), 0);
        if (boss.EntityId != CoopMissionEngine.BossEntityId ||
            boss.DefendComponentFileId != anchors.Maps[0].BossStart.ComponentFileId ||
            boss.Position != anchors.Maps[0].BossStart.Position ||
            boss.MaximumHealth != 312f * 0.8f ||
            mission.ConfirmAiDeath(boss.EntityId, 0))
            throw new Exception("Only the source enemy player can own boss vitality.");
        if (boss.ApplyHostDamage(float.NaN, 0) ||
            boss.ApplyHostDamage(float.PositiveInfinity, 0) ||
            boss.ApplyHostDamage(0, 0) ||
            boss.ApplyHostDamage(1, 1) ||
            boss.ApplyHostDamage(1, mission.DeadlineTick) ||
            mission.ConfirmBossDeath(1, 0))
            throw new Exception("Malformed or unconfirmed boss hits must not end a mission.");
        float partial = boss.MaximumHealth / 2;
        boss.Advance(1);
        if (!boss.ApplyHostDamage(partial, 1) ||
            boss.Health <= 0 || mission.Outcome != MissionOutcome.InProgress)
            throw new Exception("A partial host hit must retain boss vitality.");
        boss.Advance(2);
        if (boss.ApplyHostDamage(1, 1) ||
            !boss.ApplyHostDamage(boss.Health, 2) ||
            boss.DeathTick != 2 || mission.Outcome != MissionOutcome.Succeeded ||
            boss.ApplyHostDamage(1, 2) ||
            mission.ConfirmBossDeath(boss.EntityId, 2))
            throw new Exception("A host-confirmed boss death must finish once.");

        var zeroHealthMission = new CoopMissionEngine(missions, 49);
        zeroHealthMission.Admit(firstPlayer);
        zeroHealthMission.Admit(secondPlayer);
        zeroHealthMission.MarkReady(firstPlayer, 0);
        zeroHealthMission.MarkReady(secondPlayer, 0);
        var zeroHealthBoss = new CoopBossCombatState(zeroHealthMission,
            health.ForMission(49), anchors.MapForMission(missions, 49), 0);
        zeroHealthBoss.Advance(1);
        if (zeroHealthBoss.MaximumHealth != 0 || zeroHealthBoss.DeathTick.HasValue ||
            zeroHealthMission.Outcome != MissionOutcome.InProgress ||
            !zeroHealthBoss.ApplyHostDamage(1, 1) ||
            zeroHealthBoss.DeathTick != 1 ||
            zeroHealthMission.Outcome != MissionOutcome.Succeeded)
            throw new Exception("A source zero-health boss needs a confirmed hostile hit.");

        var timeoutMission = new CoopMissionEngine(missions, 4);
        timeoutMission.Admit(firstPlayer);
        timeoutMission.Admit(secondPlayer);
        timeoutMission.MarkReady(firstPlayer, 0);
        timeoutMission.MarkReady(secondPlayer, 0);
        var timedOutBoss = new CoopBossCombatState(timeoutMission,
            health.ForMission(4), anchors.MapForMission(missions, 4), 0);
        timedOutBoss.Advance(timeoutMission.DeadlineTick);
        if (timeoutMission.Outcome != MissionOutcome.Failed ||
            timedOutBoss.ApplyHostDamage(timedOutBoss.Health,
                timeoutMission.DeadlineTick))
            throw new Exception("A boss hit at the deadline cannot revive a failed mission.");
        return 16;
    }

    private static int VerifyCoopNavMeshRoutes(string directory, MissionCatalog missions)
    {
        CoopSpawnPointCatalog spawns = CoopSpawnPointCatalog.Load(Path.Combine(
            directory, "recovered-coop-spawn-points.json"), missions);
        CoopNavMeshSourceCatalog navigation = CoopNavMeshSourceCatalog.Load(
            Path.Combine(directory, "recovered-coop-navmesh-sources.json"), missions);
        string path = Path.Combine(directory, "recovered-coop-navmesh-paths.json");
        CoopNavMeshPathCatalog routes = CoopNavMeshPathCatalog.Load(
            path, missions, spawns, navigation);
        if (routes.Maps.Count != 5 ||
            routes.Maps.Sum(map => map.Routes.Count) != 60 ||
            routes.MapForMission(missions, 0).Between(1, 0).To != 0 ||
            routes.MapForMission(missions, 70).Between(2, 3).From != 2 ||
            routes.Maps[2].Routes.All(route => route.Corners.Count != 3))
            throw new Exception("Co-op defend routes differ from Unity's source paths.");

        string temporaryDirectory = Path.Combine(Path.GetTempPath(),
            $"war-coop-routes-{Guid.NewGuid():N}");
        Directory.CreateDirectory(temporaryDirectory);
        try
        {
            foreach (string filename in new[] { "recovered-coop-spawn-points.json",
                         "recovered-coop-navmesh-sources.json" })
                File.Copy(Path.Combine(directory, filename),
                    Path.Combine(temporaryDirectory, filename));
            JsonNode damaged = JsonNode.Parse(File.ReadAllText(path))!;
            damaged["maps"]![0]!["routes"]![0]!["corners"]![0]![0] = 9000;
            string damagedPath = Path.Combine(temporaryDirectory,
                Path.GetFileName(path));
            File.WriteAllText(damagedPath, damaged.ToJsonString());
            try
            {
                _ = CoopNavMeshPathCatalog.Load(damagedPath,
                    missions, spawns, navigation);
                throw new Exception("A route detached from its source shield was accepted.");
            }
            catch (InvalidDataException)
            {
                return 5;
            }
        }
        finally
        {
            Directory.Delete(temporaryDirectory, recursive: true);
        }
    }

    private static int VerifyCoopNavMeshSources(string directory, MissionCatalog missions)
    {
        string manifestPath = Path.Combine(directory,
            "recovered-coop-navmesh-sources.json");
        CoopNavMeshSourceCatalog navigation =
            CoopNavMeshSourceCatalog.Load(manifestPath, missions);
        string triangleManifest = Path.Combine(directory,
            "recovered-coop-navmesh-triangulation.json");
        CoopNavMeshTriangulationCatalog triangles =
            CoopNavMeshTriangulationCatalog.Load(triangleManifest,
                missions, navigation);
        CoopNavMeshConnectivity connectivity =
            CoopNavMeshConnectivity.Build(triangles);
        CoopSpawnPointCatalog spawnPoints = CoopSpawnPointCatalog.Load(
            Path.Combine(directory, "recovered-coop-spawn-points.json"),
            missions);
        CoopMapSpawnPoints desertSpawns = spawnPoints.MapForMission(
            missions, 0);
        Vector3? firstSurface = connectivity.SampleNearest(missions, 0,
            desertSpawns.PlayerPositions[1].Position, 3f);
        Vector3? secondSurface = connectivity.SampleNearest(missions, 0,
            desertSpawns.PlayerPositions[2].Position, 3f);
        ArmyNavMeshCorridor? defendCorridor =
            firstSurface.HasValue && secondSurface.HasValue
                ? connectivity.PlanCorridor(missions, 0,
                    firstSurface.Value, secondSurface.Value)
                : null;
        CoopEnemyPointCatalog enemyPoints = CoopEnemyPointCatalog.Load(
            Path.Combine(directory, "recovered-coop-enemy-points.json"),
            missions, spawnPoints);
        CoopInfantryPathFixtureCatalog sourcePaths =
            CoopInfantryPathFixtureCatalog.Load(directory, missions,
                navigation, spawnPoints, enemyPoints);
        CoopNavMeshConnectivity sourceNavigation =
            CoopNavMeshConnectivity.Build(triangles, sourcePaths);
        foreach (CoopInfantryPathFixture sourcePath in sourcePaths.Cases)
        {
            ArmyNavMeshCorridor? exactPath = sourceNavigation
                .PlanSourceSpawnCorridor(missions, sourcePath.MissionIndex,
                    sourcePath.SpawnComponentFileId,
                    sourcePath.PointComponentFileId,
                    sourcePath.RequestedStart, sourcePath.RequestedEnd);
            if (exactPath == null || !exactPath.PlanarCovered ||
                !exactPath.SmoothedPoints.SequenceEqual(sourcePath.Corners) ||
                sourceNavigation.PlanSourceSpawnCorridor(missions,
                    sourcePath.MissionIndex,
                    sourcePath.SpawnComponentFileId,
                    sourcePath.PointComponentFileId,
                    sourcePath.RequestedStart,
                    sourcePath.RequestedEnd + new Vector3(0.0001f, 0, 0)) != null)
                throw new Exception("Co-op source route must match only its exact spawn and point.");
        }
        if (sourcePaths.Cases.Count != 36)
            throw new Exception("Co-op source route inventory is incomplete.");
        CoopInfantryPathFixture midpoint = sourcePaths.Cases.First(path =>
            path.PointFraction == 0.5f);
        Vector3 nearbyDestination = midpoint.RequestedEnd +
            new Vector3(0.0001f, 0, 0);
        Vector3? nearbyStart = sourceNavigation.SampleNearest(missions,
            midpoint.MissionIndex, midpoint.RequestedStart, 3f);
        Vector3? nearbyEnd = sourceNavigation.SampleNearest(missions,
            midpoint.MissionIndex, nearbyDestination, 3f);
        ArmyNavMeshCorridor? nearbyRoute = nearbyStart.HasValue &&
            nearbyEnd.HasValue ? sourceNavigation.PlanCorridor(missions,
                midpoint.MissionIndex, nearbyStart.Value, nearbyEnd.Value) : null;
        if (sourceNavigation.PlanSourceSpawnCorridor(missions,
                midpoint.MissionIndex, midpoint.SpawnComponentFileId,
                midpoint.PointComponentFileId, midpoint.RequestedStart,
                nearbyDestination) != null ||
            nearbyRoute is not { PlanarCovered: true })
            throw new Exception("Nearby randomized co-op positions need the general route planner.");
        CoopSpawnPoint infantrySpawn = desertSpawns.EnemySpawnPoints.First(
            point => point.ComponentType == "SpawnPoint");
        CoopEnemyPoint? infantryTarget =
            CoopEnemyPointSelection.SelectOrdinary(
                enemyPoints.MapForMission(missions, 0), 14,
                infantrySpawn.Position, new HashSet<int>());
        Vector3? infantryStart = connectivity.SampleNearest(missions, 0,
            infantrySpawn.Position, 3f);
        Vector3? infantryEnd = infantryTarget == null ? null :
            connectivity.SampleNearest(missions, 0,
                infantryTarget.Position, 3f);
        ArmyNavMeshCorridor? infantryCorridor =
            infantryStart.HasValue && infantryEnd.HasValue
                ? connectivity.PlanCorridor(missions, 0,
                    infantryStart.Value, infantryEnd.Value)
                : null;
        if (navigation.Maps.Count != 5 ||
            triangles.Maps.Count != 5 ||
            triangles.Maps.Sum(map => map.Vertices.Count) != 21_068 ||
            triangles.Maps.Sum(map => map.Indices.Count / 3) != 9_682 ||
            triangles.MapForMission(missions, 0).Scene != "Desert_New" ||
            connectivity.ComponentCount(missions, 0) <= 0 ||
            defendCorridor == null || !defendCorridor.PlanarCovered ||
            infantryCorridor == null || !infantryCorridor.PlanarCovered ||
            navigation.MapForMission(missions, 0).Scene != "Desert_New" ||
            navigation.MapForMission(missions, 70).Scene != "Park_Single" ||
            navigation.Maps.Count(map => map.Format == "unity-binary-2018") != 4 ||
            navigation.Maps.Count(map => map.Format == "unity-yaml-navmesh-tiles") != 1)
            throw new Exception("Co-op NavMesh package does not match the source scenes.");

        var infantryMovement = new CoopInfantryPathState(
            infantryCorridor, movementSpeed: 2f, firstTick: 10);
        Vector3 routeStart = infantryCorridor.SmoothedPoints[0];
        Vector3 routeEnd = infantryCorridor.SmoothedPoints[^1];
        ulong arrivalTick = 10 + (ulong)Math.Ceiling(
            infantryCorridor.SmoothedLength / 2f * MatchManifest.TickRate);
        if (infantryMovement.PositionAt(10) != routeStart ||
            infantryMovement.HasArrived(10) ||
            infantryMovement.PositionAt(11) == routeStart ||
            infantryMovement.HasArrived(11) ||
            infantryMovement.PositionAt(arrivalTick) != routeEnd ||
            !infantryMovement.HasArrived(arrivalTick) ||
            infantryMovement.PositionAt(arrivalTick + 100) != routeEnd)
            throw new Exception("Co-op infantry route clock is inconsistent.");
        VerifyCoopAssaulterMotionReference(directory, missions,
            connectivity, infantrySpawn, infantryTarget);
        VerifyCoopFiveMapPathReference(directory, missions, navigation,
            spawnPoints, enemyPoints, connectivity);
        VerifyCoopNormalSpawnPaths(directory, missions, navigation,
            spawnPoints, enemyPoints, connectivity);

        string temporaryDirectory = Path.Combine(Path.GetTempPath(),
            $"war-coop-navigation-{Guid.NewGuid():N}");
        string temporaryAssets = Path.Combine(temporaryDirectory, "coop-navmesh");
        string temporaryTriangles = Path.Combine(temporaryDirectory,
            "coop-navmesh-triangulation");
        Directory.CreateDirectory(temporaryAssets);
        Directory.CreateDirectory(temporaryTriangles);
        try
        {
            File.Copy(manifestPath, Path.Combine(temporaryDirectory,
                Path.GetFileName(manifestPath)));
            File.Copy(triangleManifest, Path.Combine(temporaryDirectory,
                Path.GetFileName(triangleManifest)));
            foreach (string mesh in Directory.GetFiles(Path.Combine(directory,
                         "coop-navmesh-triangulation"), "*.json"))
                File.Copy(mesh, Path.Combine(temporaryTriangles,
                    Path.GetFileName(mesh)));
            string damagedMesh = Path.Combine(temporaryTriangles,
                "NavMesh_7.json");
            byte[] meshBytes = File.ReadAllBytes(damagedMesh);
            meshBytes[^1] ^= 1;
            File.WriteAllBytes(damagedMesh, meshBytes);
            try
            {
                _ = CoopNavMeshTriangulationCatalog.Load(
                    Path.Combine(temporaryDirectory,
                        Path.GetFileName(triangleManifest)),
                    missions, navigation);
                throw new Exception("A damaged co-op triangle mesh was accepted.");
            }
            catch (InvalidDataException)
            {
                // A packaged mesh must match Unity's pinned export bytes.
            }
            foreach (CoopNavMeshSource map in navigation.Maps)
            {
                File.Copy(Path.Combine(directory, "coop-navmesh", map.PackagedAsset),
                    Path.Combine(temporaryAssets, map.PackagedAsset));
            }
            string copiedAsset = Path.Combine(temporaryAssets,
                navigation.Maps[0].PackagedAsset);
            byte[] bytes = File.ReadAllBytes(copiedAsset);
            bytes[^1] ^= 1;
            File.WriteAllBytes(copiedAsset, bytes);
            try
            {
                _ = CoopNavMeshSourceCatalog.Load(Path.Combine(temporaryDirectory,
                    Path.GetFileName(manifestPath)), missions);
                throw new Exception("A damaged co-op NavMesh asset was accepted.");
            }
            catch (InvalidDataException)
            {
                return 8;
            }
        }
        finally
        {
            Directory.Delete(temporaryDirectory, recursive: true);
        }
    }

    private static void VerifyCoopAssaulterMotionReference(string directory,
        MissionCatalog missions, CoopNavMeshConnectivity navigation,
        CoopSpawnPoint spawn, CoopEnemyPoint? target)
    {
        string path = Path.Combine(directory,
            "coop-assaulter-motion-reference.json");
        byte[] source = File.ReadAllBytes(path);
        if (Convert.ToHexStringLower(SHA256.HashData(source)) !=
            "3e964938407869320d9998880a17024a0e8f2535384dd1de4aee6a51a9d3a9bd")
            throw new Exception("Co-op Unity motion trace changed.");
        using JsonDocument document = JsonDocument.Parse(source);
        JsonElement root = document.RootElement;
        if (target?.ComponentFileId != 1859 ||
            spawn.ComponentFileId != 1646 ||
            root.GetProperty("asset").GetString() !=
                "Assets/NavMeshData/NavMesh_7.asset" ||
            root.GetProperty("status").GetString() != "Arrived" ||
            root.GetProperty("pathStatus").GetString() != "PathComplete" ||
            root.GetProperty("speed").GetSingle() != 0.9f)
            throw new Exception("Unity motion trace does not bind the source case.");

        static Vector3 ReadVector(JsonElement value) => new(
            value.GetProperty("x").GetSingle(),
            value.GetProperty("y").GetSingle(),
            value.GetProperty("z").GetSingle());
        Vector3 requestedEnd = CoopEnemyPointSelection.GeneratePosition(
            target, 0.5f);
        using JsonDocument inputDocument = JsonDocument.Parse(File.ReadAllBytes(
            Path.Combine(directory, "coop-assaulter-motion-input.json")));
        JsonElement input = inputDocument.RootElement;
        if (input.GetProperty("asset").GetString() !=
                "Assets/NavMeshData/NavMesh_7.asset" ||
            input.GetProperty("speed").GetSingle() != 0.9f ||
            Vector3.Distance(ReadVector(input.GetProperty("start")),
                spawn.Position) > 0.001f ||
            Vector3.Distance(ReadVector(input.GetProperty("end")),
                requestedEnd) > 0.001f)
            throw new Exception("Unity motion input differs from source anchors.");
        Vector3 traceStart = ReadVector(root.GetProperty("requestedStart"));
        Vector3 traceEnd = ReadVector(root.GetProperty("requestedEnd"));
        if (Vector3.Distance(traceStart, spawn.Position) > 0.001f ||
            Vector3.Distance(traceEnd, requestedEnd) > 0.001f)
            throw new Exception("Unity motion trace endpoints changed.");

        Vector3? start = navigation.SampleNearest(missions, 0,
            spawn.Position, 3f);
        Vector3? end = navigation.SampleNearest(missions, 0,
            requestedEnd, 3f);
        ArmyNavMeshCorridor? corridor = start.HasValue && end.HasValue ?
            navigation.PlanCorridor(missions, 0, start.Value, end.Value) : null;
        if (corridor is not { PlanarCovered: true })
            throw new Exception("Unity motion trace lacks a host corridor.");
        var host = new CoopInfantryPathState(corridor, 0.9f, 0);
        JsonElement unityCorners = root.GetProperty("corners");
        if (unityCorners.GetArrayLength() != 9 ||
            corridor.SmoothedPoints.Count != unityCorners.GetArrayLength())
            throw new Exception("Co-op host path has different Unity corners.");
        for (int index = 0; index < unityCorners.GetArrayLength(); index++)
        {
            Vector3 unityCorner = ReadVector(unityCorners[index]);
            if (Vector3.Distance(unityCorner,
                    corridor.SmoothedPoints[index]) > 0.05f)
                throw new Exception("Co-op host corner differs from Unity's path.");
        }
        JsonElement samples = root.GetProperty("samples");
        if (samples.GetArrayLength() != 254)
            throw new Exception("Unity co-op motion trace is incomplete.");
        var errors = new List<float>();
        var facingErrors = new List<float>();
        var smoothedFacingErrors = new List<float>();
        float previousTime = -1;
        int previousFrame = -1;
        foreach (JsonElement sample in samples.EnumerateArray())
        {
            int frame = sample.GetProperty("frame").GetInt32();
            float seconds = sample.GetProperty("seconds").GetSingle();
            Vector3 unity = ReadVector(sample.GetProperty("position"));
            if (frame <= previousFrame || seconds < previousTime ||
                !PlayerHitbox.Finite(unity))
                throw new Exception("Unity co-op motion samples are not ordered.");
            previousFrame = frame;
            previousTime = seconds;
            ulong tick = (ulong)Math.Round(seconds * MatchManifest.TickRate);
            Vector3 predicted = host.PositionAt(tick);
            Vector2 delta = new(predicted.X - unity.X,
                predicted.Z - unity.Z);
            errors.Add(delta.Length());
            Vector3 velocity = ReadVector(sample.GetProperty("velocity"));
            if (velocity.Length() > 0.1f)
            {
                JsonElement sourceRotation = sample.GetProperty("rotation");
                var rotation = new Quaternion(
                    sourceRotation.GetProperty("x").GetSingle(),
                    sourceRotation.GetProperty("y").GetSingle(),
                    sourceRotation.GetProperty("z").GetSingle(),
                    sourceRotation.GetProperty("w").GetSingle());
                Vector3 unityFacing = Vector3.Transform(Vector3.UnitZ,
                    rotation);
                Vector3 hostFacing = host.PlanarDirectionAt(tick);
                float cosine = Math.Clamp(Vector3.Dot(unityFacing,
                    hostFacing), -1f, 1f);
                facingErrors.Add(MathF.Acos(cosine) * 180f / MathF.PI);
                Vector3 smoothedFacing = host.SmoothedPlanarDirectionAt(
                    tick, 0.6f);
                float smoothedCosine = Math.Clamp(Vector3.Dot(unityFacing,
                    smoothedFacing), -1f, 1f);
                smoothedFacingErrors.Add(
                    MathF.Acos(smoothedCosine) * 180f / MathF.PI);
            }
        }
        errors.Sort();
        facingErrors.Sort();
        smoothedFacingErrors.Sort();
        if (errors[(int)(errors.Count * 0.95)] > 0.25f ||
            errors[^1] > 0.30f || previousTime is < 8f or > 9f ||
            facingErrors.Count < 200 ||
            smoothedFacingErrors[(int)(smoothedFacingErrors.Count * 0.95)] >
                35f ||
            smoothedFacingErrors[(int)(smoothedFacingErrors.Count * 0.95)] >=
                facingErrors[(int)(facingErrors.Count * 0.95)])
            throw new Exception("Co-op host motion differs from Unity reference.");
        Console.WriteLine($"Co-op Assaulter Unity motion: host median={errors[errors.Count / 2]:F3}, " +
            $"p95={errors[(int)(errors.Count * 0.95)]:F3}, max={errors[^1]:F3}, " +
            $"facing p95={facingErrors[(int)(facingErrors.Count * 0.95)]:F1}/" +
            $"{smoothedFacingErrors[(int)(smoothedFacingErrors.Count * 0.95)]:F1} degrees, " +
            $"Unity duration={previousTime:F2}s, host duration={corridor.SmoothedLength / 0.9f:F2}s.");
    }

    private static void VerifyCoopFiveMapPathReference(string directory,
        MissionCatalog missions, CoopNavMeshSourceCatalog navSources,
        CoopSpawnPointCatalog spawns, CoopEnemyPointCatalog enemyPoints,
        CoopNavMeshConnectivity navigation)
    {
        string referencePath = Path.Combine(directory,
            "coop-infantry-five-map-path-reference.json");
        byte[] referenceBytes = File.ReadAllBytes(referencePath);
        if (Convert.ToHexStringLower(SHA256.HashData(referenceBytes)) !=
            "e69e0344f465a7ba0230c8ce9c1d289f1d9ba8b6e1f420196f45edf2703d959c")
            throw new Exception("Five-map Unity path reference changed.");
        using JsonDocument inputDocument = JsonDocument.Parse(File.ReadAllBytes(
            Path.Combine(directory, "coop-infantry-five-map-path-input.json")));
        using JsonDocument referenceDocument = JsonDocument.Parse(referenceBytes);
        JsonElement inputs = inputDocument.RootElement.GetProperty("cases");
        JsonElement references = referenceDocument.RootElement
            .GetProperty("cases");
        if (inputDocument.RootElement.GetProperty("version").GetInt32() != 1 ||
            referenceDocument.RootElement.GetProperty("version").GetInt32() != 1 ||
            inputs.GetArrayLength() != 5 || references.GetArrayLength() != 5)
            throw new Exception("Five-map Unity path inventory is incomplete.");

        static Vector3 ReadVector(JsonElement value) => new(
            value.GetProperty("x").GetSingle(),
            value.GetProperty("y").GetSingle(),
            value.GetProperty("z").GetSingle());

        for (int index = 0; index < 5; index++)
        {
            JsonElement input = inputs[index];
            JsonElement reference = references[index];
            int missionIndex = input.GetProperty("missionIndex").GetInt32();
            MissionMapRule missionMap = missions.MapForMission(missionIndex);
            CoopNavMeshSource navMesh = navSources.MapForMission(missions,
                missionIndex);
            CoopMapSpawnPoints mapSpawns = spawns.MapForMission(missions,
                missionIndex);
            CoopMapEnemyPoints mapPoints = enemyPoints.MapForMission(missions,
                missionIndex);
            CoopSpawnPoint spawn = mapSpawns.EnemySpawnPoints.First(point =>
                point.ComponentType == "SpawnPoint");
            CoopEnemyPoint? point = CoopEnemyPointSelection.SelectOrdinary(
                mapPoints, 14, spawn.Position, new HashSet<int>());
            if (point == null)
                throw new Exception("A source co-op map lacks its Assaulter point.");
            Vector3 destination = CoopEnemyPointSelection.GeneratePosition(
                point, 0.5f);
            if (missionMap.Stage != index + 1 ||
                input.GetProperty("stage").GetInt32() != missionMap.Stage ||
                input.GetProperty("scene").GetString() != missionMap.Scene ||
                input.GetProperty("asset").GetString() != navMesh.SourceAsset ||
                input.GetProperty("spawnComponentFileId").GetInt32() !=
                    spawn.ComponentFileId ||
                input.GetProperty("pointComponentFileId").GetInt32() !=
                    point.ComponentFileId ||
                Vector3.Distance(ReadVector(input.GetProperty("start")),
                    spawn.Position) > 0.001f ||
                Vector3.Distance(ReadVector(input.GetProperty("end")),
                    destination) > 0.001f)
                throw new Exception("Five-map path input differs from source.");

            if (reference.GetProperty("stage").GetInt32() != missionMap.Stage ||
                reference.GetProperty("scene").GetString() != missionMap.Scene ||
                reference.GetProperty("asset").GetString() != navMesh.SourceAsset ||
                reference.GetProperty("spawnComponentFileId").GetInt32() !=
                    spawn.ComponentFileId ||
                reference.GetProperty("pointComponentFileId").GetInt32() !=
                    point.ComponentFileId ||
                !reference.GetProperty("startSampled").GetBoolean() ||
                !reference.GetProperty("endSampled").GetBoolean() ||
                reference.GetProperty("status").GetString() != "PathComplete")
                throw new Exception("Five-map Unity path differs from input.");

            Vector3? start = navigation.SampleNearest(missions,
                missionIndex, spawn.Position, 3f);
            Vector3? end = navigation.SampleNearest(missions,
                missionIndex, destination, 3f);
            ArmyNavMeshCorridor? corridor = start.HasValue && end.HasValue ?
                navigation.PlanCorridor(missions, missionIndex,
                    start.Value, end.Value) : null;
            JsonElement unityCorners = reference.GetProperty("corners");
            if (corridor is not { PlanarCovered: true } ||
                unityCorners.GetArrayLength() < 2 ||
                unityCorners.GetArrayLength() !=
                    corridor.SmoothedPoints.Count ||
                Vector3.Distance(ReadVector(reference.GetProperty(
                    "sampledStart")), corridor.SmoothedPoints[0]) > 0.05f ||
                Vector3.Distance(ReadVector(reference.GetProperty(
                    "sampledEnd")), corridor.SmoothedPoints[^1]) > 0.05f)
                throw new Exception("Host has no source-bound co-op route.");
            float unityLength = 0;
            for (int corner = 0; corner < unityCorners.GetArrayLength(); corner++)
            {
                if (Vector3.Distance(ReadVector(unityCorners[corner]),
                        corridor.SmoothedPoints[corner]) > 0.05f)
                    throw new Exception(
                        "Host co-op corner differs from the Unity path.");
                if (corner == 0)
                    continue;
                unityLength += Vector3.Distance(
                    ReadVector(unityCorners[corner - 1]),
                    ReadVector(unityCorners[corner]));
            }
            Console.WriteLine($"Co-op map {missionMap.Scene}: Unity {unityCorners.GetArrayLength()} corners/{unityLength:F2} units; host {corridor.SmoothedPoints.Count} corners/{corridor.SmoothedLength:F2} units.");
            if (corridor.SmoothedLength > unityLength * 1.1f + 0.05f)
                throw new Exception("Host co-op route detours beyond Unity's path.");
        }
    }

    private static void VerifyCoopNormalSpawnPaths(string directory,
        MissionCatalog missions, CoopNavMeshSourceCatalog navSources,
        CoopSpawnPointCatalog spawns, CoopEnemyPointCatalog enemyPoints,
        CoopNavMeshConnectivity navigation)
    {
        string referencePath = Path.Combine(directory,
            "coop-infantry-normal-spawn-path-reference.json");
        byte[] referenceBytes = File.ReadAllBytes(referencePath);
        if (Convert.ToHexStringLower(SHA256.HashData(referenceBytes)) !=
            "42cc88552404158815a64d71f2c597752d2b8c10accf1b058bbc555abc0c92f7")
            throw new Exception("Co-op normal-spawn Unity paths changed.");
        using JsonDocument inputDocument = JsonDocument.Parse(File.ReadAllBytes(
            Path.Combine(directory, "coop-infantry-normal-spawn-path-input.json")));
        using JsonDocument referenceDocument = JsonDocument.Parse(referenceBytes);
        JsonElement inputs = inputDocument.RootElement.GetProperty("cases");
        JsonElement references = referenceDocument.RootElement
            .GetProperty("cases");
        if (inputDocument.RootElement.GetProperty("version").GetInt32() != 2 ||
            referenceDocument.RootElement.GetProperty("version").GetInt32() != 2 ||
            inputs.GetArrayLength() != 36 ||
            references.GetArrayLength() != 36)
            throw new Exception("Co-op normal-spawn path inventory is incomplete.");

        static Vector3 ReadVector(JsonElement value) => new(
            value.GetProperty("x").GetSingle(),
            value.GetProperty("y").GetSingle(),
            value.GetProperty("z").GetSingle());

        var stageCounts = new int[5];
        float worstLengthRatio = 0;
        float worstCornerDistance = 0;
        float worstSampleDistance = 0;
        int differentCornerCounts = 0;
        int differingRoutes = 0;
        int coveredUnityPaths = 0;
        float largestUnityVerticalDeviation = 0;
        for (int index = 0; index < 36; index++)
        {
            JsonElement input = inputs[index];
            JsonElement reference = references[index];
            int missionIndex = input.GetProperty("missionIndex").GetInt32();
            MissionMapRule missionMap = missions.MapForMission(missionIndex);
            CoopNavMeshSource sourceMap = navSources.MapForMission(
                missions, missionIndex);
            CoopMapSpawnPoints mapSpawns = spawns.MapForMission(
                missions, missionIndex);
            CoopMapEnemyPoints mapPoints = enemyPoints.MapForMission(
                missions, missionIndex);
            int stage = input.GetProperty("stage").GetInt32();
            int spawnId = input.GetProperty("spawnComponentFileId").GetInt32();
            int pointId = input.GetProperty("pointComponentFileId").GetInt32();
            CoopSpawnPoint spawn = mapSpawns.EnemySpawnPoints.Single(point =>
                point.ComponentFileId == spawnId);
            CoopEnemyPoint? selected = CoopEnemyPointSelection.SelectOrdinary(
                mapPoints, 14, spawn.Position, new HashSet<int>());
            float fraction = input.GetProperty("pointFraction").GetSingle();
            Vector3 destination = selected == null ? Vector3.Zero :
                CoopEnemyPointSelection.GeneratePosition(selected, fraction);
            if (stage is < 1 or > 5 || stage != missionMap.Stage ||
                sourceMap.Scene != missionMap.Scene ||
                spawn.ComponentType != "SpawnPoint" || spawn.Fraction != 1 ||
                selected?.ComponentFileId != pointId ||
                input.GetProperty("scene").GetString() != missionMap.Scene ||
                input.GetProperty("asset").GetString() != sourceMap.SourceAsset ||
                input.GetProperty("pointPositionKind").GetString() !=
                    (selected?.ComponentType == "EnemyPointObstacle" ?
                        "segment" : "fixed") ||
                (selected?.ComponentType == "EnemyPointObstacle" ?
                    fraction is not (0f or 0.5f or 1f) : fraction != 0f) ||
                Vector3.Distance(ReadVector(input.GetProperty("start")),
                    spawn.Position) > 0.001f ||
                Vector3.Distance(ReadVector(input.GetProperty("end")),
                    destination) > 0.001f)
                throw new Exception("Co-op normal-spawn case differs from Client.");
            stageCounts[stage - 1]++;

            if (reference.GetProperty("stage").GetInt32() != stage ||
                reference.GetProperty("scene").GetString() != missionMap.Scene ||
                reference.GetProperty("asset").GetString() != sourceMap.SourceAsset ||
                reference.GetProperty("spawnComponentFileId").GetInt32() !=
                    spawnId ||
                reference.GetProperty("pointComponentFileId").GetInt32() !=
                    pointId ||
                !reference.GetProperty("startSampled").GetBoolean() ||
                !reference.GetProperty("endSampled").GetBoolean() ||
                reference.GetProperty("status").GetString() != "PathComplete")
                throw new Exception("Co-op Unity path result differs from its case.");

            Vector3? start = navigation.SampleNearest(missions,
                missionIndex, spawn.Position, 3f);
            Vector3? end = navigation.SampleNearest(missions,
                missionIndex, destination, 3f);
            ArmyNavMeshCorridor? corridor = start.HasValue && end.HasValue ?
                navigation.PlanCorridor(missions, missionIndex,
                    start.Value, end.Value) : null;
            JsonElement corners = reference.GetProperty("corners");
            Vector3[] unityPoints = corners.EnumerateArray()
                .Select(ReadVector).ToArray();
            ArmyNavMeshPolylineAudit unityPathAudit =
                navigation.InspectPolyline(missions, missionIndex,
                    unityPoints);
            if (unityPathAudit.PlanarCovered)
            {
                coveredUnityPaths++;
                largestUnityVerticalDeviation = Math.Max(
                    largestUnityVerticalDeviation,
                    unityPathAudit.MaxVerticalDeviation);
            }
            float startDifference = corridor == null ? float.PositiveInfinity :
                Vector3.Distance(ReadVector(reference.GetProperty(
                    "sampledStart")), corridor.SmoothedPoints[0]);
            float endDifference = corridor == null ? float.PositiveInfinity :
                Vector3.Distance(ReadVector(reference.GetProperty(
                    "sampledEnd")), corridor.SmoothedPoints[^1]);
            if (corridor is not { PlanarCovered: true } ||
                corners.GetArrayLength() < 2 ||
                startDifference > 0.25f || endDifference > 0.25f)
                throw new Exception($"Host lacks a covered co-op source route: case {index}, scene {missionMap.Scene}, spawn {spawnId}, point {pointId}, fraction {fraction}, start {start}, end {end}, Unity start {ReadVector(reference.GetProperty("sampledStart"))}, Unity end {ReadVector(reference.GetProperty("sampledEnd"))}, corridor {corridor?.PlanarCovered}, Unity corners {corners.GetArrayLength()}.");
            worstSampleDistance = Math.Max(worstSampleDistance,
                Math.Max(startDifference, endDifference));
            float unityLength = 0;
            for (int corner = 1; corner < corners.GetArrayLength(); corner++)
                unityLength += Vector3.Distance(ReadVector(corners[corner - 1]),
                    ReadVector(corners[corner]));
            float lengthRatio = corridor.SmoothedLength / unityLength;
            worstLengthRatio = Math.Max(worstLengthRatio, lengthRatio);
            float caseCornerDistance = 0;
            if (corners.GetArrayLength() != corridor.SmoothedPoints.Count)
                differentCornerCounts++;
            else
            {
                for (int corner = 0; corner < corners.GetArrayLength(); corner++)
                    caseCornerDistance = Math.Max(caseCornerDistance,
                        Vector3.Distance(ReadVector(corners[corner]),
                            corridor.SmoothedPoints[corner]));
                worstCornerDistance = Math.Max(worstCornerDistance,
                    caseCornerDistance);
            }
            if (corners.GetArrayLength() != corridor.SmoothedPoints.Count ||
                caseCornerDistance > 0.05f)
                differingRoutes++;
        }
        if (!stageCounts.SequenceEqual([14, 9, 4, 7, 2]))
            throw new Exception("Co-op normal-spawn case counts changed.");
        if (worstLengthRatio > 1.09f || differentCornerCounts > 4 ||
            differingRoutes > 11 || worstSampleDistance > 0.09f)
            throw new Exception("Co-op path planner regressed against Unity.");
        Console.WriteLine($"Co-op 36 source paths: maximum host/Unity length {worstLengthRatio:F3}, " +
            $"different routes {differingRoutes} (corner counts {differentCornerCounts}), " +
            $"maximum paired-corner distance {worstCornerDistance:F3}, " +
            $"maximum sampled endpoint distance {worstSampleDistance:F3}, " +
            $"Unity paths covered by host mesh {coveredUnityPaths}/36, " +
            $"vertical deviation {largestUnityVerticalDeviation:F3}.");
    }

    private static int VerifyCoopSceneColliders(
        string directory, MissionCatalog missions)
    {
        string path = Path.Combine(directory,
            "recovered-coop-scene-colliders.json");
        CoopSceneColliderCatalog catalog =
            CoopSceneColliderCatalog.Load(path, missions);
        CoopMeshGeometryCatalog geometry = CoopMeshGeometryCatalog.Load(
            Path.Combine(directory, "recovered-coop-mesh-geometry.json"), catalog);
        CoopSceneColliders desert = catalog.MapForMission(missions, 0);
        CoopSceneCollider[] all = catalog.Maps
            .SelectMany(map => map.Colliders).ToArray();
        if (catalog.Maps.Count != 5 || all.Length != 795 ||
            geometry.Count != 147 || geometry.VertexCount != 14_885 ||
            geometry.TriangleCount != 13_781 ||
            all.Count(row => row.ComponentType == "MeshCollider") != 654 ||
            all.Count(row => row.ComponentType == "BoxCollider") != 139 ||
            all.Count(row => row.ComponentType == "CapsuleCollider") != 2 ||
            all.Count(row => row.Active) != 775 ||
            all.Count(row => row.ActiveInHierarchy) != 721 ||
            all.Count(row => row.ComponentType == "MeshCollider" &&
                row.Shape.MeshFileId == 0) != 54 ||
            desert.Scene != "Desert_New" || desert.Colliders.Count != 106 ||
            all.Where(row => row.Shape.MeshFileId != 0).Any(row =>
                geometry.Get(row.Shape.MeshGuid).Triangles.Count == 0) ||
            all.Any(row => row.TransformChain[0].FileId != row.TransformFileId))
            throw new Exception("Co-op scene collider source identities are incomplete.");

        string temporaryPath = Path.Combine(Path.GetTempPath(),
            $"war-coop-colliders-{Guid.NewGuid():N}.json");
        try
        {
            JsonNode altered = JsonNode.Parse(File.ReadAllText(path))!;
            altered["maps"]![0]!["colliders"]![0]!["layer"] = 31;
            File.WriteAllText(temporaryPath, altered.ToJsonString());
            try
            {
                _ = CoopSceneColliderCatalog.Load(temporaryPath, missions);
                throw new Exception("Altered co-op collider source was accepted.");
            }
            catch (InvalidDataException)
            {
                return 795;
            }
        }
        finally
        {
            File.Delete(temporaryPath);
        }
    }

    private static int VerifyCoopPrefabColliders(string directory)
    {
        string path = Path.Combine(directory,
            "recovered-coop-prefab-colliders.json");
        CoopPrefabColliderCatalog catalog = CoopPrefabColliderCatalog.Load(path);
        CoopMeshGeometryCatalog meshes = CoopMeshGeometryCatalog.LoadPrefabs(
            Path.Combine(directory,
                "recovered-coop-prefab-mesh-geometry.json"), catalog);
        using JsonDocument newGeometry = JsonDocument.Parse(File.ReadAllText(
            Path.Combine(directory, "recovered-coop-prefab-mesh-geometry.json")));
        using JsonDocument earlierGeometry = JsonDocument.Parse(File.ReadAllText(
            Path.Combine(directory, "recovered-air-unit-unity-geometry.json")));
        foreach (JsonElement mesh in newGeometry.RootElement.GetProperty("meshes")
            .EnumerateArray())
        {
            string key = mesh.GetProperty("guid").GetString() + ":4300000";
            JsonElement earlier = earlierGeometry.RootElement
                .GetProperty("meshes").GetProperty(key);
            if (!JsonElement.DeepEquals(mesh.GetProperty("vertices"),
                    earlier.GetProperty("vertices")) ||
                !JsonElement.DeepEquals(mesh.GetProperty("triangles"),
                    earlier.GetProperty("triangles")))
                throw new Exception("Independent Assault Helicopter mesh exports differ.");
        }
        CoopSceneCollider[] all = catalog.Prefabs
            .SelectMany(prefab => prefab.Colliders).ToArray();
        if (catalog.Prefabs.Count != 32 ||
            catalog.NetworkEntries.Count != 31 || all.Length != 128 ||
            meshes.Count != 6 || meshes.VertexCount != 176 ||
            meshes.TriangleCount != 284 ||
            all.Count(row => row.ComponentType == "MeshCollider") != 8 ||
            all.Count(row => row.ComponentType == "BoxCollider") != 78 ||
            all.Count(row => row.ComponentType == "CapsuleCollider") != 31 ||
            all.Count(row => row.ComponentType == "SphereCollider") != 11 ||
            all.Count(row => row.Enabled) != 117 ||
            all.Count(row => row.Trigger) != 24 ||
            all.Count(row => row.ActiveInHierarchy) != 128 ||
            catalog.Prefabs.Sum(prefab => prefab.WheelColliderCount) != 14 ||
            all.Count(row => row.ComponentType == "MeshCollider" &&
                row.Shape.MeshFileId == 0) != 2 ||
            all.Where(row => row.ComponentType == "MeshCollider" &&
                row.Shape.MeshFileId != 0).Any(row =>
                    meshes.Get(row.Shape.MeshGuid).Triangles.Count == 0) ||
            catalog.ForPoolField("enemy").Colliders.Count != 7 ||
            catalog.ForPoolField("assaultHelicopter").Colliders.Count != 11 ||
            catalog.ForPoolField("network:MineAmmo").Colliders.Count != 2 ||
            catalog.ForPoolField("transporter").WheelColliderCount != 6 ||
            catalog.NetworkEntries[0].PrefabField != "enemy")
            throw new Exception("Battle prefab collider inventory changed.");

        string temporaryPath = Path.Combine(Path.GetTempPath(),
            $"war-coop-prefabs-{Guid.NewGuid():N}.json");
        try
        {
            JsonNode altered = JsonNode.Parse(File.ReadAllText(path))!;
            altered["prefabs"]![0]!["colliders"]![0]!["trigger"] = true;
            File.WriteAllText(temporaryPath, altered.ToJsonString());
            try
            {
                _ = CoopPrefabColliderCatalog.Load(temporaryPath);
                throw new Exception("A changed battle prefab collider was accepted.");
            }
            catch (InvalidDataException)
            {
                return all.Length;
            }
        }
        finally
        {
            File.Delete(temporaryPath);
        }
    }

    private static int VerifyCoopNativeSceneRays(
        string directory, MissionCatalog missions)
    {
        string path = Path.Combine(directory,
            "recovered-coop-scene-ray-reference.json");
        byte[] bytes = File.ReadAllBytes(path);
        string digest = Convert.ToHexStringLower(SHA256.HashData(bytes));
        if (digest != "eb3c33575e998192684060320ea1e63a1e950a307086156cca30fe921382a39d")
            throw new Exception("Unity co-op ray reference changed.");

        CoopSceneColliderCatalog colliders = CoopSceneColliderCatalog.Load(
            Path.Combine(directory, "recovered-coop-scene-colliders.json"),
            missions);
        CoopMeshGeometryCatalog geometry = CoopMeshGeometryCatalog.Load(
            Path.Combine(directory, "recovered-coop-mesh-geometry.json"),
            colliders);
        CoopSpawnPointCatalog playerAnchors = CoopSpawnPointCatalog.Load(
            Path.Combine(directory, "recovered-coop-spawn-points.json"),
            missions);
        foreach (CoopSceneColliders sourceMap in colliders.Maps)
        {
            CoopMapSpawnPoints sourceAnchors = playerAnchors.Maps.Single(
                map => map.Scene == sourceMap.Scene);
            _ = new CoopPlayerShotCollisionWorld(sourceMap,
                sourceAnchors, geometry);
        }
        using JsonDocument document = JsonDocument.Parse(bytes);
        JsonElement maps = document.RootElement.GetProperty("maps");
        int checkedRays = 0;
        var physxDifferences = new List<string>();
        var rawMeshDifferences = new List<string>();
        foreach (JsonElement map in maps.EnumerateArray())
        {
            string scene = map.GetProperty("scene").GetString()!;
            CoopSceneColliders source = colliders.Maps.Single(item =>
                item.Scene == scene);
            var raycaster = new CoopNativeSceneRaycaster(source, geometry);
            foreach (JsonElement ray in map.GetProperty("rays").EnumerateArray())
            {
                int componentId = ray.GetProperty("componentFileId").GetInt32();
                Vector3 origin = ReadRayVector(ray.GetProperty("origin"));
                Vector3 direction = ReadRayVector(ray.GetProperty("direction"));
                float maximum = ray.GetProperty("maxDistance").GetSingle();
                CoopNativeRayHit? actual = raycaster.RaycastCollider(
                    componentId, origin, direction, maximum);
                bool expectedHit = ray.GetProperty("hit").GetBoolean();
                string componentType = source.Colliders.Single(c =>
                    c.ComponentFileId == componentId).ComponentType;
                bool differentFromPhysx = expectedHit != (actual != null);
                if (expectedHit && actual != null)
                {
                    float distance = ray.GetProperty("distance").GetSingle();
                    differentFromPhysx |= Math.Abs(actual.Distance - distance) > 0.03f;
                }
                if (differentFromPhysx)
                    physxDifferences.Add($"{scene}/{componentId} {componentType}");

                JsonElement raw = ray.GetProperty("rawMeshDistance");
                if (componentType == "MeshCollider")
                {
                    bool rawHit = raw.ValueKind != JsonValueKind.Null;
                    bool differentFromRaw = rawHit != (actual != null);
                    if (rawHit && actual != null)
                    {
                        float rawDistance = raw.GetSingle();
                        differentFromRaw |= Math.Abs(actual.Distance - rawDistance) > 0.01f;
                    }
                    if (differentFromRaw)
                        rawMeshDifferences.Add($"{scene}/{componentId} " +
                            $"UnityRaw={raw}, host={actual?.Distance}");
                }
                else if (raw.ValueKind != JsonValueKind.Null)
                    throw new Exception("A primitive has a raw mesh ray result.");
                checkedRays++;
            }
        }
        if (maps.GetArrayLength() != 5 || checkedRays != 3_876)
            throw new Exception("Unity co-op ray reference is incomplete.");
        // The raw calculation uses Unity's own sharedMesh and transform.
        // Eight axis-aligned probes graze thin geometry at nearly 90-degree
        // rotations; small matrix-rounding differences change the first hit.
        if (rawMeshDifferences.Count != 8)
            throw new Exception($"Host and Unity raw mesh rays changed: " +
                $"{rawMeshDifferences.Count}: " +
                string.Join("; ", rawMeshDifferences.Take(20)));
        if (physxDifferences.Count != 86 || physxDifferences.Any(item =>
            !item.EndsWith(" MeshCollider", StringComparison.Ordinal)))
            throw new Exception($"Co-op PhysX comparison changed: " +
                $"{physxDifferences.Count}/{checkedRays}: " +
                string.Join("; ", physxDifferences.Take(20)));
        var emptySpace = new CoopShotCollisionWorld(
            new CoopNativeSceneRaycaster(colliders.Maps[0], geometry));
        Vector3 distantOrigin = new(1000, 1000, 1000);
        const string firstAlly = "00000000000000000000000000000001";
        const string secondAlly = "00000000000000000000000000000002";
        PlayerCollisionModel AllyPose(string path, Vector3 center)
        {
            var body = new PlayerHitbox(path + "/body",
                PlayerHitboxKind.Box, 1, center,
                new Vector3(1, 1, 1), Quaternion.Identity, 0,
                Vector3.Zero, 0);
            var head = new PlayerHitbox(path + "/head",
                PlayerHitboxKind.Sphere, 2,
                center + Vector3.UnitY, Vector3.Zero,
                Quaternion.Identity, 0.3f, Vector3.Zero, 0);
            return PlayerCollisionModel.InitializedFrame("test", path,
                center, Quaternion.Identity, [body, head]);
        }
        var alliedPoses = new CollisionPlayer[]
        {
            new(firstAlly, AllyPose("ally/one",
                distantOrigin + new Vector3(0, 0, 5)), 22, 2),
            new(secondAlly, AllyPose("ally/two",
                distantOrigin + new Vector3(3, 0, 5)), 22, 2)
        };
        var playerWorld = new CoopPlayerShotCollisionWorld(
            colliders.Maps[0], playerAnchors.MapForMission(missions, 0),
            geometry);
        ShieldMutation[] intactShields = Enumerable.Range(0, 4)
            .Select(index => new ShieldMutation(index, 2, 100, 100,
                false, 0)).ToArray();
        JsonElement shieldRay = maps[0].GetProperty("rays")
            .EnumerateArray().First(ray =>
                ray.GetProperty("componentFileId").GetInt32() == 1531 &&
                ray.GetProperty("direction")[0].GetSingle() == 1);
        Vector3 shieldRayStart = ReadRayVector(
            shieldRay.GetProperty("origin"));
        Vector3 shieldRayDirection = ReadRayVector(
            shieldRay.GetProperty("direction"));
        uint shieldLayer = 1u << 24;
        CoopPlayerShotHit? intactShieldHit = playerWorld.Trace(
            shieldRayStart, shieldRayDirection, 4, shieldLayer,
            alliedPoses, intactShields);
        ShieldMutation[] destroyedShields = intactShields.ToArray();
        destroyedShields[1] = destroyedShields[1] with
        {
            Health = 0,
            Destroyed = true
        };
        CoopPlayerShotHit? destroyedShieldHit = playerWorld.Trace(
            shieldRayStart, shieldRayDirection, 4, shieldLayer,
            alliedPoses, destroyedShields);
        ShieldMutation[] zeroStartShields = intactShields.ToArray();
        zeroStartShields[0] = zeroStartShields[0] with
        {
            Health = 0,
            MaxHealth = 0
        };
        if (intactShieldHit?.SceneColliderFileId != 1531 ||
            destroyedShieldHit != null ||
            playerWorld.Trace(shieldRayStart, shieldRayDirection, 4,
                shieldLayer, alliedPoses, intactShields)
                ?.SceneColliderFileId != 1531 ||
            playerWorld.Trace(shieldRayStart, shieldRayDirection, 4,
                shieldLayer, alliedPoses, zeroStartShields)
                ?.SceneColliderFileId != 1531)
            throw new Exception("Co-op shield collision did not follow live cover state: " +
                $"intact={intactShieldHit?.SceneColliderFileId}, " +
                $"destroyed={destroyedShieldHit?.SceneColliderFileId}");
        uint recoveredEnemyMask = unchecked((uint)-143121921);
        CoopPlayerShotHit? allyHit = playerWorld.Trace(distantOrigin,
            Vector3.UnitZ, 10, recoveredEnemyMask, alliedPoses);
        if (allyHit?.PlayerId != firstAlly ||
            allyHit.PlayerPartPath != "ally/one/body" ||
            Math.Abs(allyHit.Distance - 4.5f) > 0.001f ||
            playerWorld.Trace(distantOrigin, Vector3.UnitZ, 10,
                recoveredEnemyMask & ~(1u << 22), alliedPoses) != null)
            throw new Exception("Co-op enemy ray lost allied pose or source mask.");
        try
        {
            playerWorld.Trace(distantOrigin, Vector3.UnitZ, 10,
                recoveredEnemyMask, [alliedPoses[0], alliedPoses[0]]);
            throw new Exception("A duplicate co-op ally was accepted.");
        }
        catch (InvalidDataException) { }
        try
        {
            playerWorld.Trace(distantOrigin, Vector3.UnitZ, 10,
                recoveredEnemyMask,
                [alliedPoses[0] with { Fraction = 1 }, alliedPoses[1]]);
            throw new Exception("A non-allied co-op pose was accepted.");
        }
        catch (InvalidDataException) { }
        var hitbox = new PlayerHitbox("host/drone", PlayerHitboxKind.Sphere,
            1, distantOrigin + new Vector3(0, 0, 5), Vector3.Zero,
            Quaternion.Identity, 1, Vector3.Zero, 0);
        var target = new DynamicShotTarget(7, 42, 27, hitbox,
            DroneRoot: true);
        var completeFrame = new CoopEnemyCollisionFrame([target], []);
        uint enemyLayer = 1u << 27;
        CoopShotHit? hostHit = emptySpace.Trace(distantOrigin, Vector3.UnitZ,
            10, enemyLayer, completeFrame);
        if (hostHit?.EnemyEntityId != 7 ||
            hostHit.EnemyPartFileId != 42 ||
            Math.Abs(hostHit.Distance - 4) > 0.001f ||
            emptySpace.Trace(distantOrigin, Vector3.UnitZ, 10, 0,
                completeFrame) != null ||
            emptySpace.Trace(distantOrigin, Vector3.UnitZ, 3, enemyLayer,
                completeFrame) != null)
            throw new Exception("Co-op shot tracing lost host enemy geometry or layer/range bounds.");
        bool rejectedDuplicate = false;
        try
        {
            emptySpace.Trace(distantOrigin, Vector3.UnitZ, 10, enemyLayer,
                new CoopEnemyCollisionFrame([target, target], []));
        }
        catch (InvalidDataException)
        {
            rejectedDuplicate = true;
        }
        if (!rejectedDuplicate)
            throw new Exception("One co-op collider was supplied twice.");
        bool rejectedMissing = false;
        try
        {
            emptySpace.Trace(distantOrigin, Vector3.UnitZ, 10,
                enemyLayer, new CoopEnemyCollisionFrame([target], [8]));
        }
        catch (InvalidOperationException)
        {
            rejectedMissing = true;
        }
        if (!rejectedMissing)
            throw new Exception("A live co-op enemy was omitted from shot authority.");
        var infantryPart = new DynamicShotTarget(8, 0, 23, hitbox,
            ArmyInfantry: true);
        CoopShotHit? infantryHit = emptySpace.Trace(distantOrigin,
            Vector3.UnitZ, 10, 1u << 23,
            new CoopEnemyCollisionFrame([infantryPart], []));
        if (infantryHit?.EnemyEntityId != 8 ||
            infantryHit.EnemyPartFileId != null ||
            infantryHit.EnemyPartPath != hitbox.SourcePath ||
            infantryHit.PartWeight != hitbox.Weight)
            throw new Exception("Source infantry hit part lost its path or damage weight.");
        return checkedRays - physxDifferences.Count + 6;
    }

    private static Vector3 ReadRayVector(JsonElement values)
    {
        return new Vector3(values[0].GetSingle(), values[1].GetSingle(),
            values[2].GetSingle());
    }

    private static int VerifyCoopEnemyPoints(
        string directory, MissionCatalog missions, ArmyDeploymentCatalog army)
    {
        CoopSpawnPointCatalog spawns = CoopSpawnPointCatalog.Load(
            Path.Combine(directory, "recovered-coop-spawn-points.json"),
            missions);
        string path = Path.Combine(directory,
            "recovered-coop-enemy-points.json");
        CoopEnemyPointCatalog catalog = CoopEnemyPointCatalog.Load(path,
            missions, spawns);
        string rusherPath = Path.Combine(directory,
            "recovered-coop-rusher-points.json");
        CoopRusherPointCatalog rushers = CoopRusherPointCatalog.Load(
            rusherPath, missions, spawns);
        CoopMapEnemyPoints desert = catalog.MapForMission(missions, 0);
        CoopMapRusherPoints desertRushers = rushers.MapForMission(missions, 0);
        CoopEnemyPoint[] all = catalog.Maps.SelectMany(map => map.Points)
            .ToArray();
        CoopEnemyPoint obstacle = desert.Points.First(point =>
            point.ComponentType == "EnemyPointObstacle");
        CoopEnemyPoint engineer = desert.Points.First(point =>
            point.ComponentType == "EnemyPointEngineerTurret");
        CoopEnemyPoint corner = desert.Points.Single(point =>
            point.ComponentFileId == 1698);
        CoopEnemyPoint? sciFiInitial =
            CoopEnemyPointSelection.SelectNearestToFloor(desert, 2,
                new HashSet<int>());
        Vector3 expectedEngineer = engineer.TransformPosition -
            Vector3.Transform(Vector3.UnitZ, engineer.Rotation) * 0.2f;
        if (catalog.Maps.Count != 5 || all.Length != 130 ||
            rushers.Maps.Sum(map => map.PlayerPoints.Sum(player =>
                player.Points.Count)) != 80 ||
            desertRushers.PlayerPoints.Count != 4 ||
            desert.Points.Count != 26 ||
            desert.FloorTransformFileId != 689 ||
            sciFiInitial?.ComponentFileId != 1832 ||
            catalog.MapForMission(missions, 0).Scene !=
                missions.MapForMission(0).Scene ||
            all.Count(point => point.SegmentStart.HasValue) != 58 ||
            all.Count(point => point.ComponentType ==
                "EnemyPointEngineerTurret") != 20 ||
            all.Count(point => point.CornerDirection.HasValue) != 5 ||
            corner.CornerDirection != Vector3.UnitX ||
            corner.CornerRightSide != true ||
            obstacle.SegmentStart == null || obstacle.SegmentEnd == null ||
            Vector3.Distance(obstacle.Position,
                (obstacle.SegmentStart.Value +
                 obstacle.SegmentEnd.Value) * 0.5f) > 0.0001f ||
            Vector3.Distance(engineer.Position, expectedEngineer) > 0.0001f)
            throw new Exception("Co-op enemy destinations differ from the source scenes.");

        Vector3 enemyAtCorner = corner.Position;
        // direction +X makes -X the zero-angle line. The first target is
        // exposed on the serialized right side; the second is behind cover.
        if (!CoopCornerShotPolicy.CanExpose(corner, enemyAtCorner,
                enemyAtCorner + new Vector3(-1, 0, 1)) ||
            CoopCornerShotPolicy.CanExpose(corner, enemyAtCorner,
                enemyAtCorner + new Vector3(-1, 0, -1)) ||
            CoopCornerShotPolicy.CanExpose(corner, enemyAtCorner,
                enemyAtCorner + new Vector3(-1, 0, 0.1f)))
            throw new Exception("Co-op corner side/dead-zone gate differs from Client.");

        CoopPlayerRusherPoints sourceShield = desertRushers.PlayerPoints[0];
        CoopRusherPoint[] orderedRushers = sourceShield.Points.ToArray();
        CoopPlayerRusherPoints priorityShield = sourceShield with
        {
            Points =
            [
                orderedRushers[0] with { Position = new Vector3(2, 0, 0) },
                orderedRushers[1] with { Position = new Vector3(3, 0, 0) },
                orderedRushers[2] with { Position = Vector3.Zero },
                orderedRushers[3] with { Position = new Vector3(0.1f, 0, 0) }
            ]
        };
        CoopRusherPoint? preferred = CoopRusherPointCatalog.ChooseInitial(
            priorityShield, Vector3.Zero, new HashSet<int>(), 0);
        CoopRusherPoint? fallback = CoopRusherPointCatalog.ChooseInitial(
            priorityShield, Vector3.Zero,
            new HashSet<int>
            {
                orderedRushers[0].ComponentFileId,
                orderedRushers[1].ComponentFileId
            }, 0);
        if (preferred?.SourceIndex != 0 || fallback?.SourceIndex != 2 ||
            CoopRusherPointCatalog.ChooseInitial(priorityShield,
                Vector3.Zero, new HashSet<int>(), 4) != null)
            throw new Exception("Shield-linked Rusher point priority differs from Client.");

        string maskPath = Path.Combine(directory,
            "recovered-coop-enemy-point-masks.json");
        CoopEnemyPointMaskCatalog masks = CoopEnemyPointMaskCatalog.Load(
            maskPath, army);
        CoopSoldierPointMask assaulter = masks.Soldiers[0];
        if (masks.Soldiers.Count != 16 ||
            assaulter.UnitId != "ID_UNIT-ASSAULT" || assaulter.Mask != 14)
            throw new Exception("Co-op soldier point masks differ from MainScene.");
        CoopSoldierPointMask engineerMask = masks.Soldiers.Single(soldier =>
            soldier.BehaviorType == "SoldierBehaviourEngineer");
        CoopSoldierPointMask parachuterMask = masks.Soldiers.Single(soldier =>
            soldier.BehaviorType == "SoldierBehaviourParachuter");
        CoopSoldierPointMask swatMask = masks.Soldiers.Single(soldier =>
            soldier.BehaviorType == "SoldierBehaviourSwat");
        CoopSoldierPointMask sniperMask = masks.Soldiers.Single(soldier =>
            soldier.BehaviorType == "SoldierBehaviourSniper");
        if (CoopEnemyPointSelection.InitialMask(engineerMask, false) != 256 ||
            CoopEnemyPointSelection.InitialMask(parachuterMask, true) != 6 ||
            CoopEnemyPointSelection.InitialMask(swatMask, true) != 32 ||
            sniperMask.MinimumPlayerDistance != 6f)
            throw new Exception("Special soldier point acceptance differs from Client.");
        try
        {
            _ = CoopEnemyPointSelection.InitialMask(parachuterMask, false);
            throw new Exception("Ordinary Parachuter bypassed shield-linked Rusher points.");
        }
        catch (NotSupportedException)
        {
            // Its inherited GetInitPoint uses the active player's rusher list.
        }
        try
        {
            _ = CoopEnemyPointSelection.InitialMask(swatMask, false);
            throw new Exception("Ordinary Swat bypassed shield-linked Rusher points.");
        }
        catch (NotSupportedException)
        {
            // Card-spawned Swat uses GetPoint; ordinary Swat does not.
        }

        CoopEnemyPoint? nearest = CoopEnemyPointSelection.SelectOrdinary(
            desert, assaulter.Mask, obstacle.TransformPosition,
            new HashSet<int>());
        if (nearest == null || (assaulter.Mask & PointBit(nearest)) == 0)
            throw new Exception("Ordinary soldier did not select a free accepted point.");
        HashSet<int> occupied = [nearest.ComponentFileId];
        CoopEnemyPoint? next = CoopEnemyPointSelection.SelectOrdinary(
            desert, assaulter.Mask, obstacle.TransformPosition, occupied);
        if (next?.ComponentFileId == nearest.ComponentFileId)
            throw new Exception("Occupied enemy point was selected again.");

        // A source-only specialist point must not become an ordinary hiding point.
        CoopEnemyPoint? minigunner = CoopEnemyPointSelection.SelectOrdinary(
            desert, 128, obstacle.TransformPosition, new HashSet<int>());
        if (minigunner?.ComponentType != "EnemyPointMinigunner")
            throw new Exception("Co-op point mask did not restrict the point type.");

        CoopEnemyPoint[] equalDistance =
        [
            obstacle with { Order = 0, ComponentFileId = 1,
                TransformPosition = new Vector3(-1, 0, 0),
                Position = new Vector3(-1, 0, 0) },
            obstacle with { Order = 1, ComponentFileId = 2,
                TransformPosition = new Vector3(1, 0, 0),
                Position = new Vector3(1, 0, 0) }
        ];
        CoopMapEnemyPoints tiedMap = desert with { Points = equalDistance };
        CoopEnemyPoint? first = CoopEnemyPointSelection.SelectOrdinary(
            tiedMap, 2, Vector3.Zero, new HashSet<int>());
        if (first?.ComponentFileId != 1)
            throw new Exception("Equal-distance enemy points lost source order.");
        CoopMapEnemyPoints nextMap = tiedMap with
        {
            Points =
            [
                equalDistance[0], equalDistance[1],
                equalDistance[1] with
                {
                    Order = 2, ComponentFileId = 3,
                    Position = new Vector3(3, 0, 0),
                    TransformPosition = new Vector3(3, 0, 0)
                }
            ]
        };
        CoopEnemyPoint? distantSciFi = CoopEnemyPointSelection.SelectNext(
            nextMap, 2, 1, new HashSet<int> { 1 }, _ => 0,
            sciFiPosition: Vector3.Zero);
        if (distantSciFi?.ComponentFileId != 3)
            throw new Exception("SciFi retarget did not prefer a distant free point.");

        CoopEnemyPointReservations reservations = new(desert);
        if (!reservations.TryReserve(100, nearest) ||
            reservations.TryReserve(101, nearest) ||
            !reservations.OccupiedPointIds.Contains(nearest.ComponentFileId))
            throw new Exception("Two enemies claimed one co-op destination.");
        if (next != null &&
            (!reservations.TryReserve(100, next) ||
             reservations.OccupiedPointIds.Contains(nearest.ComponentFileId) ||
             !reservations.OccupiedPointIds.Contains(next.ComponentFileId)))
            throw new Exception("Retargeting did not release the previous point.");
        if (!reservations.Release(100) || reservations.Release(100) ||
            reservations.OccupiedPointIds.Count != 0)
            throw new Exception("Enemy death did not free its destination once.");
        reservations.SetEngineerTurret(engineer, true);
        if (reservations.TryReserve(102, engineer) ||
            !reservations.OccupiedPointIds.Contains(engineer.ComponentFileId))
            throw new Exception("Live engineer turret left its point free.");
        reservations.SetEngineerTurret(engineer, false);
        if (!reservations.TryReserve(102, engineer) ||
            !reservations.Release(102))
            throw new Exception("Destroyed engineer turret did not free its point.");

        Vector3 obstacleStart = CoopEnemyPointSelection.GeneratePosition(
            obstacle, 0);
        Vector3 obstacleEnd = CoopEnemyPointSelection.GeneratePosition(
            obstacle, 1);
        if (Vector3.Distance(obstacleStart, obstacle.SegmentStart!.Value) >
                0.00001f ||
            Vector3.Distance(obstacleEnd, obstacle.SegmentEnd!.Value) >
                0.00001f ||
            CoopEnemyPointSelection.GeneratePosition(engineer, 0.5f) !=
                engineer.Position)
            throw new Exception("Point destination generation differs from Client.");

        CoopEnemyPoint? tooClose = CoopEnemyPointSelection.SelectOrdinary(
            tiedMap, 2, Vector3.Zero, new HashSet<int>(),
            new Vector3(-1, 0, 0), 0.5f);
        if (tooClose?.ComponentFileId != 2)
            throw new Exception("Sniper minimum distance did not filter a point.");

        string damagedMaskPath = Path.Combine(Path.GetTempPath(),
            $"war-coop-point-masks-{Guid.NewGuid():N}.json");
        try
        {
            JsonNode damagedMasks = JsonNode.Parse(
                File.ReadAllText(maskPath))!;
            damagedMasks["soldiers"]![0]!["enemyPointMask"] = 0;
            File.WriteAllText(damagedMaskPath, damagedMasks.ToJsonString());
            try
            {
                _ = CoopEnemyPointMaskCatalog.Load(damagedMaskPath, army);
                throw new Exception("Changed co-op point mask was accepted.");
            }
            catch (InvalidDataException)
            {
                // The complete source artifact is pinned before selection.
            }
        }
        finally
        {
            File.Delete(damagedMaskPath);
        }

        string damagedPath = Path.Combine(Path.GetTempPath(),
            $"war-coop-enemy-points-{Guid.NewGuid():N}.json");
        try
        {
            JsonNode damaged = JsonNode.Parse(File.ReadAllText(path))!;
            damaged["maps"]![0]!["points"]![0]!["componentFileId"] = 0;
            File.WriteAllText(damagedPath, damaged.ToJsonString());
            try
            {
                _ = CoopEnemyPointCatalog.Load(damagedPath, missions, spawns);
                throw new Exception("Changed co-op enemy point authority was accepted.");
            }
            catch (InvalidDataException)
            {
                // Source identities cannot be substituted at Worker startup.
            }
        }
        finally
        {
            File.Delete(damagedPath);
        }
        return 30 + CoopExternalPointSelectionTests.Run(desert, obstacle) + CoopCrewFallbackTests.Run(missions, spawns);
    }

    private static int PointBit(CoopEnemyPoint point) => point.ComponentType switch
    {
        "EnemyPointObstacle" => 2,
        "EnemyPointCorner" => 4,
        "EnemyPointMinigunner" => 128,
        _ => 0
    };

    private static int VerifyCoopSpawnCatalog(string directory, MissionCatalog missions)
    {
        string path = Path.Combine(directory, "recovered-coop-spawn-points.json");
        CoopSpawnPointCatalog spawns = CoopSpawnPointCatalog.Load(path, missions);
        CoopMapSpawnPoints desert = spawns.MapForMission(missions, 0);
        if (spawns.Maps.Count != 5 ||
            spawns.Maps.Sum(map => map.SpawnPoints.Count) != 59 ||
            spawns.Maps.Sum(map => map.PlayerPositions.Count) != 20 ||
            spawns.Maps.SelectMany(map => map.PlayerPositions).Any(anchor =>
                anchor.SourceRotation is null ||
                Math.Abs(anchor.SourceRotation.Value.LengthSquared() - 1) > 0.0002f) ||
            spawns.Maps.SelectMany(map => map.SpawnPoints).Any(point =>
                point.SourceRotation is null ||
                Math.Abs(point.SourceRotation.Value.LengthSquared() - 1) > 0.0002f) ||
            desert.Scene != "Desert_New" || desert.EnemySpawnPoints.Count != 13 ||
            desert.SpawnPoints.Any(point =>
                point.Collection == "spawnPointsCollectionAssaultHelis"))
            throw new Exception("Co-op spawn anchors do not match the five source scenes.");

        CoopMapSpawnPoints snow = spawns.Maps[1];
        if (snow.SpawnPoints.Count(point => point.Fraction == 2) != 4 ||
            snow.EnemySpawnPoints.Any(point => point.Fraction != 1))
            throw new Exception("Allied source spawns must not become enemy AI anchors.");

        foreach (MissionRule mission in missions.Missions.Where(
                     mission => mission.MissionType != "KillOpponent"))
            _ = new CoopAiSpawnSelector(missions, spawns, mission.Index);
        try
        {
            _ = new CoopAiSpawnSelector(missions, spawns, 4);
            throw new Exception("A boss mission used single-player AI spawn anchors.");
        }
        catch (InvalidDataException)
        {
        }
        CoopAiSpawnSelector desertSelector = new(missions, spawns, 0);
        if (desertSelector.Candidates("Drone").Any(point =>
                point.Collection != "spawnPointsCollectionDrones" || point.Fraction != 1) ||
            desertSelector.Candidates("Tank").Any(point =>
                point.Collection != "spawnPointsCollectionCars" || point.Fraction != 1) ||
            desertSelector.Candidates("DeployHeli").Any(point =>
                point.Collection != "spawnPointsCollectionHelicopters" || point.Fraction != 1))
            throw new Exception("Co-op AI must use its source enemy spawn collection.");

        string temporaryPath = Path.Combine(Path.GetTempPath(),
            $"war-coop-spawns-{Guid.NewGuid():N}.json");
        try
        {
            JsonNode document = JsonNode.Parse(File.ReadAllText(path))!;
            document["maps"]![0]!["spawnPoints"]![0]!["fraction"] = 0;
            File.WriteAllText(temporaryPath, document.ToJsonString());
            try
            {
                _ = CoopSpawnPointCatalog.Load(temporaryPath, missions);
                throw new Exception("A corrupt co-op spawn fraction was accepted.");
            }
            catch (InvalidDataException)
            {
                return 79;
            }
        }
        finally
        {
            File.Delete(temporaryPath);
        }
    }

    internal static int Run(string directory)
    {
        int count=0;
        count += HelicopterRopeAlignmentTests.Run(directory);
        var content=BattleCombatContent.Load(Path.Combine(directory,"combat-content-manifest.json"));
        count += HelicopterSlidePalmTests.Run(directory, content.EnemyPoses);
        count += HelicopterPalmBlendTests.Run(directory, content.EnemyPoses);
        count += HelicopterPalmRawWeightTests.Run(directory, content.EnemyPoses);
        count += HelicopterPalmRemainderTests.Run(directory, content.EnemyPoses);
        count += HelicopterCrewRetryClockTests.Run(directory);
        count += CoopEntityIdAllocatorTests.Run();
        count += TransportCrewActorTests.Run();
        count += HelicopterSlideFadeTests.Run(directory);
        count += HelicopterRopeExtensionTests.Run(directory);
        count += HelicopterRopeInitializationTests.Run(directory);
        count += HelicopterRopeConstraintFrameTests.Run(directory);
        count += HelicopterRopeSimulationTests.Run(directory);
        count += VerifyMissionCatalog(directory, content);
        void Check(bool ok,string name) { if (!ok) throw new Exception(name);count++; }
        void Reject(Action action) { try { action(); } catch (InvalidDataException) { count++;return; } throw new Exception("Invalid combat allocation accepted."); }
        var sourceWeaponPose = content.Poses.SampleBlended("idle", 0, true,
            "idle", 0, true, 0);
        var placedWeaponPose = sourceWeaponPose.Place(new Vector3(3, 0, -2),
            Quaternion.CreateFromAxisAngle(Vector3.UnitY, MathF.PI));
        foreach (var binding in content.AllWeaponBindings.AllBindings)
        {
            var root = sourceWeaponPose.WeaponRoot(binding.SourceId);
            var placedRoot = placedWeaponPose.WeaponRoot(binding.SourceId);
            Vector3 expected = placedRoot.RootPosition + Vector3.Transform(
                root.Position - root.RootPosition,
                placedRoot.RootRotation * Quaternion.Inverse(root.RootRotation));
            Check(root.SourcePath == binding.WeaponPath &&
                  Vector3.Distance(placedRoot.Position, expected) < 0.0001f,
                "source weapon root follows the validated player rig: " + binding.SourceId);
        }
        Reject(() => sourceWeaponPose.WeaponRoot("unknown-weapon"));
        Vector3 Vec(JsonElement value)=>new(value.GetProperty("x").GetSingle(),
            value.GetProperty("y").GetSingle(),value.GetProperty("z").GetSingle());
        var firstAssaultMuzzle = content.AssaultHelicopterWeapons.Muzzle(
            0, Vector3.Zero, Quaternion.Identity);
        var secondAssaultMuzzle = content.AssaultHelicopterWeapons.Muzzle(
            1, Vector3.Zero, Quaternion.Identity);
        Check(firstAssaultMuzzle == new Vector3(.3287352f, -.24099445f, .04579982f) &&
              secondAssaultMuzzle == new Vector3(-.31855813f, -.24099472f, .045799464f),
            "pinned Assault Helicopter prefab binds two distinct source gun muzzles");
        var turnedAssaultMuzzle = content.AssaultHelicopterWeapons.Muzzle(0,
            new Vector3(1, 2, 3), Quaternion.CreateFromAxisAngle(Vector3.UnitY, MathF.PI));
        Check(Vector3.Distance(turnedAssaultMuzzle,
                  new Vector3(1 - .3287352f, 2 - .24099445f, 3 - .04579982f)) < .000001f,
            "Assault Helicopter gun muzzle follows the host root rotation");
        Reject(() => content.AssaultHelicopterWeapons.Muzzle(2,
            Vector3.Zero, Quaternion.Identity));
        var assaultBodyBox = content.AssaultHelicopterBoxCollider.Place(
            Vector3.Zero, Quaternion.Identity);
        Check(assaultBodyBox.Kind == PlayerHitboxKind.Box &&
              Vector3.Distance(assaultBodyBox.Center,
                  new Vector3(.0043849445f, .0405483f, .03434353f)) < .00001f &&
              assaultBodyBox.Size == new Vector3(.50202096f, .542398f, .27047324f),
            "pinned Assault Helicopter body box retains its source center and size");
        Reject(() => content.AssaultHelicopterBoxCollider.Place(Vector3.Zero, default));
        var tetrahedron = new TriangleMeshGeometry(
            [Vector3.Zero, Vector3.UnitX, Vector3.UnitY, Vector3.UnitZ],
            [0, 2, 1, 0, 1, 3, 0, 3, 2, 1, 2, 3]);
        var tetrahedronHitbox = new PlayerHitbox("test-convex-mesh", 1,
            Vector3.Zero, Quaternion.Identity, tetrahedron, Vector3.Zero);
        Check(tetrahedronHitbox.Raycast(new Vector3(2, .2f, .2f), -Vector3.UnitX, 3f)
                  is > 1f and < 2f &&
              tetrahedronHitbox.Raycast(new Vector3(.1f, .1f, .1f), Vector3.UnitX, 3f) == null &&
              tetrahedronHitbox.OverlapsSphere(new Vector3(.1f, .1f, .1f), .01f) &&
              tetrahedronHitbox.DistanceToPoint(new Vector3(.1f, .1f, .1f)) == 0,
            "convex mesh queries preserve exterior rays and interior overlap semantics");
        var assaultBodyMeshes = content.AssaultHelicopterMeshColliders.Place(
            Vector3.Zero, Quaternion.Identity);
        Check(content.AssaultHelicopterMeshColliders.Count == 5 &&
              assaultBodyMeshes.Count == 5 &&
              assaultBodyMeshes.Select(mesh => mesh.ColliderFileId).Distinct().Count() == 5 &&
              assaultBodyMeshes.All(mesh => mesh.Hitbox.Kind == PlayerHitboxKind.Mesh &&
                  content.AssaultHelicopterMeshColliders.HasCollider(mesh.ColliderFileId)),
            "independent Unity triangle export binds five distinct Assault Helicopter body parts");
        Check(assaultBodyMeshes.All(mesh =>
                  mesh.Hitbox.Raycast(mesh.Hitbox.Center + Vector3.UnitX * 5,
                      -Vector3.UnitX, 10f).HasValue &&
                  mesh.Hitbox.Raycast(mesh.Hitbox.Center + Vector3.UnitX * 5,
                      Vector3.UnitX, 10f) == null),
            "Assault Helicopter body meshes use their triangles for hit and miss rays");
        var frontGlass = content.AssaultHelicopterMeshColliders.PlaceFrontGlass(
            Vector3.Zero, Quaternion.Identity);
        Check(frontGlass.ColliderFileId == 6468680 &&
              frontGlass.PartComponentFileId == 11485712 &&
              frontGlass.Hitbox.Kind == PlayerHitboxKind.Mesh &&
              frontGlass.Hitbox.OverlapsSphere(frontGlass.Hitbox.Center, .5f),
            "front glass uses its own damage part and assigned Unity mesh triangles");
        using (var glassGeometry = JsonDocument.Parse(File.ReadAllBytes(Path.Combine(directory,
            "recovered-air-unit-unity-geometry.json"))))
        {
            var sourceMesh = glassGeometry.RootElement.GetProperty("meshes")
                .GetProperty("799a7c85c474ee0449daf0e57600399c:4300000");
            var vertices = sourceMesh.GetProperty("vertices");
            var triangle = sourceMesh.GetProperty("triangles");
            Vector3 Point(JsonElement point) => new(point[0].GetSingle(),
                point[1].GetSingle(), point[2].GetSingle());
            Vector3 Vertex(int index)
            {
                var point = vertices[triangle[index].GetInt32()];
                return Point(point);
            }
            Vector3 first = Vertex(0), second = Vertex(1), third = Vertex(2);
            Vector3 glassTriangleMidpoint = (first + second + third) / 3f;
            Vector3 glassTriangleNormal = Vector3.Normalize(Vector3.Cross(second - first, third - first));
            var allGlassVertices = vertices.EnumerateArray().Select(Point).ToArray();
            Vector3 glassBoundsCenter = (allGlassVertices.Aggregate(Vector3.Min) +
                allGlassVertices.Aggregate(Vector3.Max)) / 2f;
            Vector3 glassOrigin = frontGlass.Hitbox.Center -
                Vector3.Transform(glassBoundsCenter, frontGlass.Hitbox.Rotation);
            Vector3 worldMidpoint = glassOrigin +
                Vector3.Transform(glassTriangleMidpoint, frontGlass.Hitbox.Rotation);
            Vector3 worldNormal = Vector3.Transform(glassTriangleNormal, frontGlass.Hitbox.Rotation);
            Check(frontGlass.Hitbox.Raycast(worldMidpoint + worldNormal, -worldNormal, 2f)
                      is > .9f and < 1.1f ||
                  frontGlass.Hitbox.Raycast(worldMidpoint - worldNormal, worldNormal, 2f)
                      is > .9f and < 1.1f,
                "a ray aimed at a recovered front glass triangle intersects its live hitbox");
        }
        Reject(() => content.AssaultHelicopterMeshColliders.PlaceFrontGlass(
            Vector3.Zero, default));
        var heliBoxes=content.HelicopterBodyColliders.Place(Vector3.Zero,Quaternion.Identity);
        using(var geometryReference=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(directory,
            "recovered-air-unit-unity-geometry.json"))))
        {
            var unityHeli=geometryReference.RootElement.GetProperty("units").EnumerateArray()
                .Single(x=>x.GetProperty("source").GetString()=="Assets/GameObject/Helicopter.prefab");
            var unityBoxes=unityHeli.GetProperty("colliders").EnumerateArray().ToArray();
            Check(content.HelicopterBodyColliders.Count==11&&heliBoxes.Count==11&&
                  unityBoxes.Length==11&&heliBoxes.Select(x=>x.ColliderFileId)
                      .SequenceEqual(unityBoxes.Select(x=>x.GetProperty("componentFileId").GetInt32()))&&
                  heliBoxes.Select(x=>x.PartComponentFileId).Distinct().Count()==11&&
                  heliBoxes.All(x=>x.Layer==8&&x.Hitbox.Kind==PlayerHitboxKind.Box),
                  "combat package binds eleven ordered Helicopter boxes to unique damage parts");
            for(int i=0;i<heliBoxes.Count;i++)
            {
                var reference=unityBoxes[i];var center=reference.GetProperty("center");
                var q=reference.GetProperty("rotation");
                Check(Vector3.Distance(heliBoxes[i].Hitbox.Center,
                          new Vector3(center[0].GetSingle(),center[1].GetSingle(),
                              center[2].GetSingle()))<.0002f&&
