            var paratrooperSpawns = new CardSpawnUnitSchedule("ELITEPARA", 90);
            Check(paratrooperSpawns.Count == 2 &&
                  paratrooperSpawns.DueTick(0) == 90 &&
                  paratrooperSpawns.DueTick(1) == 105,
                "the second paratrooper card call follows the source half-second delay");
            var sniperSpawns = new CardSpawnUnitSchedule("ELITESNIPER", 90);
            Check(sniperSpawns.Count == 2 &&
                  sniperSpawns.DueTick(0) == 90 &&
                  sniperSpawns.DueTick(1) == 90,
                "zero-delay card calls may spawn both sniper units on one host tick");
            var droneSpawns = new CardSpawnUnitSchedule("HEAVYDRONE", 90);
            Check(droneSpawns.Count == 1 && droneSpawns.DueTick(0) == 90,
                "single-unit card activation schedules exactly one drone");
            Reject(()=>paratrooperSpawns.DueTick(2));
            Reject(()=>droneSpawns.DueTick(1));
            Reject(()=>new CardSpawnUnitSchedule("ELITEPARA", ulong.MaxValue));
            var cardSpawnState = new CardUnitSpawnState(pendingLimit: 2);
            const string firstCardRequest = "a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1";
            const string secondCardRequest = "b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2";
            Check(cardSpawnState.TrySchedule(firstCardRequest, "card-owner", "ELITEPARA", 90) &&
                  !cardSpawnState.TrySchedule(firstCardRequest, "card-owner", "ELITEPARA", 90) &&
                  !cardSpawnState.TrySchedule(secondCardRequest, "card-owner", "HEAVYDRONE", 90) &&
                  cardSpawnState.PendingCount == 2,
                "unit-card scheduling is bounded and duplicate requests cannot create extra units");
            var firstDueCardUnit = cardSpawnState.Due(90).Single();
            Check(firstDueCardUnit.SourceCardId == "ELITEPARA" &&
                  firstDueCardUnit.UnitIndex == 0 &&
                  !cardSpawnState.Complete(firstDueCardUnit, 89) &&
                  cardSpawnState.Complete(firstDueCardUnit, 90) &&
                  !cardSpawnState.Complete(firstDueCardUnit, 90) &&
                  cardSpawnState.Due(104).Count == 0,
                "the first unit is consumed once and the delayed second unit waits");
            Check(cardSpawnState.TrySchedule(secondCardRequest, "card-owner", "HEAVYDRONE", 104) &&
                  cardSpawnState.Due(104).Single().SourceCardId == "HEAVYDRONE" &&
                  cardSpawnState.Due(105).Count == 2,
                "another card can occupy released pending capacity without shifting due times");
            Check(!cardSpawnState.CancelBeforeSpawn(firstCardRequest) &&
                  cardSpawnState.CancelBeforeSpawn(secondCardRequest) &&
                  cardSpawnState.PendingCount == 1 &&
                  cardSpawnState.TrySchedule(secondCardRequest,
                      "card-owner", "HEAVYDRONE", 106),
                "a failed activation can undo only its entirely unspawned card call");
            Reject(()=>cardSpawnState.TrySchedule("not-a-request", "card-owner", "HEAVYDRONE", 1));
            Reject(()=>cardSpawnState.TrySchedule("C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3",
                "card-owner", "HEAVYDRONE", 1));
            var cardMap = content.Maps[0];
            string cardEnemyPointPath = Path.Combine(directory,
                "recovered-multiplayer-card-enemy-points.json");
            var cardInitialPoints = content.CardUnitInitialPoints;
            string parachuteReferencePath = Path.Combine(directory,
                "recovered-parachute-fall-reference.json");
            byte[] parachuteReferenceBytes = File.ReadAllBytes(parachuteReferencePath);
            Check(Convert.ToHexStringLower(SHA256.HashData(parachuteReferenceBytes)) ==
                  "86a20fac4001a59892c0f66082172f5a1b4f83a7f1fa877b7a0ccd5bd815177e",
                "Parachute Unity trace summary retains its reviewed source revision");
            using var parachuteDocument = JsonDocument.Parse(parachuteReferenceBytes);
            JsonElement parachuteReference = parachuteDocument.RootElement;
            Check(parachuteReference.GetProperty("unityVersion").GetString() ==
                      "2018.3.0f2" &&
                  parachuteReference.GetProperty("sourcePrefabSha256").GetString() ==
                      "0c6bf529101a625276bd3560a5b83a7249e404275dbf15b0ad2ac2c2864c729a" &&
                  parachuteReference.GetProperty("physicsSettingsSha256").GetString() ==
                      "044c87594dbc3f5a1bc257f823e49c587e4ce03558d0edcc31c367168d19ddf1" &&
                  parachuteReference.GetProperty("parachuteCollisionMask").GetString() ==
                      "000020c9" &&
                  parachuteReference.GetProperty("fixedTimestep").GetSingle() ==
                      CardParachutePreContactMotion.FixedSeconds &&
                  parachuteReference.GetProperty("dragFactor").GetSingle() ==
                      CardParachutePreContactMotion.DragFactor &&
                  parachuteReference.GetProperty("forwardForce").GetSingle() ==
                      CardParachutePreContactMotion.ForwardForce,
                "host free-flight constants bind the imported source-equivalent prefab");
            static Vector3 ParachuteVector(JsonElement values) => new(
                values[0].GetSingle(), values[1].GetSingle(),
                values[2].GetSingle());
            int checkedParachuteFalls = 0;
            int prematureParachuteContacts = 0;
            foreach (JsonElement scene in parachuteReference.GetProperty("maps")
                .EnumerateArray())
            {
                RecoveredBattleMap sourceMap = content.Maps[checkedParachuteFalls / 2];
                Check(scene.GetProperty("source").GetString() == sourceMap.Source &&
                      scene.GetProperty("sha256").GetString() == sourceMap.SourceHash,
                    "Parachute physics fixture binds its recovered multiplayer scene");
                foreach (JsonElement fall in scene.GetProperty("falls").EnumerateArray())
                {
                    int fraction = fall.GetProperty("fraction").GetInt32();
                    int spawnId = fall.GetProperty("spawnComponentFileId").GetInt32();
                    Vector3 origin = ParachuteVector(fall.GetProperty("origin"));
                    ArmySpawnPoint sourceSpawn = content.ArmySpawnPoints.ForMap(sourceMap)
                        .Single(point => point.ComponentFileId == spawnId);
                    Check(sourceSpawn.ComponentType == "SpawnPointParachute" &&
                          sourceSpawn.Fraction == fraction &&
                          Vector3.Distance(sourceSpawn.Position, origin) < 0.0001f &&
                          fall.GetProperty("firstImpulseFrame").GetInt32() is > 300 and < 550,
                        "Parachute impulse trace binds one source faction spawn");
                    ArmyDeploymentFamily paratrooperFamily = content.Army.Families
                        .Single(family => family.UnitId == "ID_UNIT-PARATROOPER");
                    ArmySpawnPoint? selectedParachute =
                        new ArmySpawnPointSelector(content.ArmySpawnPoints)
                            .Select(sourceMap, paratrooperFamily, fraction,
                                Vector3.Zero, _ => 0, _ => true);
                    Check(paratrooperFamily.SpawnPointMask == 1 &&
                          paratrooperFamily.BehaviorFileId == 38324 &&
                          selectedParachute?.ComponentFileId == spawnId,
                        "Paratrooper's source override chooses the parachute point");
                    JsonElement candidates = fall.GetProperty("collisionCandidates");
                    Check(candidates.GetArrayLength() is > 0 and <= 5 &&
                          candidates.EnumerateArray().All(candidate =>
                              candidate.GetProperty("path").GetString() is
                                  { Length: > 0 and <= 1024 } &&
                              (candidate.GetProperty("type").GetString() is
                                  "MeshCollider" or "BoxCollider") &&
                              (0x20c9u & (1u << candidate.GetProperty(
                                  "layer").GetInt32())) != 0 &&
                              candidate.GetProperty("boundsDistance").GetSingle()
                                  is >= 0f and <= 2f),
                        "Unity impact has nearby source-collision-layer candidates");
                    Quaternion Rotation(JsonElement values) => new(
                        values[0].GetSingle(), values[1].GetSingle(),
                        values[2].GetSingle(), values[3].GetSingle());
                    Vector3 impactPosition = ParachuteVector(fall.GetProperty(
                        "firstImpulsePosition"));
                    Quaternion impactRotation = Rotation(fall.GetProperty(
                        "firstImpulseRotation"));
                    Check(CardParachuteCompoundContact.HasNearbySceneSurface(
                              sourceMap, impactPosition, impactRotation, 0.005f),
                        "source compound boxes find all measured scene impacts");
                    foreach (JsonElement earlySample in fall.GetProperty(
                        "preContactVelocitySamples").EnumerateArray().Take(5))
                    {
                        Check(!CardParachuteCompoundContact.HasNearbySceneSurface(
                                  sourceMap,
                                  ParachuteVector(earlySample.GetProperty("position")),
                                  Rotation(earlySample.GetProperty("rotation")),
                                  0.005f),
                            "compound boxes stay clear during early free flight");
                    }
                    JsonElement nearImpact = fall.GetProperty(
                        "preContactVelocitySamples")[7];
                    if (CardParachuteCompoundContact.HasNearbySceneSurface(
                            sourceMap,
                            ParachuteVector(nearImpact.GetProperty("position")),
                            Rotation(nearImpact.GetProperty("rotation")), 0.005f))
                        prematureParachuteContacts++;
                    var flight = new CardParachutePreContactMotion(origin, fraction);
                    foreach (JsonElement sample in fall.GetProperty(
                        "preContactVelocitySamples").EnumerateArray())
                    {
                        int frame = sample.GetProperty("frame").GetInt32();
                        while (flight.FixedFrame < frame)
                            flight.AdvanceFixedStep();
                        Vector3 observedVelocity = ParachuteVector(
                            sample.GetProperty("velocity"));
                        Vector3 observedRoot = ParachuteVector(
                            sample.GetProperty("position"));
                        Vector3 observedAngularVelocity = ParachuteVector(
                            sample.GetProperty("angularVelocity"));
                        Quaternion observedRotation = Rotation(sample.GetProperty(
                            "rotation"));
                        Check(Vector3.Distance(flight.Velocity, observedVelocity) <
                                  0.00002f &&
                              Vector3.Distance(flight.Position, observedRoot) <
                                  0.0001f &&
                              Vector3.Distance(flight.AngularVelocity,
                                  observedAngularVelocity) < 0.0001f &&
                              1f - Math.Abs(Quaternion.Dot(flight.Rotation,
                                  observedRotation)) < 0.00001f,
                            "source Parachute pose and velocity match Unity before collision");
                    }
                    var hostFlight = new CardParachuteFlightState(
                        origin, fraction, 0f);
                    Vector3? landed = null;
                    for (int hostStep = 0; hostStep < 400 && !landed.HasValue;
                         hostStep++)
                        landed = hostFlight.AdvanceHostTick(sourceMap);
                    int unityImpulse = fall.GetProperty("firstImpulseFrame")
                        .GetInt32();
                    Check(landed.HasValue && hostFlight.Landed &&
                          Math.Abs(hostFlight.FixedFrame - unityImpulse) <= 1,
                        "host two-contact landing agrees with Unity within one fixed step");
                    Reject(() => hostFlight.AdvanceHostTick(sourceMap));
                    Vector3 landingPosition = landed ??
                        throw new InvalidDataException("Parachute landing was not detected.");
                    Vector3? navStart = content.ArmyNavMeshConnectivity
                        .SampleNearest(sourceMap, landingPosition, 1.25f);
                    CardUnitInitialPoint? landingPoint = cardInitialPoints.Select(
                        sourceMap, "ELITEPARA", fraction, landingPosition,
                        _ => true);
                    Vector3? navEnd = landingPoint == null ? null :
                        content.ArmyNavMeshConnectivity.SampleNearest(
                            sourceMap, landingPoint.Position, 0.5f);
                    Check(navStart.HasValue &&
                          (landingPoint == null ||
                           navEnd.HasValue &&
                           content.ArmyNavMeshConnectivity.PlanCorridor(
                               sourceMap, navStart.Value, navEnd.Value) != null),
                        "measured parachute landing has a source-backed walk start");
                    foreach (float swayPhase in new[]
                        { 0.25f, 0.5f, 1f, 1.5f, 1.99f })
                    {
                        var variedFlight = new CardParachuteFlightState(
                            origin, fraction, swayPhase);
                        Vector3? variedLanding = null;
                        for (int hostStep = 0;
                             hostStep < 400 && !variedLanding.HasValue;
                             hostStep++)
                            variedLanding = variedFlight.AdvanceHostTick(sourceMap);
                        Vector3? variedStart = variedLanding.HasValue ?
                            content.ArmyNavMeshConnectivity.SampleNearest(
                                sourceMap, variedLanding.Value, 1.25f) : null;
                        CardUnitInitialPoint? variedPoint = variedLanding.HasValue ?
                            cardInitialPoints.Select(sourceMap, "ELITEPARA",
                                fraction, variedLanding.Value, _ => true) : null;
                        Vector3? variedEnd = variedPoint == null ? null :
                            content.ArmyNavMeshConnectivity.SampleNearest(
                                sourceMap, variedPoint.Position, 0.5f);
                        Check(variedFlight.Landed && variedStart.HasValue &&
                              (variedPoint == null || variedEnd.HasValue &&
                               content.ArmyNavMeshConnectivity.PlanCorridor(
                                   sourceMap, variedStart.Value,
                                   variedEnd.Value) != null),
                            "server-owned sway phase keeps a source-backed landing route");
                    }
                    checkedParachuteFalls++;
                }
            }
            Check(checkedParachuteFalls == 10,
                "all ten multiplayer Parachute spawn flights have pinned impulses");
            var stationaryRoute = new ArmyNavMeshCorridor(
                [Vector3.Zero, Vector3.Zero], 0f,
                [Vector3.Zero, Vector3.Zero], 0f, true, 0f);
            var stationaryCardWalk = new CardSoldierWalkState(1,
                stationaryRoute, content.Army.InfantryAgent, 0.8f);
            stationaryCardWalk.AdvanceTick();
            Check(stationaryCardWalk.Arrived &&
                  stationaryCardWalk.Position == Vector3.Zero &&
                  stationaryCardWalk.Facing == null,
                "a card soldier already at its source point has no walking step");
            Check(prematureParachuteContacts == 1,
                "Desert geometry can overlap before Unity's first measured impulse");
            Reject(() => new CardParachutePreContactMotion(
                new Vector3(float.NaN, 0, 0), 1));
            Reject(() => new CardParachutePreContactMotion(Vector3.Zero, 3));
            Reject(() => new CardParachutePreContactMotion(
                Vector3.Zero, 1, float.NaN));
            Reject(() => new CardParachutePreContactMotion(
                Vector3.Zero, 1, 2f));
            var oppositeSway = new CardParachutePreContactMotion(
                Vector3.Zero, 1, 1f);
            oppositeSway.AdvanceFixedStep();
            Check(oppositeSway.AngularVelocity.X > 0f,
                "a later source sway phase reverses the first tilt");
            Reject(() => CardParachuteCompoundContact.HasNearbySceneSurface(
                content.Maps[0], new Vector3(float.NaN, 0, 0),
                Quaternion.Identity, 0.005f));
            Reject(() => CardParachuteCompoundContact.HasNearbySceneSurface(
                content.Maps[0], Vector3.Zero,
                new Quaternion(0, 0, 0, 0), 0.005f));
            Reject(() => CardParachuteCompoundContact.HasNearbySceneSurface(
                content.Maps[0], Vector3.Zero,
                Quaternion.Identity, -0.001f));
            foreach (var sourceMap in content.Maps)
            {
                for (int fraction = 1; fraction <= 2; fraction++)
                {
                    var swatPoint = cardInitialPoints.Select(sourceMap,
                        "ELITESWAT", fraction, Vector3.Zero, _ => true);
                    var paraPoint = cardInitialPoints.Select(sourceMap,
                        "ELITEPARA", fraction, Vector3.Zero, _ => true);
                    Check(swatPoint is { ComponentType: "EnemyPointSwat" } &&
                          swatPoint.Fraction == fraction &&
                          swatPoint.CornerDirection == null &&
                          swatPoint.CornerRightSide == null &&
                          (sourceMap.Source.Contains("Snow_Multiplayer",
                              StringComparison.Ordinal)
                              ? paraPoint == null
                              : paraPoint is { ComponentType: "EnemyPointCorner" } &&
                                paraPoint.Fraction == fraction &&
                                paraPoint.CornerDirection ==
                                    new Vector3(fraction == 1 ? 1 : -1, 0, 0) &&
                                paraPoint.CornerRightSide.HasValue),
                        "card soldiers select source point types and Corner shooting sides");
                }
            }
            var parkCardMap = content.Maps.Single(map =>
                map.Source == "Assets/Scenes/Park_Multiplayer.unity");
            var nearestPara = cardInitialPoints.Select(parkCardMap,
                "ELITEPARA", 1, Vector3.Zero, _ => true);
            var alternatePara = cardInitialPoints.Select(parkCardMap,
                "ELITEPARA", 1, Vector3.Zero,
                id => id != nearestPara!.ComponentFileId);
            Check(nearestPara != null && alternatePara != null &&
                  nearestPara.ComponentFileId != alternatePara.ComponentFileId &&
                  nearestPara.CornerRightSide != alternatePara.CornerRightSide,
                "occupied card Paratrooper initial point selects the next source point");
            foreach (CardUnitInitialPoint corner in new[]
                { nearestPara!, alternatePara! })
            {
                Vector3 soldier = corner.Position;
                Vector3 exposedSide = soldier + new Vector3(0, 0,
                    corner.CornerRightSide == true ? 1 : -1);
                Vector3 blockedSide = soldier + new Vector3(0, 0,
                    corner.CornerRightSide == true ? -1 : 1);
                Check(CornerShotPolicy.CanExpose(corner.CornerDirection!.Value,
                          corner.CornerRightSide!.Value, soldier, exposedSide) &&
                      !CornerShotPolicy.CanExpose(corner.CornerDirection.Value,
                          corner.CornerRightSide.Value, soldier, blockedSide),
                    "Park Paratrooper corners expose only their serialized shooting side");
            }
            var swatPointOwners = new CardEnemyPointOccupancy(cardInitialPoints,
                parkCardMap);
            const ulong firstSwatKey = (1UL << 32) | 101;
            const ulong secondSwatKey = (1UL << 32) | 102;
            const ulong thirdSwatKey = (1UL << 32) | 103;
            var firstSwatPoint = swatPointOwners.TryAssign(firstSwatKey,
                "ELITESWAT", 1, Vector3.Zero);
            var secondSwatPoint = swatPointOwners.TryAssign(secondSwatKey,
                "ELITESWAT", 1, Vector3.Zero);
            Check(firstSwatPoint != null && secondSwatPoint != null &&
                  firstSwatPoint.ComponentFileId != secondSwatPoint.ComponentFileId &&
                  swatPointOwners.TryAssign(firstSwatKey,
                      "ELITESWAT", 1, Vector3.Zero) == firstSwatPoint &&
                  swatPointOwners.TryAssign(thirdSwatKey,
                      "ELITESWAT", 1, Vector3.Zero) == null &&
                  swatPointOwners.Occupant(firstSwatPoint.ComponentFileId) == firstSwatKey,
                "card SWAT soldiers reserve distinct source enemy points");
            Reject(() => swatPointOwners.TryAssign(firstSwatKey,
                "ELITEPARA", 1, Vector3.Zero));
            Check(swatPointOwners.Release(firstSwatKey) &&
                  !swatPointOwners.Release(firstSwatKey) &&
                  swatPointOwners.TryAssign(thirdSwatKey,
                      "ELITESWAT", 1, Vector3.Zero)?.ComponentFileId ==
                      firstSwatPoint!.ComponentFileId,
                "released card SWAT point can be claimed by a later soldier");
            var sniperPointOwners = new CardEnemyPointOccupancy(cardInitialPoints,
                parkCardMap);
            CardUnitInitialPoint[] sniperCorners =
            [
                nearestPara!, alternatePara!
            ];
            CardUnitInitialPoint nearCorner = sniperCorners[0];
            CardUnitInitialPoint farCorner = sniperCorners[1];
            const ulong firstSniperKey = (1UL << 32) | 201;
            const ulong secondSniperKey = (1UL << 32) | 202;
            const ulong thirdSniperKey = (1UL << 32) | 203;
            CardUnitInitialPoint? safeSniperPoint =
                sniperPointOwners.TryAssignSniper(firstSniperKey, 1,
                    nearCorner.Position, nearCorner.Position);
            Check(safeSniperPoint?.ComponentFileId == farCorner.ComponentFileId &&
                  sniperPointOwners.Occupant(farCorner.ComponentFileId) ==
                      firstSniperKey,
                "card Sniper excludes a nearby opponent before choosing its first Corner");
            CardUnitInitialPoint? secondSniperPoint =
                sniperPointOwners.TryAssignSniper(secondSniperKey, 1,
                    nearCorner.Position, new Vector3(100, 0, 100));
            Check(secondSniperPoint?.ComponentFileId == nearCorner.ComponentFileId &&
                  sniperPointOwners.TryAssignSniper(thirdSniperKey, 1,
                      nearCorner.Position, new Vector3(100, 0, 100)) == null &&
                  sniperPointOwners.TryAssignSniper(firstSniperKey, 1,
                      nearCorner.Position, nearCorner.Position) == safeSniperPoint,
                "card Sniper uses nearest free eligible point with stable reservation replay");
            Check(sniperPointOwners.Release(firstSniperKey) &&
                  sniperPointOwners.Occupant(farCorner.ComponentFileId) == null,
                "Sniper death frees the alternate source point");
            Check(sniperPointOwners.NextSniperPoints(secondSniperKey, 1,
                      farCorner.Position).Count == 0,
                "Sniper retarget cannot choose a point inside the opponent distance gate");
            Reject(() => sniperPointOwners.Transfer(secondSniperKey,
                "ELITESNIPER", farCorner, farCorner.Position));
            Check(sniperPointOwners.TryAssignSniper(thirdSniperKey, 1,
                      farCorner.Position, new Vector3(100, 0, 100))?
                      .ComponentFileId == farCorner.ComponentFileId,
                "freed Sniper point can be claimed by a later soldier");
            RecoveredBattleMap snowSniperMap = content.Maps.Single(map =>
                map.Source == "Assets/Scenes/Snow_Multiplayer.unity");
            Check(cardInitialPoints.SelectSniper(snowSniperMap, 1,
                      Vector3.Zero, new Vector3(100, 0, 100), _ => true) == null,
                "Snow card Sniper has no source Corner or Hiding destination");
            Reject(() => CardUnitInitialPointCatalog.Load(cardEnemyPointPath,
                new string('0', 64), content.Maps));
            var cardDroneFamily = CardSpawnUnitSourceCatalog.Family(content.Army,
                "HEAVYDRONE");
            var cardPoint = new ArmySpawnPointSelector(content.ArmySpawnPoints).Select(
                cardMap, cardDroneFamily, 1, Vector3.Zero, _ => 0, _ => true);
            Check(cardPoint != null, "a source Drone card has a host-selectable spawn point");
            var cardEntities = new CardUnitEntityRegistry();
            var droneIntent = new CardUnitSpawnIntent(secondCardRequest,
                "11111111111111111111111111111111", "HEAVYDRONE", 0, 104);
            var droneStats = content.Army.CardBaseStats("HEAVYDRONE", 0,
                content.BarrelPolicy.MaxDisplayLevel);
            var cardEntity = cardEntities.Add(droneIntent, 1, cardPoint!, droneStats,
                content.Army, 104);
            var cardRoster = CardUnitEntityProjection.Create(cardEntity!, 1);
            var cardRosterWire = BattleArmyEntityState.Parser.ParseFrom(
                cardRoster.ToByteArray());
            Check(cardRosterWire.EntityKey == cardEntity!.EntityKey &&
                  cardRosterWire.OwnerPlayerId == droneIntent.OwnerPlayerId &&
                  cardRosterWire.SourceCardId == "HEAVYDRONE" &&
                  cardRosterWire.OptionIndex == -1 &&
                  cardRosterWire.UnitId == "ID_UNIT-DRONE" &&
                  cardRosterWire.MaxHealth == droneStats.Combat.Health &&
                  cardRosterWire.Health == cardRosterWire.MaxHealth &&
                  cardRosterWire.X == cardPoint!.Position.X &&
                  cardRosterWire.Y == cardPoint.Position.Y &&
                  cardRosterWire.Z == cardPoint.Position.Z &&
                  cardRosterWire.DroneRotation?.W == 1,
                "card-unit roster preserves source identity, card health, and spawn pose");
            Reject(() => CardUnitEntityProjection.Create(cardEntity, 2));
            Check(cardEntity != null &&
                  cardEntity.LocalEntityId == CardUnitEntityRegistry.FirstLocalEntityId &&
                  cardEntity.EntityKey == ((1UL << 32) | (uint)cardEntity.LocalEntityId) &&
                  cardEntity.UnitId == "ID_UNIT-DRONE" &&
                  cardEntities.ActiveCount == 1 &&
                  cardEntities.Add(droneIntent, 1, cardPoint!, droneStats,
                      content.Army, 104) == null &&
                  cardEntities.Remove(cardEntity.LocalEntityId) == cardEntity &&
                  cardEntities.ActiveCount == 0,
                "card units receive distinct, replay-safe host identities without army options");
            Reject(()=>cardEntities.Add(droneIntent with {SourceCardId="ELITESNIPER"},
                1, cardPoint!, droneStats, content.Army, 104));
            var coordinatedCards = new CardUnitSpawnState();
            var coordinatedEntities = new CardUnitEntityRegistry();
            var sharedRoutes = new ArmySpawnReservationLedger(
                content.ArmySpawnPoints, cardMap);
            var cardCoordinator = new CardUnitSpawnCoordinator(
                coordinatedCards, coordinatedEntities, content.Army, cardMap,
                new ArmySpawnPointSelector(content.ArmySpawnPoints), sharedRoutes,
                content.BarrelPolicy.MaxDisplayLevel, _ => 0);
            const string coordinatedRequest = "c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3";
            var ordinaryArmy = new ArmyDeploymentState(content.Army,
                ["ID_UNIT-ASSAULT"]);
            int energyBeforeCard = ordinaryArmy.Energy;
            Check(coordinatedCards.TrySchedule(coordinatedRequest,
                  "card-owner", "HEAVYDRONE", 105),
                "card activation schedules a source Drone without selecting an army option");
            var dueCard = coordinatedCards.Due(105).Single();
            var createdCard = cardCoordinator.SpawnDue(dueCard, 1, 0,
                Vector3.Zero, 105);
            Check(createdCard != null &&
                  createdCard.SourceCardId == "HEAVYDRONE" &&
                  createdCard.BaseStats.Combat.Health == droneStats.Combat.Health &&
                  sharedRoutes.Owns(createdCard.EntityKey,
                      createdCard.ReservationFileId) &&
                  coordinatedCards.PendingCount == 0 &&
                  ordinaryArmy.Energy == energyBeforeCard,
                "due card unit binds source stats and shared route without spending army energy");
            Reject(() => cardCoordinator.RemoveConfirmed(createdCard! with
            {
                ReservationFileId = createdCard!.ReservationFileId + 1
            }));
            Check(coordinatedEntities.Find(createdCard!.LocalEntityId) == createdCard &&
                  sharedRoutes.Owns(createdCard.EntityKey,
                      createdCard.ReservationFileId) &&
                  cardCoordinator.RemoveConfirmed(createdCard) &&
                  !cardCoordinator.RemoveConfirmed(createdCard) &&
                  coordinatedEntities.ActiveCount == 0 &&
                  ordinaryArmy.Energy == energyBeforeCard,
                "confirmed card-unit cleanup needs the owned route and never grants army energy");
            var combatSchedule = new CardUnitSpawnState();
            var combatEntities = new CardUnitEntityRegistry();
            var combatRoutes = new ArmySpawnReservationLedger(
                content.ArmySpawnPoints, cardMap);
            var combatCoordinator = new CardUnitSpawnCoordinator(
                combatSchedule, combatEntities, content.Army, cardMap,
                new ArmySpawnPointSelector(content.ArmySpawnPoints), combatRoutes,
                content.BarrelPolicy.MaxDisplayLevel, _ => 0);
