              liveSabotageMatch.ArmyEntityBatch(decoyOpponent, 0, 0)
                  .Entities.All(row => row.EntityKey != liveSabotageDroneId) &&
              liveSabotageMatch.Snapshot().CardActivations == 2 &&
              liveSabotageMatch.Command(decoyPlayer, new MatchCommand
              {
                  CommandId = 4,
                  UseSabotage = new UseSabotageCommand
                  {
                      RequestId = liveSabotageCommand.UseSabotage.RequestId
                  }
              }).Code == "sabotage-applied" &&
              liveSabotageMatch.Snapshot().CardActivations == 2,
            "authenticated Sabotage consumes one card and kills the host-selected opposing Drone");
        var sabotageScore = liveSabotageMatch.BonusProgress.ScoreSnapshot(decoyPlayer);
        Check(sabotageScore.Counts[PvpArmyKillSkillShotPolicy.Kill] == 1 &&
              sabotageScore.Counts[PvpArmyKillSkillShotPolicy.OneHitKill] == 1 &&
              sabotageScore.Counts[PvpArmyKillSkillShotPolicy.VehicleDestroyed] == 1 &&
              sabotageScore.Score == 46,
            "confirmed Sabotage Drone death credits source Kill, OneHitKill, and VehicleDestroyed");
        liveSabotageMatch.Command(decoyPlayer, new MatchCommand
        {
            CommandId = 5,
            Forfeit = new ForfeitCommand()
        });
        var cardDroneTerminal = liveSabotageMatch.TerminalEvidenceSnapshot();
        Check(cardDroneTerminal.Players.Single(player =>
                  player.PlayerId == decoyPlayer).ConfirmedSkillShotCounts.Single(row =>
                      row.Flag == PvpArmyKillSkillShotPolicy.OneHitKill).Count == 1,
            "private terminal skill-shot evidence retains the Sabotage one-hit kill");
        var cardDroneKill = cardDroneTerminal.DirectArmyKills.Single();
        Check(cardDroneKill.EntityKey == liveSabotageDroneId &&
              cardDroneKill.VictimSourceCardId == "HEAVYDRONE" &&
              cardDroneKill.VictimSpawnRequestId == new string('8', 32) &&
              cardDroneKill.VictimSpawnTick <= cardDroneKill.Tick,
            "Sabotage retains the released Card Drone's exact source spawn identity");
        byte[] cardDronePayload = cardDroneTerminal.ToByteArray();
        var cardDroneStats = BattleSabotageKillStatsProjection.FromPayload(
            cardDronePayload, liveSabotageMatch.MatchId,
            TerminalResultDigest.Compute(cardDronePayload));
        Check(cardDroneStats.Single(row => row.PlayerId == decoyPlayer) is
              { Kills: 1, OneHitKills: 1, VehiclesDestroyed: 1, TanksDestroyed: 0 },
            "validated Card Drone death projects source Sabotage kill credit");
        void RejectCardDroneProof(Action<BattleArmyKillEvidence> corrupt)
        {
            var forged = cardDroneTerminal.Clone();
            corrupt(forged.DirectArmyKills[0]);
            byte[] payload = forged.ToByteArray();
            Reject(() => TerminalOutbox.ValidatePayload(payload,
                liveSabotageMatch.MatchId, TerminalResultDigest.Compute(payload)));
        }
        RejectCardDroneProof(row => row.VictimSourceCardId = "ELITESWAT");
        RejectCardDroneProof(row => row.VictimSpawnRequestId = "invalid");
        RejectCardDroneProof(row => row.VictimSpawnTick = row.Tick + 1);
        RejectCardDroneProof(row => row.VictimOwnerPlayerId = decoyPlayer);
        RejectCardDroneProof(row => row.Cause = "player-bullet");
        var wrongSpawnCard = cardDroneTerminal.Clone();
        wrongSpawnCard.CardUsage.Single(row => row.SourceCardId == "HEAVYDRONE")
            .SourceCardId = "ELITESWAT";
        byte[] wrongSpawnCardPayload = wrongSpawnCard.ToByteArray();
        Reject(() => TerminalOutbox.ValidatePayload(wrongSpawnCardPayload,
            liveSabotageMatch.MatchId,
            TerminalResultDigest.Compute(wrongSpawnCardPayload)));
        var airborneFiringMatch = ReadyCardMatch(
            "host-card-para-air-fire", "ELITEPARA");
        MatchReply airborneMove = airborneFiringMatch.Command(decoyOpponent,
            new MatchCommand
            {
                CommandId = 3,
                MoveCover = new MoveCoverCommand { Direction = -1 }
            });
        Check(airborneMove.Code == "moving" &&
              airborneFiringMatch.TryScheduleCardUnit(
                  "abababababababababababababababab",
                  decoyPlayer, "ELITEPARA"),
            "defender moves toward the source Park parachute lane");
        ulong airborneFiringEntity = airborneFiringMatch
            .ArmyEntityBatch(decoyPlayer, 0, 0).Entities.Single().EntityKey;
        ulong firstAirSightTick = 0;
        ulong firstAirShotTick = 0;
        for (ulong airTick = 61; airTick <= 150 &&
             !airborneFiringMatch.Terminal && firstAirShotTick == 0; airTick++)
        {
            if (airTick == 90)
            {
                airborneFiringMatch.ArmyBatch(decoyPlayer);
                airborneFiringMatch.ArmyBatch(decoyOpponent);
            }
            airborneFiringMatch.Advance(airTick);
            CardParatrooperAirTarget? airborneShotAim = airborneFiringMatch
                .CardParatrooperAirAim(airborneFiringEntity);
            if (firstAirSightTick == 0 &&
                airborneShotAim is { WithinRange: true, HasClearSight: true })
                firstAirSightTick = airTick;
            if (airborneFiringMatch.EventBatch(decoyPlayer, 0).Events.Any(
                    row => row.Kind == MatchEventKind.Shot &&
                           row.ActorId == decoyPlayer &&
                           row.TargetId == decoyOpponent &&
                           row.Reason == "army"))
                firstAirShotTick = airTick;
        }
        Check(firstAirSightTick > 0 &&
              firstAirShotTick >= firstAirSightTick + 9 &&
              airborneFiringMatch.CardParatrooperFalling(
                  airborneFiringEntity) &&
              airborneFiringMatch.CardEnemyPoint(
                  airborneFiringEntity) == null,
            "host launches a card Paratrooper rifle round after clear airborne Shield sight and windup");
        MatchEvent? airborneShot = airborneFiringMatch
            .EventBatch(decoyPlayer, 0).Events.FirstOrDefault(row =>
                row.Kind == MatchEventKind.Shot &&
                row.ActorId == decoyPlayer && row.Reason == "army");
        var airborneProjectile = airborneShot == null ? null :
            airborneFiringMatch.ArmyProjectileLaunch(
                airborneShot.ProjectileId);
        CoopMuzzlePose? sampledFiringMuzzle = airborneFiringMatch
            .CardParatrooperAirFiringMuzzle(airborneFiringEntity);
        Check(airborneShot != null && sampledFiringMuzzle != null &&
              Vector3.Distance(new Vector3(airborneShot.X,
                      airborneShot.Y, airborneShot.Z),
                  sampledFiringMuzzle.Position) < 0.0001f,
            "airborne projectile launches from the sampled half-speed rifle animation muzzle");
        float airborneCardDamage = content.Army.CardBaseStats(
            "ELITEPARA", 22, content.BarrelPolicy.MaxDisplayLevel)
            .Combat.Damage;
        Check(airborneShot != null && airborneProjectile is { } airborneFlight &&
              airborneFlight.OwnerPlayerId == decoyPlayer &&
              airborneFlight.OwnerFraction == 1 &&
              airborneFlight.Damage == airborneCardDamage,
            "airborne round enters the host projectile path with card-row damage");
        Check(airborneFiringMatch.ConfirmArmyDeath(
                  airborneFiringEntity, false) &&
              !airborneFiringMatch.CardParatrooperAirAttacking(
                  airborneFiringEntity),
            "airborne Paratrooper death releases its pending shot clock");
        Check(airborneFiringMatch.ArmyProjectileLaunch(
                  airborneShot!.ProjectileId) == airborneProjectile,
            "confirmed Paratrooper death keeps its already launched round authoritative");
        var cardMatch = ReadyCardMatch("host-card-unit");
        var grenadierCardMatch = ReadyCardMatch(
            "host-card-grenadier-setup", "GREATGRENADIER");
        const string grenadierSetupRequest =
            "f5f5f5f5f5f5f5f5f5f5f5f5f5f5f5f5";
        Check(grenadierCardMatch.TryScheduleCardUnit(grenadierSetupRequest,
                  decoyPlayer, "GREATGRENADIER"),
            "trusted Grenadier card schedules its recovered source unit");
        var grenadierEntity = grenadierCardMatch.ArmyEntityBatch(
            decoyPlayer, 0, 0).Entities.Single();
        var grenadierStats = content.Army.CardBaseStats("GREATGRENADIER",
            22, content.BarrelPolicy.MaxDisplayLevel);
        var sicknessWindow = new SicknessSpawnWindow(
            grenadierEntity.OwnerFraction == 1 ? 2 : 1, content.Army);
        Check(!grenadierCardMatch.ApplySicknessToCardGrenadier(
                grenadierEntity.EntityKey, sicknessWindow),
            "unarmed Sickness cannot modify a spawned Grenadier grenade");
        var sicknessFamily = content.Army.Families.Single(family => family.UnitId == "ID_UNIT-ASSAULT");
        int sicknessOption = sicknessFamily.Options[0].Index;
        var sicknessDeployment = new ArmyDeploymentState(content.Army, [sicknessFamily.UnitId]);
        sicknessDeployment.SetOffers([sicknessOption, sicknessOption, sicknessOption]);
        sicknessDeployment.TryDeploy(sicknessOption, 0);
        sicknessWindow.Arm();
        sicknessWindow.DeploymentStarted(grenadierEntity.OwnerFraction, sicknessDeployment.LastAcceptedWave!);
        Check(grenadierCardMatch.ApplyArmyHostDamage(
                grenadierEntity.EntityKey, grenadierEntity.MaxHealth * 0.75f),
            "host damage injures the Grenadier before its Sickness callback");
        Check(grenadierCardMatch.ApplySicknessToCardGrenadier(
                grenadierEntity.EntityKey, sicknessWindow) &&
            grenadierCardMatch.CardGrenadierDamage(grenadierEntity.EntityKey) ==
                grenadierStats.Grenade! with { Minimum = grenadierStats.Grenade.Minimum * 0.5f } &&
            grenadierCardMatch.ArmyDamage(grenadierEntity.EntityKey) == grenadierStats.Combat.Damage * 0.5f &&
            content.Army.CardBaseStats("GREATGRENADIER", 22, content.BarrelPolicy.MaxDisplayLevel) == grenadierStats,
            "host Sickness grenade binding scales current minimum without rewriting source or inner blast damage");
        var sickGrenadier = grenadierCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0).Entities.Single();
        Check(sickGrenadier.MaxHealth == grenadierEntity.MaxHealth &&
            sickGrenadier.Health == grenadierEntity.MaxHealth * 0.5f,
            "Sickness refills the injured Grenadier to half maximum while preserving its maximum");
        Check(grenadierCardMatch.ApplyArmyHostDamage(
                grenadierEntity.EntityKey, grenadierEntity.MaxHealth * 0.25f) &&
            grenadierCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0).Entities.Single().Health ==
                grenadierEntity.MaxHealth * 0.25f,
            "subsequent host damage uses the updated Grenadier vitality authority");
        Check(grenadierCardMatch.CardGrenadierThrow(
                  grenadierEntity.EntityKey) == grenadierStats.Grenadier &&
              grenadierCardMatch.CardEnemyPoint(
                  grenadierEntity.EntityKey) is {ComponentType: "EnemyPointCorner"} &&
              grenadierCardMatch.CardGrenadierWalking(grenadierEntity.EntityKey),
            "spawned card Grenadier binds its throw setup and nearest free Corner");
        int grenadierPointId = grenadierCardMatch.CardEnemyPoint(
            grenadierEntity.EntityKey)!.ComponentFileId;
        Vector3 grenadierStart = new(grenadierEntity.X, grenadierEntity.Y,
            grenadierEntity.Z);
        grenadierCardMatch.Advance(61);
        var movingGrenadier = grenadierCardMatch.ArmyEntityBatch(
            decoyPlayer, 0, 0).Entities.Single();
        Check(movingGrenadier.PositionTick == 61 &&
              Vector3.Distance(grenadierStart, new Vector3(
                  movingGrenadier.X, movingGrenadier.Y,
                  movingGrenadier.Z)) > 0 &&
              grenadierCardMatch.CardEnemyPointOccupant(grenadierPointId) ==
                  grenadierEntity.EntityKey,
            "card Grenadier movement retains its reserved source point");
        for (ulong grenadierTick = 62;
             grenadierTick <= 900 && grenadierCardMatch.CardGrenadierWalking(
                 grenadierEntity.EntityKey); grenadierTick++)
            grenadierCardMatch.Advance(grenadierTick);
        var grenadierAim = grenadierCardMatch.CardGrenadierChooseTarget(
            grenadierEntity.EntityKey);
        Check(!grenadierCardMatch.CardGrenadierWalking(
                  grenadierEntity.EntityKey) &&
              grenadierCardMatch.CardGrenadierAttack(
                  grenadierEntity.EntityKey) is
                  { Phase: ArmyRusherAttackPhase.Cooldown } &&
              grenadierAim is { Target: { PlayerId: var grenadierTargetPlayer } } &&
              grenadierTargetPlayer == decoyOpponent &&
              grenadierAim.Target.EntityKey == grenadierEntity.EntityKey &&
              grenadierAim.Target.RusherPointFileId == grenadierPointId &&
              PlayerHitbox.Finite(grenadierAim.Target.Position),
            "arrived card Grenadier selects a host-owned opposing player target");
        int grenadierShieldId = content.PlayerShotTargets.Gameplay.Single(target =>
            target.Type == 2).TransformFileId;
        Check(grenadierAim?.Target.TargetFileId == grenadierShieldId &&
              Vector3.Distance(grenadierAim.Target.Position,
                  park.Covers[grenadierCardMatch.Snapshot().Players.Single(player =>
                      player.PlayerId == decoyOpponent).CoverIndex].ShotPosition) < .0001f,
            "card Grenadier uses GameShootableEntityPlayer's current-cover Shield target override");
        MatchEngine.CardGrenadierShotIntent? grenadierIntent = null;
        ulong grenadierStartTick = grenadierCardMatch.Snapshot().ServerTick;
        for (ulong grenadierTick = grenadierStartTick + 1;
             grenadierTick <= grenadierStartTick + 600 &&
                 grenadierIntent == null; grenadierTick++)
        {
            grenadierCardMatch.Advance(grenadierTick);
            grenadierIntent = grenadierCardMatch.CardGrenadierShotIntents()
                .FirstOrDefault();
        }
        Check(grenadierIntent is { Aim: { Target: { PlayerId: var shotPlayer } } } &&
              shotPlayer == decoyOpponent &&
              grenadierIntent.EntityKey == grenadierEntity.EntityKey &&
              grenadierIntent.Aim.ThrowGrenade &&
              grenadierIntent.IsReal &&
              grenadierIntent.BatchSize == 1 &&
              grenadierIntent.ShotIndex == 0 &&
              grenadierIntent.GrenadeMuzzlePosition is Vector3 &&
              grenadierIntent.GrenadeLaunchVelocity is Vector3,
            "arrived card Grenadier reaches a real one-shot grenade intent on the host clock");
        Vector3 intentMuzzle = grenadierIntent!.GrenadeMuzzlePosition!.Value;
        Vector3 intentVelocity = grenadierIntent.GrenadeLaunchVelocity!.Value;
        var firingGrenadier = grenadierCardMatch.ArmyEntityBatch(
            decoyPlayer, 0, 0).Entities.Single();
        Vector3 firingPosition = new(firingGrenadier.X,
            firingGrenadier.Y, firingGrenadier.Z);
        Vector3 expectedMuzzle = content.ArmyWeapons.CardGrenadierRestMuzzle(
            firingPosition, grenadierIntent.Aim.Target.Position - firingPosition);
        Check(PlayerHitbox.Finite(intentMuzzle) &&
              Vector3.Distance(intentMuzzle, expectedMuzzle) < .00001f &&
              Vector3.Distance(intentVelocity,
                  grenadierCardMatch.CardGrenadierThrow(
                      grenadierEntity.EntityKey)!.LaunchVelocity(intentMuzzle,
                      grenadierIntent.Aim.Target.Position)) < .00001f &&
              grenadierCardMatch.CardGrenadierActiveFlightCount == 1 &&
              grenadierCardMatch.PendingProjectileCount >= 1,
            "Grenadier shot intent launches a bounded host grenade from its source muzzle");
        BattleProjectileState grenadierProjectile =
            grenadierCardMatch.Snapshot().Projectiles.Single(row =>
                row.Kind == "card-grenadier");
        ArmyGrenadeDamageStats? frozenGrenadierDamage =
            grenadierCardMatch.CardGrenadierLaunchDamage(grenadierProjectile.ProjectileId);
        Check(frozenGrenadierDamage == grenadierCardMatch.CardGrenadierDamage(grenadierEntity.EntityKey),
            "actual host grenade launch captures the modified ammo setup");
        Check(grenadierCardMatch.ApplySicknessToCardGrenadier(
                grenadierEntity.EntityKey, sicknessWindow) &&
            grenadierCardMatch.CardGrenadierDamage(grenadierEntity.EntityKey)!.Minimum ==
                grenadierStats.Grenade!.Minimum * 0.25f &&
            grenadierCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0).Entities.Single().Health ==
                grenadierEntity.MaxHealth * 0.5f &&
            grenadierCardMatch.CardGrenadierLaunchDamage(grenadierProjectile.ProjectileId) == frozenGrenadierDamage,
            "a later weapon modification cannot rewrite the already launched grenade");
        sicknessWindow.Disconnect();
        Check(!grenadierCardMatch.ApplySicknessToCardGrenadier(
                grenadierEntity.EntityKey, sicknessWindow),
            "disconnected Sickness cannot modify the next grenade setup");
        Check(grenadierProjectile.OwnerPlayerId == decoyPlayer &&
              grenadierProjectile.ProjectileId > 0 &&
              Vector3.Distance(new Vector3(grenadierProjectile.X,
                  grenadierProjectile.Y, grenadierProjectile.Z),
                  intentMuzzle) < .00001f &&
              Vector3.Distance(new Vector3(
                  grenadierProjectile.VelocityX,
                  grenadierProjectile.VelocityY,
                  grenadierProjectile.VelocityZ),
                  intentVelocity) < .00001f,
            "Grenadier projectile snapshot publishes its host pose and velocity");
        int grenadierNextPointId = grenadierPointId;
        CardGrenadierExplosion? liveGrenadierExplosion = null;
        ulong grenadierChangeStart = grenadierCardMatch.Snapshot().ServerTick;
        for (ulong grenadierTick = grenadierChangeStart + 1;
             grenadierTick <= grenadierChangeStart + 600 &&
                 grenadierNextPointId == grenadierPointId; grenadierTick++)
        {
            grenadierCardMatch.Advance(grenadierTick);
            liveGrenadierExplosion ??= grenadierCardMatch.CardGrenadierExplosions()
                .FirstOrDefault();
            if (grenadierTick % 60 == 0)
            {
                grenadierCardMatch.EventBatch(decoyPlayer, 0);
                grenadierCardMatch.EventBatch(decoyOpponent, 0);
            }
            grenadierNextPointId = grenadierCardMatch.CardEnemyPoint(
                grenadierEntity.EntityKey)?.ComponentFileId ?? 0;
        }
        Check(grenadierNextPointId != grenadierPointId &&
              grenadierNextPointId > 0 &&
              grenadierCardMatch.CardEnemyPointOccupant(grenadierPointId) == null &&
              grenadierCardMatch.CardEnemyPointOccupant(
                  grenadierNextPointId) == grenadierEntity.EntityKey &&
              grenadierCardMatch.CardGrenadierWalking(
                  grenadierEntity.EntityKey) &&
              grenadierCardMatch.CardGrenadierAttack(
                  grenadierEntity.EntityKey) == null,
            "Grenadier changes to a free Corner without retaining its old shot clock");
        Check(liveGrenadierExplosion is
              { SoldierEntityKey: var explodedGrenadier } &&
              explodedGrenadier == grenadierEntity.EntityKey &&
              liveGrenadierExplosion.Tick > grenadierIntent.Tick + 90 &&
              PlayerHitbox.Finite(liveGrenadierExplosion.Position) &&
              grenadierCardMatch.Snapshot().Projectiles.All(row =>
                  row.ProjectileId != grenadierProjectile.ProjectileId),
            "live Park grenade lands, keeps its fuse, and reaches a host explosion");
        Check(grenadierCardMatch.ConfirmArmyDeath(
                  grenadierEntity.EntityKey, false) &&
              grenadierCardMatch.CardGrenadierThrow(
                  grenadierEntity.EntityKey) == null &&
              grenadierCardMatch.CardGrenadierAttack(
                  grenadierEntity.EntityKey) == null &&
              grenadierCardMatch.CardGrenadierDamage(grenadierEntity.EntityKey) == null &&
              grenadierCardMatch.ArmyDamage(grenadierEntity.EntityKey) == null &&
              !grenadierCardMatch.CardGrenadierWalking(
                  grenadierEntity.EntityKey) &&
              grenadierCardMatch.CardEnemyPointOccupant(
                  grenadierNextPointId) == null,
            "card Grenadier death releases its throw setup and point reservation");
        MatchEngine? primaryDrawOwner = null;
        ulong primaryDrawEntity = 0;
        int primaryReadyDraws = 0;
        ulong primaryPreparationTick = 0;
        int ChoosePrimaryArmyDraw(int maximum)
        {
            if (maximum != 1_000_000 || primaryDrawOwner?.CardGrenadierAttack(primaryDrawEntity)?.Phase !=
                ArmyRusherAttackPhase.Ready)
            {
                primaryReadyDraws = 0;
                return 0;
            }

            // PickTarget draws secondary choice first. Later target/batch/real-shot draws stay zero.
            if (primaryReadyDraws == 0)
            {
                primaryPreparationTick = primaryDrawOwner.Snapshot().ServerTick;
            }
            return primaryReadyDraws++ == 0 ? 400_000 : 0;
        }

        var primaryGrenadierMatch = ReadyCardMatch("host-grenadier-primary", "GREATGRENADIER",
            armyDraw: ChoosePrimaryArmyDraw);
        primaryDrawOwner = primaryGrenadierMatch;
        Check(primaryGrenadierMatch.TryScheduleCardUnit("f4f4f4f4f4f4f4f4f4f4f4f4f4f4f4f4", decoyPlayer,
                "GREATGRENADIER"), "primary-fire fixture spawns its selected Grenadier");
        var primarySoldier = primaryGrenadierMatch.ArmyEntityBatch(decoyPlayer, 0, 0).Entities.Single();
        primaryDrawEntity = primarySoldier.EntityKey;
        var primarySickness = new SicknessSpawnWindow(primarySoldier.OwnerFraction == 1 ? 2 : 1, content.Army);
        primarySickness.Arm();
        primarySickness.DeploymentStarted(primarySoldier.OwnerFraction, sicknessDeployment.LastAcceptedWave!);
        Check(primaryGrenadierMatch.ApplySicknessToCardGrenadier(primarySoldier.EntityKey, primarySickness),
            "primary-fire fixture applies Sickness before the first shot");
        MatchEngine.CardGrenadierShotIntent? primaryIntent = null;
        for (ulong primaryTick = 61; primaryTick <= 1200 && primaryIntent == null; primaryTick++)
        {
            primaryGrenadierMatch.Advance(primaryTick);
            primaryIntent = primaryGrenadierMatch.CardGrenadierShotIntents()
                .FirstOrDefault(intent => !intent.Aim.ThrowGrenade);
        }

        Check(primaryIntent is { IsReal: true }, "forced primary choice reaches a real pistol shot intent");
        Check(primaryIntent!.Tick == primaryPreparationTick + GrenadierCornerMuzzleCatalog.FirstShotDelayTicks,
            "primary pistol waits for the native callback's following gameplay poll");
        var primaryProjectile = primaryGrenadierMatch.Snapshot().Projectiles.Single(row =>
            row.ArmySourceCardId == "GREATGRENADIER" && row.Kind == "army-bullet");
        Check(primaryGrenadierMatch.ArmyProjectileLaunch(primaryProjectile.ProjectileId)?.Damage ==
                grenadierStats.Combat.Damage * 0.5f &&
            primaryGrenadierMatch.ArmyProjectileSpeed(primaryProjectile.ProjectileId) == 5f,
            "actual pistol launch uses current Sickness damage and the selected weapon's speed");
        Check(primaryGrenadierMatch.ApplySicknessToCardGrenadier(primarySoldier.EntityKey, primarySickness) &&
            primaryGrenadierMatch.ArmyDamage(primarySoldier.EntityKey) == grenadierStats.Combat.Damage * 0.25f &&
            primaryGrenadierMatch.ArmyProjectileLaunch(primaryProjectile.ProjectileId)?.Damage ==
                grenadierStats.Combat.Damage * 0.5f,
            "later Sickness changes future primary damage without rewriting the airborne pistol round");
        Check(primaryGrenadierMatch.ConfirmArmyDeath(primarySoldier.EntityKey, false) &&
            primaryGrenadierMatch.ArmyDamage(primarySoldier.EntityKey) == null &&
            primaryGrenadierMatch.ArmyProjectileLaunch(primaryProjectile.ProjectileId) != null,
            "Grenadier death removes current primary setup while preserving its launched round");
        ulong primaryCursor = primaryGrenadierMatch.EventBatch(decoyPlayer, 0).LatestEventId;
        MatchSnapshot primaryBeforeImpact = primaryGrenadierMatch.Snapshot();
        for (ulong primaryTick = primaryIntent!.Tick + 1;
             primaryTick <= primaryIntent.Tick + 900 &&
                primaryGrenadierMatch.ArmyProjectileLaunch(primaryProjectile.ProjectileId) != null; primaryTick++)
        {
            primaryGrenadierMatch.Advance(primaryTick);
        }

        Check(primaryGrenadierMatch.EventBatch(decoyPlayer, primaryCursor).Events.Any(item =>
                item.Kind == MatchEventKind.Impact && item.ProjectileId == primaryProjectile.ProjectileId),
            "actual pistol flight reaches host collision after its Grenadier dies");
        MatchSnapshot primaryAfterImpact = primaryGrenadierMatch.Snapshot();
        float primaryPlayerDamage = primaryBeforeImpact.Players.Single(row => row.PlayerId == decoyOpponent).Health -
            primaryAfterImpact.Players.Single(row => row.PlayerId == decoyOpponent).Health;
        float primaryShieldDamage = primaryBeforeImpact.Shields.Sum(row => row.Health) -
            primaryAfterImpact.Shields.Sum(row => row.Health);
        Console.WriteLine($"Grenadier primary collision: player damage {primaryPlayerDamage}, " +
            $"shield damage {primaryShieldDamage}, raw launch damage {grenadierStats.Combat.Damage * 0.5f}.");
        var shotGrenadierMatch = ReadyCardMatch(
            "host-card-grenadier-shot", "GREATGRENADIER");
        Check(shotGrenadierMatch.TryScheduleCardUnit(
                  new string('c', 32), decoyPlayer, "GREATGRENADIER"),
            "shot-detonation match owns a selected Grenadier card");
        DynamicShotTarget? liveGrenadeTarget = null;
        for (ulong simulationTick = 61; simulationTick < 1800 &&
             liveGrenadeTarget == null && !shotGrenadierMatch.Terminal;
             simulationTick++)
        {
            shotGrenadierMatch.Advance(simulationTick);
            liveGrenadeTarget = shotGrenadierMatch
                .PlayerShotTargets(decoyOpponent)
                .FirstOrDefault(target => target.GrenadierGrenade);
            if (simulationTick % 60 == 0)
            {
                shotGrenadierMatch.EventBatch(decoyPlayer, 0);
                shotGrenadierMatch.EventBatch(decoyOpponent, 0);
            }
        }
        Check(liveGrenadeTarget is { Layer: 27,
                  GrenadierGrenade: true } &&
              liveGrenadeTarget.Hitbox.Kind == PlayerHitboxKind.Sphere &&
              liveGrenadeTarget.Hitbox.Radius == .06f &&
              shotGrenadierMatch.PlayerShotTargets(decoyPlayer)
                  .All(target => !target.GrenadierGrenade),
            "falling grenade enters only the opposing player's source bullet layer");
        var grenadeShotWorld = new ShotCollisionWorld(null,
        [
            new(decoyPlayer, referencePose.Place(
                new(100, 0, 100), Quaternion.Identity).Collision),
            new(decoyOpponent, referencePose.Place(
                new(110, 0, 100), Quaternion.Identity).Collision)
        ], dynamicTargets: shotGrenadierMatch.PlayerShotTargets);
        Vector3 grenadeShotCenter = liveGrenadeTarget!.Hitbox.Center;
        ShotCollision? grenadeBulletHit = grenadeShotWorld.Raycast(
            decoyOpponent, grenadeShotCenter + Vector3.UnitX * .2f,
            -Vector3.UnitX, .4f, content.Bindings.BulletMask(2));
        Check(grenadeBulletHit is
              { DynamicGrenadierGrenade: true, SourceDestroyable: true,
                  PartWeight: 1f } &&
              grenadeBulletHit.DynamicEntityId == liveGrenadeTarget.EntityId,
            "player bullet ray selects the host-owned Grenadier grenade collider");
        Check(grenadeShotWorld.OverlapEnemy(decoyOpponent,
                  grenadeShotCenter + Vector3.UnitX * .2f, .5f,
                  content.Bindings.BulletMask(2)).Any(target =>
                      target.MainEntityId == "grenade:" +
                          liveGrenadeTarget.EntityId) &&
              !grenadeShotWorld.OverlapEnemy(decoyOpponent,
                  grenadeShotCenter + Vector3.UnitX * .2f, .5f,
                  0).Any(target => target.MainEntityId == "grenade:" +
                      liveGrenadeTarget.EntityId),
            "shotgun overlap selects the enemy grenade only through its source layer");
        ulong shotEventBefore = shotGrenadierMatch
            .EventBatch(decoyOpponent, 0).LatestEventId;
        Reject(() => shotGrenadierMatch.ApplyCardGrenadierShot(decoyPlayer,
            liveGrenadeTarget.EntityId, 1000f));
        Check(shotGrenadierMatch.ApplyCardGrenadierShot(decoyOpponent,
                  liveGrenadeTarget.EntityId, 400f) &&
              shotGrenadierMatch.CardGrenadierActiveFlightCount == 1,
            "a partial shot leaves the host Grenadier grenade in flight");
        Check(shotGrenadierMatch.ApplyCardGrenadierShot(decoyOpponent,
                  liveGrenadeTarget.EntityId, 600f) &&
              shotGrenadierMatch.CardGrenadierActiveFlightCount == 0 &&
              shotGrenadierMatch.CardGrenadierExplosions().Count == 1 &&
              shotGrenadierMatch.EventBatch(decoyOpponent, shotEventBefore)
                  .Events.Any(item => item.Kind == MatchEventKind.Impact &&
                      item.ProjectileId == liveGrenadeTarget.EntityId &&
                      item.Reason == "card-grenadier"),
            "lethal host shot publishes one immediate Grenadier explosion and retires its flight");
        Check(!shotGrenadierMatch.ApplyCardGrenadierShot(decoyOpponent,
                  liveGrenadeTarget.EntityId, 1f) &&
              shotGrenadierMatch.CardGrenadierExplosions().Count == 1,
            "a later bullet cannot detonate an already retired grenade twice");
        var firedGrenadierMatch = ReadyCardMatch(
            "player-fire-card-grenadier", "GREATGRENADIER");
        Check(firedGrenadierMatch.TryScheduleCardUnit(new string('d', 32),
                  decoyPlayer, "GREATGRENADIER"),
            "player Fire test starts with one trusted Grenadier card");
        ulong grenadeFireCommand = 3;
        bool playerBulletHitGrenade = false;
        var grenadeFireCodes = new Dictionary<string, int>(StringComparer.Ordinal);
        for (ulong simulationTick = 61; simulationTick < 1800 &&
             !playerBulletHitGrenade && !firedGrenadierMatch.Terminal;
             simulationTick++)
        {
            DynamicShotTarget? target = firedGrenadierMatch
                .PlayerShotTargets(decoyOpponent)
                .FirstOrDefault(row => row.GrenadierGrenade);
            float? previousShotHealth = target == null ? null :
                firedGrenadierMatch.CardGrenadierShotHealth(target.EntityId);
            if (target != null)
            {
                Vector3 aim = target.Hitbox.Center;
                string code = firedGrenadierMatch.Command(decoyOpponent,
                    new MatchCommand
                    {
                        CommandId = grenadeFireCommand++,
                        Fire = new FireCommand
                        {
                            TargetX = aim.X,
                            TargetY = aim.Y,
                            TargetZ = aim.Z
                        }
                    }).Code;
                grenadeFireCodes[code] = grenadeFireCodes.GetValueOrDefault(code) + 1;
            }
            firedGrenadierMatch.Advance(simulationTick);
            if (target != null && previousShotHealth is float before &&
                firedGrenadierMatch.CardGrenadierShotHealth(target.EntityId)
                    is float after && after < before)
                playerBulletHitGrenade = true;
            if (simulationTick % 60 == 0)
            {
                firedGrenadierMatch.EventBatch(decoyPlayer, 0);
                firedGrenadierMatch.EventBatch(decoyOpponent, 0);
            }
        }
        Check(playerBulletHitGrenade,
            "normal player Fire damages a falling Grenadier grenade: " +
            string.Join(", ", grenadeFireCodes.Select(row =>
                row.Key + "=" + row.Value)));
        var lethalFireMatch = ReadyCardMatch(
            "player-fire-lethal-grenadier", "GREATGRENADIER");
        Check(lethalFireMatch.TryScheduleCardUnit(new string('e', 32),
                  decoyPlayer, "GREATGRENADIER"),
            "lethal Fire test starts with one trusted Grenadier card");
        ulong lethalFireCommand = 3;
        ulong? preparedGrenadeId = null;
        bool fireTriggeredExplosion = false;
        var lethalFireCodes = new Dictionary<string, int>(StringComparer.Ordinal);
        for (ulong simulationTick = 61; simulationTick < 1800 &&
             !fireTriggeredExplosion && !lethalFireMatch.Terminal;
             simulationTick++)
        {
            DynamicShotTarget? target = lethalFireMatch
                .PlayerShotTargets(decoyOpponent)
                .FirstOrDefault(row => row.GrenadierGrenade &&
                    (preparedGrenadeId == null ||
                     row.EntityId == preparedGrenadeId.Value));
            if (target != null && preparedGrenadeId == null)
            {
                preparedGrenadeId = target.EntityId;
                Check(lethalFireMatch.ApplyCardGrenadierShot(decoyOpponent,
                          target.EntityId, 999f) &&
                      lethalFireMatch.CardGrenadierShotHealth(target.EntityId)
                          == 1f,
                    "trusted prior damage leaves one hit point for the real Fire command");
            }
            if (target != null)
            {
                Vector3 aim = target.Hitbox.Center;
                string fireCode = lethalFireMatch.Command(decoyOpponent,
                    new MatchCommand
                {
                    CommandId = lethalFireCommand++,
                    Fire = new FireCommand
                    {
                        TargetX = aim.X, TargetY = aim.Y, TargetZ = aim.Z
                    }
                }).Code;
                lethalFireCodes[fireCode] =
                    lethalFireCodes.GetValueOrDefault(fireCode) + 1;
            }
            lethalFireMatch.Advance(simulationTick);
            fireTriggeredExplosion = preparedGrenadeId is ulong grenadeId &&
                lethalFireMatch.CardGrenadierExplosions().Any(explosion =>
                    explosion.ProjectileId == grenadeId &&
                    explosion.ShotTriggered);
            if (simulationTick % 60 == 0)
            {
                lethalFireMatch.EventBatch(decoyPlayer, 0);
                lethalFireMatch.EventBatch(decoyOpponent, 0);
            }
        }
        var lethalFireEvents = new List<MatchEvent>();
        ulong lethalFireEventCursor = 0;
        while (true)
        {
            var page = lethalFireMatch.EventBatch(decoyOpponent,
                lethalFireEventCursor);
            lethalFireEvents.AddRange(page.Events);
            if (page.Events.Count == 0 ||
                page.Events[^1].EventId == page.LatestEventId)
                break;
            lethalFireEventCursor = page.Events[^1].EventId;
        }
        Check(fireTriggeredExplosion && preparedGrenadeId is ulong detonatedId &&
              lethalFireMatch.CardGrenadierActiveFlightCount == 0 &&
              lethalFireMatch.Snapshot().Projectiles.All(projectile =>
                  projectile.ProjectileId != detonatedId) &&
              lethalFireEvents.Any(item =>
                  item.Kind == MatchEventKind.Impact &&
                  item.ProjectileId == detonatedId &&
                  item.Reason == "card-grenadier"),
            "normal Fire finishes a weakened grenade and publishes its authoritative explosion: " +
            string.Join(", ", lethalFireCodes.Select(row =>
                row.Key + "=" + row.Value)));
        var grenadierDecoyMatch = ReadyCardMatch(
            "host-card-grenadier-decoy", "GREATGRENADIER",
            opponentCardId: "DECOY");
        Check(grenadierDecoyMatch.Command(decoyOpponent,
                  new MatchCommand
                  {
                      CommandId = 3,
                      UseDecoy = new UseDecoyCommand
                      {
                          RequestId = new string('a', 32)
                      }
                  }).Code == "decoy-spawned" &&
              grenadierDecoyMatch.TryScheduleCardUnit(
                  new string('b', 32), decoyPlayer,
                  "GREATGRENADIER"),
            "host Grenadier can face an authenticated opposing Decoy");
        var grenadierDecoyUnit = grenadierDecoyMatch.ArmyEntityBatch(
            decoyPlayer, 0, 0).Entities.Single();
        bool grenadeDamagedDecoy = false;
        for (ulong simulationTick = 61; simulationTick < 1800 &&
             !grenadeDamagedDecoy && !grenadierDecoyMatch.Terminal;
             simulationTick++)
        {
            var previousHealth = grenadierDecoyMatch.Snapshot().Decoys
                .ToDictionary(row => row.EntityId, row => row.Health);
            grenadierDecoyMatch.Advance(simulationTick);
            if (grenadierDecoyMatch.CardGrenadierExplosions().Count > 0)
            {
                grenadeDamagedDecoy =
                    grenadierDecoyMatch.Snapshot().Decoys.Any(row =>
                        previousHealth.TryGetValue(row.EntityId,
                            out float before) && row.Health < before);
            }
            if (simulationTick % 60 == 0)
            {
                grenadierDecoyMatch.EventBatch(decoyPlayer, 0);
                grenadierDecoyMatch.EventBatch(decoyOpponent, 0);
            }
        }
        Check(grenadeDamagedDecoy && !grenadierDecoyMatch.Terminal &&
              grenadierDecoyUnit.EntityKey > 0,
            "live Grenadier explosion reduces an opposing Decoy's host health");
        var snowGrenadierMap = content.Maps.Single(sourceMap =>
            sourceMap.Source.Contains("Snow_Multiplayer",
                StringComparison.Ordinal));
        var snowGrenadierMatch = ReadyCardMatch(
            "host-card-grenadier-snow", "GREATGRENADIER", snowGrenadierMap);
        Check(snowGrenadierMatch.TryScheduleCardUnit(
                  "f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6",
                  decoyPlayer, "GREATGRENADIER"),
            "Grenadier card can spawn on Snow without inventing a Corner");
        var snowGrenadier = snowGrenadierMatch.ArmyEntityBatch(
            decoyPlayer, 0, 0).Entities.Single();
        Check(snowGrenadierMatch.CardEnemyPoint(
                  snowGrenadier.EntityKey) == null &&
              !snowGrenadierMatch.CardGrenadierWalking(
                  snowGrenadier.EntityKey),
            "Snow Grenadier waits for its five-second source point retry");
        var grenadierBoxMatch = ReadyCardMatch(
            "host-card-grenadier-box", "GREATGRENADIER",
            withBonusBox: true);
        grenadierBoxMatch.BonusPlanner.EnqueueConfirmedBonus(
            new string('4', 32), decoyPlayer, 6);
        for (int hit = 0; hit < 3; hit++)
            grenadierBoxMatch.BonusProgress.RecordConfirmedSkillShot(decoyPlayer,
                new string((char)('6' + hit), 32), 0x1210, 1f);
        for (ulong simulationTick = 61; simulationTick <= 153; simulationTick++)
            grenadierBoxMatch.Advance(simulationTick);
        var grenadierBox = grenadierBoxMatch.BonusPlanner.ActiveBoxesSnapshot().Single();
        Check(grenadierBoxMatch.TryScheduleCardUnit(new string('9', 32),
                  decoyPlayer, "GREATGRENADIER"),
            "host deploys a Grenadier soldier after issuing the box");
        int grenadierBoxExplosions = 0;
        float nearestGrenadierBlast = float.PositiveInfinity;
        Vector3 nearestGrenadierBlastPosition = Vector3.Zero;
        bool grenadierBoxCollected = false;
        for (ulong simulationTick = 154; simulationTick < 1800 &&
             !grenadierBoxMatch.Terminal && !grenadierBoxCollected;
             simulationTick++)
        {
            grenadierBoxMatch.Advance(simulationTick);
            foreach (var explosion in grenadierBoxMatch.CardGrenadierExplosions())
            {
                grenadierBoxExplosions++;
                float distance = Vector3.Distance(explosion.Position,
                    grenadierBox.Position);
                if (distance < nearestGrenadierBlast)
                {
                    nearestGrenadierBlast = distance;
                    nearestGrenadierBlastPosition = explosion.Position;
                }
            }
            grenadierBoxCollected = grenadierBoxMatch.BonusPlanner
                .BoxSnapshot(grenadierBox.BoxId).Phase == PvpBonusBoxPhase.Collected;
            if (simulationTick % 60 == 0)
            {
                grenadierBoxMatch.EventBatch(decoyPlayer, 0);
                grenadierBoxMatch.EventBatch(decoyOpponent, 0);
            }
        }
        float grenadierOuterRadius = content.Army.CardBaseStats(
            "GREATGRENADIER", 22,
            content.BarrelPolicy.MaxDisplayLevel).Grenadier!.OuterRadius;
        Check(!grenadierBoxCollected && grenadierBoxExplosions > 0 &&
              nearestGrenadierBlast > grenadierOuterRadius &&
              grenadierBoxMatch.BonusPlanner.BoxSnapshot(grenadierBox.BoxId)
                  .Health == 1f &&
              grenadierBoxMatch.Snapshot().Players[0].KevlarHealth == 0f,
            $"deployed Grenadier cannot collect an out-of-range box: " +
            $"box={grenadierBox.Position}, " +
            $"explosions={grenadierBoxExplosions}, nearest={nearestGrenadierBlast}, " +
            $"blastPosition={nearestGrenadierBlastPosition}, " +
            $"phase={grenadierBoxMatch.BonusPlanner.BoxSnapshot(grenadierBox.BoxId).Phase}");

        var rocketBoxMatch = ReadyCardMatch("host-card-rocket-box", "BIGROCKET",
            withBonusBox: true);
        rocketBoxMatch.BonusPlanner.EnqueueConfirmedBonus(
            "c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4", decoyPlayer, 6);
        for (int hit = 0; hit < 3; hit++)
            rocketBoxMatch.BonusProgress.RecordConfirmedSkillShot(decoyPlayer,
                new string((char)('1' + hit), 32), 0x1210, 1f);
        for (ulong simulationTick = 61; simulationTick <= 153; simulationTick++)
            rocketBoxMatch.Advance(simulationTick);
        var rocketBox = rocketBoxMatch.BonusPlanner.ActiveBoxesSnapshot().Single();
        Check(rocketBox.Plan.SourceIndex == 6 &&
              rocketBox.Plan.AreaColliderFileId ==
                  content.PvpBonusSpawnAreas.ForMap(park)[1].ColliderFileId,
            "host issues the queued Kevlar box in the selected source area");
        Check(rocketBoxMatch.TryScheduleCardUnit(
                  new string('5', 32), decoyPlayer,
                  "BIGROCKET"),
            $"host deploys a Rocket soldier after the box appears: " +
            $"phase={rocketBoxMatch.Snapshot().Phase}, " +
            $"cards={rocketBoxMatch.Snapshot().CardActivations}, " +
            $"selected={rocketBoxMatch.Snapshot().Players[0].CardsSelected}, " +
            $"events={rocketBoxMatch.EventBatch(decoyPlayer, 0).LatestEventId}, " +
            $"box={rocketBox.Phase}");
        bool rocketBoxCollected = false;
        int realRocketImpacts = 0;
        float nearestRocketDistance = float.PositiveInfinity;
        float nearestRocketFlightDistance = float.PositiveInfinity;
        Vector3 nearestRocketFlightPosition = Vector3.Zero;
        for (ulong simulationTick = 154; simulationTick < 1800 &&
             !rocketBoxMatch.Terminal && !rocketBoxCollected; simulationTick++)
        {
            rocketBoxMatch.Advance(simulationTick);
            foreach (var projectile in rocketBoxMatch.Snapshot().Projectiles
                         .Where(row => row.Kind == "card-rocket"))
            {
                Vector3 position = new(projectile.X, projectile.Y, projectile.Z);
                float distance = Vector3.Distance(position, rocketBox.Position);
                if (distance < nearestRocketFlightDistance)
                {
                    nearestRocketFlightDistance = distance;
                    nearestRocketFlightPosition = position;
                }
            }
            foreach (var impact in rocketBoxMatch.CardRocketImpacts()
                         .Where(impact => !impact.IsFake))
            {
                realRocketImpacts++;
                nearestRocketDistance = Math.Min(nearestRocketDistance,
                    Vector3.Distance(impact.Position, rocketBox.Position));
            }
            rocketBoxCollected = rocketBoxMatch.BonusPlanner
                .BoxSnapshot(rocketBox.BoxId).Phase == PvpBonusBoxPhase.Collected;
            if (simulationTick % 60 == 0)
            {
                rocketBoxMatch.EventBatch(decoyPlayer, 0);
                rocketBoxMatch.EventBatch(decoyOpponent, 0);
            }
        }
        Check(rocketBoxCollected && realRocketImpacts > 0 &&
              rocketBoxMatch.Snapshot().Players[0].KevlarHealth > 0f,
            $"deployed Rocket soldier collects a live box: " +
            $"box={rocketBox.Position}, realImpacts={realRocketImpacts}, " +
            $"nearestImpact={nearestRocketDistance}, " +
            $"nearestFlight={nearestRocketFlightDistance}, " +
            $"flightPosition={nearestRocketFlightPosition}, " +
            $"phase={rocketBoxMatch.BonusPlanner.BoxSnapshot(rocketBox.BoxId).Phase}");

        var rocketCardMatch = ReadyCardMatch("host-card-rocket-setup", "BIGROCKET");
        const string rocketSetupRequest = "d5d5d5d5d5d5d5d5d5d5d5d5d5d5d5d5";
        Check(rocketCardMatch.TryScheduleCardUnit(rocketSetupRequest,
                  decoyPlayer, "BIGROCKET"),
            "a trusted Rocket card call creates its source unit");
        var rocketEntity = rocketCardMatch.ArmyEntityBatch(
            decoyPlayer, 0, 0).Entities.Single();
        var rocketStats = content.Army.CardBaseStats("BIGROCKET", 22,
            content.BarrelPolicy.MaxDisplayLevel);
        Check(rocketEntity.SourceCardId == "BIGROCKET" &&
              rocketCardMatch.CardRocketMissile(rocketEntity.EntityKey) ==
                  rocketStats.Rocket,
            "card Rocket spawn binds its level-scaled missile setup to the host entity");
        var rocketSickness = new SicknessSpawnWindow(
            rocketEntity.OwnerFraction == 1 ? 2 : 1, content.Army);
        Check(!rocketCardMatch.ApplySicknessToCardRocket(rocketEntity.EntityKey, rocketSickness),
            "unarmed Sickness cannot modify a Rocket Soldier weapon");
        rocketSickness.Arm();
        rocketSickness.DeploymentStarted(rocketEntity.OwnerFraction, sicknessDeployment.LastAcceptedWave!);
        Check(rocketCardMatch.ApplyArmyHostDamage(rocketEntity.EntityKey, rocketEntity.MaxHealth * 0.75f),
            "host damage injures the Rocket Soldier before its Sickness callback");
        Check(rocketCardMatch.ApplySicknessToCardRocket(rocketEntity.EntityKey, rocketSickness) &&
            rocketCardMatch.CardRocketMissile(rocketEntity.EntityKey) ==
                rocketStats.Rocket! with { DirectDamage = rocketStats.Rocket.DirectDamage * 0.5f },
            "host Sickness modifies Rocket contact damage while preserving explosion and flight authority");
        var sickRocket = rocketCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0).Entities.Single();
        Check(sickRocket.MaxHealth == rocketEntity.MaxHealth &&
            sickRocket.Health == rocketEntity.MaxHealth * 0.5f,
            "Sickness refills the injured Rocket to half maximum without reducing its maximum");
        Check(rocketCardMatch.ApplyArmyHostDamage(rocketEntity.EntityKey, rocketEntity.MaxHealth * 0.25f) &&
            rocketCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0).Entities.Single().Health ==
                rocketEntity.MaxHealth * 0.25f,
            "subsequent host damage uses the updated Rocket vitality authority");
        var rocketBody = new PlayerHitbox("rocket-target/body",
            PlayerHitboxKind.Box, 1, Vector3.Zero,
            new Vector3(.4f, .4f, .4f), Quaternion.Identity, 0,
            Vector3.Zero, 0);
        var rocketHead = new PlayerHitbox("rocket-target/head",
            PlayerHitboxKind.Sphere, 1, Vector3.UnitY,
            Vector3.Zero, Quaternion.Identity, .15f,
            Vector3.Zero, 0);
        var rocketPose = PlayerCollisionModel.InitializedFrame("test",
            "rocket-target", Vector3.Zero, Quaternion.Identity,
            [rocketBody, rocketHead]);
        var grenadeArmyHit =
            CardGrenadierExplosionDamage.ResolveArmy(Vector3.Zero,
                Vector3.Zero, [rocketBody, rocketHead],
                grenadierStats.Grenade!, grenadierStats.Grenadier!);
        Check(grenadeArmyHit is
              { Kind: CombatDamageType.Explosion } &&
              grenadeArmyHit.RawDamage ==
                  grenadierStats.Grenade!.Explosion &&
              CardGrenadierExplosionDamage.ResolveArmy(
                  new Vector3(4f, 0, 0), Vector3.Zero,
                  [rocketBody, rocketHead],
                  grenadierStats.Grenade,
                  grenadierStats.Grenadier!) == null,
            "Grenadier dynamic targets share the source nearest-bounds blast rule");
        var closeGrenadePlayer =
            CardGrenadierExplosionDamage.ResolvePlayer(Vector3.Zero,
                rocketPose, Vector3.Zero, grenadierStats.Grenade!,
                grenadierStats.Grenadier!, false);
        var shieldedGrenadePlayer =
            CardGrenadierExplosionDamage.ResolvePlayer(
                new Vector3(.95f, 0, 0), rocketPose, Vector3.Zero,
                grenadierStats.Grenade!, grenadierStats.Grenadier!, true);
        Check(closeGrenadePlayer is
              { Kind: CombatDamageType.Explosion } &&
              closeGrenadePlayer.RawDamage ==
                  grenadierStats.Grenade!.Explosion &&
              shieldedGrenadePlayer is
              { Kind: CombatDamageType.Shiver } &&
              shieldedGrenadePlayer.RawDamage >
                  grenadierStats.Grenade.Minimum *
                      grenadierStats.Grenadier!.PlayerBehindShieldRatio &&
              shieldedGrenadePlayer.RawDamage <
                  grenadierStats.Grenade.Explosion *
                      grenadierStats.Grenadier.PlayerBehindShieldRatio,
            "Grenadier player blast uses its .7 overlap radius and shield reduction");
        var nearRocketHit = CardRocketExplosion.ResolvePlayer(Vector3.Zero,
            rocketPose, Vector3.Zero, rocketStats.Rocket!, false);
        Check(nearRocketHit is { Kind: CombatDamageType.Explosion } &&
              nearRocketHit.RawDamage == rocketStats.Rocket!.ExplosionDamage,
            "Rocket direct-radius impact applies the card's full explosion damage");
        var edgeRocketHit = CardRocketExplosion.ResolvePlayer(
            new Vector3(1.1f, 0, 0), rocketPose, Vector3.Zero,
            rocketStats.Rocket!, true);
        float edgeFalloff = 1f - (1.1f - .8f) / (.4f);
        float expectedEdgeDamage = (rocketStats.Rocket!.DirectDamage +
            (rocketStats.Rocket.ExplosionDamage -
                rocketStats.Rocket.DirectDamage) * edgeFalloff * edgeFalloff) *
            rocketStats.Rocket.PlayerBehindShieldRatio;
        Check(edgeRocketHit is { Kind: CombatDamageType.Shiver } &&
              MathF.Abs(edgeRocketHit.RawDamage - expectedEdgeDamage) < .0001f,
            "Rocket outer-radius impact uses root-distance falloff and shield ratio");
        Check(CardRocketExplosion.ResolvePlayer(new Vector3(4, 0, 0),
                  rocketPose, Vector3.Zero, rocketStats.Rocket!, false) == null,
            "Rocket outside its recovered hurt radius cannot damage a player");
        var nearDynamic = new MapDynamicCollider(11, "test/shield/near",
            "test-shield", 10, Vector3.Zero,
            new Vector3(-.2f), new Vector3(.2f));
        var farDynamic = nearDynamic with
        {
            ColliderIndex = 12,
            SourcePath = "test/shield/far",
            TransformPosition = Vector3.UnitX,
            BoundsMin = new Vector3(.9f, -.1f, -.1f),
            BoundsMax = new Vector3(1.1f, .1f, .1f)
        };
        var distinctDynamic = farDynamic with
        {
            ColliderIndex = 13,
            DynamicOwner = "test-barrel"
        };
        var selectedRocketColliders = CardRocketExplosion.ClosestColliders(
            Vector3.Zero, [farDynamic, nearDynamic, distinctDynamic]);
        Check(selectedRocketColliders.Count == 2 &&
              selectedRocketColliders[0].ColliderIndex == 11 &&
              selectedRocketColliders[1].ColliderIndex == 13,
            "Rocket blast chooses one closest collider per dynamic owner");
        var directDynamic = CardRocketExplosion.ResolveDynamic(Vector3.Zero,
            nearDynamic, rocketStats.Rocket!);
        Check(directDynamic.Kind == CombatDamageType.Explosion &&
              directDynamic.RawDamage == rocketStats.Rocket!.ExplosionDamage,
            "Rocket blast applies full card damage inside the dynamic dead radius");
        var outerDynamic = CardRocketExplosion.ResolveDynamic(Vector3.Zero,
            farDynamic, rocketStats.Rocket!);
        Check(outerDynamic.Kind == CombatDamageType.Shiver &&
              outerDynamic.RawDamage >= rocketStats.Rocket.DirectDamage &&
              outerDynamic.RawDamage < rocketStats.Rocket.ExplosionDamage,
            "Rocket blast attenuates dynamic damage in the outer radius");
        var directArmyRocket = CardRocketExplosion.ResolveArmy(Vector3.Zero,
            Vector3.Zero, [rocketBody, rocketHead], rocketStats.Rocket!);
        Check(directArmyRocket is { Kind: CombatDamageType.Explosion } &&
              directArmyRocket.RawDamage == rocketStats.Rocket!.ExplosionDamage,
            "Rocket blast gives a directly overlapped army body full card damage");
        var outerArmyRocket = CardRocketExplosion.ResolveArmy(
            new Vector3(1.1f, 0, 0), Vector3.Zero,
            [rocketBody, rocketHead], rocketStats.Rocket!);
        Check(outerArmyRocket is { Kind: CombatDamageType.Shiver } &&
              MathF.Abs(outerArmyRocket.RawDamage -
                  (rocketStats.Rocket!.DirectDamage +
                   (rocketStats.Rocket.ExplosionDamage -
                    rocketStats.Rocket.DirectDamage) *
                   edgeFalloff * edgeFalloff)) < .0001f,
            "Rocket army blast uses nearest bounds and root-distance falloff");
        Check(CardRocketExplosion.ResolveArmy(new Vector3(4, 0, 0),
                  Vector3.Zero, [rocketBody, rocketHead],
                  rocketStats.Rocket!) == null,
            "Rocket blast leaves infantry outside its source radius untouched");
        int rocketCollisionChecks = 0;
        var rocketFlight = new CardRocketMissileFlight(81,
            rocketEntity.EntityKey, rocketStats.Rocket!, Vector3.Zero,
            new Vector3(3, 0, 0), 0, false, (start, movement, distance) =>
            {
                rocketCollisionChecks++;
                return new ShotCollision(.05f,
                    start + Vector3.UnitX * .05f,
                    "rocket-test-target", null, 1);
            });
        for (ulong flightTick = 1; flightTick <= 6; flightTick++)
            Check(rocketFlight.Advance(flightTick) == null,
                "Rocket flight waits until its initial half-unit travel ends");
        Check(rocketCollisionChecks == 0 &&
              MathF.Abs(rocketFlight.Position.X - .6f) < .0001f,
            "Rocket travels at its recovered three-unit speed before collision checks");
        CardRocketMissileImpact? rocketHit = rocketFlight.Advance(7);
        Check(rocketHit is { ProjectileId: 81, Tick: 7, IsFake: false,
                  Collision: not null } &&
              rocketHit.SoldierEntityKey == rocketEntity.EntityKey &&
              rocketCollisionChecks == 1 && rocketFlight.Finished,
            "Rocket stops at one validated host collision after its startup distance");
        var expiringRocket = new CardRocketMissileFlight(82,
            rocketEntity.EntityKey, rocketStats.Rocket!, Vector3.Zero,
            new Vector3(3, 0, 0), 0, true,
            (_, _, _) => null);
        CardRocketMissileImpact? rocketExpiry = null;
        for (ulong flightTick = 1; flightTick <= 95 && rocketExpiry == null;
             flightTick++)
            rocketExpiry = expiringRocket.Advance(flightTick);
        Check(rocketExpiry is { ProjectileId: 82, IsFake: true,
                  Collision: null } && rocketExpiry.Position.X > 9f,
            "fake Rocket flight retains visual travel and ends without collision");
        var farRocket = new CardRocketMissileFlight(83,
            rocketEntity.EntityKey, rocketStats.Rocket!, Vector3.Zero,
            new Vector3(100, 0, 0), 0, false, (_, _, _) => null);
        Check(farRocket.TargetPosition == new Vector3(50, 0, 0),
            "Rocket launch caps the original target to fifty units");
        Reject(() => new CardRocketMissileFlight(84,
            rocketEntity.EntityKey, rocketStats.Rocket! with { Speed = CardRocketMissileFlight.MaximumSpeed + 1f },
            Vector3.Zero, Vector3.UnitX, 0, false, (_, _, _) => null));
        var rocketAim = rocketCardMatch.CardRocketAim(rocketEntity.EntityKey);
        CoverNode opposingCover = park.Covers.First(cover =>
            cover.Fraction == 2 && cover.Main);
        Check(rocketAim == opposingCover.ShotPosition,
            "spawned Rocket card aims at the opponent's current cover shield");
        Vector3 rocketStart = new(rocketEntity.X, rocketEntity.Y, rocketEntity.Z);
        CardUnitInitialPoint? rocketPoint = content.CardUnitInitialPoints.Select(
            park, "BIGROCKET", 1, rocketStart, _ => true);
        Check(rocketPoint != null &&
              rocketCardMatch.CardEnemyPoint(rocketEntity.EntityKey) == rocketPoint &&
              rocketCardMatch.CardEnemyPointOccupant(rocketPoint.ComponentFileId) ==
                  rocketEntity.EntityKey &&
              rocketCardMatch.CardRocketWalking(rocketEntity.EntityKey),
            "Rocket card reserves the nearest source Corner point and starts its walk");
        int rocketMoveDestination = park.Adjacent(
            park.Covers.ToList().IndexOf(opposingCover), -1, 2);
        Check(rocketMoveDestination >= 0 &&
              rocketCardMatch.Command(decoyOpponent, new MatchCommand
              {
                  CommandId = 3,
                  MoveCover = new MoveCoverCommand { Direction = -1 }
              }).Code == "moving" &&
              rocketCardMatch.CardRocketAim(rocketEntity.EntityKey) ==
                  park.Covers[rocketMoveDestination].ShotPosition,
            "moving opponent changes the Rocket aim to the destination cover shield");
        for (ulong rocketTick = 61; rocketTick <= 90; rocketTick++)
            rocketCardMatch.Advance(rocketTick);
        var movingRocket = rocketCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
            .Entities.Single(entity => entity.EntityKey == rocketEntity.EntityKey);
        Check(Vector3.Distance(rocketStart,
                  new Vector3(movingRocket.X, movingRocket.Y, movingRocket.Z)) > .01f &&
              movingRocket.InfantryClip == "bazooka_run" &&
              rocketCardMatch.CardEnemyPointOccupant(
                  rocketPoint!.ComponentFileId) == rocketEntity.EntityKey,
            "Rocket card publishes its running pose while retaining the point");
        CardRocketShotIntent? firstRocketShot = null;
        for (ulong rocketTick = 91; rocketTick <= 900; rocketTick++)
        {
            rocketCardMatch.Advance(rocketTick);
            firstRocketShot = rocketCardMatch.CardRocketShotIntents()
                .FirstOrDefault(intent => intent.EntityKey == rocketEntity.EntityKey);
            if (firstRocketShot != null)
                break;
            if (rocketTick % 60 == 0)
            {
                rocketCardMatch.EventBatch(decoyPlayer, 0);
                rocketCardMatch.EventBatch(decoyOpponent, 0);
            }
        }
        Check(firstRocketShot != null &&
              rocketCardMatch.CardRocketAttack(rocketEntity.EntityKey) != null &&
              firstRocketShot.TargetPosition ==
                  park.Covers[rocketMoveDestination].ShotPosition &&
              firstRocketShot.ShotIndex == 0 && firstRocketShot.BatchSize >= 1,
            "Rocket card latches its shield aim after Corner arrival and source windup");
        var firingRocket = rocketCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
            .Entities.Single(entity => entity.EntityKey == rocketEntity.EntityKey);
        Vector3 expectedRocketMuzzle = CardRocketMuzzlePose.Place(
            content.CoopEnemyMuzzles, content.CoopAssaulterWeapon,
            rocketPoint!, new Vector3(firingRocket.X, firingRocket.Y,
                firingRocket.Z), firstRocketShot!.TargetPosition);
        Check(firstRocketShot.MuzzlePosition == expectedRocketMuzzle &&
              Vector3.Distance(firstRocketShot.MuzzlePosition,
                  new Vector3(firingRocket.X, firingRocket.Y,
                      firingRocket.Z)) < 5f &&
              rocketCardMatch.CardRocketActiveFlightCount == 1,
            "Rocket intent launches one missile from the animated BazookaEnemy Spawn position");
        var rocketProjectileRow = rocketCardMatch.Snapshot().Projectiles
            .Single(row => row.Kind is "card-rocket" or "card-rocket-fake");
        Check(rocketProjectileRow.Kind ==
                  (firstRocketShot.IsReal ? "card-rocket" : "card-rocket-fake") &&
              rocketProjectileRow.OwnerPlayerId == decoyPlayer &&
              rocketProjectileRow.X == firstRocketShot.MuzzlePosition.X &&
              MathF.Abs(new Vector3(rocketProjectileRow.VelocityX,
                  rocketProjectileRow.VelocityY,
                  rocketProjectileRow.VelocityZ).Length() - 3f) < .0001f,
            "Rocket snapshot publishes a source-speed projectile for reconnect");
        ArmyCardRocketRuntime? frozenRocketMissile =
            rocketCardMatch.CardRocketLaunchMissile(rocketProjectileRow.ProjectileId);
        Check(frozenRocketMissile == rocketCardMatch.CardRocketMissile(rocketEntity.EntityKey),
            "actual Rocket launch captures the Sickness-modified contact damage");
        Check(rocketCardMatch.ApplySicknessToCardRocket(rocketEntity.EntityKey, rocketSickness) &&
            rocketCardMatch.CardRocketMissile(rocketEntity.EntityKey)!.DirectDamage ==
                rocketStats.Rocket!.DirectDamage * 0.25f &&
            rocketCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0).Entities.Single().Health ==
                rocketEntity.MaxHealth * 0.5f &&
            rocketCardMatch.CardRocketLaunchMissile(rocketProjectileRow.ProjectileId) == frozenRocketMissile,
            "later Sickness changes future Rocket contact damage without rewriting an airborne missile");
        rocketSickness.Disconnect();
        Check(!rocketCardMatch.ApplySicknessToCardRocket(rocketEntity.EntityKey, rocketSickness),
            "disconnected Sickness cannot modify a Rocket weapon");
        ulong rocketShotEventId = rocketCardMatch
            .EventBatch(decoyPlayer, 0).LatestEventId;
        var rocketShotEvent = rocketCardMatch
            .EventBatch(decoyPlayer, rocketShotEventId - 1).Events.Single();
        Check(rocketShotEvent.Kind == MatchEventKind.Shot &&
              rocketShotEvent.ProjectileId == rocketProjectileRow.ProjectileId &&
              rocketShotEvent.Reason == rocketProjectileRow.Kind,
            "Rocket firing publishes one replayable event with its projectile identity");
        rocketCardMatch.Advance(firstRocketShot.Tick + 1);
        Check(rocketCardMatch.CardRocketActiveFlightCount == 1 &&
              rocketCardMatch.CardRocketImpacts().Count == 0,
            "Rocket missile advances on the next host tick without an immediate impact");
        Check(rocketCardMatch.ConfirmArmyDeath(rocketEntity.EntityKey, false) &&
              rocketCardMatch.CardRocketMissile(rocketEntity.EntityKey) == null &&
              rocketCardMatch.CardRocketLaunchMissile(rocketProjectileRow.ProjectileId) == frozenRocketMissile &&
              rocketCardMatch.CardRocketAim(rocketEntity.EntityKey) == null &&
              !rocketCardMatch.CardRocketWalking(rocketEntity.EntityKey) &&
              rocketCardMatch.CardRocketAttack(rocketEntity.EntityKey) == null &&
              rocketCardMatch.CardRocketShotIntents().Count == 0 &&
              rocketCardMatch.CardRocketActiveFlightCount == 1 &&
              rocketCardMatch.CardEnemyPointOccupant(
                  rocketPoint!.ComponentFileId) == null,
            "card Rocket death removes attack authority but keeps its launched missile");
        ulong rocketBeforeImpactEventId = rocketCardMatch
            .EventBatch(decoyPlayer, 0).LatestEventId;
        CardRocketMissileImpact? liveRocketImpact = null;
        for (ulong flightTick = firstRocketShot.Tick + 2;
             flightTick <= firstRocketShot.Tick + 1800 &&
                 liveRocketImpact == null; flightTick++)
        {
            rocketCardMatch.Advance(flightTick);
            liveRocketImpact = rocketCardMatch.CardRocketImpacts()
                .FirstOrDefault(impact =>
                    impact.SoldierEntityKey == rocketEntity.EntityKey);
            if (flightTick % 60 == 0)
            {
                rocketCardMatch.EventBatch(decoyPlayer, 0);
                rocketCardMatch.EventBatch(decoyOpponent, 0);
            }
        }
        Check(liveRocketImpact != null &&
              rocketCardMatch.CardRocketActiveFlightCount == 0 &&
              rocketCardMatch.Snapshot().Projectiles.All(row =>
                  row.ProjectileId != rocketProjectileRow.ProjectileId),
            "a launched Rocket reaches a terminal host impact after its soldier dies");
        var rocketImpactEvents = new List<MatchEvent>();
        ulong rocketEventCursor = rocketBeforeImpactEventId;
        while (true)
        {
            var page = rocketCardMatch.EventBatch(decoyPlayer,
                rocketEventCursor);
            rocketImpactEvents.AddRange(page.Events);
            if (page.Events.Count == 0 ||
                page.Events[^1].EventId == page.LatestEventId)
                break;
            rocketEventCursor = page.Events[^1].EventId;
        }
        Check(rocketImpactEvents.Any(item =>
                  item.Kind == MatchEventKind.Impact &&
                  item.ProjectileId == rocketProjectileRow.ProjectileId &&
                  item.Reason == rocketProjectileRow.Kind &&
                  item.X == liveRocketImpact!.Position.X),
            "Rocket impact remains replayable after the firing soldier dies");
        Check(BattleTerminalPolicy.IsAbortedReason("invalid-card-unit-authority"),
            "invalid card-unit authority has a durable unscored terminal reason");
        const string hostCardRequest = "e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5";
        Check(cardMatch.Command(decoyPlayer, new MatchCommand
        {
            CommandId = 3,
            UseUnitCard = new() { RequestId = hostCardRequest,
                SourceCardId = "GREATGRENADIER" }
        }).Code == "unit-card-unavailable" &&
              cardMatch.ArmyEntityBatch(decoyPlayer, 0, 0).ActiveCount == 0,
            "an unselected Grenadier card cannot spawn or consume inventory");
        string[] presentedUnitCards =
            ["ELITEMINIGUN", "ELITESWAT", "ELITESNIPER", "ELITEPARA",
                "HEAVYDRONE", "BIGROCKET", "GREATGRENADIER"];
        for (int cardIndex = 0; cardIndex < presentedUnitCards.Length; cardIndex++)
        {
            string cardId = presentedUnitCards[cardIndex];
            var playableCardMatch = ReadyCardMatch(
                "playable-unit-card-" + cardId.ToLowerInvariant(), cardId);
            string requestId = new string((char)('1' + cardIndex), 32);
            var activation = new MatchCommand
            {
                CommandId = 3,
                UseUnitCard = new UseUnitCardCommand
                {
                    RequestId = requestId,
                    SourceCardId = cardId
                }
            };
            Check(MatchEndpoint.ValidClientBody(new Packet
                  {
                      MatchCommand = activation
                  }),
                "UDP ingress accepts the canonical unit-card source and request fields");
            var activationReply = playableCardMatch.Command(decoyPlayer, activation);
            var spawned = playableCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0);
            Check(activationReply.Code == "unit-card-activated" &&
                  activationReply.Snapshot.CardActivations == 1 &&
                  spawned.Entities.Count >= 1 &&
                  spawned.Entities.All(row => row.SourceCardId == cardId &&
                      row.OptionIndex == -1 && row.OwnerPlayerId == decoyPlayer),
                "authenticated unit card creates only its Backend-selected source soldiers");
            Check(playableCardMatch.Command(decoyPlayer, activation).Code ==
                  "unit-card-activated" &&
                  playableCardMatch.Snapshot().CardActivations == 1 &&
                  playableCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
                      .ActiveCount == spawned.ActiveCount,
                "unit-card command replay cannot spend or spawn twice");
        }
        Check(cardMatch.TryScheduleCardUnit(hostCardRequest, decoyPlayer,
                  "HEAVYDRONE") &&
              !cardMatch.TryScheduleCardUnit(hostCardRequest, decoyPlayer,
                  "HEAVYDRONE"),
            "host card activation charges one selected source identity once");
        var liveCardRow = cardMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
            .Entities.Single();
        var liveCardStats = content.Army.CardBaseStats("HEAVYDRONE", 22,
            content.BarrelPolicy.MaxDisplayLevel);
        Check(liveCardRow.SourceCardId == "HEAVYDRONE" &&
              liveCardRow.OptionIndex == -1 &&
              liveCardRow.UnitId == "ID_UNIT-DRONE" &&
              liveCardRow.Health == liveCardRow.MaxHealth &&
              liveCardRow.Health == liveCardStats.Combat.Health &&
              cardMatch.ArmyDamage(liveCardRow.EntityKey) ==
                  liveCardStats.Combat.Damage &&
              cardMatch.ArmySpeed(liveCardRow.EntityKey) ==
                  liveCardStats.Drone!.MovementSpeed &&
              cardMatch.DroneShotDefinition(liveCardRow.EntityKey) is
                  { } cardDroneShot &&
              cardDroneShot.ShotSpeed == liveCardStats.Drone.ShotSpeed &&
              cardDroneShot.ProbabilityOfRealShot ==
                  liveCardStats.Shot.ProbabilityOfRealShot &&
              !cardMatch.ArmyDroneImmortal(liveCardRow.EntityKey) &&
              cardMatch.DroneTargetSnapshot().Any(target =>
                  target.Id == "army:" + liveCardRow.EntityKey) &&
              cardMatch.EventBatch(decoyPlayer, 0).Events.Any(row =>
                  row.Kind == MatchEventKind.ArmySpawned &&
                  row.SourceCardId == "HEAVYDRONE" &&
                  row.ArmyEntityId == liveCardRow.LocalEntityId),
            "match roster and event publish the source card unit and card-level health");
        cardMatch.Advance(61);
        Check(cardMatch.ArmyEntityBatch(decoyPlayer, 0, 0).Entities
                  .Any(row => row.EntityKey == liveCardRow.EntityKey &&
                      row.PositionTick == 61 && row.DroneRotation != null),
            "card Drone uses host flight motion on the next live simulation tick");
        var cardDroneColliders = cardMatch.GroundVehicleShotTargets(decoyOpponent)
            .Where(target => target.EntityId == liveCardRow.EntityKey).ToArray();
        Check(cardDroneColliders.Length == 2 &&
              cardDroneColliders.Count(target => target.DroneRoot) == 1,
            "card Drone exposes the recovered root and child bullet colliders");
        cardMatch.ApplyArmyBodyProjectileImpact(decoyOpponent,
            liveCardRow.EntityKey, 13511718, 10);
        Check(cardMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
                  .Entities.Single().Health == liveCardRow.Health,
            "card Drone child sphere has no damage-owning DestroyableObject");
        cardMatch.ApplyArmyBodyProjectileImpact(decoyOpponent,
            liveCardRow.EntityKey, 6544804, 10);
        Check(cardMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
                  .Entities.Single().Health == liveCardRow.Health - 10,
            "card Drone root bullet hit reduces its card-row health");
        Check(cardMatch.ApplyArmyHostDamage(liveCardRow.EntityKey,
                  liveCardRow.Health / 4) &&
              cardMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
                  .Entities.Single().Health < liveCardRow.Health,
            "trusted match damage updates the public card-unit health");
        Check(cardMatch.ConfirmArmyDeath(liveCardRow.EntityKey, false) &&
              !cardMatch.ConfirmArmyDeath(liveCardRow.EntityKey, false) &&
              cardMatch.ArmyEntityBatch(decoyPlayer, 0, 0).ActiveCount == 0 &&
              cardMatch.ArmyDamage(liveCardRow.EntityKey) == null &&
              cardMatch.ArmySpeed(liveCardRow.EntityKey) == null &&
              cardMatch.DroneShotDefinition(liveCardRow.EntityKey) == null &&
              !cardMatch.DroneTargetSnapshot().Any(target =>
                  target.Id == "army:" + liveCardRow.EntityKey) &&
              cardMatch.EventBatch(decoyPlayer, 0).Events.Any(row =>
                  row.Kind == MatchEventKind.ArmyDied &&
                  row.SourceCardId == "HEAVYDRONE" &&
                  row.ArmyEntityId == liveCardRow.LocalEntityId &&
                  row.ArmyEnergyRecipientId == ""),
            "card death removes the match roster and emits no ordinary army energy recipient");
        var firingCardMatch = ReadyCardMatch("host-card-drone-fire");
        const string firingCardRequest = "f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6";
        Check(firingCardMatch.TryScheduleCardUnit(firingCardRequest,
                  decoyPlayer, "HEAVYDRONE"),
            "second host match admits its selected Drone card for firing playback");
        var firingCardRow = firingCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
            .Entities.Single();
        Check(firingCardMatch.DroneAttackDeadline(firingCardRow.EntityKey) ==
                  60f / MatchManifest.TickRate + 2,
            "card Drone attack clock starts at its actual source spawn time");
        ulong firingEventCursor = 0;
        MatchEvent? cardFiringEvent = null;
        for (ulong firingTick = 61; firingTick <= 256 &&
             cardFiringEvent == null && !firingCardMatch.Terminal; firingTick++)
        {
            firingCardMatch.Advance(firingTick);
            while (true)
            {
                var batch = firingCardMatch.EventBatch(decoyPlayer,
                    firingEventCursor);
                if (batch.Code != "events" || batch.Events.Count == 0)
                    break;
                cardFiringEvent ??= batch.Events.FirstOrDefault(row =>
                    row.Kind == MatchEventKind.DroneFired &&
                    row.DroneShot?.ArmyEntityKey == firingCardRow.EntityKey);
                firingEventCursor = batch.Events[^1].EventId;
            }
        }
        var cardFiringIntent = firingCardMatch.LastDroneIntent(
            firingCardRow.EntityKey);
        var cardDamagePolicy = content.Army.PlayerDamagePolicy(
            "ID_UNIT-DRONE");
        Check(cardFiringEvent != null &&
              cardFiringIntent is { Speed: > 0, Damage: > 0 } &&
              cardFiringIntent.Damage == liveCardStats.Combat.Damage &&
              cardFiringEvent.DroneShot?.Speed == cardFiringIntent.Speed &&
              cardFiringEvent.DroneShot?.Fake ==
                  cardFiringIntent.Shot.Batch.IsFake &&
              cardFiringIntent.Speed == content.DroneProjectile.Speed(
                  liveCardStats.Drone!.ShotSpeed,
                  cardFiringEvent.TargetId == "player:" + decoyOpponent,
                  cardFiringIntent.Shot.Batch.IsFake) &&
              cardFiringIntent.PlayerDamageCoefficient ==
                  cardDamagePolicy.PlayerDamageRatio &&
              cardFiringIntent.PlayerOvertimeDamageCoefficient ==
                  cardDamagePolicy.OvertimePlayerDamageRatio &&
              firingCardMatch.DroneAttackDeadline(firingCardRow.EntityKey) >
                  60f / MatchManifest.TickRate + 2,
            "card Drone fires through the host projectile clock and source player-damage policy");
        var paraCardMatch = ReadyCardMatch("host-card-para", "ELITEPARA");
        const string paraCardRequest = "a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7a7";
        Check(paraCardMatch.TryScheduleCardUnit(paraCardRequest,
                  decoyPlayer, "ELITEPARA"),
            "host accepts one selected Paratrooper card as two source calls");
        var firstParaRows = paraCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
            .Entities.ToArray();
        Check(firstParaRows.Length == 1 &&
              firstParaRows[0].SourceCardId == "ELITEPARA" &&
              firstParaRows[0].InfantryClip == "idle_1" &&
              paraCardMatch.InfantryPose(firstParaRows[0].EntityKey)?.Clip == "idle_1" &&
              firstParaRows[0].ParachuteActive &&
              firstParaRows[0].ParachuteRotation != null &&
              firstParaRows[0].SpawnTick == 60 &&
              firstParaRows[0].OptionIndex == -1 &&
              paraCardMatch.CardParatrooperAirAttacking(
                  firstParaRows[0].EntityKey),
            "first Paratrooper card unit publishes with its airborne shot clock");
        bool rejectedSkippedCardTicks = false;
        try { paraCardMatch.Advance(75); }
        catch (InvalidOperationException error) when
            (error.Message == "Pending card units require every simulation tick.")
        { rejectedSkippedCardTicks = true; }
        Check(rejectedSkippedCardTicks,
            "pending delayed card calls require every host simulation tick");
        for (ulong paraTick = 61; paraTick <= 75; paraTick++)
            paraCardMatch.Advance(paraTick);
        var paraRows = paraCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
            .Entities.OrderBy(row => row.LocalEntityId).ToArray();
        Check(paraRows.Length == 2 &&
              paraRows[0].EntityKey != paraRows[1].EntityKey &&
              paraRows[0].SpawnTick == 60 &&
              paraRows[1].SpawnTick == 75 &&
              paraRows.All(row => row.SourceCardId == "ELITEPARA" &&
                  row.UnitId == "ID_UNIT-PARATROOPER" &&
                  row.InfantryClip == "idle_1" &&
                  paraCardMatch.InfantryPose(row.EntityKey)?.Clip == row.InfantryClip &&
                  row.ParachuteActive && row.ParachuteRotation != null &&
                  row.OptionIndex == -1),
            "delayed second Paratrooper card unit receives a distinct host identity at tick 75");
        var paraStats = content.Army.CardBaseStats("ELITEPARA", 22,
            content.BarrelPolicy.MaxDisplayLevel);
        ArmyBaseShotStats sourceAirShot = content.Army.Families.Single(
            family => family.UnitId == "ID_UNIT-PARATROOPER").BaseShot!;
        var airborneClock = new ArmyRusherAttackState(sourceAirShot,
            () => 0.99f, shotIntervalTicks: 16);
        Check(airborneClock.TryBegin(true, 1,
                  content.ArmyWeapons.WindupTicks("ID_UNIT-PARATROOPER")) &&
              airborneClock.BatchSize == 3,
            "airborne shot clock draws the recovered Paratrooper batch before its windup");
        for (int airTick = 0; airTick < 9; airTick++)
        {
            airborneClock.AdvanceTick();
            Check(!airborneClock.ShotDue,
                "airborne shot remains pending through the nine-tick rifle windup");
        }
        airborneClock.AdvanceTick();
        Check(airborneClock.ShotDue && airborneClock.CommitShot(),
            "airborne first round starts after the recovered 0.3-second windup");
        for (int airTick = 0; airTick < 15; airTick++)
        {
            airborneClock.AdvanceTick();
            Check(!airborneClock.ShotDue,
                "airborne rifle does not fire before its half-second cadence");
        }
        airborneClock.AdvanceTick();
        Check(airborneClock.ShotDue,
            "airborne next round is due after the half-second cadence");
        Check(paraRows.All(row => paraCardMatch.ArmyDamage(row.EntityKey) ==
                  paraStats.Combat.Damage),
            "both Paratroopers retain card-specific damage while awaiting landing");
        Check(paraCardMatch.ConfirmArmyDeath(paraRows[0].EntityKey, false) &&
              paraCardMatch.ArmyDamage(paraRows[0].EntityKey) == null &&
              !paraCardMatch.CardParatrooperFalling(paraRows[0].EntityKey) &&
              !paraCardMatch.CardParatrooperAirAttacking(
                  paraRows[0].EntityKey) &&
              paraCardMatch.ArmyDamage(paraRows[1].EntityKey) ==
                  paraStats.Combat.Damage,
            "one Paratrooper death clears only its own combat authority");
        var remainingPara = paraRows[1];
        var paraLandingPoint = content.CardUnitInitialPoints.Select(park,
            "ELITEPARA", remainingPara.OwnerFraction,
            new Vector3(remainingPara.X, remainingPara.Y, remainingPara.Z),
            _ => true)!;
        Vector3? paraLandingCandidate = null;
        Vector3? paraDestination = content.ArmyNavMeshConnectivity.SampleNearest(
            park, paraLandingPoint.Position, 0.5f);
        foreach (Vector3 offset in new[]
        {
            new Vector3(0.4f, 0, 0), new Vector3(-0.4f, 0, 0),
            new Vector3(0, 0, 0.4f), new Vector3(0, 0, -0.4f)
        })
        {
            Vector3 candidate = paraLandingPoint.Position + offset;
            Vector3? start = content.ArmyNavMeshConnectivity.SampleNearest(
                park, candidate, 0.5f);
            if (start.HasValue && paraDestination.HasValue &&
                content.ArmyNavMeshConnectivity.PlanCorridor(
                    park, start.Value, paraDestination.Value) != null)
            {
                paraLandingCandidate = candidate;
                break;
            }
        }
        Check(paraLandingCandidate.HasValue,
            "Park Corner point has a nearby walkable landing fixture");
        Vector3 paraLanding = paraLandingCandidate ??
            throw new InvalidDataException("Park Paratrooper landing fixture is missing.");
        var canopyPageMatch = ReadyCardMatch("host-card-para-pages", "ELITEPARA");
        Check(canopyPageMatch.TryScheduleCardUnit(
                  "adadadadadadadadadadadadadadadad", decoyPlayer,
                  "ELITEPARA") &&
              canopyPageMatch.TryScheduleCardUnit(
                  "aeaeaeaeaeaeaeaeaeaeaeaeaeaeaeae", decoyOpponent,
                  "ELITEPARA"),
            "both players schedule card Paratroopers for a canopy page");
        for (ulong pageTick = 61; pageTick <= 75; pageTick++)
            canopyPageMatch.Advance(pageTick);
        ulong pageLandingEntity = canopyPageMatch.ArmyEntityBatch(
            decoyPlayer, 0, 0).Entities.First(row =>
                row.OwnerPlayerId == decoyPlayer).EntityKey;
        Check(canopyPageMatch.ConfirmCardParatrooperLanding(
                  pageLandingEntity, paraLanding),
            "one Paratrooper lands while four card soldiers remain active");
        var firstCanopyPage = canopyPageMatch.ArmyEntityBatch(
            decoyPlayer, 0, 0);
        var finalCanopyPage = canopyPageMatch.ArmyEntityBatch(decoyPlayer,
            firstCanopyPage.Entities[^1].EntityKey, firstCanopyPage.Revision);
        Check(firstCanopyPage.ActiveCount == 4 &&
              firstCanopyPage.Entities.Count == 3 && firstCanopyPage.HasMore &&
              finalCanopyPage.Entities.Count == 1 && !finalCanopyPage.HasMore &&
              firstCanopyPage.Entities.Concat(finalCanopyPage.Entities)
                  .Single(row => row.EntityKey == pageLandingEntity)
                  .ParachuteLandingTick == 75,
            "the expanded canopy pose uses a three-entity UDP page and a final cursor page");
        ulong beforeCanopyDeath = canopyPageMatch.EventBatch(decoyPlayer, 0)
            .LatestEventId;
        Check(canopyPageMatch.ConfirmArmyDeath(pageLandingEntity, false),
            "the landed Paratrooper can die before the next client roster poll");
        var canopyDeath = canopyPageMatch.EventBatch(decoyPlayer,
            beforeCanopyDeath).Events.Single(row =>
                row.Kind == MatchEventKind.ArmyDied &&
                row.SourceCardId == "ELITEPARA");
        Check(canopyDeath.ParachuteEntityKey == pageLandingEntity &&
              canopyDeath.ParachuteLandingTick == 75 &&
              canopyDeath.Tick == 75 &&
              canopyDeath.ParachuteRotation != null &&
              Vector3.Distance(new Vector3(canopyDeath.ParachuteLandingX,
                  canopyDeath.ParachuteLandingY, canopyDeath.ParachuteLandingZ),
                  paraLanding) < .0001f &&
              canopyPageMatch.ArmyEntityBatch(decoyPlayer, 0, 0).Entities
                  .All(row => row.EntityKey != pageLandingEntity),
            "death event retains canopy impact pose after its soldier leaves the roster");
        var survivingCanopy = canopyPageMatch.Snapshot();
        War.Client.BattleLandedCanopyPolicy.Validate(survivingCanopy);
        Check(survivingCanopy.LandedCanopies.Count == 1 &&
              survivingCanopy.LandedCanopies[0].EntityKey == pageLandingEntity &&
              survivingCanopy.LandedCanopies[0].LandingTick == 75,
            "a reconnect snapshot restores a dead soldier's unexpired canopy");
        var corruptCanopy = survivingCanopy.Clone();
        corruptCanopy.LandedCanopies[0].Rotation = null;
        bool corruptCanopyRejected = false;
        try { War.Client.BattleLandedCanopyPolicy.Validate(corruptCanopy); }
        catch (InvalidOperationException) { corruptCanopyRejected = true; }
        Check(corruptCanopyRejected,
            "the portable SDK rejects a reconnect canopy without its source rotation");
        for (ulong canopyTick = 76; canopyTick <= 165; canopyTick++)
            canopyPageMatch.Advance(canopyTick);
        Check(canopyPageMatch.Snapshot().LandedCanopies.Count == 0,
            "dead soldier canopy leaves reconnect state at its source deadline");
        var landingDuringShot = ReadyCardMatch(
            "host-card-para-land-during-shot", "ELITEPARA");
        Check(landingDuringShot.Command(decoyOpponent, new MatchCommand
              {
                  CommandId = 3,
                  MoveCover = new MoveCoverCommand { Direction = -1 }
              }).Code == "moving" &&
              landingDuringShot.TryScheduleCardUnit(
                  "bcbcbcbcbcbcbcbcbcbcbcbcbcbcbcbc",
                  decoyPlayer, "ELITEPARA"),
            "Park defender moves into the airborne rifle lane before landing");
        ulong landingShotEntity = landingDuringShot
            .ArmyEntityBatch(decoyPlayer, 0, 0).Entities.Single().EntityKey;
        ulong landingWindupTick = 60;
        for (ulong candidateTick = 61; candidateTick <= 150 &&
             landingDuringShot.CardParatrooperAirAttack(landingShotEntity)?
                 .Phase != ArmyRusherAttackPhase.Windup; candidateTick++)
        {
            if (candidateTick == 90)
            {
                landingDuringShot.ArmyBatch(decoyPlayer);
                landingDuringShot.ArmyBatch(decoyOpponent);
            }
            landingDuringShot.Advance(candidateTick);
            landingWindupTick = candidateTick;
        }
        ArmyRusherAttackState? landingAirAttack = landingDuringShot
            .CardParatrooperAirAttack(landingShotEntity);
        Check(landingAirAttack is
                  { Phase: ArmyRusherAttackPhase.Windup, BatchSize: >= 2 } &&
              landingDuringShot.CardParatrooperFalling(landingShotEntity) &&
              landingDuringShot.ConfirmCardParatrooperLanding(
                  landingShotEntity, paraLanding),
            "host confirms landing after the source rifle batch has begun winding up");
        bool heldCornerForAirBatch = false;
        bool sampledWalkMuzzleSeen = false;
        var airborneRoundsAfterLanding = new HashSet<ulong>();
        bool beganCornerAfterAirBatch = false;
        for (ulong shotTick = landingWindupTick + 1; shotTick <= 300 &&
             !landingDuringShot.Terminal && !beganCornerAfterAirBatch;
             shotTick++)
        {
            if (shotTick % 90 == 0)
            {
                landingDuringShot.ArmyBatch(decoyPlayer);
                landingDuringShot.ArmyBatch(decoyOpponent);
            }
            CoopMuzzlePose? walkMuzzleBeforeStep = landingDuringShot
                .CardParatrooperPostLandingMuzzle(landingShotEntity, shotTick);
            landingDuringShot.Advance(shotTick);
            ArmyRusherAttackState? pendingAir = landingDuringShot
                .CardParatrooperAirAttack(landingShotEntity);
            if (landingDuringShot.CardParatrooperWalkArrived(landingShotEntity) &&
                pendingAir?.Phase is ArmyRusherAttackPhase.Windup or
                    ArmyRusherAttackPhase.Firing)
            {
                heldCornerForAirBatch = true;
                Check(!landingDuringShot.CardParatrooperAttacking(
                          landingShotEntity),
                    "Corner attack waits while a pre-landing rifle batch is pending");
            }
            foreach (MatchEvent round in landingDuringShot
                .EventBatch(decoyPlayer, 0).Events.Where(row =>
                    row.Kind == MatchEventKind.Shot &&
                    row.Tick == shotTick &&
                    landingDuringShot.ArmyProjectileSourceEntity(
                        row.ProjectileId) == landingShotEntity))
            {
                if (pendingAir != null &&
                    landingDuringShot.CardParatrooperWalking(landingShotEntity))
                {
                    Check(walkMuzzleBeforeStep != null &&
                          Vector3.Distance(new Vector3(round.X, round.Y,
                                  round.Z),
                              walkMuzzleBeforeStep.Position) < 0.0001f,
                        "post-landing airborne batch uses the sampled rifle Walk muzzle");
                    sampledWalkMuzzleSeen = true;
                }
                airborneRoundsAfterLanding.Add(round.ProjectileId);
            }
            beganCornerAfterAirBatch = pendingAir == null &&
                landingDuringShot.CardParatrooperAttacking(landingShotEntity);
        }
        Check(heldCornerForAirBatch &&
              sampledWalkMuzzleSeen &&
              landingAirAttack!.BatchCursor == landingAirAttack.BatchSize &&
              airborneRoundsAfterLanding.Count > 0 &&
              beganCornerAfterAirBatch,
            "pre-landing rifle rounds finish after touchdown before Corner attack starts");
        Reject(() => paraCardMatch.ConfirmCardParatrooperLanding(
            remainingPara.EntityKey,
            paraLandingPoint.Position + new Vector3(0.4f, 0, 0)));
        Check(paraCardMatch.CardEnemyPoint(remainingPara.EntityKey) == null &&
              paraCardMatch.CardEnemyPointOccupant(
                  paraLandingPoint.ComponentFileId) == null,
            "failed Paratrooper route releases the tentative Corner reservation");
        Check(paraCardMatch.ConfirmCardParatrooperLanding(
                  remainingPara.EntityKey, paraLanding) &&
              paraCardMatch.CardParatrooperWalking(remainingPara.EntityKey) &&
              paraCardMatch.CardEnemyPoint(remainingPara.EntityKey)?
                  .ComponentFileId == paraLandingPoint.ComponentFileId &&
              !paraCardMatch.ConfirmCardParatrooperLanding(
                  remainingPara.EntityKey, paraLanding),
            "host-confirmed Paratrooper landing reserves one Corner point once");
        var landedPara = paraCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
            .Entities.Single(row => row.EntityKey == remainingPara.EntityKey);
        Check(!landedPara.ParachuteActive &&
              landedPara.ParachuteLandingTick == 75 &&
              landedPara.ParachuteLandingX == paraLanding.X &&
              landedPara.ParachuteLandingY == paraLanding.Y &&
              landedPara.ParachuteLandingZ == paraLanding.Z &&
              landedPara.ParachuteRotation != null,
            "landed Paratrooper keeps its canopy at the host impact pose");
        paraCardMatch.Advance(76);
        var walkingPara = paraCardMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
            .Entities.Single();
        Check(walkingPara.EntityKey == remainingPara.EntityKey &&
              walkingPara.InfantryClip == "run_0" &&
              paraCardMatch.InfantryPose(walkingPara.EntityKey)?.Clip == "run_0" &&
              !walkingPara.ParachuteActive &&
              walkingPara.ParachuteLandingTick == 75 &&
              walkingPara.ParachuteRotation != null &&
              new Vector3(walkingPara.X, walkingPara.Y, walkingPara.Z) !=
                  paraLanding,
            "landed Paratrooper begins host-owned movement to its Corner point");
        ulong paraAttackTick = 76;
        for (ulong cardTick = 77; cardTick < 180 &&
             !paraCardMatch.CardParatrooperAttacking(remainingPara.EntityKey);
             cardTick++)
        {
            paraCardMatch.Advance(cardTick);
            paraAttackTick = cardTick;
        }
        Check(paraCardMatch.CardParatrooperAttacking(remainingPara.EntityKey) &&
              !paraCardMatch.CardParatrooperWalking(remainingPara.EntityKey),
            "Paratrooper enters its card-specific Corner attack clock on arrival");
        bool paraShotSeen = false;
        for (ulong cardTick = paraAttackTick + 1; cardTick < 1000 &&
             !paraCardMatch.Terminal && !paraShotSeen; cardTick++)
        {
            if (cardTick % 90 == 0)
            {
                paraCardMatch.ArmyBatch(decoyPlayer);
                paraCardMatch.ArmyBatch(decoyOpponent);
            }
            paraCardMatch.Advance(cardTick);
            paraShotSeen = paraCardMatch.EventBatch(decoyPlayer, 0)
                .Events.Any(row => row.Kind == MatchEventKind.Shot &&
                    row.ActorId == decoyPlayer && row.Reason == "army");
        }
        Check(!paraShotSeen,
            "Paratrooper does not fire through the blocked side of its Corner");
        Check(paraCardMatch.ConfirmArmyDeath(remainingPara.EntityKey, false) &&
              !paraCardMatch.CardParatrooperWalking(remainingPara.EntityKey) &&
              !paraCardMatch.CardParatrooperAttacking(remainingPara.EntityKey) &&
              paraCardMatch.CardEnemyPoint(remainingPara.EntityKey) == null &&
              paraCardMatch.CardEnemyPointOccupant(
                  paraLandingPoint.ComponentFileId) == null,
            "Paratrooper death releases its walk and Corner reservation");
        var exposedParaPoint = content.CardUnitInitialPoints.Select(park,
            "ELITEPARA", 1, Vector3.Zero,
            id => id != paraLandingPoint.ComponentFileId)!;
        var firingParaMatch = ReadyCardMatch("host-card-para-fire", "ELITEPARA");
        const string firingParaRequest = "edededededededededededededededed";
        Check(firingParaMatch.TryScheduleCardUnit(firingParaRequest,
                  decoyPlayer, "ELITEPARA"),
            "host accepts a second Paratrooper fixture for exposed-side firing");
        var firingPara = firingParaMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
            .Entities.Single();
        Vector3? exposedLanding = null;
        Vector3? exposedDestination = content.ArmyNavMeshConnectivity.SampleNearest(
            park, exposedParaPoint.Position, 0.5f);
        foreach (Vector3 offset in new[]
        {
            new Vector3(0.4f, 0, 0), new Vector3(-0.4f, 0, 0),
            new Vector3(0, 0, 0.4f), new Vector3(0, 0, -0.4f)
        })
        {
            Vector3 candidate = exposedParaPoint.Position + offset;
            Vector3? start = content.ArmyNavMeshConnectivity.SampleNearest(
                park, candidate, 0.5f);
            if (start.HasValue && exposedDestination.HasValue &&
                content.ArmyNavMeshConnectivity.PlanCorridor(
                    park, start.Value, exposedDestination.Value) != null)
            {
                exposedLanding = candidate;
                break;
            }
        }
        Vector3 confirmedExposedLanding = exposedLanding ??
            throw new InvalidDataException("Exposed Park Corner has no walkable landing fixture.");
        Check(firingParaMatch.ConfirmCardParatrooperLanding(firingPara.EntityKey,
                  confirmedExposedLanding) &&
              firingParaMatch.CardEnemyPoint(firingPara.EntityKey)?
                  .ComponentFileId == exposedParaPoint.ComponentFileId,
            "exposed-side Paratrooper lands beside the other Park Corner");
        bool firingParaShotSeen = false;
        bool paraLookPoseSeen = false;
        bool paraFirePoseSeen = false;
        bool paraCoverBackPoseSeen = false;
        bool paraFiringDirectionMatched = false;
        void RecordParatrooperPose()
        {
            var row = firingParaMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
                .Entities.Single(entity => entity.EntityKey == firingPara.EntityKey);
            if (row.InfantryClip != firingParaMatch.InfantryPose(row.EntityKey)?.Clip)
                throw new Exception("Card Paratrooper visual and collision poses diverged.");
            paraLookPoseSeen |= row.InfantryClip.StartsWith("player_look_",
                StringComparison.Ordinal);
            paraFirePoseSeen |= row.InfantryClip.StartsWith("player_fire_",
                StringComparison.Ordinal);
            if (row.InfantryClip.StartsWith("player_fire_", StringComparison.Ordinal))
            {
                Vector3 sourceDirection = exposedParaPoint.CornerDirection ??
                    throw new InvalidDataException("Paratrooper Corner lost its direction.");
                Vector3 expectedFacing = Vector3.Normalize(new Vector3(
                    -sourceDirection.X, 0, -sourceDirection.Z));
                Vector3 actualFacing = firingParaMatch.InfantryPose(
                    row.EntityKey)?.Facing ?? Vector3.Zero;
                paraFiringDirectionMatched |= Vector3.Dot(actualFacing,
                    expectedFacing) > .99f;
            }
            paraCoverBackPoseSeen |= row.InfantryClip.Contains("_coverBack3",
                StringComparison.Ordinal);
        }
        ulong firingParaTick = 60;
        for (ulong cardTick = 61; cardTick < 1000 &&
             !firingParaMatch.Terminal && !firingParaShotSeen; cardTick++)
        {
            if (cardTick % 90 == 0)
            {
                firingParaMatch.ArmyBatch(decoyPlayer);
                firingParaMatch.ArmyBatch(decoyOpponent);
            }
            firingParaMatch.Advance(cardTick);
            RecordParatrooperPose();
            firingParaTick = cardTick;
            firingParaShotSeen = firingParaMatch.EventBatch(decoyPlayer, 0)
                .Events.Any(row => row.Kind == MatchEventKind.Shot &&
                    row.ActorId == decoyPlayer && row.Reason == "army");
        }
        Check(firingParaShotSeen &&
              firingParaMatch.CardParatrooperAttacking(firingPara.EntityKey),
            "exposed Park Corner fires a card Paratrooper projectile on the host clock");
        CoopMuzzlePose? cornerMuzzle = firingParaMatch
            .CardParatrooperCornerMuzzle(firingPara.EntityKey);
        Vector3 cornerDirection = exposedParaPoint.CornerDirection ??
            throw new InvalidDataException("Park Corner lost its source direction.");
        float cornerYaw = MathF.Atan2(-cornerDirection.X,
            -cornerDirection.Z);
        Quaternion cornerFacing = Quaternion.CreateFromAxisAngle(
            Vector3.UnitY, cornerYaw);
        var posedPara = firingParaMatch
            .ArmyEntityBatch(decoyPlayer, 0, 0).Entities
            .Single(row => row.EntityKey == firingPara.EntityKey);
        string cornerFireClip = exposedParaPoint.CornerRightSide == true
            ? "player_fire_right3" : "player_fire_left3";
        CoopMuzzlePose expectedCornerMuzzle = content.CoopEnemyMuzzles.Place(
            cornerFireClip,
            new Vector3(posedPara.X, posedPara.Y, posedPara.Z),
            cornerFacing, 0.05f);
        Check(cornerMuzzle != null &&
              Vector3.Distance(cornerMuzzle.Position,
                  expectedCornerMuzzle.Position) < 0.0001f,
            "Corner rifle muzzle follows the Client's -direction turn and side-specific fire clip");
        bool paraChangedCorner = false;
        for (ulong cardTick = firingParaTick + 1; cardTick < 1000 &&
             !firingParaMatch.Terminal && !paraChangedCorner; cardTick++)
        {
            if (cardTick % 90 == 0)
            {
                firingParaMatch.ArmyBatch(decoyPlayer);
                firingParaMatch.ArmyBatch(decoyOpponent);
            }
            firingParaMatch.Advance(cardTick);
            RecordParatrooperPose();
            paraChangedCorner = firingParaMatch.CardParatrooperWalking(
                firingPara.EntityKey) &&
                firingParaMatch.CardEnemyPoint(firingPara.EntityKey)?
                    .ComponentFileId != exposedParaPoint.ComponentFileId;
        }
        ulong occupiedOtherCorner = firingParaMatch.CardEnemyPointOccupant(
            paraLandingPoint.ComponentFileId) ?? 0;
        Check(paraLookPoseSeen && paraFirePoseSeen && paraCoverBackPoseSeen &&
              paraFiringDirectionMatched,
            "card Paratrooper Corner publishes reveal, fire, and cover-return poses facing its muzzle");
        var expiredCanopy = firingParaMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
            .Entities.Single(row => row.EntityKey == firingPara.EntityKey);
        Check(!expiredCanopy.ParachuteActive &&
              expiredCanopy.ParachuteLandingTick == 0 &&
              expiredCanopy.ParachuteRotation == null,
            "Paratrooper canopy leaves the roster after three host seconds");
        Check(!paraChangedCorner && occupiedOtherCorner != 0 &&
              firingParaMatch.CardParatrooperCornerChangeTick(
                  firingPara.EntityKey) > 999,
            "Corner Paratrooper retries after its partner occupies the only other point");
        Check(firingParaMatch.ConfirmArmyDeath(occupiedOtherCorner, false),
            "partner death releases the alternate Corner before retry");
        ulong transferTick = 0;
        for (ulong cardTick = 1000; cardTick < 1400 &&
             !firingParaMatch.Terminal && !paraChangedCorner; cardTick++)
        {
            if (cardTick % 90 == 0)
            {
                firingParaMatch.ArmyBatch(decoyPlayer);
                firingParaMatch.ArmyBatch(decoyOpponent);
            }
            firingParaMatch.Advance(cardTick);
            paraChangedCorner = firingParaMatch.CardParatrooperWalking(
                firingPara.EntityKey) &&
                firingParaMatch.CardEnemyPoint(firingPara.EntityKey)?
                    .ComponentFileId == paraLandingPoint.ComponentFileId;
            if (paraChangedCorner)
                transferTick = cardTick;
        }
        Check(paraChangedCorner &&
              firingParaMatch.CardEnemyPointOccupant(
                  exposedParaPoint.ComponentFileId) == null &&
              firingParaMatch.CardEnemyPointOccupant(
                  paraLandingPoint.ComponentFileId) == firingPara.EntityKey &&
              !firingParaMatch.CardParatrooperAttacking(firingPara.EntityKey),
            "Corner Paratrooper transfers its reservation before walking to a free point");
        bool reachedNewCorner = false;
        for (ulong cardTick = transferTick + 1; cardTick < transferTick + 400 &&
             !firingParaMatch.Terminal && !reachedNewCorner; cardTick++)
        {
            if (cardTick % 90 == 0)
            {
                firingParaMatch.ArmyBatch(decoyPlayer);
                firingParaMatch.ArmyBatch(decoyOpponent);
            }
            firingParaMatch.Advance(cardTick);
            reachedNewCorner = firingParaMatch.CardParatrooperAttacking(
                firingPara.EntityKey);
        }
        Check(reachedNewCorner &&
              !firingParaMatch.CardParatrooperWalking(firingPara.EntityKey),
            "transferred Paratrooper resumes its Corner attack clock on arrival");
        Check(firingParaMatch.ConfirmArmyDeath(firingPara.EntityKey, false) &&
              !firingParaMatch.CardParatrooperAttacking(firingPara.EntityKey) &&
              firingParaMatch.InfantryPose(firingPara.EntityKey) == null &&
              firingParaMatch.CardEnemyPointOccupant(
                  paraLandingPoint.ComponentFileId) == null,
            "Paratrooper death clears its attack and Corner reservation after firing");
        var snowCardMap = content.Maps.Single(sourceMap =>
            sourceMap.Source == "Assets/Scenes/Snow_Multiplayer.unity");
        var snowFallbackSpawn = content.ArmySpawnPoints.ForMap(snowCardMap)
            .First(point => point.Collection == "spawnPointsCollection" &&
                point.ComponentType == "SpawnPoint" && point.Fraction == 1);
        Vector3? snowLanding = null;
        Vector3? snowDestination = content.ArmyNavMeshConnectivity.SampleNearest(
            snowCardMap, snowFallbackSpawn.Position, 0.5f);
        foreach (Vector3 offset in new[]
        {
            new Vector3(0.4f, 0, 0), new Vector3(-0.4f, 0, 0),
            new Vector3(0, 0, 0.4f), new Vector3(0, 0, -0.4f)
        })
        {
            Vector3 candidate = snowFallbackSpawn.Position + offset;
            Vector3? start = content.ArmyNavMeshConnectivity.SampleNearest(
                snowCardMap, candidate, 0.5f);
            if (start.HasValue && snowDestination.HasValue &&
                content.ArmyNavMeshConnectivity.PlanCorridor(
                    snowCardMap, start.Value, snowDestination.Value) != null)
            {
                snowLanding = candidate;
                break;
            }
        }
        Vector3 confirmedSnowLanding = snowLanding ??
            throw new InvalidDataException("Snow normal spawn has no walkable landing fixture.");
        var snowParaMatch = ReadyCardMatch("host-card-para-snow", "ELITEPARA",
            snowCardMap);
        const string snowParaRequest = "fefefefefefefefefefefefefefefefe";
        Check(snowParaMatch.TryScheduleCardUnit(snowParaRequest,
                  decoyPlayer, "ELITEPARA"),
            "Snow Paratrooper card creates its first parachute unit");
        var snowPara = snowParaMatch.ArmyEntityBatch(decoyPlayer, 0, 0)
            .Entities.Single();
        Check(snowParaMatch.ConfirmCardParatrooperLanding(snowPara.EntityKey,
                  confirmedSnowLanding) &&
              snowParaMatch.CardParatrooperFallbackSpawn(snowPara.EntityKey) ==
                  snowFallbackSpawn.ComponentFileId &&
              snowParaMatch.CardEnemyPoint(snowPara.EntityKey) == null,
            "Snow landing selects the source same-faction normal spawn without inventing a Corner");
        for (ulong cardTick = 61; cardTick <= 225; cardTick++)
        {
            if (cardTick % 90 == 0)
            {
                snowParaMatch.ArmyBatch(decoyPlayer);
                snowParaMatch.ArmyBatch(decoyOpponent);
            }
            snowParaMatch.Advance(cardTick);
        }
        Check(snowParaMatch.CardParatrooperFallbackSpawn(snowPara.EntityKey) ==
                  snowFallbackSpawn.ComponentFileId &&
              snowParaMatch.CardEnemyPoint(snowPara.EntityKey) == null &&
              !snowParaMatch.CardParatrooperAttacking(snowPara.EntityKey),
            "Snow five-second point retry leaves the Paratrooper at its fallback spawn");
        Check(snowParaMatch.ConfirmArmyDeath(snowPara.EntityKey, false) &&
              snowParaMatch.CardParatrooperFallbackSpawn(snowPara.EntityKey) == null,
            "Snow Paratrooper death clears its fallback walk and retry clock");
        RecoveredBattleMap cityCardMap = content.Maps.Single(sourceMap =>
            sourceMap.Source.EndsWith("City_Multiplayer.unity"));
        var automaticCityLanding = ReadyCardMatch(
            "host-card-para-auto-city", "ELITEPARA", cityCardMap);
        Check(automaticCityLanding.TryScheduleCardUnit(
                  "acacacacacacacacacacacacacacacac",
                  decoyOpponent, "ELITEPARA"),
            "City faction-two card starts host-owned parachute flight");
        var cityParatrooper = automaticCityLanding.ArmyEntityBatch(
            decoyOpponent, 0, 0).Entities.Single();
        float citySpawnHeight = cityParatrooper.Y;
        ArmySpawnPoint citySourceSpawn = content.ArmySpawnPoints.ForMap(cityCardMap)
            .Single(point => point.ComponentFileId ==
                cityParatrooper.SpawnComponentFileId);
        Check(citySourceSpawn.ComponentType == "SpawnPointParachute" &&
              citySpawnHeight > 6f &&
              automaticCityLanding.CardParatrooperFalling(
                  cityParatrooper.EntityKey),
            "new City Paratrooper starts at its elevated source parachute point");
        int sourceShieldTargetId = content.PlayerShotTargets.Gameplay
            .Single(target => target.Type == 2).TransformFileId;
        CardParatrooperAirTarget? initialAirAim = automaticCityLanding
            .CardParatrooperAirAim(cityParatrooper.EntityKey);
        CoopMuzzlePose? initialAirMuzzle = automaticCityLanding
            .CardParatrooperAirMuzzle(cityParatrooper.EntityKey);
        CoopMuzzlePose sourceIdleMuzzle = content.CoopEnemyMuzzles.Place(
            "idle_1", new Vector3(cityParatrooper.X, cityParatrooper.Y,
                cityParatrooper.Z),
            Quaternion.CreateFromAxisAngle(Vector3.UnitY, -MathF.PI / 2f),
            0f);
        Check(initialAirAim?.TransformFileId == sourceShieldTargetId &&
              initialAirAim.Distance > 0f,
            "airborne Paratrooper selects the posed source Shield target");
        Check(initialAirMuzzle != null &&
              Vector3.Distance(initialAirMuzzle.Position,
                  sourceIdleMuzzle.Position) < 0.0001f &&
              Quaternion.Dot(initialAirMuzzle.Rotation,
                  sourceIdleMuzzle.Rotation) > 0.9999f &&
              MathF.Abs(sourceIdleMuzzle.Position.Y -
                  (cityParatrooper.Y + content.ArmyWeapons
                      .Muzzle("ID_UNIT-PARATROOPER").RestPosition.Y)) > 0.02f,
            "airborne rifle muzzle begins at the Unity-sampled idle pose under the parachute rotation");
        HelicopterSightRay directAirSight = CardParatrooperAirTarget.SightRay(
            Vector3.Zero, 1f, new Vector3(0f, 1f, 8f));
        Check(Vector3.Distance(directAirSight.Origin,
                  new Vector3(0f, 1f, 0.18f)) < 0.0001f &&
              directAirSight.Direction == Vector3.UnitZ &&
              MathF.Abs(directAirSight.Range - 7.32f) < 0.0001f &&
              directAirSight.LayerMask ==
                  HelicopterTurretSightRay.SourceLayerMask,
            "airborne visibility ray keeps the Client offset, near-target stop, and collider mask");
        Reject(() => CardParatrooperAirTarget.Select(
            content.PlayerShotTargets,
            automaticCityLanding.CombatPose(decoyPlayer),
            new Vector3(float.NaN, 0f, 0f)));
        Reject(() => CardParatrooperAirTarget.SightRay(
            Vector3.Zero, float.NaN, Vector3.UnitZ));
        for (ulong cardTick = 61; cardTick <= 365 &&
             !automaticCityLanding.Terminal; cardTick++)
        {
            if (cardTick % 90 == 0)
            {
                automaticCityLanding.ArmyBatch(decoyPlayer);
                automaticCityLanding.ArmyBatch(decoyOpponent);
            }
            automaticCityLanding.Advance(cardTick);
            if (cardTick == 100)
            {
                var fallingCityParatrooper = automaticCityLanding.ArmyEntityBatch(
                    decoyOpponent, 0, 0).Entities.Single(entity =>
                        entity.EntityKey == cityParatrooper.EntityKey);
                Check(automaticCityLanding.CardParatrooperFalling(
                          cityParatrooper.EntityKey) &&
                      automaticCityLanding.CardEnemyPoint(
                          cityParatrooper.EntityKey) == null &&
                      fallingCityParatrooper.Y < citySpawnHeight,
                    "host publishes a falling pose without reserving a Corner early");
                CardParatrooperAirTarget? fallingAim = automaticCityLanding
                    .CardParatrooperAirAim(cityParatrooper.EntityKey);
                Check(fallingAim?.TransformFileId == sourceShieldTargetId &&
                      Vector3.Distance(fallingAim.Position,
                          automaticCityLanding.CombatPose(decoyPlayer)
                              .BodyTarget(sourceShieldTargetId).Position) < 0.0001f &&
                      fallingAim.WithinRange ==
                          (fallingAim.Distance <=
                           CardParatrooperAirTarget.MaximumRange) &&
                      (!fallingAim.HasClearSight || fallingAim.WithinRange),
                    "falling Paratrooper tracks the live Shield pose and source range gate");
            }
        }
        Check(!automaticCityLanding.Terminal &&
              !automaticCityLanding.CardParatrooperFalling(
                  cityParatrooper.EntityKey) &&
              automaticCityLanding.CardParatrooperAirAim(
                  cityParatrooper.EntityKey) == null &&
              automaticCityLanding.CardParatrooperAirMuzzle(
